ClinicalChunks.register("data/orders-013.js",[{"id":"orders-b6ed78ea4ffa6b2ef27f","key":"v1-c9ccc21dfe2a3058|orders-b6ed78ea4ffa6b2ef27f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班头晕处理","category":"值班宝典","raw":{"name":"夜班头晕处理","category":"值班宝典","summary":"定义：头晕是一类主观不适的总称，包括旋转性眩晕、晕前状态（眼前发黑、将要晕倒感）与平衡不稳感，病因覆盖内耳前庭、脑干小脑、心血管、代谢与精神心理多个系统。\n夜班目标：先从急性持续性眩晕中筛出后循环卒中，再识别心源性晕厥前状态、体位性低血压与低血糖，避免把中枢性眩晕当成耳石症处理。","symptoms":["眩晕型（周围性多见）：旋转感或视物晃动，持续数十秒至数天，伴恶心呕吐、出汗、耳鸣与听力下降；良性阵发性位置性眩晕多在翻身、起床、低头时发作，持续<1分钟。","晕前型：站立时眼前发黑、乏力、心慌、耳鸣，多见于体位性低血压、心律失常、贫血与血容量不足。","平衡不稳型：走路不稳、踩棉花感，多见于小脑、深感觉障碍与药物影响。","中枢警示信号：突发持续性眩晕伴走路不稳、复视、言语含糊、吞咽困难、面部或肢体麻木无力、剧烈枕部头痛、意识改变与抽搐。"],"diagnosis":["起病方式（关键）：突发还是渐进、持续数秒还是数小时至数天、是否与体位变化或头位改变相关。","诱因与伴随：起床或转头时发作、近期上呼吸道感染、头部外伤、噪声暴露、耳部手术史；是否伴耳聋、耳鸣与耳闷胀感。","既往史与用药：高血压、糖尿病、房颤、冠心病、颈椎病、偏头痛、焦虑抑郁；是否使用降压药、镇静催眠药、氨基糖苷类、抗癫痫药与利尿剂。","鉴别方向：良性阵发性位置性眩晕、前庭神经炎、梅尼埃病、后循环缺血或脑梗死、体位性低血压、心律失常、贫血、低血糖与甲状腺功能异常。"],"infusion":["补液：容量不足或体位性低血压者给0.9%氯化钠注射液500mL静滴，按血压、心率与心功能调整速度。","止晕（不能口服者）：茶苯海明50mg肌内注射，或异丙嗪25mg肌内注射，按本院规范。","止吐：甲氧氯普胺10mg肌内注射，用于急性眩晕伴明显呕吐者；疑中枢性眩晕时避免用镇静类止晕药掩盖病情。","低血糖：床旁血糖低者给50%葡萄糖注射液20~40mL静推，随后15分钟后复测血糖。"],"oral_medication":["眩晕：甲磺酸倍他司汀6~12mg口服，每日3次；或氟桂利嗪5~10mg睡前口服。","急性发作：茶苯海明50mg口服，每6小时按需；或地芬尼多25mg口服，每日3次。","梅尼埃病缓解期：按专科方案限盐并用药，必要时用氢氯噻嗪等利尿剂，按本院规范。","禁忌：呕吐明显、意识改变或疑卒中者不口服给药；前列腺增生与青光眼患者慎用抗组胺类止晕药。"],"treatment":["首要：排除中枢性病因——存在突发持续眩晕伴走路不稳、眼震方向改变、甩头试验正常或眼偏斜等中枢体征时，立即按卒中流程完成影像与神经科评估。","其次：对症止晕止吐、补液纠正容量不足，逐一核对并调整可疑降压药、镇静药与耳毒性药物。","随后：明确病因后针对性处理——良性阵发性位置性眩晕行手法复位，前庭神经炎对症并鼓励早期活动，梅尼埃病按专科方案限盐与用药，体位性低血压调整用药与生活方式。","最后：慢性头晕患者安排前庭康复训练与跌倒防范宣教。"],"management":["复评频率：急性期每小时记录卧立位血压、心率与意识，观察眩晕持续时间与诱因；稳定后每4小时评估。","观察要点：有无新发神经体征（复视、构音障碍、肢体无力、共济失调）、发作后步态是否恢复、有无跌倒与外伤。","用药管理：记录止晕药的种类、剂量与时间，评估日间嗜睡与步态不稳；症状缓解后尽早停用镇静类止晕药。","留观与收治标准：急性持续性眩晕、神经体征阳性、反复发作伴跌倒、心电图异常或不能进食者留观并收治神经内科、心内科或耳鼻喉科。"],"notes":["以本院规范为准：止晕药物的选择与静脉给药剂量、影像检查与卒中绿色通道流程按本院常规执行。","避免与禁忌：不把急性持续性眩晕一律归因于颈椎病或耳石症而延误影像检查；多种镇静类止晕药不叠加使用（老年患者易致跌倒与谵妄）；不长期使用氟桂利嗪等药物；急性眩晕期不做剧烈颈部按摩与手法扳动。","提醒：眩晕伴听力骤降应按突发性耳聋处理并尽早请耳鼻喉科会诊。"],"emergency":["立即升级：突发眩晕伴复视、构音障碍、吞咽困难、肢体无力或共济失调，或发病4.5小时内疑缺血性卒中 → 立即启动卒中绿色通道并呼叫上级。","循环阈值：收缩压<90mmHg或立位收缩压下降≥20mmHg伴晕倒、心率<40次/分或>150次/分、SpO2<92% → 心电监护并呼叫上级。","其他：眩晕伴剧烈头痛、呕吐与颈项强直 → 疑蛛网膜下腔出血或中枢感染，急诊头颅CT并评估腰穿。"],"pinyin":"yebantouyunchuli","icd10":"R42","physical_exam":"生命体征：卧位与立位血压（站立3分钟内收缩压下降≥20mmHg或舒张压下降≥10mmHg为体位性低血压）、心率与心律、呼吸、SpO2、体温。\n神经与前庭：自发与凝视诱发眼震、甩头试验、眼偏斜、指鼻与跟膝胫试验、闭目难立、步态与转身、脑神经与肢体肌力、病理反射。\n其他：听力粗测、外耳道与鼓膜检查、眼底、颈部血管杂音与心脏杂音、颈项强直（疑中枢感染）。","lab_tests":"必查：床旁血糖、血常规、电解质、肾功能、心电图。\n按需：头颅磁共振（含弥散加权成像，疑中枢病变时优先于CT）、头颅CT（急诊排除出血）、动态心电图与超声心动图、前庭功能检查与Dix-Hallpike位置试验、纯音测听、颈动脉与椎动脉超声、甲状腺功能与心肌损伤标志物。","nursing":"体位与起床：发作期卧床，避免快速转头与起身，起床遵循“平卧30秒—坐起30秒—站立30秒”三步法。\n安全防护：床栏保护，下床需人陪同，卫生间加扶手与防滑垫，夜间照明良好，防跌倒与外伤。\n监测与记录：卧立位血压、心率、意识与神经体征，记录眩晕发作时间、持续时间与诱因。\n宣教：发作期避免驾驶与高空作业；按医嘱逐渐停用止晕药；长期眩晕者做前庭康复训练并复查。","diet":"进食清淡低盐易消化饮食，避免过饱，采取少量多餐。\n梅尼埃病与内耳水肿者每日食盐限制在 2~3g，避免咖啡、浓茶、酒精与烟草。\n发作期恶心呕吐明显时暂禁食 4~6 小时，之后给温凉流质如米汤、稀粥。\n体位性低血压者适当增加饮水与盐分，起床前先饮温水，避免饮酒。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1196},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"183f3bcd999707b8e9b1bd0ffb0180ab1b6b3d6cba82d446dc4bb32eff8bd94b","pinyin":"yebantouyunchuli","initials":"ybtycl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","眩晕型（周围性多见）：旋转感或视物晃动，持续数十秒至数天，伴恶心呕吐、出汗、耳鸣与听力下降；良性阵发性位置性眩晕多在翻身、起床、低头时发作，持续<1分钟。\\n晕前型：站立时眼前发黑、乏力、心慌、耳鸣，多见于体位性低血压、心律失常、贫血与血容量不足。\\n平衡不稳型：走路不稳、踩棉花感，多见于小脑、深感觉障碍与药物影响。\\n中枢警示信号：突发持续性眩晕伴走路不稳、复视、言语含糊、吞咽困难、面部或肢体麻木无力、剧烈枕部头痛、意识改变与抽搐。",60],["摘要","定义：头晕是一类主观不适的总称，包括旋转性眩晕、晕前状态（眼前发黑、将要晕倒感）与平衡不稳感，病因覆盖内耳前庭、脑干小脑、心血管、代谢与精神心理多个系统。\n夜班目标：先从急性持续性眩晕中筛出后循环卒中，再识别心源性晕厥前状态、体位性低血压与低血糖，避免把中枢性眩晕当成耳石症处理。",30],["疾病编码","R42",30],["原首字母","yebantouyunchuli",60]]},{"id":"orders-39666840637b541db184","key":"v1-c9ccc21dfe2a3058|orders-39666840637b541db184","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班心悸处理","category":"值班宝典","raw":{"name":"夜班心悸处理","category":"值班宝典","summary":"定义：心悸是患者自觉心跳或心搏不适，可由心律失常（期前收缩、阵发性室上性心动过速、心房颤动、室性心动过速）、心脏结构病变、贫血、甲状腺功能亢进、电解质紊乱、发热与焦虑等引起。\n夜班目标：先判断血流动力学是否稳定，再依据12导联心电图区分快速性与缓慢性心律失常，识别恶性心律失常并即刻纠正可逆诱因。","symptoms":["心律相关：突发突止的心跳加快（阵发性室上性心动过速典型）、心跳漏搏感、持续不规则搏动（心房颤动）、持续快速而规则的搏动。","伴随表现：乏力、头晕、气短、胸闷、胸痛、出汗、黑矇甚至晕厥。","诱因：情绪激动、咖啡浓茶、饮酒、熬夜、发热、腹泻呕吐后低钾、甲状腺功能亢进、贫血、使用麻黄碱类或部分抗心律失常药。","危险信号：心悸伴晕厥、持续胸痛、呼吸困难或意识改变、心率持续>150次/分、血压下降、皮肤湿冷。"],"diagnosis":["发作特点：起始与终止方式（突发突止提示阵发性室上性心动过速）、持续时间、频率、是否规则与诱发因素。","既往史：心律失常、冠心病、心肌病、心脏瓣膜病、甲状腺疾病、贫血、出血、呕吐腹泻与进食情况。","用药史：洋地黄、抗心律失常药、抗抑郁药、支气管扩张剂、甲状腺素与含麻黄碱类保健品。","鉴别方向：窦性心动过速（发热、贫血、甲亢、疼痛、焦虑、低血容量）、期前收缩、心房颤动、室上性心动过速、室性心动过速与电解质紊乱所致心律失常。"],"infusion":["血流动力学不稳定：立即同步电复律，复律前后按本院规范给镇静与抗凝评估。","窄QRS心动过速（稳定）：腺苷6mg快速静推（近心端，随后立即生理盐水冲管），无效可增至12mg；或维拉帕米5mg缓慢静推，注意低血压与心功能。","宽QRS心动过速（稳定）：胺碘酮150mg加5%葡萄糖注射液20mL，缓慢静推10分钟以上，随后按1mg/min维持静滴。","心动过缓伴症状：阿托品0.5~1mg静推，必要时每3~5分钟重复，总量不超过3mg，无效准备临时起搏。","纠正电解质：低钾、低镁者按规范静脉补充并心电监护。"],"oral_medication":["窦性心动过速：以治疗病因为主（退热、补液、纠正贫血、控制甲亢），必要时美托洛尔25mg口服，每日2次。","稳定期心房颤动或阵发性室上性心动过速：美托洛尔25~50mg口服每日2次，或比索洛尔2.5~5mg口服每日1次，控制心室率。","普罗帕酮150mg口服每8小时1次，仅用于无结构性心脏病者；胺碘酮200mg口服每日1次用于特定患者，按本院规范。","禁忌：禁食、意识不清或血流动力学不稳定者不口服给药；哮喘患者慎用β受体阻滞剂。"],"treatment":["首要：判断血流动力学——低血压、胸痛、呼吸困难或意识改变者立即同步电复律并呼叫上级。","其次：稳定者先完成12导联心电图并明确心律类型，按窄QRS、宽QRS或缓慢心律分路处理，同时纠正低钾、低镁、缺氧、发热与甲亢等诱因。","随后：心律失常控制后评估病因与血栓栓塞风险，安排超声心动图与动态心电图，评估抗凝、射频消融或起搏器指征。","最后：向患者说明诱发因素与随访计划，避免自行停药或加药。"],"management":["复评频率：持续心电监护，急性期每15~30分钟记录心率、心律、血压与意识；稳定后每小时评估一次。","观察要点：有无晕厥前症状、胸痛、气促与尿量减少；复律后有无栓塞表现（新发神经体征）；补钾期间复查血钾与心电图。","用药管理：记录抗心律失常药的种类、剂量、途径与时间，避免同类药物叠加；长期用胺碘酮者监测甲状腺功能与肺毒性。","收治标准：持续性心动过速、宽QRS心动过速、血流动力学不稳定、疑急性冠脉综合征或需电复律者收入监护病房。"],"notes":["以本院规范为准：腺苷、维拉帕米、胺碘酮的静脉用法与剂量、电复律镇静方案与抗凝评估按本院流程执行。","避免与禁忌：宽QRS心动过速未经评估不得按室上性心动过速处理而误用维拉帕米；结构性心脏病或心功能不全者禁用普罗帕酮；预激合并心房颤动者禁用洋地黄与维拉帕米；不明原因心悸不常规长期使用抗心律失常药。","提醒：心悸伴血流动力学不稳定时优先电复律，不要先反复尝试药物。"],"emergency":["立即升级：心率>150次/分伴血压下降、胸痛或意识改变 → 立即同步电复律；心率<40次/分伴晕厥或低血压 → 阿托品并准备临时起搏。","致命心律：出现室性心动过速、心室颤动或无脉 → 立即除颤并按高级生命支持流程抢救，呼叫抢救团队。","其他阈值：SpO2<92%、收缩压<90mmHg或心电图提示急性缺血改变 → 请心内科会诊并转监护病房。"],"pinyin":"yebanxinjichuli","icd10":"R00.2","physical_exam":"生命体征与灌注：血压、心率、呼吸、SpO2、意识、皮肤温度与毛细血管再充盈时间、尿量。\n心脏：心率与心律是否规整、心音强弱、额外心音、杂音、颈静脉充盈、肺部啰音（提示心衰）。\n其他：甲状腺大小与震颤、突眼、贫血貌、下肢水肿与出血征象，评估有无感染与容量不足。","lab_tests":"必查：12导联心电图（到院10分钟内完成）、血常规、电解质（钾、镁、钙）、肾功能、心肌损伤标志物、床旁血糖。\n按需：动脉血气与乳酸、甲状腺功能、脑钠肽、超声心动图、24小时动态心电图、胸部影像；疑肺栓塞时查D-二聚体与肺动脉CT血管成像；疑药物中毒时查血药浓度。","nursing":"监测：持续心电监护，记录发作与终止时间、心率与节律变化、血压与意识。\n安全：血流动力学不稳定者绝对卧床至稳定，床栏保护，除颤仪与抢救车处于备用状态。\n记录：心悸发作与诱因、抗心律失常药给药时间与反应、电解质结果与补钾速度。\n宣教：避免咖啡、浓茶、酒精与熬夜；教会患者自测脉搏并记录发作情况；出现晕厥前症状或持续胸痛立即呼叫医护人员。","diet":"进食清淡低盐低脂易消化饮食，少量多餐，避免过饱与夜间加餐。\n禁饮浓茶、咖啡与酒精，戒烟。\n低钾者可多食香蕉、橙子、土豆与菠菜，心衰者限盐每日 2~3g 并限制入量。\n避免大量冷饮与暴饮暴食诱发迷走反射与心律失常。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1197},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a2f720df7b384be8cebeff6604c5aa9e67cee4cc726a3c6def34c95aea48ee13","pinyin":"yebanxinjichuli","initials":"ybxjcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","心律相关：突发突止的心跳加快（阵发性室上性心动过速典型）、心跳漏搏感、持续不规则搏动（心房颤动）、持续快速而规则的搏动。\\n伴随表现：乏力、头晕、气短、胸闷、胸痛、出汗、黑矇甚至晕厥。\\n诱因：情绪激动、咖啡浓茶、饮酒、熬夜、发热、腹泻呕吐后低钾、甲状腺功能亢进、贫血、使用麻黄碱类或部分抗心律失常药。\\n危险信号：心悸伴晕厥、持续胸痛、呼吸困难或意识改变、心率持续>150次/分、血压下降、皮肤湿冷。",60],["摘要","定义：心悸是患者自觉心跳或心搏不适，可由心律失常（期前收缩、阵发性室上性心动过速、心房颤动、室性心动过速）、心脏结构病变、贫血、甲状腺功能亢进、电解质紊乱、发热与焦虑等引起。\n夜班目标：先判断血流动力学是否稳定，再依据12导联心电图区分快速性与缓慢性心律失常，识别恶性心律失常并即刻纠正可逆诱因。",30],["疾病编码","R00.2",30],["原首字母","yebanxinjichuli",60]]},{"id":"orders-2807a630668b8b84c0dd","key":"v1-c9ccc21dfe2a3058|orders-2807a630668b8b84c0dd","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班胸闷处理","category":"值班宝典","raw":{"name":"夜班胸闷处理","category":"值班宝典","summary":"定义：胸闷是胸前区不适、压迫感或憋气感的统称，既可能是急性冠脉综合征、肺栓塞、气胸与主动脉夹层等致命疾病的表现，也可能源于反流性食管炎、肋软骨炎、带状疱疹与焦虑。\n夜班目标：10分钟内完成并判读心电图，按“致命五联”顺序排查，先处理危及生命的病因，再考虑功能性胸闷。","symptoms":["心源性：胸骨后压榨性胸闷或疼痛，可向左肩、左臂、下颌与背部放射，持续>10分钟，伴出汗、恶心与气促；活动或情绪激动可诱发，休息或含服硝酸酯类可缓解。","肺源性：突发胸痛伴呼吸困难与咯血（肺栓塞）、突发单侧胸痛伴呼吸困难（气胸）、伴发热与咳嗽咳痰（肺炎、胸膜炎）。","消化与功能性：餐后或平卧后加重伴反酸烧心（反流）；与情绪相关、伴叹气样呼吸与手足麻木（焦虑或过度通气）。","危险信号：撕裂样胸背痛并向背部放射（主动脉夹层）、持续胸痛>20分钟不缓解伴大汗、SpO2<92%、血压下降、意识改变、一侧呼吸音消失。"],"diagnosis":["胸痛特征：部位、性质、持续时间、放射部位、诱发与缓解因素，与活动、进食、体位和呼吸的关系。","危险因素：年龄、吸烟、高血压、糖尿病、血脂异常、既往冠心病、近期手术或制动、长途旅行、肿瘤与妊娠（肺栓塞风险）。","既往史与用药：慢性阻塞性肺疾病、气胸史、消化道疾病、焦虑抑郁；是否使用硝酸酯类、抗凝药与激素。","鉴别方向：急性冠脉综合征、肺栓塞、气胸、主动脉夹层、心包炎、食管痉挛与反流、肋软骨炎、带状疱疹与惊恐发作。"],"infusion":["抗血小板与抗凝（急性冠脉综合征）：阿司匹林300mg嚼服（或按本院规范用静脉制剂），联合肝素或低分子肝素按体重给药。","镇痛与扩冠：硝酸甘油5~10μg/min静脉泵入起始，按血压与症状滴定；收缩压<90mmHg或疑右室梗死者禁用硝酸酯类。","肺栓塞：按危险分层抗凝，高危者评估溶栓，按本院规范。","气胸与夹层：张力性气胸立即穿刺减压并置管引流；主动脉夹层按规范静脉泵入β受体阻滞剂控制心率至60次/分左右后再降压。"],"oral_medication":["急性冠脉综合征：阿司匹林300mg嚼服（负荷量），随后100mg口服每日1次；氯吡格雷300mg负荷后75mg口服每日1次，或替格瑞洛180mg负荷后90mg每日2次，按本院规范与他汀联合。","功能性或反流相关：含服硝酸甘油片0.5mg，5分钟可重复，最多3次；反流者加用质子泵抑制剂。","禁忌：低血压、右室梗死或48小时内使用磷酸二酯酶5抑制剂者禁用硝酸酯类；意识不清、休克或需急诊手术者不口服给药。"],"treatment":["首要：评估生命体征并按“致命五联”排查，10分钟内完成心电图；不稳定者立即监护、吸氧、建立静脉通路并呼叫上级。","其次：按病因处理——急性冠脉综合征启动再灌注评估与双联抗血小板加抗凝；肺栓塞按分层抗凝或溶栓；气胸穿刺减压或闭式引流；主动脉夹层控制心率与血压并请心血管外科会诊。","随后：无致命病因者对症处理反流、胸壁痛与焦虑，避免反复使用镇痛药掩盖症状。","最后：症状反复或高危因素多者安排动态心电图、运动试验或冠脉CT等进一步评估。"],"management":["复评频率：急性期每15~30分钟记录生命体征与胸痛评分，稳定后每小时记录；肌钙蛋白按流程复查。","观察要点：胸痛是否再发或持续、心电图有无动态演变、心律与血压变化、尿量与皮肤灌注；抗栓药物使用后注意出血征象（牙龈、皮肤、消化道与穿刺部位）。","用药管理：记录抗栓与扩冠药物的剂量、给药时间与反应，硝酸酯类使用后监测血压。","收治标准：疑急性冠脉综合征、肺栓塞、气胸、主动脉夹层或肌钙蛋白升高者收入监护病房；功能性胸闷需排除器质性疾病后方可离院并安排随访。"],"notes":["以本院规范为准：抗血小板与抗凝方案、硝酸酯类与β受体阻滞剂泵入剂量、再灌注治疗流程按本院胸痛中心流程执行。","避免与禁忌：疑主动脉夹层时禁用抗凝与抗血小板药物；收缩压<90mmHg或疑右室梗死者禁用硝酸酯类；不因胸痛缓解而省略心电图与肌钙蛋白复查；不把反复胸闷一律归因于情绪而漏查器质性心脏病。","提醒：夜间胸闷伴阵发性呼吸困难与端坐呼吸者，要考虑急性左心衰并按心衰处理。"],"emergency":["立即升级：持续胸痛>20分钟不缓解、心电图ST段抬高或压低、肌钙蛋白升高 → 立即启动急性冠脉综合征救治流程并呼叫上级。","其他阈值：SpO2<92%、收缩压<90mmHg、心率>120次/分或<50次/分、意识改变、一侧呼吸音消失、双上肢血压差异>20mmHg → 立即监护并按急诊流程处理。","特殊提示：疑主动脉夹层时禁用抗凝与抗血小板药物，先完成影像学检查。"],"pinyin":"yebanxiongmenchuli","icd10":"R07.4","physical_exam":"生命体征与心肺：血压（双上肢血压差异>20mmHg提示主动脉夹层）、心率、呼吸、SpO2；呼吸音是否对称、有无啰音与胸膜摩擦音、心音与杂音、颈静脉充盈。\n循环与外周：脉搏是否对称、下肢周径与压痛、水肿、毛细血管再充盈、皮肤湿冷与出汗。\n腹部与皮肤：上腹压痛与反流相关体征、沿肋间神经分布的皮疹与水疱（带状疱疹）、胸壁压痛（肋软骨炎）。","lab_tests":"必查：心电图（到院10分钟内完成）、心肌损伤标志物（高敏肌钙蛋白，必要时3~6小时复查）、血常规、电解质、肾功能、凝血功能。\n按需：D-二聚体、动脉血气、胸部影像或胸部CT血管成像、超声心动图、床旁肺部与心脏超声、腹部超声与淀粉酶、胃镜（反流相关，择期）。","nursing":"体位与休息：急性胸痛者绝对卧床、减少搬动；呼吸困难者取半卧位并给氧。\n监测：持续心电与血压监护，记录胸痛发作时间、性质与缓解情况，动态观察心电图与心肌标志物结果。\n安全：床旁备除颤仪、抢救车与吸氧装置，保持静脉通路通畅，避免穿刺侧肢体剧烈活动。\n宣教：指导识别胸痛危险信号并立即呼叫医护人员；说明戒烟、控制血压血糖血脂与规律服药的重要性。","diet":"急性期禁食，病情稳定后给低盐低脂半流质。\n宜米粥、面条与蒸蛋，少食多餐避免饱餐。\n禁浓茶、咖啡、酒精与辛辣食物；保持大便通畅，必要时用缓泻剂，避免用力排便诱发心脏事件。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1198},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7b98b91684d8f72e5528b66cfc2870303165c859b95f53507bb141ff272448a0","pinyin":"yebanxiongmenchuli","initials":"ybxmcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","心源性：胸骨后压榨性胸闷或疼痛，可向左肩、左臂、下颌与背部放射，持续>10分钟，伴出汗、恶心与气促；活动或情绪激动可诱发，休息或含服硝酸酯类可缓解。\\n肺源性：突发胸痛伴呼吸困难与咯血（肺栓塞）、突发单侧胸痛伴呼吸困难（气胸）、伴发热与咳嗽咳痰（肺炎、胸膜炎）。\\n消化与功能性：餐后或平卧后加重伴反酸烧心（反流）；与情绪相关、伴叹气样呼吸与手足麻木（焦虑或过度通气）。\\n危险信号：撕裂样胸背痛并向背部放射（主动脉夹层）、持续胸痛>20分钟不缓解伴大汗、SpO2<92%、血压下降、意识改变、一侧呼吸音消失。",60],["摘要","定义：胸闷是胸前区不适、压迫感或憋气感的统称，既可能是急性冠脉综合征、肺栓塞、气胸与主动脉夹层等致命疾病的表现，也可能源于反流性食管炎、肋软骨炎、带状疱疹与焦虑。\n夜班目标：10分钟内完成并判读心电图，按“致命五联”顺序排查，先处理危及生命的病因，再考虑功能性胸闷。",30],["疾病编码","R07.4",30],["原首字母","yebanxiongmenchuli",60]]},{"id":"orders-e6c751d226f706447a5c","key":"v1-c9ccc21dfe2a3058|orders-e6c751d226f706447a5c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"窄QRS波心动过速处理流程","category":"夜班急症流程","raw":{"name":"窄QRS波心动过速处理流程","category":"夜班急症流程","summary":"QRS波时限<0.12s、心室率快于正常的快速性心律失常鉴别与处理：先按血流动力学是否稳定分流，再按节律齐否分型（窦速、交界性心动过速、房扑、AVNRT、AVRT、房速、房颤、多源性房速、频发房早）。","symptoms":["心悸、胸闷、头晕、乏力；血流动力学不稳定者出现血压下降、意识改变、胸痛、急性心衰表现；心室率多在100-250次/分。"],"diagnosis":["心电图是第一诊断手段：先判断QRS波是否窄（<0.12s）及节律是否整齐；找以往心电图对比；窦速心率=220-年龄上限；交界性心动过速心率多100-200次/分、P波缺失；房扑呈2:1下传时心室率固定约150次/分、下壁及V1导联见房扑波；AVNRT约180±20次/分、逆传P波藏于QRS（寻找假q波/假s波）；AVRT为短RP间期可见逆传P波；房速心率常<250次/分、长RP；房颤绝对不齐；多源性房速同导联见≥3种形态P波。"],"infusion":["血流动力学不稳定（低血压、休克、心衰、意识改变）的窄QRS心动过速按高级生命支持流程处理：同步电复律（房颤/房扑/AVNRT/AVRT），必要时镇静后复律。稳定者按类型给药。"],"oral_medication":["窦速对因处理；房早症状明显可予β受体阻滞剂缓解并纠正电解质。"],"treatment":["1.先问有无症状及血流动力学是否稳定：不稳定→准备同步电复律并呼叫上级；2.做12导联心电图并快速查体，判断为新发还是既往已知；3.按心律是否整齐分型处理：①整齐的窄QRS：先试迷走神经刺激（颈动脉窦按摩需除外颈动脉杂音）或腺苷6mg快速静推（可重复12mg，用于终止AVNRT/AVRT或显露房扑波），无效可用维拉帕米/地尔硫卓、β受体阻滞剂、普罗帕酮；洋地黄中毒禁用电复律，交界性心动过速对因处理；②不齐的窄QRS：房颤或房扑不成比例下传——控制心室率可用β受体阻滞剂或钙通道阻滞剂，伴心衰/低血压者首选胺碘酮，新发房颤考虑抗凝（CHA2DS2-VASc评估）与转复；多源性房速对因治疗，维拉帕米可能有效；4.房扑可电转复或房室结阻滞药物控制；5.寻找并处理诱因（低氧、低血容量、感染、发热、贫血、甲亢、肺栓塞、酒精戒断等）。"],"management":["上心电监护，建立静脉通路；记录发作与用药时间；效果不佳或诊断不明及时呼叫总住院医师/心内科；复律后观察心律与血压。"],"notes":["勿对预激综合征合并房颤使用腺苷、β受体阻滞剂、钙通道阻滞剂等房室结阻滞剂（可加快旁路下传诱发室颤）；宽窄QRS判断务必准确；电解质（低钾低镁）是诱因也影响疗效。"],"emergency":["出现低血压、休克、急性肺水肿、胸痛、晕厥或意识改变时立即同步电复律，勿延迟。"],"pinyin":"zhaiQRSboxindongguosuchuliliucheng","icd10":"R00.0","physical_exam":"测血压、脉搏、呼吸、血氧；听诊心肺注意心音强弱与杂音；观察皮肤湿冷、颈静脉怒张等心衰/低灌注体征。","lab_tests":"电解质（尤其钾、镁）、血气、血常规、肌钙蛋白、甲状腺功能（疑甲亢）；用药后复查电解质。","nursing":"持续心电监护，备好除颤仪与抢救车；观察血压心率节律变化；嘱病人安静、减少活动；用药时观察不良反应（腺苷面红、胸闷、短暂停搏）。","diet":"避免浓茶、咖啡、酒精等刺激性饮品；原发病（甲亢、心衰）饮食管理。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1199},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"158b77c95a506521c51326c9637a664e06acc238913c781b5e533a78fc8fb10c","pinyin":"zhaiQRSboxindongguosuchuliliucheng","initials":"zQbxdgscllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","心悸、胸闷、头晕、乏力；血流动力学不稳定者出现血压下降、意识改变、胸痛、急性心衰表现；心室率多在100-250次/分。",60],["摘要","QRS波时限<0.12s、心室率快于正常的快速性心律失常鉴别与处理：先按血流动力学是否稳定分流，再按节律齐否分型（窦速、交界性心动过速、房扑、AVNRT、AVRT、房速、房颤、多源性房速、频发房早）。",30],["疾病编码","R00.0",30],["原首字母","zhaiQRSboxindongguosuchuliliucheng",60]]},{"id":"orders-49f53722a73efffa7ccc","key":"v1-c9ccc21dfe2a3058|orders-49f53722a73efffa7ccc","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"宽QRS波心动过速鉴别处理流程","category":"夜班急症流程","raw":{"name":"宽QRS波心动过速鉴别处理流程","category":"夜班急症流程","summary":"QRS波时限≥0.12s的快速心律失常：对基础心脏病人出现宽QRS心动过速应先假定为室速处理直至排除；按节律齐否分流，齐者按Brugada标准鉴别室速与室上速伴差传，不齐者考虑室颤、多形性室速或房颤伴预激。","symptoms":["心悸、头晕、黑矇、胸痛、呼吸困难，可突发晕厥或心脏骤停；血流动力学可迅速恶化。"],"diagnosis":["12导联心电图逐条判断（Brugada标准）：①V1-V6胸前导联QRS主波是否均向下→是则为室速；②V4-V6主波均向下→室速；③任一胸前导联RS间期（R起点至S最低点）>100ms→室速（注意排除抗心律失常药物影响）；④是否存在房室分离或室房传导阻滞→室速；再看V1导联QRS形态（RBBB型V1主波向上、LBBB型主波向下）。以上均不符合则诊断室上速伴差传。"],"infusion":["血流动力学不稳定的宽QRS心动过速立即同步电复律；稳定者可试用抗心律失常药。"],"oral_medication":["稳定者血流动力学可维持时可选用胺碘酮等，暂不口服。"],"treatment":["1.宽QRS心动过速且节律齐：有基础心脏病者一律按室速处理——首选同步电复律（不稳定时）；稳定者可予胺碘酮150mg加入适量液体缓慢静推（10分钟），继以1mg/min静滴6小时、0.5mg/min维持，或利多卡因1-1.5mg/kg静推；禁止对不能除外室速者使用腺苷以外的房室结阻滞药作为试验治疗（维拉帕米可致室速血流动力学崩溃）；2.宽QRS且节律不齐：多为室颤、多形性室速或房颤伴预激——房颤伴预激不能用房室结阻滞剂（腺苷、β阻滞剂、洋地黄），可予普罗帕酮、胺碘酮或同步电复律；3.纠正缺血与电解质紊乱（尤其低钾低镁）；QT延长伴尖端扭转性室速：停用延长QT药物、补镁（硫酸镁2g静推）、必要时超速起搏；4.病因处理（急性心梗、心肌病、电解质、药物中毒），治疗后复查心电图。"],"management":["入监护病房监护，反复复查心电图，动态观察QRS变化；记录每次发作；准备除颤仪；请心内科/总住院医师。"],"notes":["无脉性室速等同室颤处理；宽QRS心动过速中90%以上为室速，宁可先按室速处理；洋地黄中毒致室速禁用电复律（可加重），宜补钾补镁并用利多卡因/苯妥英钠；注意房颤伴预激禁用房室结阻滞剂。"],"emergency":["意识丧失/无脉→立即CPR+非同步电除颤（按心脏骤停流程）；低血压休克→同步电复律；多形性室速反复发作→呼叫上级并予胺碘酮、补镁。"],"pinyin":"kuanQRSboxindongguosujianbiechuliliucheng","icd10":"I49.9","physical_exam":"立即评估意识与生命体征；听诊心率心律、颈静脉搏动（房室分离时可见大炮波）；观察低灌注体征。","lab_tests":"电解质（钾镁）、血气、肌钙蛋白、心电图动态对比；必要时查药物浓度（洋地黄）。","nursing":"持续心电血压监护，除颤仪备用；记录发作持续时间与用药；防跌倒（晕厥风险）；安抚病人。","diet":"急性期暂禁食；原发心脏病饮食管理（限盐、戒烟酒咖啡）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1200},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"47e311528fd09e9a4c699b7209806a83be2f15367dc09cb4e124d239f10378dc","pinyin":"kuanQRSboxindongguosujianbiechuliliucheng","initials":"kQbxdgsjbcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","心悸、头晕、黑矇、胸痛、呼吸困难，可突发晕厥或心脏骤停；血流动力学可迅速恶化。",60],["摘要","QRS波时限≥0.12s的快速心律失常：对基础心脏病人出现宽QRS心动过速应先假定为室速处理直至排除；按节律齐否分流，齐者按Brugada标准鉴别室速与室上速伴差传，不齐者考虑室颤、多形性室速或房颤伴预激。",30],["疾病编码","I49.9",30],["原首字母","kuanQRSboxindongguosujianbiechuliliucheng",60]]},{"id":"orders-879b3e915a4606e9cb2e","key":"v1-c9ccc21dfe2a3058|orders-879b3e915a4606e9cb2e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"高血压急症与次急症处理流程","category":"夜班急症流程","raw":{"name":"高血压急症与次急症处理流程","category":"夜班急症流程","summary":"血压显著升高伴或不伴急性靶器官损害时的分类处理：高血压急症（血压显著升高合并急性靶器官损害）需住院静脉降压，高血压次急症（多>200/120mmHg但无严重靶器官损害）可口服药降压。","symptoms":["血压明显升高，可伴头痛、视物模糊、意识改变（卒中）、胸痛、呼吸困难、心悸；脑、心、肾靶器官损害表现。"],"diagnosis":["多次规范测量血压确认升高；分急症/次急症：急症=血压急剧升高伴急性靶器官损害（高血压脑病、脑卒中、急性心衰肺水肿、ACS、主动脉夹层、急性肾损伤、子痫等）；次急症=血压>200/120mmHg但无严重靶器官损害；查体注意双上肢血压、神经系统、眼底（视乳头水肿、火焰状出血）、心肺（奔马律、啰音）、肾（少尿水肿血尿）。"],"infusion":["高血压急症予静脉降压：常用硝普钠（0.5-2μg/(kg·min)避光泵入）、硝酸甘油（起始5-10μg/min）、乌拉地尔（压宁定，10-50mg静推后泵入）、尼莫地平（蛛网膜下腔出血时0.5mg/h起可增至2mg/h）；伴左心衰首选硝普钠或硝酸甘油；急性心梗用β阻滞剂与硝酸酯。"],"oral_medication":["次急症可口服联合降压：卡托普利6.25-25mg tid（用药前注意血钾血肌酐与过敏史）、美托洛尔12.5-25mg bid等；避免短效硝苯地平口服或舌下含服（可能增加不良事件）。"],"treatment":["1.判断是否为高血压急症，检查有无脑、心、肾、眼底靶器官损害（卒中、脑病、急性心衰、ACS、主动脉夹层、肾衰竭）；2.次急症：不必急诊大幅降压，可口服药物（如氨氯地平 5mg qd、缬沙坦 80mg qd）并观察，多数无需住院；3.急症：收住院，心电血压监护，静脉给药降压（乌拉地尔 12.5-25mg 静推后 5-40mg/h 泵入，或尼卡地平 5mg/h 起泵入）——最初1-2小时血压下降不超过最高值的25%，2-6小时内降至并稳定于160/100mmHg左右；过快过度降压可加重脑/心肌缺血；4.特殊情形：急性缺血性卒中血压<180/110mmHg可暂不降压（过度降压不利脑灌注），避免硝普钠/硝酸甘油（升高颅内压），脑出血与蛛网膜下腔出血可用尼莫地平 60mg q4h 口服或 1-2mg/h 静滴；主动脉夹层首选艾司洛尔（β阻滞剂）0.5mg/kg 静推后 50-200μg/kg/min 泵入，顽固高血压可加用硝普钠 0.25-0.5μg/kg/min 泵入但需警惕增加主动脉剪切力；硬皮病肾危象用ACEI（卡托普利 6.25-25mg 口服）并监测肾功能血钾；嗜铬细胞瘤先用α阻滞剂（酚妥拉明 1-5mg 静推/酚苄明 10mg bid 口服）再用β阻滞剂；妊娠高血压以肼屈嗪 5-10mg 静推 q20min、拉贝洛尔 20-80mg 静推 q10min 一线。"],"management":["持续血压监测（每5-15分钟），按目标逐步调整泵速；记录出入量、神志、尿量；请心内科/专科会诊；防止低血压。"],"notes":["区分急症与次急症是关键，次急症切勿过度快速降压；避免短效二氢吡啶类（如硝苯地平）用于紧急降压；夹层与脑卒中降压策略相反需鉴别清楚；使用硝普钠避光并警惕氰化物蓄积。"],"emergency":["高血压急症伴脑卒中、主动脉夹层、急性心衰、ACS、子痫时应按相应流程急救并尽快静脉降压；血压骤降或意识恶化立即调整方案。"],"pinyin":"gaoxueyajizhengyucijizhengchuliliucheng","icd10":"I10","physical_exam":"双上肢血压对比、神志瞳孔、眼底、心肺听诊、腹部血管杂音、周围动脉搏动、尿量。","lab_tests":"血常规、电解质、肌酐尿素氮、心肌酶肌钙蛋白、尿常规；心电图、胸片，必要时头颅CT/CTA（疑脑出血或夹层）。","nursing":"安静环境，减少刺激；严格卧床；持续心电血压监护，记录降压过程；观察头痛、呕吐、肢体无力等变化。","diet":"低盐低脂饮食；意识障碍者禁食水并防误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1201},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7ff346357b5162774701da3eb8298f4c124b948bf909421658dadf17cc466bbd","pinyin":"gaoxueyajizhengyucijizhengchuliliucheng","initials":"gxyjzycjzcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","血压明显升高，可伴头痛、视物模糊、意识改变（卒中）、胸痛、呼吸困难、心悸；脑、心、肾靶器官损害表现。",60],["摘要","血压显著升高伴或不伴急性靶器官损害时的分类处理：高血压急症（血压显著升高合并急性靶器官损害）需住院静脉降压，高血压次急症（多>200/120mmHg但无严重靶器官损害）可口服药降压。",30],["疾病编码","I10",30],["原首字母","gaoxueyajizhengyucijizhengchuliliucheng",60]]},{"id":"orders-fe18aedfed442c9b00ae","key":"v1-c9ccc21dfe2a3058|orders-fe18aedfed442c9b00ae","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性左心衰处理流程","category":"夜班急症流程","raw":{"name":"急性左心衰处理流程","category":"夜班急症流程","summary":"突发严重呼吸困难、端坐呼吸、咳粉红色泡沫样痰为主的急性左心功能衰竭（含输液过快所致急性肺水肿）的紧急处理流程。","symptoms":["突发严重呼吸困难、端坐呼吸、呼吸频率30-40次/分，咳嗽、咳粉红色泡沫样痰，大汗、面色苍白或紫绀，四肢湿冷，血压可下降或升高，双肺广泛湿啰音。"],"diagnosis":["根据典型症状体征诊断：端坐呼吸、双肺满布湿啰音、奔马律；鉴别急性肺水肿是否由输液过快、容量负荷过重引起（输液后突发）；明确基础心脏病（缺血性、高血压性、瓣膜病等）；查脑钠肽（BNP/NT-proBNP）、心肌酶肌钙蛋白、心电图、胸片（肺淤血/肺水肿）。"],"infusion":["呋塞米20-40mg缓慢静推（根据尿量与容量状态，可重复）；急性肺水肿伴血压高者可予硝酸甘油静滴/泵入扩血管（起始5-10μg/min）；血压低、心源性休克时慎用扩血管、加用正性肌力药（多巴酚丁胺、去甲肾上腺素），吗啡2-5mg缓慢静注（呼吸抑制者慎用）。"],"oral_medication":["病情稳定后继续口服利尿剂、ACEI/ARB、β阻滞剂（稳定后）等心衰药物（急性期以静脉为主）。"],"treatment":["1.端坐位或半坐卧位，双腿下垂，减少回心血量；2.高流量吸氧，可用酒精湿化（抗泡沫）；血氧仍低或CO2潴留者考虑无创通气（CPAP/BiPAP），必要时气管插管；3.建立静脉通路、心电血氧监护，准备抢救器材；4.利尿：呋塞米 20-40mg 静脉推注（先利尿减少前负荷）；5.扩血管：血压偏高或正常者用硝酸甘油 5-10μg/min 起泵入/硝普钠 0.3-0.5μg/kg/min 泵入减轻前后负荷（血压偏低者避免）；6.必要时镇静：吗啡 3-5mg 静推（注意呼吸抑制）；7.正性肌力：低血压或灌注不足者用多巴酚丁胺 2.5-10μg/kg/min、去甲肾上腺素 0.05-0.5μg/kg/min 泵入等；8.如由快速心律失常诱发，控制心室率或电复律；由急性心肌梗死诱发者按ACS处理并考虑再灌注；9.必要时四肢轮流缚扎止血带减少回心血量（现在多被无创通气替代）；10.严格控制输液速度，去除诱因（感染、心律失常、钠水负荷等）。"],"management":["严密监测血压、呼吸、血氧、心率心律、尿量、肺部啰音变化；记录24小时出入量；血气动态复查；病情重者转ICU。"],"notes":["输液相关的急性肺水肿应即刻停止输液并保留静脉通道；急性期禁用或慎用β受体阻滞剂与钙通道阻滞剂（负性肌力）；吗啡禁用于昏迷、严重呼吸抑制、COPD急性加重患者；利尿剂用量需依据血压与肾功能个体化。"],"emergency":["严重低氧、呼吸衰竭、心源性休克、意识障碍时立即准备气管插管机械通气并呼救；无脉性心脏骤停按CPR流程。"],"pinyin":"jixingzuoxinshuaichuliliucheng","icd10":"I50.1","physical_exam":"神志、血压、心率心律、呼吸频率与氧饱和度、颈静脉怒张、双肺啰音分布、下肢水肿、肢端温度。","lab_tests":"血气分析、BNP/NT-proBNP、心肌损伤标志物、电解质、肾功能、血常规；床旁心电图、胸片、超声心动图（有条件）。","nursing":"协助半卧位、双腿下垂；吸氧湿化；吸痰保持气道通畅；观察痰液颜色性状量、肺部体征；记录出入量，控制输液速度；稳定情绪。","diet":"急性期暂禁食或少量流质；稳定后严格限钠（每日<2-3g盐）、限水（量出为入），避免饱餐。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1202},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ff84ecc524cddb1995d7f2a0bcbbdac2c5c0abf82ec31fbcf5fd3a6540e9129c","pinyin":"jixingzuoxinshuaichuliliucheng","initials":"jxzxscllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发严重呼吸困难、端坐呼吸、呼吸频率30-40次/分，咳嗽、咳粉红色泡沫样痰，大汗、面色苍白或紫绀，四肢湿冷，血压可下降或升高，双肺广泛湿啰音。",60],["摘要","突发严重呼吸困难、端坐呼吸、咳粉红色泡沫样痰为主的急性左心功能衰竭（含输液过快所致急性肺水肿）的紧急处理流程。",30],["疾病编码","I50.1",30],["原首字母","jixingzuoxinshuaichuliliucheng",60]]},{"id":"orders-3fe02bd33cba646158bd","key":"v1-c9ccc21dfe2a3058|orders-3fe02bd33cba646158bd","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"消化道大出血处理流程","category":"夜班急症流程","raw":{"name":"消化道大出血处理流程","category":"夜班急症流程","summary":"呕血、黑便等消化道大出血（含消化性溃疡出血与肝硬化食管胃底静脉曲张破裂出血）的紧急评估与处理：评估出血量与休克程度、复苏补液输血、药物止血、急诊内镜或三腔二囊管、手术准备。","symptoms":["呕血、黑便（可伴鲜血便）、面色苍白、皮肤湿冷、心率加快、血压下降、头晕心悸乏力口渴，活动性出血者可有腹痛腹胀、肠鸣音亢进；严重者休克。"],"diagnosis":["根据呕血/黑便及失血表现诊断消化道出血；评估出血量（轻度失血心率略快血压正常；大量出血出现血压下降、脉压减小、尿少）；病因鉴别：消化性溃疡（最常见，多有溃疡病史）、肝硬化门脉高压静脉曲张（肝病面容、腹水、脾大）、急性胃黏膜病变、肿瘤等；查血红蛋白动态下降、尿素氮肌酐比值升高提示上消化道出血；必要时急诊内镜明确并止血。"],"infusion":["建立两条以上大口径静脉通道，快速补液（平衡液、生理盐水），备血输血（Hb<70g/L或失血性休克者输红细胞，注意新鲜冰冻血浆与血小板按需）；活动性出血时：奥美拉唑/艾司奥美拉唑80mg静推后8mg/h泵入，或泮托拉唑80mg静滴q12h（抑制胃酸）；疑静脉曲张出血：生长抑素首剂250μg静推后250μg/h泵入（或奥曲肽首剂50-100μg静推后25-50μg/h），同时用PPI；可加用去甲肾上腺素8mg+NS 500ml口服/胃管注入（局部收缩血管）；凝血酶等局部止血药。"],"oral_medication":["急性期禁食；稳定后口服PPI序贯治疗溃疡；静脉曲张出血禁口服药物期后按肝病用药。"],"treatment":["1.评估并维持生命体征：平卧、头偏向一侧防误吸，吸氧，心电监护；判断休克程度，快速补液输血；2.禁食水，留置胃管（观察出血并冲洗，疑静脉曲张者置管操作轻柔）；3.药物止血：消化性溃疡出血用PPI静脉强化（奥美拉唑 80mg 静推后 8mg/h 泵入，使胃内pH>6利于止血）+必要时生长抑素类；疑静脉曲张破裂出血尽早用血管加压素类似物/生长抑素（奥曲肽 50μg 静推后 50μg/h 泵入 或 生长抑素 250μg 静推后 250μg/h 泵入）+PPI+抗生素预防（肝硬化出血者，如头孢曲松 1g qd 静滴）；4.争取急诊内镜下止血（12-24小时内，活动性大出血尽早）：溃疡出血行电凝/夹闭/注射，静脉曲张行套扎或硬化；5.气囊压迫：静脉曲张出血药物内镜不能控制者用三腔二囊管压迫（明确适应证、专人管理）；6.TIPS或外科手术备选；7.处理诱因与并发症：停用抗凝抗血小板（评估血栓风险），纠正凝血异常，防肝性脑病（乳果糖 15-30ml 口服 bid-tid），密切监测。"],"management":["重症监护：生命体征、呕血黑便量色、肠鸣音、胃管引流、出入量、Hb动态；每30分钟-1小时评估；呼叫消化科/内镜中心、备好三腔二囊管；必要时输血与手术。"],"notes":["静脉曲张出血患者三腔二囊管需定时放气防黏膜坏死并防窒息；PPI大剂量泵入才足以稳定血栓；肝硬化出血者用抗生素可降再出血与感染风险；停用抗血小板抗凝需与心脑血管风险权衡并记录。"],"emergency":["失血性休克、持续活动性出血、血红蛋白进行性下降、呕血不止时立即快速输血补液并呼叫上级，准备急诊内镜/介入/手术。"],"pinyin":"xiaohuadaodachuxuechuliliucheng","icd10":"K92.2","physical_exam":"生命体征（休克指数）、神志、皮肤黏膜色泽与弹性、肠鸣音、腹部压痛；肝硬化者注意肝掌、蜘蛛痣、腹水、脾大。","lab_tests":"血常规（动态Hb/Hct）、凝血功能、肝肾功能电解质、血型与交叉配血、感染筛查（备输血）；必要时血气。","nursing":"绝对卧床、头偏向一侧防误吸窒息；监测生命体征与尿量；观察并记录呕血黑便量、颜色、性状；胃管护理；口腔清洁；防压疮；及时清理呕吐物并安抚。","diet":"急性大出血禁食水；出血停止24-48小时后无再出血可渐进温凉流质→半流质；静脉曲张出血者低盐软食避免粗糙食物；避免辛辣、过烫食物。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1203},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c7df82e2eeecd8399c34604e86d3390dd70e7becb28a1f375d8174cef350710b","pinyin":"xiaohuadaodachuxuechuliliucheng","initials":"xhddcxcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呕血、黑便（可伴鲜血便）、面色苍白、皮肤湿冷、心率加快、血压下降、头晕心悸乏力口渴，活动性出血者可有腹痛腹胀、肠鸣音亢进；严重者休克。",60],["摘要","呕血、黑便等消化道大出血（含消化性溃疡出血与肝硬化食管胃底静脉曲张破裂出血）的紧急评估与处理：评估出血量与休克程度、复苏补液输血、药物止血、急诊内镜或三腔二囊管、手术准备。",30],["疾病编码","K92.2",30],["原首字母","xiaohuadaodachuxuechuliliucheng",60]]},{"id":"orders-59a1b8b0fcc534e3eb5a","key":"v1-c9ccc21dfe2a3058|orders-59a1b8b0fcc534e3eb5a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖尿病酮症酸中毒处理流程","category":"夜班急症流程","raw":{"name":"糖尿病酮症酸中毒处理流程","category":"夜班急症流程","summary":"糖尿病（多为1型或应激状态）胰岛素严重缺乏所致高血糖、高酮血症与代谢性酸中毒的急诊处理：补液为首要，小剂量胰岛素持续静滴，纠正电解质紊乱，处理诱因与并发症。","symptoms":["口渴、多尿、恶心呕吐、厌食、腹痛，皮肤失水干燥，呼吸深快（Kussmaul），呼气有烂苹果味，脉搏细速、血压下降，嗜睡甚至昏迷；常有感染、胰岛素中断、手术应激等诱因。"],"diagnosis":["血糖明显升高（多16.7-33.3mmol/L）、血酮体显著升高、血pH降低、二氧化碳结合力下降，尿酮阳性；结合糖尿病史与诱因确诊；需监测血钠钾氯、渗透压、血气。"],"infusion":["补液：最初1-2小时快速输注生理盐水1000-1500ml（无休克者约15-20ml/(kg·h)），总量按体重10%估算；血糖降至13.9mmol/L左右改用5%葡萄糖+胰岛素继续滴注；低血压休克者可用胶体；胰岛素：小剂量持续静滴0.1U/(kg·h)（或按血糖调节），血糖下降速度约3-5mmol/L/h，避免过快；补钾：尿量>30ml/h且血钾<5.5mmol/L即开始补钾（可予10%氯化钾加入液体，监测心电图）。"],"oral_medication":["神志清醒、呕吐停止后可过渡皮下胰岛素与口服补液；酮症纠正前暂以静脉为主。"],"treatment":["1.评估生命体征，昏迷或呕吐者防误吸，吸氧监护，建立静脉通路；2.补液是首要措施：先快后慢生理盐水扩容，纠正低血容量；3.小剂量胰岛素持续静滴降糖（同时抑制酮体生成）；血糖降至13.9mmol/L左右改为葡萄糖+胰岛素联合，防低血糖与脑水肿；4.纠正电解质与酸碱失衡：重点是补钾（随着胰岛素与补液血钾可骤降），血钾<3.3mmol/L应先补钾暂缓胰岛素；pH<6.9才考虑补碱（碳酸氢钠）；5.处理诱因：感染最常见，查感染灶并经验性抗生素；停用/调整可能诱因药物；6.防治并发症：脑水肿（儿童与重度者警惕，避免血糖下降过快）、低血糖、低钾、血栓、急性肾损伤；7.意识清醒鼓励饮水；昏迷者留置胃管防误吸。"],"management":["入抢救室或ICU密切监护：每小时血糖，每2-4小时电解质血气，记录出入量与尿量；心电监护观察钾相关心律失常；病情稳定后转普通病房调整胰岛素方案并病因管理。"],"notes":["补液与胰岛素同样重要，先补液再足量胰岛素；血钾未补足前勿用碱性液；血糖不可降得过快（防脑水肿）；排除急性胰腺炎、急腹症、心肌梗死等诱因；老年与肾功能不全者补液量与速度个体化。"],"emergency":["休克、意识障碍进行性加重、严重低钾/高钾、疑脑水肿或心梗等并发症时立即呼救并强化监护处理。"],"pinyin":"tangniaobingtongzhengsuanzhongduchuliliucheng","icd10":"E11.1","physical_exam":"神志、皮肤黏膜弹性、呼吸频率与深度、呼气气味、脉搏血压、腹部体征（排除急腹症）、脱水体征。","lab_tests":"血气、血糖（每小时）、血酮/尿酮、电解质（钾钠氯，每2-4小时）、肾功能、渗透压、血常规、感染相关检查、心电图（钾相关）、淀粉酶（腹痛时）。","nursing":"记录出入量与每小时尿量；监测血糖、神志瞳孔、生命体征；皮肤口腔护理（脱水干燥）；昏迷者防误吸压疮；输液泵控制滴速。","diet":"酮症纠正后由流质过渡；恢复期按糖尿病饮食管理，控制糖摄入。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1204},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"505d800366e6875d656835cf482d2af37fb4282096316202747465eed1d2d6d3","pinyin":"tangniaobingtongzhengsuanzhongduchuliliucheng","initials":"tnbtzszdcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口渴、多尿、恶心呕吐、厌食、腹痛，皮肤失水干燥，呼吸深快（Kussmaul），呼气有烂苹果味，脉搏细速、血压下降，嗜睡甚至昏迷；常有感染、胰岛素中断、手术应激等诱因。",60],["摘要","糖尿病（多为1型或应激状态）胰岛素严重缺乏所致高血糖、高酮血症与代谢性酸中毒的急诊处理：补液为首要，小剂量胰岛素持续静滴，纠正电解质紊乱，处理诱因与并发症。",30],["疾病编码","E11.1",30],["原首字母","tangniaobingtongzhengsuanzhongduchuliliucheng",60]]},{"id":"orders-bdcb0513abde7f0e6a16","key":"v1-c9ccc21dfe2a3058|orders-bdcb0513abde7f0e6a16","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"高渗高血糖状态处理流程","category":"夜班急症流程","raw":{"name":"高渗高血糖状态处理流程","category":"夜班急症流程","summary":"以严重高血糖、血浆高渗透压、脱水而无明显酮症酸中毒为特征的糖尿病急性并发症（多发生于2型糖尿病老年患者），处理核心是积极补液、小剂量胰岛素、纠正电解质与处理诱因。","symptoms":["进行性脱水（口渴、皮肤黏膜干燥、眼窝凹陷）、嗜睡、幻觉、震颤、抽搐甚至昏迷；血糖多>33.3mmol/L，血浆渗透压>320mOsm/L，血钠正常或显著增高；常无明显深大呼吸与烂苹果味。"],"diagnosis":["血糖显著升高（>33.3mmol/L）、有效血浆渗透压>320mOsm/L、血酮体不高或轻度升高、尿酮阴性或弱阳性；血钠多升高；常有感染、心脑血管事件、糖皮质激素等诱因，老年人多见；排除脑卒中与其它昏迷原因（查头颅CT）。"],"infusion":["补液：首选生理盐水，最初1-2小时1000-2000ml快速输注（有心衰者减量并监测）；当血钠>150mmol/L或渗透压极高时可用0.45%低渗盐水（需警惕脑水肿）；休克者先快速补液或用胶体；血糖降至13.9-16.7mmol/L后改用5%葡萄糖并继续胰岛素；胰岛素：小剂量持续静滴0.1U/(kg·h)。"],"oral_medication":["神志恢复、能进食后逐渐过渡口服降糖药与皮下胰岛素方案（原降糖药需重新评估）。"],"treatment":["1.监测生命体征并评估脱水量，建立两条静脉通道；2.补液量通常较DKA更大，前12小时补总量的50%左右；纠正低血压休克；3.小剂量胰岛素持续滴注，血糖下降至约13.9-16.7mmol/L时加用葡萄糖，避免血糖降太快致脑水肿；4.电解质：按需补钾（开始补液和胰岛素后血钾下降，尿量充足即补），低磷血症按需补充；5.治疗诱因与基础病：感染、心肌梗死、脑卒中、创伤、药物（激素/利尿/噻嗪类）等；6.深静脉血栓预防（高渗脱水易栓）；7.意识障碍者防误吸，必要时留置胃管/导尿。"],"management":["密切监测神志、血糖、渗透压、电解质、出入量与尿量；老年人心肺功能差者密切观察心衰肺水肿；稳定后转内科调整长期降糖方案。"],"notes":["老年人更易出现医源性液体过负荷与心衰，补液速度个体化；低渗盐水补液过快可诱发脑水肿与溶血；本症酮症较轻，勿大剂量补碱；纠正速度宜平稳（血钠每小时下降不宜过快）。"],"emergency":["昏迷、休克、严重电解质紊乱、惊厥持续或疑脑水肿/脑卒中时按相应急症处理并呼救。"],"pinyin":"gaoshengaoxuetangzhuangtaichuliliucheng","icd10":"E11.0","physical_exam":"神志、脱水程度、血压脉搏、皮肤弹性、神经系统检查（局灶体征提示卒中）、心肺腹部（诱因感染灶）。","lab_tests":"血糖（每小时）、血浆渗透压（计算或实测）、电解质（钠钾氯）每2-4小时、血气、肾功能、血常规、尿常规、心电图；诱因相关检查（血培养、胸片等）。","nursing":"严格记录出入量与每小时尿量；监测血糖渗透压电解质；皮肤黏膜护理防干燥破损；昏迷防误吸压疮；心电监护观察心律失常。","diet":"能进食后由流质渐进；按糖尿病饮食长期管理。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1205},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d2c94595f01b1fb0385cb600abb691b94a57691f202fb86d00d81b8541b672e7","pinyin":"gaoshengaoxuetangzhuangtaichuliliucheng","initials":"gsgxtztcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","进行性脱水（口渴、皮肤黏膜干燥、眼窝凹陷）、嗜睡、幻觉、震颤、抽搐甚至昏迷；血糖多>33.3mmol/L，血浆渗透压>320mOsm/L，血钠正常或显著增高；常无明显深大呼吸与烂苹果味。",60],["摘要","以严重高血糖、血浆高渗透压、脱水而无明显酮症酸中毒为特征的糖尿病急性并发症（多发生于2型糖尿病老年患者），处理核心是积极补液、小剂量胰岛素、纠正电解质与处理诱因。",30],["疾病编码","E11.0",30],["原首字母","gaoshengaoxuetangzhuangtaichuliliucheng",60]]},{"id":"orders-ee36c10f4e1e79a4172c","key":"v1-c9ccc21dfe2a3058|orders-ee36c10f4e1e79a4172c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"哮喘急性发作处理流程","category":"夜班急症流程","raw":{"name":"哮喘急性发作处理流程","category":"夜班急症流程","summary":"支气管哮喘急性加重的分级评估与处理：反复吸入速效β2受体激动剂为首要，联合糖皮质激素（吸入/全身），根据严重程度（轻中重危重）升级治疗并决定住院或转ICU。","symptoms":["发作性呼气性呼吸困难、喘息、咳嗽、胸闷；呼气相延长伴广泛哮鸣音；严重者端坐呼吸、言语断续、大汗、发绀、意识改变；夜间发作更需警惕。"],"diagnosis":["根据反复发作史与体征诊断；客观评估严重度：轻（活动后气短、PEF>80%预计值）、中（说话断续、PEF60%-80%）、重（静息气短、端坐、单字表达、PEF<60%）、危重（嗜睡昏迷、胸腹矛盾运动、哮鸣音减弱或消失、PEF<33%）；哮鸣音消失伴呼吸费力提示濒危。"],"infusion":["重度发作需静脉给药：甲泼尼龙40-80mg静推或静滴（可重复，每6-8小时）或氢化可的松琥珀酸钠100-200mg；硫酸镁1-2g加入液体静滴（30分钟以上，重症可改善肺功能）；氧疗（目标SpO2 93%-95%）。"],"oral_medication":["吸入速效β2受体激动剂（沙丁胺醇气雾剂/雾化2.5-5mg或按需）为首选，可重复（第1小时每20分钟）；口服或吸入糖皮质激素早期使用；茶碱类（氨茶碱0.25g+液体缓慢静滴，需监测浓度）用于重症或β2激动剂无效时。"],"treatment":["1.评估严重程度分级；2.轻中度：反复吸入β2激动剂（沙丁胺醇 100-200μg 定量吸入 q20min×3次，或雾化 2.5-5mg）+口服/吸入激素（泼尼松 30-50mg qd 口服 或 布地奈德 400-800μg bid 吸入）+氧疗，观察反应；3.重度：氧疗+反复雾化β2激动剂（沙丁胺醇 2.5-5mg 雾化 q20min×3次，必要时加用异丙托溴铵 0.5mg 雾化）+全身糖皮质激素（静推甲泼尼龙 40-80mg q6-12h 或氢化可的松 100-200mg q6h）+镁剂静脉（硫酸镁 2g 静滴 20分钟），监测血气；4.危重：上述基础上考虑无创/有创通气，准备气管插管；β2激动剂持续雾化（沙丁胺醇 10-20mg/h），呼救与转ICU；5.祛除诱因（过敏原、感染、阿司匹林/NSAIDs、β阻滞剂等），停止诱发药物；6.治疗无效或出现气胸等并发症及时处理并请专科；7.缓解期哮喘教育与长期控制药物（ICS+LABA，如布地奈德/福莫特罗 160/4.5μg 吸入 bid）方案调整。"],"management":["密切监测神志、SpO2、PEF、血气变化；发作未缓解每小时评估；病情重或反复发作者住院；出院前制定书面行动计划与复诊安排。"],"notes":["哮鸣音突然消失伴呼吸费力是濒危征兆而非好转；β2激动剂用量不足是常见错误，需反复足量吸入；避免镇静剂抑制呼吸；心源性哮喘（心衰）鉴别可查BNP；合并COPD者避免高浓度氧（防CO2潴留，目标SpO2 88%-92%）。"],"emergency":["意识障碍、寂静胸、发绀、CO2潴留、PEF<33%或进行性下降→立即呼救并准备机械通气；张力性气胸需紧急减压。"],"pinyin":"xiaochuanjixingfazuochuliliucheng","icd10":"J46","physical_exam":"神志、语态（成句/成词/单字）、呼吸频率与辅助呼吸肌使用、双肺哮鸣音分布及强弱、心率、血压、血氧饱和度、奇脉。","lab_tests":"血氧饱和度/血气分析（重症必查，注意CO2潴留提示病情极重）、血常规、电解质、PEF监测；胸片（排除气胸肺炎）；疑感染时炎症指标。","nursing":"协助半卧位；持续血氧监护；雾化吸入按医嘱执行并观察心慌手抖等副作用；鼓励深慢呼吸、勿用力咳痰；记出入量。","diet":"避免过敏与刺激食物，清淡易消化；鼓励多饮温水稀释痰液。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1206},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"26b7fbb43b9c0ceca648bf08ace79ec7a5e57820f8988d0fce08c552320f375f","pinyin":"xiaochuanjixingfazuochuliliucheng","initials":"xcjxfzcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发作性呼气性呼吸困难、喘息、咳嗽、胸闷；呼气相延长伴广泛哮鸣音；严重者端坐呼吸、言语断续、大汗、发绀、意识改变；夜间发作更需警惕。",60],["摘要","支气管哮喘急性加重的分级评估与处理：反复吸入速效β2受体激动剂为首要，联合糖皮质激素（吸入/全身），根据严重程度（轻中重危重）升级治疗并决定住院或转ICU。",30],["疾病编码","J46",30],["原首字母","xiaochuanjixingfazuochuliliucheng",60]]},{"id":"orders-b9fb9972cd4d852d120e","key":"v1-c9ccc21dfe2a3058|orders-b9fb9972cd4d852d120e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"COPD急性加重处理流程","category":"夜班急症流程","raw":{"name":"COPD急性加重处理流程","category":"夜班急症流程","summary":"慢阻肺患者咳痰喘症状急性加重的处理：评估严重度与呼吸衰竭风险，氧疗（目标SpO2 88%-92%）、支气管扩张剂雾化、糖皮质激素、抗生素（按指征），必要时无创通气。","symptoms":["原有呼吸困难、咳嗽、咳痰加重，痰量增多或脓性痰，可伴发热；重者端坐呼吸、辅助呼吸肌参与、神志改变（CO2潴留嗜睡）；多有感染、气候变化等诱因。"],"diagnosis":["根据病史（长期吸烟/慢性咳痰喘+气流受限史）与本次加重表现诊断；评估急性加重程度及呼吸衰竭（血气）；排除肺炎、气胸、心衰、肺栓塞等加重原因；查胸片、血气。"],"infusion":["氧疗（鼻导管或Venturi面罩，目标SpO2 88%-92%，警惕CO2潴留）；吸入短效β2激动剂（沙丁胺醇雾化）+短效抗胆碱药（异丙托溴铵雾化）可联合；重症加用全身激素：甲泼尼龙40mg静滴qd-q8h或泼尼松口服，疗程5-7天；静滴抗生素：按当地耐药与严重度选择，轻中度可用阿莫西林克拉维酸、二代/三代头孢、呼吸喹诺酮（左氧氟沙星/莫西沙星）口服或静滴；重症（有铜绿假单胞菌危险因素）用抗假单胞菌β内酰胺（哌拉西林他唑巴坦、头孢他啶）±氨基糖苷/环丙沙星；氨茶碱0.25g缓慢静滴（效果差时，注意监测）。"],"oral_medication":["稳定期维持吸入长效支气管扩张剂（LABA/LAMA）与ICS；急性加重期可短期口服泼尼松30-40mg/d并渐减，抗生素口服序贯；祛痰药（氨溴索等）辅助。"],"treatment":["1.评估严重度并吸氧（控制性氧疗目标SpO2 88%-92%）；2.支气管扩张剂：首选吸入短效β2激动剂+异丙托溴铵联合雾化（沙丁胺醇 2.5mg + 异丙托溴铵 0.5mg 雾化），每小时或持续；3.糖皮质激素：全身激素可缩短病程、改善肺功能，静推或口服（甲泼尼龙 40mg qd 静推 或 泼尼松 30-40mg qd 口服，疗程5-7天）；4.抗生素：仅在有脓痰或临床感染证据时使用，尽早经验性并降阶梯（如阿莫西林克拉维酸 0.625g tid 口服 或 左氧氟沙星 0.5g qd 静滴）；5.无创通气（BiPAP）：急性呼吸性酸中毒（pH<7.35）、严重呼吸困难但意识清醒者尽早使用；无效或意识障碍加重则气管插管有创通气；6.促进排痰（体位、拍背、祛痰药，如氨溴索 30mg tid 口服）；7.处理并发症与合并症（气胸、心衰、心律失常、肺栓塞），寻找诱因；8.营养支持与早期活动；9.恢复期评估并调整长期治疗方案、戒烟教育。"],"management":["密切监测血气、SpO2、神志与呼吸；无创通气者观察耐受与人机配合；病情重转呼吸科/ICU；记录痰量与性状。"],"notes":["COPD患者避免高浓度氧——FiO2过高可加重CO2潴留；镇静剂禁用或慎用；激素宜短程（5-7天）不需长期减量疗程；抗生素疗程5-7天，铜绿假单胞菌高危者需覆盖；出院前评估家庭氧疗与康复。"],"emergency":["意识障碍、pH<7.25、无创通气不耐受或失败、血流动力学不稳定→立即气管插管有创通气并呼救；张力性气胸紧急减压。"],"pinyin":"COPDjixingjiazhongchuliliucheng","icd10":"J44.1","physical_exam":"神志、呼吸频率、胸廓活动度与辅助呼吸肌、双肺呼吸音与干湿啰音、发绀、杵状指、下肢水肿（右心衰征象）、血氧。","lab_tests":"血气分析（判断呼吸衰竭类型）、血常规、CRP/PCT、痰培养（脓痰者）、胸片、电解质；疑PE查D-二聚体等。","nursing":"控制性氧疗并监测血气；雾化吸入指导（用后漱口）；拍背排痰；观察意识（CO2潴留最早表现神志改变）；无创通气面罩护理防面部压疮。","diet":"高蛋白高维生素易消化饮食，少量多餐；鼓励饮水稀释痰液；进食时抬高床头防误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1207},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e6d275fbab528f8e734d4486d06c0a6eda1e22f700c45c52c1f978d253f2dad0","pinyin":"COPDjixingjiazhongchuliliucheng","initials":"Cjxjzcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","原有呼吸困难、咳嗽、咳痰加重，痰量增多或脓性痰，可伴发热；重者端坐呼吸、辅助呼吸肌参与、神志改变（CO2潴留嗜睡）；多有感染、气候变化等诱因。",60],["摘要","慢阻肺患者咳痰喘症状急性加重的处理：评估严重度与呼吸衰竭风险，氧疗（目标SpO2 88%-92%）、支气管扩张剂雾化、糖皮质激素、抗生素（按指征），必要时无创通气。",30],["疾病编码","J44.1",30],["原首字母","COPDjixingjiazhongchuliliucheng",60]]},{"id":"orders-8aaf78e4297b8bd1341c","key":"v1-c9ccc21dfe2a3058|orders-8aaf78e4297b8bd1341c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肺栓塞处理流程","category":"夜班急症流程","raw":{"name":"肺栓塞处理流程","category":"夜班急症流程","summary":"怀疑肺栓塞患者的风险分层与处理：稳定者尽早抗凝，高危（血流动力学不稳定）者评估溶栓或介入/手术；鉴别呼吸困难与胸痛时要常规考虑肺栓塞（尤其卧床、术后、肿瘤、下肢深静脉血栓患者）。","symptoms":["突发呼吸困难、胸痛（可胸膜性）、咯血、晕厥、心悸；大块肺栓塞可突发休克、猝死；症状缺乏特异性，凡呼吸困难的住院/术后/肿瘤患者均应考虑肺栓塞。"],"diagnosis":["Wells评分等临床可能性评估；D-二聚体阴性可用于排除低-中度可能患者；确诊需CT肺动脉造影（CTA）或核素肺通气灌注显像；超声心动图发现右室扩大/功能不全提示高危；下肢静脉超声支持DVT；心电图（SⅠQⅢTⅢ、右束支等非特异）与血气（低氧低碳酸）仅作参考。"],"infusion":["高危肺栓塞（休克/持续低血压）：评估溶栓指征，无禁忌者尽早溶栓：阿替普酶100mg/2h静滴（或50mg/2h）；溶栓禁忌或失败者考虑导管介入或外科取栓；同时准备血管活性药（去甲肾上腺素）维持血压。"],"oral_medication":["抗凝治疗：低分子肝素皮下（按体重，肾功能不全者调整）或普通肝素静脉泵入（监测APTT），病情稳定后过渡口服华法林（与肝素重叠至INR达标2-3）或新型口服抗凝药（利伐沙班/达比加群等）；肿瘤患者首选低分子肝素。"],"treatment":["1.疑诊肺栓塞且血流动力学不稳定者：稳定生命体征，尽快确诊（床旁超声）并评估溶栓（阿替普酶 50-100mg 静滴 2小时），同时抗凝（肝素 80U/kg 静推后 18U/kg/h 泵入）；2.非高危：按临床可能性查D-二聚体/CTPA确诊后启动治疗性抗凝（依诺肝素 1mg/kg 皮下 q12h 或 利伐沙班 15mg bid 口服×21天）；3.危险分层决定强度与去向：高危（休克）→溶栓/介入或手术；中危（右室功能不全+肌钙蛋白升高）→抗凝+密切观察，病情恶化考虑补救溶栓；低危→抗凝，可门诊或短期住院；4.一般支持：吸氧、卧床、镇痛（吗啡 3-5mg 静推）、必要时血管活性药（去甲肾上腺素 0.05-0.5μg/kg/min 泵入）；5.治疗诱因：手术、骨折、肿瘤、妊娠、口服避孕药等；评估抗凝疗程（诱因性3个月，特发≥3-6个月或长期）；6.预防复发（滤器用于抗凝禁忌或复发）。"],"management":["高危者入ICU监护血压与右心功能；抗凝期间监测出血征象（黑便、血尿、颅内等）与INR/APTT；指导患者识别再发症状。"],"notes":["呼吸困难鉴别时勿漏肺栓塞——住院卧床、近期手术/骨折、肿瘤、深静脉血栓者是高危；D-二聚体仅用于排除低-中度可能；溶栓主要禁忌为活动性出血与近期大手术、卒中史等，需个体化评估；抗凝前评估出血风险。"],"emergency":["血压骤降、晕厥、心跳骤停（大块栓塞）立即抢救：CPR、液体复苏、溶栓或手术取栓并呼救。"],"pinyin":"feishuansaichuliliucheng","icd10":"I26.9","physical_exam":"生命体征（尤其血压——是风险分层核心）、呼吸急促、心动过速、右心衰体征（颈静脉怒张、P2亢进）、下肢不对称肿胀（DVT）、发绀。","lab_tests":"D-二聚体、血气、肌钙蛋白（心肌损伤提示预后差）、BNP/NT-proBNP、心电图、胸片、下肢静脉超声、CTPA；肾功能（造影前）。","nursing":"绝对卧床（急性期），避免突然活动致栓子再脱落；抬高患肢观察DVT侧肢体肿胀；监测生命体征与SpO2；抗凝期间观察皮肤黏膜出血；指导踝泵运动预防深静脉血栓。","diet":"抗凝期间饮食相对稳定（华法林注意富含维生素K食物如绿叶蔬菜不要骤变）；低盐低脂按基础病。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1208},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"008e6c1fe77bc754a519d9559907fcb5c98d8f347a23d403db02792b40aaea7b","pinyin":"feishuansechuliliucheng","initials":"fsscllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发呼吸困难、胸痛（可胸膜性）、咯血、晕厥、心悸；大块肺栓塞可突发休克、猝死；症状缺乏特异性，凡呼吸困难的住院/术后/肿瘤患者均应考虑肺栓塞。",60],["摘要","怀疑肺栓塞患者的风险分层与处理：稳定者尽早抗凝，高危（血流动力学不稳定）者评估溶栓或介入/手术；鉴别呼吸困难与胸痛时要常规考虑肺栓塞（尤其卧床、术后、肿瘤、下肢深静脉血栓患者）。",30],["疾病编码","I26.9",30],["原首字母","feishuansaichuliliucheng",60]]},{"id":"orders-d6650dce13ac108f4a85","key":"v1-c9ccc21dfe2a3058|orders-d6650dce13ac108f4a85","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性胰腺炎处理流程","category":"夜班急症流程","raw":{"name":"急性胰腺炎处理流程","category":"夜班急症流程","summary":"急性胰腺炎（胆源性、酒精性、高脂血症性等）的诊断与分级处理：早期液体复苏、疼痛管理、营养支持、器官功能支持，重症者识别与ICU管理。","symptoms":["持续性中上腹剧痛，可向腰背放射，弯腰抱膝位可减轻；伴恶心呕吐、腹胀、发热；重症出现烦躁、呼吸急促、少尿、休克表现；进食后加重。"],"diagnosis":["符合以下2条以上可诊断：典型上腹痛、血淀粉酶/脂肪酶>3倍正常上限、影像（CT/超声）符合胰腺炎表现；病因鉴别：胆石症（最常见，查肝功胆红素超声）、高甘油三酯血症（>11.3mmol/L易诱发）、酒精、药物、ERCP后等；严重度评估（改良CTSI、Ranson、APACHE-II）识别重症与器官衰竭。"],"infusion":["早期积极液体复苏：平衡液或生理盐水，前12-24小时按5-10ml/(kg·h)并根据心率血压尿量Hct调整（警惕液体过负荷），重症可5-10ml/kg快速冲击后调整；疼痛：布桂嗪、曲马多或盐酸哌替啶镇痛（吗啡可用但部分指南避免），必要时持续泵注；重症早期肠内营养（留置鼻胃/鼻空肠管）。"],"oral_medication":["轻症无呕吐者早期可尝试经口进食（低脂）缩短病程，或空肠营养；抑制胰酶分泌药物（生长抑素/奥曲肽）不改善预后不常规推荐；质子泵抑制剂用于应激性溃疡预防或合并溃疡者。"],"treatment":["1.监测生命体征与器官功能，评估严重度；2.液体复苏（核心）：纠正低血容量与灌注不足，动态评估（乳酸林格液 5-10ml/kg/h 起，早期目标导向）；3.镇痛（哌替啶 50-100mg 肌注 q4-6h 或 布桂嗪 100mg 肌注）；4.营养：重症尽早肠内营养（24-72小时），轻症可早期经口低脂流质，避免长期禁食；5.胆源性胰腺炎：合并胆管炎或胆道梗阻者尽早ERCP（24小时内），胆囊切除宜在出院前完成；6.高甘油三酯血症性胰腺炎：胰岛素+肝素降脂（胰岛素 0.1-0.3U/kg/h 泵入）或血浆置换（重度）并严格低脂；7.抗生素：不预防性用于所有患者，仅用于感染性坏死、胆管炎或明确感染灶（覆盖肠道菌群：碳青霉烯或三代头孢+甲硝唑等）；8.重症监护：ARDS机械通气（肺保护通气）、急性肾损伤CRRT、器官支持；9.处理并发症：胰腺坏死感染（延迟抗生素、介入引流或清创）、假性囊肿、腹腔高压、消化道出血等；10.防血栓（低分子肝素，如依诺肝素 40mg 皮下 qd）。"],"management":["重症者入ICU；每4-6小时评估器官功能与液体平衡；动态复查淀粉酶（诊断后不必反复）、CRP、血气、电解质、血糖；观察腹痛腹胀变化。"],"notes":["镇痛勿延误诊断与评估，但需排除其它外科急腹症；重症胰腺炎液体复苏过度可致腹高压，需量出为入；血淀粉酶不用于评估严重度；胆源性胰腺炎抗菌指征明确；出院前必须处理病因（切胆囊/降脂/戒酒）预防复发。"],"emergency":["休克、呼吸衰竭、少尿、意识改变提示重症胰腺炎并器官衰竭，立即转ICU综合救治；胆管炎高热黄疸按感染性休克处理并紧急ERCP。"],"pinyin":"jixingyixianyanchuliliucheng","icd10":"K85.9","physical_exam":"上腹压痛、反跳痛与肌紧张（重症）、肠鸣音减弱或消失（麻痹性肠梗阻）、Grey-Turner/Cullen征（出血坏死型少见）、发热、呼吸循环状态。","lab_tests":"血淀粉酶脂肪酶、血常规、CRP、肝肾功能、电解质（血钙低提示重症）、血糖、甘油三酯、血气（评估ARDS/酸中毒）、凝血功能；腹部超声（胆道病因）、增强CT（48-72小时后评估坏死）。","nursing":"半卧位减轻腹痛；记录出入量、中心静脉压、尿量；胃肠减压护理（呕吐腹胀重者）；监测血糖与电解质；防压疮与血栓；心理安抚。","diet":"早期可进食者低脂低刺激饮食，少量多餐；重症肠内营养；恢复期低脂，戒酒，避免暴饮暴食；高脂血症者严格低脂。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1209},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b6e15e5be3b2bb1ad8d7d0a39f9de86cbe19c8eabd8b68c88b982880f9c01404","pinyin":"jixingyixianyanchuliliucheng","initials":"jxyxycllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续性中上腹剧痛，可向腰背放射，弯腰抱膝位可减轻；伴恶心呕吐、腹胀、发热；重症出现烦躁、呼吸急促、少尿、休克表现；进食后加重。",60],["摘要","急性胰腺炎（胆源性、酒精性、高脂血症性等）的诊断与分级处理：早期液体复苏、疼痛管理、营养支持、器官功能支持，重症者识别与ICU管理。",30],["疾病编码","K85.9",30],["原首字母","jixingyixianyanchuliliucheng",60]]},{"id":"orders-62624fd4cbd2a866f58b","key":"v1-c9ccc21dfe2a3058|orders-62624fd4cbd2a866f58b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺危象处理流程","category":"夜班急症流程","raw":{"name":"甲状腺危象处理流程","category":"夜班急症流程","summary":"甲亢未控者在感染、手术、应激等诱因下发生的危及生命的甲亢急性加重，表现为高热、心动过速、烦躁、恶心呕吐、腹泻、意识障碍，需抗甲状腺药物、β受体阻滞剂、糖皮质激素等综合抢救。","symptoms":["发热（可>39℃）、明显心动过速或房颤、大汗、烦躁不安、谵妄甚至昏迷，恶心呕吐、腹痛腹泻、黄疸；可有心衰表现。"],"diagnosis":["临床诊断为主（结合Graves病史与诱因）；实验室支持：甲状腺功能FT3/FT4升高、TSH受抑，但危象为临床诊断不必等待化验；排除感染、嗜铬细胞瘤、恶性高热等发热心动过速病因。"],"infusion":["抗甲状腺药物（首选丙硫氧嘧啶PTU：首剂600mg口服/胃管，继200-250mg q6h，或甲巯咪唑首剂60mg后20mg q6h）；1小时后予碘剂（复方碘溶液5滴q6h或碘化钠1g静滴）抑制释放（碘剂必须在ATD后使用）；普萘洛尔20-40mg口服q4-6h或1mg缓慢静注（心衰者慎用并加洋地黄）；氢化可的松100mg静滴q8h或地塞米松；补液、降温、抗感染。"],"oral_medication":["PTU与甲巯咪唑口服/胃管给入是治疗核心之一；普萘洛尔口服控制心率。"],"treatment":["1.综合监护：吸氧、心电血压监护、降温（物理降温，慎用阿司匹林——可升高游离甲状腺激素）；2.抑制合成：ATD（PTU首选 600mg 口服或胃管注入，后 200mg q6h，因可抑制T4→T3转化）；3.抑制释放：ATD使用1小时后加碘剂（复方碘溶液 5-10滴 q6h 口服 或 碘化钠 500mg 静滴 q8h）；4.阻断外周效应：β受体阻滞剂（普萘洛尔 20-40mg q6h 口服 或 1-2mg 静推后 1-2mg/h），心衰者与洋地黄合用慎用β阻滞；5.糖皮质激素：氢化可的松 100mg 静滴 q8h/地塞米松 2mg 静推 q6h 抑制T4向T3转化并防肾上腺皮质功能相对不足；6.去除诱因：感染（抗生素）、控制血糖电解质、停用诱发药物（碘造影剂、胺碘酮等）；7.支持治疗：充分补液、纠正电解质与高血糖，处理心衰与心律失常（房颤控制心室率）；8.上述效果差或粒细胞缺乏不能服ATD者可考虑血浆置换；9.请内分泌科会诊。"],"management":["入ICU/监护病房密切监测体温心率血压神志；甲状腺功能动态复查；观察ATD粒细胞缺乏（咽喉痛发热时查血常规）；心衰者限制液体。"],"notes":["碘剂必须在抗甲状腺药物之后给（先抑制合成再抑制释放，否则反致激素蓄积加重）；阿司匹林升高游离甲状腺素应避免用于退热；β受体阻滞剂禁用于重度心衰者（需先控制心衰）；该病病死率高，宜尽早转入ICU综合救治。"],"emergency":["高热不退、意识障碍加重、心律失常（房颤快速心室率）、心衰休克时按相应急症处理并尽快请内分泌与ICU会诊。"],"pinyin":"jiazhuangxianweixiangchuliliucheng","icd10":"E05.5","physical_exam":"体温、心率心律、血压、神志、皮肤（温暖潮湿）、甲状腺肿大与血管杂音、眼征、心衰体征、腹部。","lab_tests":"甲状腺功能（FT3、FT4、TSH）、血常规、肝功能、电解质、血糖、血培养（感染诱因）、心电图、胸片。","nursing":"物理降温并监测体温；心电监护观察心率心律；观察神志与皮肤（大汗）；口腔护理；记录出入量；安抚患者。","diet":"高热量高蛋白高维生素、易消化饮食，保证能量；不能进食者鼻饲或静脉营养。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1210},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ff629c9fb8762af0b5d529b3cdee8ebb82f94fc267330d128b168550eb2346ce","pinyin":"jiazhuangxianweixiangchuliliucheng","initials":"jzxwxcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（可>39℃）、明显心动过速或房颤、大汗、烦躁不安、谵妄甚至昏迷，恶心呕吐、腹痛腹泻、黄疸；可有心衰表现。",60],["摘要","甲亢未控者在感染、手术、应激等诱因下发生的危及生命的甲亢急性加重，表现为高热、心动过速、烦躁、恶心呕吐、腹泻、意识障碍，需抗甲状腺药物、β受体阻滞剂、糖皮质激素等综合抢救。",30],["疾病编码","E05.5",30],["原首字母","jiazhuangxianweixiangchuliliucheng",60]]},{"id":"orders-1d86155be377e2e81a24","key":"v1-c9ccc21dfe2a3058|orders-1d86155be377e2e81a24","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肾上腺危象处理流程","category":"夜班急症流程","raw":{"name":"肾上腺危象处理流程","category":"夜班急症流程","summary":"肾上腺皮质功能不全（原发/继发，含长期激素治疗突然停药）在应激下出现的急性衰竭：低血压休克、低血糖、低钠高钾、恶心呕吐、意识障碍，核心治疗是及时补糖皮质激素、补液纠正休克。","symptoms":["乏力、恶心呕吐、腹痛腹泻、低血压甚至休克、低血糖表现（出汗心慌意识障碍）、发热或低体温、皮肤色素沉着（原发者）、意识模糊。"],"diagnosis":["临床紧急诊断为主，勿等化验：长期糖皮质激素治疗史（突然减停）、结核/自身免疫/肾上腺出血（抗凝治疗者）、垂体病变等背景，出现难以解释的低血压休克、低血糖、低钠高钾即考虑；查皮质醇与ACTH可确诊（不延误治疗）；血钠低血钾高、血糖低、嗜酸细胞可升高为线索。"],"infusion":["立即静脉氢化可的松：首剂100mg静推，继100mg加入液体每6-8小时滴注（首日300-500mg，稳定后渐减）；快速补液：生理盐水500-1000ml/h起步（心衰者调整），首日补液总量常需4-6L或更多；10%葡萄糖纠正低血糖（先于或同步给药）；高钾按需处理（补液激素常能纠正，勿常规给钙剂除非有心脏毒性）。"],"oral_medication":["稳定后改口服氢化可的松20-30mg/d（分次，晨起量大）或泼尼松+氟氢可的松（原发者0.05-0.1mg/d）。"],"treatment":["1.怀疑即处理：抽血（皮质醇、ACTH、电解质、血糖、血培养）后不等结果立即静推氢化可的松100mg并开始补液；2.纠正休克：快速补液为主，必要时加血管活性药（去甲肾上腺素），糖皮质激素起效后血压多回升；3.低血糖：静注50%葡萄糖40-60ml后持续滴注10%葡萄糖；4.纠正电解质：低钠随补液激素纠正，避免过快纠钠（防渗透性脱髓鞘）；高钾随补液、激素与血糖恢复多自行下降；5.寻找诱因：感染（经验抗生素）、手术创伤、腹泻脱水、停激素史等并处理；6.监测并防心衰（老年人补液适度）；7.危重者入ICU，请内分泌会诊。"],"management":["持续监测血压心率血糖电解质出入量；静脉激素按时间阶梯减量（首日300-500mg氢化可的松，第二日减半，逐日减至维持量）；教育患者终身激素替代与应激剂量（\"生病加倍\"原则）。"],"notes":["治疗不能等待确诊；勿因等待化验延误激素；使用氢化可的松（兼具盐皮质激素活性）优于单纯地塞米松；长期激素者任何手术感染应激需增加激素剂量并防突然停药诱发；原发者维持期需加氟氢可的松并教育急救用法。"],"emergency":["难治性休克、顽固低血糖、意识障碍、高钾致心电图改变或心律失常时立即强化处理并呼救。"],"pinyin":"shenshangxianweixiangchuliliucheng","icd10":"E27.2","physical_exam":"血压（休克）、皮肤黏膜色素、脱水体征、神志、体温、腹部（腹痛）与感染灶（诱因）。","lab_tests":"血糖（床旁）、电解质（钠钾氯）、肾功能、皮质醇与ACTH（治疗前抽血后即可给药）、血常规、血培养（感染）、心电图（高钾改变）。","nursing":"心电血压监护；监测血糖（每小时至稳定）与电解质；记录出入量；观察意识与肤色；防感染；向患者与家属宣教激素急救卡。","diet":"意识清醒者高盐高糖易消化饮食；低血糖者立即口服糖水；昏迷者禁食并防误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1211},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d25f60527f9c9b194cc8f255918791206aa787a1ccbb620ee8281b8a04f61ca9","pinyin":"shenshangxianweixiangchuliliucheng","initials":"ssxwxcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、恶心呕吐、腹痛腹泻、低血压甚至休克、低血糖表现（出汗心慌意识障碍）、发热或低体温、皮肤色素沉着（原发者）、意识模糊。",60],["摘要","肾上腺皮质功能不全（原发/继发，含长期激素治疗突然停药）在应激下出现的急性衰竭：低血压休克、低血糖、低钠高钾、恶心呕吐、意识障碍，核心治疗是及时补糖皮质激素、补液纠正休克。",30],["疾病编码","E27.2",30],["原首字母","shenshangxianweixiangchuliliucheng",60]]},{"id":"orders-8d3970097cf98c595729","key":"v1-c9ccc21dfe2a3058|orders-8d3970097cf98c595729","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"癫痫持续状态处理流程","category":"夜班急症流程","raw":{"name":"癫痫持续状态处理流程","category":"夜班急症流程","summary":"癫痫发作持续5分钟以上或两次发作间意识未恢复（SE）的紧急处理：保护气道与生命体征，按时间阶梯给予苯二氮䓬类、抗癫痫药，顽固者全麻治疗，并寻找病因。","symptoms":["持续或反复抽搐（全身强直阵挛最常见）、意识障碍不恢复，可伴发绀、咬舌、尿失禁；非惊厥性持续状态表现为持续意识模糊而无明显抽搐（更易漏诊）。"],"diagnosis":["临床诊断：持续抽搐>5分钟或反复发作间期意识未恢复；判断是否为新发（卒中、外伤、感染、代谢、中毒、停药/漏服抗癫痫药等）或已知癫痫患者诱因（漏服、感染、酒精戒断、睡眠剥夺）；查血糖、电解质、药物浓度、感染指标，疑结构性/血管病变者急查头颅CT；脑电图辅助（非惊厥性）。"],"infusion":["一线：地西泮10mg缓慢静推（2-5mg/min，儿童0.1-0.3mg/kg）可重复，或劳拉西泮2-4mg静推；二线：地西泮后仍未止→丙戊酸钠15-45mg/kg（负荷，10分钟内）静滴，或左乙拉西坦60mg/kg（负荷），或苯妥英钠18mg/kg静滴（心电监护）；难治性：咪达唑仑0.2mg/kg负荷后0.05-2mg/(kg·h)泵注，或丙泊酚2mg/kg负荷后泵注，多需气管插管机械通气并脑电监护；同时低血糖者先予50%葡萄糖+维生素B1（酒精者）。"],"oral_medication":["发作控制后过渡口服/胃管抗癫痫药维持，接诊前长期用药者恢复原方案并调整。"],"treatment":["1.立即评估：保护气道（侧卧、清理口咽、勿强压肢体），吸氧监护，建立静脉通路，床旁查血糖；2.低血糖（<3.9mmol/L）先纠正；3.按阶梯用药：苯二氮䓬（地西泮/劳拉西泮）一线→观察5分钟未止予第二剂→仍未止进入难治性阶段用静脉抗癫痫药（丙戊酸/左乙拉西坦/苯妥英）→再无效按超难治性处理（咪达唑仑或丙泊酚全麻，脑电监测）；4.寻找并治疗病因（电解质、感染、脑卒中、外伤、肿瘤、药物中毒/戒断等）；5.持续状态者多需ICU：气管插管指征（意识不能保护气道、呼吸抑制、难治性需全麻）；6.发作停止后评估神经系统（新局灶体征/持续意识障碍查脑电与影像）；7.防并发症（误吸肺炎、横纹肌溶解、高钾、脑水肿）；8.告知家属并请神经内科会诊。"],"management":["时间窗管理（每阶段限时）并记录；心电血氧监护；反复发作或非惊厥持续状态查脑电图；转神经科/ICU后续抗癫痫治疗与病因管理。"],"notes":["地西泮静注过快可致呼吸抑制，儿童尤其注意；勿在抽搐中强行撬口塞物；停用苯二氮䓬或丙泊酚时观察再发抽搐；苯妥英钠输注需心电监护并避免外渗；酒精戒断性发作需补维生素B1与镁。"],"emergency":["发作持续>5分钟即按持续状态启动阶梯用药并呼救；出现呼吸抑制（苯二氮䓬后）备好球囊面罩/插管；难治性持续状态立即气管插管。"],"pinyin":"dianxianchixuzhuangtaichuliliucheng","icd10":"G41.9","physical_exam":"生命体征与SpO2、意识与瞳孔、抽搐类型与部位、有无头外伤舌咬伤、神经系统定位体征、发热感染征象。","lab_tests":"床旁血糖、电解质（钠钙镁）、血气、肝肾功能、抗癫痫药血药浓度、血常规与感染指标、毒物筛查；头颅CT（新发/外伤/抗凝者）。","nursing":"专人守护防坠床咬伤；侧卧防误吸；记录发作起止时间与类型；吸氧并监测SpO2；静脉给药观察呼吸；约束使用规范并记录。","diet":"发作控制后常规饮食；寻找并回避诱发因素（酒精、睡眠剥夺）；抗癫痫药与进食时间按医嘱。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1212},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"623b2f7865c033dd5cc75206e43c40b90046be31ab858bd2ffa1515ba176b6d5","pinyin":"dianxianchixuzhuangtaichuliliucheng","initials":"dxcxztcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续或反复抽搐（全身强直阵挛最常见）、意识障碍不恢复，可伴发绀、咬舌、尿失禁；非惊厥性持续状态表现为持续意识模糊而无明显抽搐（更易漏诊）。",60],["摘要","癫痫发作持续5分钟以上或两次发作间意识未恢复（SE）的紧急处理：保护气道与生命体征，按时间阶梯给予苯二氮䓬类、抗癫痫药，顽固者全麻治疗，并寻找病因。",30],["疾病编码","G41.9",30],["原首字母","dianxianchixuzhuangtaichuliliucheng",60]]},{"id":"orders-4f2c3d9a4cd4800d9eac","key":"v1-c9ccc21dfe2a3058|orders-4f2c3d9a4cd4800d9eac","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性缺血性脑卒中处理流程","category":"夜班急症流程","raw":{"name":"急性缺血性脑卒中处理流程","category":"夜班急症流程","summary":"疑似急性缺血性脑卒中患者的急诊通道管理：快速识别与评估（卒中量表）、尽快头颅影像排除出血、发病4.5小时内评估静脉溶栓、大血管闭塞评估介入取栓，并启动卒中绿色通道。","symptoms":["突发一侧肢体无力/麻木、面瘫、言语不清或不能理解、视野缺损、复视、眩晕共济失调、突发意识改变等；症状多突然起病，时间明确性关键（发病时间=最后正常时间）。"],"diagnosis":["床旁快速识别（FAST/中风120）；立即查床旁血糖（低血糖可酷似卒中）；头颅CT平扫区分出血与缺血并排除占位；CTA/磁共振评估大血管闭塞与灌注（拟取栓者）；心电图（房颤）、化验（电解质、凝血、血小板、血糖）。"],"infusion":["静脉溶栓（发病4.5小时内、无禁忌）：阿替普酶0.9mg/kg（最大90mg），先10%静推1分钟，余60分钟静滴，溶栓前后血压管理（<185/110mmHg）；桥接血管内治疗评估。"],"oral_medication":["溶栓24小时后复查CT无出血可启动抗血小板（阿司匹林）；非溶栓者早期阿司匹林；长期二级预防按病因（抗血小板/抗凝——房颤者华法林或NOAC）。"],"treatment":["1.立即启动卒中绿色通道，通知影像与卒中团队；2.稳定气道呼吸循环，血糖<3.9mmol/L者先纠正；3.快速CT排除出血并明确缺血→评估静脉溶栓适应证与禁忌（发病时间、近期手术出血、血压、血小板凝血等）；4.4.5小时内无禁忌→阿替普酶溶栓；5.大血管闭塞（颈内动脉/大脑中动脉M1等）在发病6小时内（影像评估可延长至24小时）评估机械取栓；6.血压管理：拟溶栓/取栓者<185/110mmHg，溶栓后24小时内维持<180/105mmHg；不溶栓者急性期一般不需积极降压（除非>220/120mmHg或合并心衰夹层等），避免过度降压；7.一般监护：吞咽评估（防误吸）、血糖管理（降糖勿过低）、体温控制、预防深静脉血栓（抗凝禁忌期间用间歇充气加压）、早期康复；8.明确病因（房颤、颈动脉狭窄、卵圆孔未闭等）指导二级预防。"],"management":["卒中单元监护：血压血糖体温、NIHSS动态评分、吞咽功能；溶栓后24小时内神经功能恶化者急诊CT（排除出血）；记录各时间点（door-to-CT、door-to-needle）。"],"notes":["时间就是大脑——院内延误要最短化；溶栓前必查血糖与CT；血压不是溶栓禁忌但需可控；症状轻微或快速好转也应评估（残疾风险）；醒后卒中按最后正常时间计算并可用影像评估延长时间窗。"],"emergency":["症状快速进展、意识恶化、溶栓后头痛呕吐或神经功能加重（出血转化）→急诊复查CT并处理；大血管闭塞尽快转有介入条件医院。"],"pinyin":"jixingquexuexingnaozuzhongchuliliucheng","icd10":"I63.9","physical_exam":"生命体征与血压、意识（GCS/NIHSS评分）、瞳孔、脑膜刺激征、心脏（房颤）与颈部血管杂音；神经功能缺陷定位。","lab_tests":"床旁血糖、血常规、凝血功能、电解质、肾功能、肌钙蛋白、心电图；影像：头颅CT平扫（必须、尽快）、CTA/CTP或MRI（条件允许）。","nursing":"吸氧按需、心电血压监护；侧卧防误吸；吞咽筛查前禁食水；定时翻身防压疮；记录意识与肢体肌力变化；溶栓后观察皮肤黏膜出血。","diet":"吞咽障碍者鼻饲营养；可吞咽者低盐低脂软食，糖尿病者按糖尿病饮食。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1213},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6f216ddca763c31772d62495ae7969459a635f4de0153184de8f3596c9242891","pinyin":"jixingquexuexingnaozuzhongchuliliucheng","initials":"jxqxxnzzcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发一侧肢体无力/麻木、面瘫、言语不清或不能理解、视野缺损、复视、眩晕共济失调、突发意识改变等；症状多突然起病，时间明确性关键（发病时间=最后正常时间）。",60],["摘要","疑似急性缺血性脑卒中患者的急诊通道管理：快速识别与评估（卒中量表）、尽快头颅影像排除出血、发病4.5小时内评估静脉溶栓、大血管闭塞评估介入取栓，并启动卒中绿色通道。",30],["疾病编码","I63.9",30],["原首字母","jixingquexuexingnaozuzhongchuliliucheng",60]]},{"id":"orders-8ac91dc6530a198dbf79","key":"v1-c9ccc21dfe2a3058|orders-8ac91dc6530a198dbf79","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"脑出血处理流程","category":"夜班急症流程","raw":{"name":"脑出血处理流程","category":"夜班急症流程","summary":"自发性脑出血（多为高血压性）的急诊处理：立即CT确诊、控制血压与颅内压、止血/逆转凝血、防止血肿扩大与再出血，外科评估与ICU支持。","symptoms":["突发头痛、呕吐、意识障碍进行性加重，可伴偏瘫、失语、凝视；基底节出血多见；小脑或脑干出血表现眩晕呕吐共济失调或迅速昏迷；抗凝/溶栓后出血有相应病史。"],"diagnosis":["头颅CT平扫立即确诊并定位（基底节、丘脑、脑叶、小脑、脑干）；CTA/MRI评估血管畸形动脉瘤（年轻/非典型部位）；询问抗凝抗血小板与溶栓史；血压多显著升高。"],"infusion":["降压：收缩压>200mmHg或MAP>150mmHg者持续静脉降压（拉贝洛尔/尼卡地平/乌拉地尔泵入），目标收缩压130-180mmHg并平稳；溶栓相关性出血：冷沉淀+氨甲环酸/氨基己酸并请血液科（若用阿替普酶）；逆转华法林：维生素K10mg静注+凝血酶原复合物或新鲜冰冻血浆（按INR）；血压管理避免过低影响灌注。"],"oral_medication":["急性期停用抗血小板抗凝（评估血栓风险）；稳定后按卒中二级预防指南个体化恢复用药。"],"treatment":["1.稳定气道（GCS≤8或呼吸不规则者气管插管）、呼吸循环支持，吸氧，头部抬高30°利于静脉回流；2.控制血压：规律测压，目标收缩压约140mmHg（130-180区间），避免骤降；3.降低颅内压：甘露醇0.25-1g/kg快速静滴q6-8h或高渗盐水，抬高头位、镇静镇痛、避免过度通气（临时）；脑室引流（脑室出血伴脑积水）；4.逆转凝血异常（华法林/抗凝/抗血小板相关）与停用抗凝；5.血糖管理（<10mmol/L，避免低血糖）、体温控制、预防癫痫（临床发作或脑电发作时用抗癫痫药，不预防用药）、防深静脉血栓（出血稳定48小时后低分子肝素或物理预防早期）；6.外科评估：小脑出血>3cm伴脑干受压或脑积水→急诊手术；幕上大量出血/脑疝者个体化考虑开颅或微创；脑室出血伴梗阻性脑积水→脑室外引流；7.防止血肿扩大（血压、出血倾向、勿过度搬动）；8.重症入ICU并请神经内外科会诊。"],"management":["神经重症监护：GCS与瞳孔每1-2小时、血压连续、血肿与中线移位动态复查CT（恶化时）；记录出入量、渗透压（甘露醇时）；预防感染（肺炎、泌尿道）；早期康复介入。"],"notes":["降压要平稳勿骤降；避免大量补液加重脑水肿；停用抗栓药需与心脑血管血栓风险权衡；甘露醇注意肾损与反跳；老年人血压管理个体化；早期病死率高，及时家属沟通预后。"],"emergency":["意识快速恶化、瞳孔改变（脑疝）→立即甘露醇+呼救并准备手术；脑室出血急性脑积水→急诊脑室外引流；癫痫持续→按持续状态处理。"],"pinyin":"naochuxuechuliliucheng","icd10":"I61.9","physical_exam":"生命体征血压、GCS、瞳孔（不等大提示脑疝）、眼球位置、运动感觉障碍、脑膜刺激征（蛛血时）、共济（小脑）。","lab_tests":"血常规、凝血功能（PT/APTT/INR）、血小板、电解质、血糖、肝肾功能；影像：头颅CT平扫（急诊）、CTA（疑血管畸形）、必要时复查CT观察血肿扩大。","nursing":"卧床、头抬高、少搬动；监测瞳孔意识GCS；防误吸引流护理；肢体防压疮与挛缩；口腔会阴护理；记录出入量与尿比重。","diet":"急性期禁食或鼻饲流质（应激性溃疡预防用PPI）；稳定后低盐低脂，吞咽评估后进食；控制血糖饮食。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1214},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0db5aaafe3d9ed91da9cddf805f8371ae74e7be301da1a612298a0db5e4fdd1a","pinyin":"naochuxiechuliliucheng","initials":"ncxcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发头痛、呕吐、意识障碍进行性加重，可伴偏瘫、失语、凝视；基底节出血多见；小脑或脑干出血表现眩晕呕吐共济失调或迅速昏迷；抗凝/溶栓后出血有相应病史。",60],["摘要","自发性脑出血（多为高血压性）的急诊处理：立即CT确诊、控制血压与颅内压、止血/逆转凝血、防止血肿扩大与再出血，外科评估与ICU支持。",30],["疾病编码","I61.9",30],["原首字母","naochuxuechuliliucheng",60]]},{"id":"orders-2fe81429529a030877a0","key":"v1-c9ccc21dfe2a3058|orders-2fe81429529a030877a0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肾内科常用药物","category":"夜班科室用药","raw":{"name":"肾内科常用药物","category":"夜班科室用药","summary":"肾内科夜班常用药物汇总：保肾/降蛋白、肠道排毒、降磷补钙、促红、抗感染（注意按肾功能调整剂量）、透析相关用药等。","symptoms":["慢性肾脏病、肾病综合征、急慢性肾衰竭、肾性贫血、高磷低钙、尿路感染等肾脏疾病的用药。"],"diagnosis":["依据肾功能（eGFR/肌酐）、电解质与贫血、蛋白尿等指标选择用药，所有经肾排泄药物需按肾功能调整剂量。"],"infusion":["保肾降蛋白：黄葵胶囊0.5g×5粒tid（2.5g tid）、金水宝胶囊0.99g tid、百令胶囊按说明书；肠道排毒：尿毒清颗粒4-10g tid、药用炭（爱西特）按说明书；降蛋白兼降压用ACEI/ARB；肾康注射液100ml+5%GS 150ml静滴qd；促红细胞生成素/罗沙司他（贫血）；抗感染：按eGFR调整——哌拉西林他唑巴坦4.5g q8-12h、头孢替安2g q12h、头孢唑肟1-1.5g bid、头孢美唑2g bid、莫西沙星0.4g qd、氨曲南2g bid、美罗培南0.5g q12h（透析患者调整剂量与给药时机）；止血：卡络磺钠80mg qd、矛头蝮蛇血凝酶1IU肌注/静推；前列地尔10μg+NS 20ml静推qd（改善循环）；参芎葡萄糖注射液100ml qd；羟苯磺酸钙0.5g tid。"],"oral_medication":["肾衰宁片一次3片tid、尿毒清颗粒（无糖型）5-10g tid、百令胶囊、复方α-酮酸片（配合优质低蛋白饮食）4片tid或2.52g tid、醋酸钙/碳酸钙降磷（随餐）、骨化三醇0.25μg qd-qn、左卡尼汀（透析后）；降压与排钾利尿按肾功能个体化。"],"treatment":["1.按肾功能分期管理原发病（高血压、糖尿病等，降压优选ACEI/ARB并据eGFR调整）；2.肾性贫血：促红素50-100IU/kg皮下每周2-3次，并补铁、叶酸、甲钴胺0.5mg tid；3.钙磷代谢紊乱：限磷＋磷结合剂（碳酸钙/醋酸钙）随餐嚼服＋活性维生素D（骨化三醇0.25-0.5μg qd）；4.代谢性酸中毒：碳酸氢钠片0.5-1g口服tid，重者5%碳酸氢钠125-250ml静滴；5.感染按eGFR调整剂量并监测耳肾毒性；6.透析患者血透后左卡尼汀1g静推，管理容量与电解质；7.避免肾毒性药物（NSAIDs、造影剂、氨基糖苷等）；8.急慢性肾衰竭高钾血症按高钾流程处理。"],"management":["监测血压、体重、出入量、电解质与肾功能变化；用药前核查eGFR调整剂量；记录透析时间；观察利尿与心衰表现。"],"notes":["几乎所有药物在肾功能不全时均需调整剂量（部分免调）；避免造影剂肾损伤（必要时水化）；NSAIDs在肾功能不全者禁用或慎用；磷结合剂须随餐服用才有效；活性维生素D监测血钙；金水宝/百令等虫草制剂按说明书剂量，勿超量。"],"emergency":["高钾血症（心电图改变）、急性肺水肿/容量超负荷、严重酸中毒、尿毒症脑病需急诊透析时按相应流程并呼叫肾内科/透析室。"],"pinyin":"shenneikechangyongyaowu","icd10":"N28.9","physical_exam":"血压、水肿程度、出入量、皮肤黏膜、心肺（容量状态）。","lab_tests":"血常规（Hb）、肾功能（肌酐、尿素氮、eGFR）、电解质（钾钠钙磷）、尿常规与24小时尿蛋白、血气（酸中毒）。","nursing":"记录出入量与体重（每日）；观察尿液颜色与量；水肿者限水并抬高下肢；透析通路（内瘘/导管）保护；指导低盐低磷优质低蛋白饮食。","diet":"低盐（<5g/d）低磷优质低蛋白饮食，配合α-酮酸；限水（量出为入）；高钾食物（香蕉橙子等）限制并宣教。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1215},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"95b6993fbc49bd0bcdb721e3be33151632607f7a44012a0f6ff0560206dda4ba","pinyin":"shenneikechangyongyaowu","initials":"snkcyyw","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","慢性肾脏病、肾病综合征、急慢性肾衰竭、肾性贫血、高磷低钙、尿路感染等肾脏疾病的用药。",60],["摘要","肾内科夜班常用药物汇总：保肾/降蛋白、肠道排毒、降磷补钙、促红、抗感染（注意按肾功能调整剂量）、透析相关用药等。",30],["疾病编码","N28.9",30],["原首字母","shenneikechangyongyaowu",60]]},{"id":"orders-14b0f901a66cfdbc3eac","key":"v1-c9ccc21dfe2a3058|orders-14b0f901a66cfdbc3eac","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"血液内科常用药物","category":"夜班科室用药","raw":{"name":"血液内科常用药物","category":"夜班科室用药","summary":"血液内科夜班常用药物汇总：升白、升血小板、补血（铁剂叶酸维生素B12）、止血、抗感染（粒缺发热按危险分层）、化疗辅助（止吐）与急救药物。","symptoms":["白细胞减少/粒缺发热、血小板减少出血、贫血、化疗后骨髓抑制、凝血异常、DIC等血液病的支持与急救用药。"],"diagnosis":["根据血常规（三系）、骨髓与病因诊断选择：粒缺发热按危险分层经验抗感染，血小板<20-30×10^9/L或有出血评估输注，贫血按类型补铁/叶酸/B12或输血。"],"infusion":["升白细胞：重组人粒细胞刺激因子（瑞白等）300μg皮下qd（WBC<2.0×10^9/L）；升血小板：重组人白介素-11（巨和粒）3mg皮下qd或2mg皮下qd（监测心功能与水肿）；补铁：右旋糖酐铁100mg肌注qd（需深部注射）；造血支持：腺苷钴胺1.5mg肌注qd、甲钴胺0.5mg口服tid；止血：酚磺乙胺4g+液体静滴qd、矛头蝮蛇血凝酶1IU静推q8-12h、卡络磺钠80mg qd、氨甲环酸（原发性纤溶亢进）静滴；抗感染：粒缺发热经验性广谱（亚胺培南/美罗培南0.5g q8h-q6h或头孢哌酮舒巴坦3g bid等）并覆盖G+（万古霉素/利奈唑胺/替考拉宁）与真菌（氟康唑/伏立康唑/卡泊芬净按指征）；抗病毒：阿昔洛韦0.5g q8h、更昔洛韦等。"],"oral_medication":["叶酸10mg tid、乳酸亚铁0.2g tid或琥珀酸亚铁、甲钴胺0.5mg tid、云芝胞内糖肽1g tid（免疫调节）、氟康唑150mg qd预防真菌等。"],"treatment":["1.粒缺发热（ANC<0.5且体温≥38.3℃或≥38℃1小时）：血培养后立即经验性广谱抗感染（覆盖铜绿假单胞菌），48-72小时评估调整，危险分层决定是否住院/升级（头孢他啶、哌拉西林他唑巴坦、碳青霉烯或加氨基糖苷）；2.血小板减少出血：PLT<10-20×10^9/L输注血小板，活动性出血目标更高，同时治疗原发病；3.重度贫血Hb<60-70g/L或症状明显输红细胞；4.DIC：处理原发病为主，按出血/血栓表型补充凝血因子/血小板/肝素（审慎，请血液科）；5.化疗后骨髓抑制支持治疗；6.肿瘤溶解综合征/高尿酸预防（别嘌醇/非布司他、水化碱化）；7.出血患者避免肌注与NSAIDs，监测出血征象。"],"management":["粒缺者单间隔离、口腔会阴护理、监测体温；动态血常规；输注血小板前后评估疗效；发热者反复血培养；记录出血点变化。"],"notes":["粒细胞刺激因子在化疗后24-72小时使用而非化疗同时；白介素-11慎用于心衰肾衰患者并注意水肿；铁剂过量有铁过载风险勿滥用；输注血小板禁忌（如TTP）除外；肝素诱导血小板减少（HIT）者改用非肝素抗凝。"],"emergency":["严重粒缺高热、颅内出血或内脏大出血、急性溶血、DIC、肿瘤溶解综合征时按相应流程抢救并呼叫血液科/ICU。"],"pinyin":"xueyeneikechangyongyaowu","icd10":"D75.9","physical_exam":"生命体征、皮肤黏膜出血点瘀斑、口腔咽喉感染灶、心肺、腹部（肝脾）。","lab_tests":"血常规（动态）、网织红细胞、铁蛋白/叶酸/B12、凝血功能（D-二聚体、FDP）、CRP/PCT、血培养（发热时）；必要时骨髓检查。","nursing":"口腔护理（防口腔黏膜炎感染）、会阴肛周护理、皮肤出血点观察、输血护理；粒缺发热者监测体温q4h；防跌倒碰撞。","diet":"粒缺期无菌/熟食饮食，避免生冷；贫血者高铁高蛋白饮食；血小板低者软食防黏膜损伤出血。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1216},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9d124c1ebc468a5d737a56c1579dd2f4baaf617acf1a41b95c865285daf8b7ac","pinyin":"xueyeneikechangyongyaowu","initials":"xynkcyyw","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","白细胞减少/粒缺发热、血小板减少出血、贫血、化疗后骨髓抑制、凝血异常、DIC等血液病的支持与急救用药。",60],["摘要","血液内科夜班常用药物汇总：升白、升血小板、补血（铁剂叶酸维生素B12）、止血、抗感染（粒缺发热按危险分层）、化疗辅助（止吐）与急救药物。",30],["疾病编码","D75.9",30],["原首字母","xueyeneikechangyongyaowu",60]]},{"id":"orders-602d2a799281170e5ab1","key":"v1-c9ccc21dfe2a3058|orders-602d2a799281170e5ab1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肿瘤科常用药物","category":"夜班科室用药","raw":{"name":"肿瘤科常用药物","category":"夜班科室用药","summary":"肿瘤患者夜班常用药物：化疗辅助支持（止吐、升白升血小板、保肝、镇痛）、抗肿瘤中成药辅助与抗感染。本条按抗肿瘤辅助用药与临床常规整理，具体化疗方案以各瘤种指南为准。","symptoms":["肿瘤患者化疗后恶心呕吐、骨髓抑制（发热粒缺）、疼痛、出血、肝功能异常、感染等夜班常见问题的用药处理。"],"diagnosis":["根据化疗后时间与症状判断（迟发呕吐、粒缺发热、血小板低下出血等），查血常规、肝肾功能、炎症指标。"],"infusion":["止吐：托烷司琼5mg+NS 100ml静滴qd（化疗前）或昂丹司琼、格拉司琼；参芪扶正注射液250ml静滴qd、艾迪注射液50ml静滴qd（与放化疗同步，抗肿瘤辅助）、复方苦参（岩舒）20ml+NS 250ml静滴qd（癌痛出血辅助）；复方斑蝥胶囊口服、硒酵母片200μg bid（辅助）、华蟾素（口服/静滴按说明书）；保肝：谷胱甘肽1.2g+GS 100ml静滴qd、异甘草酸镁100-150mg静滴qd、多烯磷脂酰胆碱；升白：粒细胞集落刺激因子300μg皮下qd；升血小板：白介素-11 3mg皮下qd。"],"oral_medication":["阿瑞匹坦等止吐口服（化疗后）、甲氧氯普胺10mg口服q4-6h、洛芬待因/曲马多（中重度癌痛按三阶梯）、塞来昔布（轻中度）、升血小板胶囊/利可君、叶酸甲钴胺（营养支持）、别嘌醇（化疗前防TLS）。"],"treatment":["1.化疗相关恶心呕吐：按致吐等级预防性止吐（5-HT3拮抗剂如昂丹司琼8mg静注±地塞米松10mg静注±NK1拮抗剂阿瑞匹坦125mg口服），持续呕吐纠正水电解质；2.粒缺发热：立即经验性广谱抗感染（参照血液内科条）；3.疼痛按三阶梯（轻：对乙酰氨基酚0.5-1g q6h口服或布洛芬0.4g q8h口服；中：曲马多50-100mg q6h口服；重：吗啡5-10mg皮下q4h或10-30mg口服q4h），规范滴定并处理便秘恶心等副作用；4.出血/血小板低下参照血液支持治疗；5.保肝降酶按肝功能情况选择；6.抗肿瘤中成药辅助使用需与化疗间隔并注意肝肾毒性监测；7.肿瘤溶解综合征高危（淋巴瘤、ALL高负荷）化疗前水化碱化+别嘌醇300mg qd口服或拉布立酶0.2mg/kg静滴；8.终末期以舒适照护为主（镇痛、镇静、营养、症状管理），与家属充分沟通。"],"management":["评估NRS疼痛评分并记录；观察呕吐与出入量；监测血常规与肝肾功能；粒缺者保护性隔离；与家属沟通预后与照护目标。"],"notes":["化疗药物选择与剂量务必按各瘤种指南与药品说明书执行；止吐药注意QT延长（托烷司琼与昂丹司琼）；NSAIDs在血小板低/出血风险者避免；阿片类规范使用防成瘾但需满足镇痛，注意呼吸抑制与便秘。"],"emergency":["粒缺发热休克、大出血、急性TLS（高钾高磷低钙肾衰）、溶骨痛或脊髓压迫、上腔静脉综合征按相应急症处理。"],"pinyin":"zhongliukechangyongyaowu","icd10":"C80","physical_exam":"生命体征、口腔黏膜（溃疡）、皮肤出血点、感染灶、腹部肝区（肝损）。","lab_tests":"血常规动态、肝肾功能电解质、CRP/PCT、呕吐致电解质紊乱时查血气；发热时血培养。","nursing":"化疗后观察输液部位（防外渗）；口腔护理防溃疡感染；呕吐者侧卧防误吸并记录；疼痛评估（面部数字评分）；心理支持。","diet":"高蛋白高维生素清淡饮食，少食多餐；化疗期间多饮水（防TLS与便秘）；忌辛辣油腻。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1217},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9061ccdb64f80b146bac220b83a4d13705c0ab832c5291d3d0b6b12008e9aee2","pinyin":"zhongliukechangyongyaowu","initials":"zlkcyyw","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肿瘤患者化疗后恶心呕吐、骨髓抑制（发热粒缺）、疼痛、出血、肝功能异常、感染等夜班常见问题的用药处理。",60],["摘要","肿瘤患者夜班常用药物：化疗辅助支持（止吐、升白升血小板、保肝、镇痛）、抗肿瘤中成药辅助与抗感染。本条按抗肿瘤辅助用药与临床常规整理，具体化疗方案以各瘤种指南为准。",30],["疾病编码","C80",30],["原首字母","zhongliukechangyongyaowu",60]]},{"id":"orders-8f0b5383957cd81fb977","key":"v1-c9ccc21dfe2a3058|orders-8f0b5383957cd81fb977","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"感染科常用药物","category":"夜班科室用药","raw":{"name":"感染科常用药物","category":"夜班科室用药","summary":"感染科（肝炎/肝硬化/发热待查等）夜班常用药物：乙肝抗病毒核苷类似物、保肝降酶退黄、肝硬化门脉高压并发症（出血/腹水/肝性脑病）用药、免疫调节与肝病相关止血药物。","symptoms":["慢性乙肝/丙肝抗病毒管理、肝功能异常（转氨酶升高、黄疸）、肝硬化腹水、食管胃底静脉曲张出血、肝性脑病、感染发热等。"],"diagnosis":["根据病毒标志物（HBsAg/HBV-DNA）、肝功能（ALT胆红素白蛋白）、凝血、血氨、Child-Pugh分级与并发症表现用药；抗病毒药物需依据病毒载量与耐药史选择。"],"infusion":["抗病毒口服（见口服药）；保肝降酶：异甘草酸镁100-150mg+GS 100ml静滴qd（医保限肝衰竭者注意）、复方甘草酸苷静滴、谷胱甘肽1.2g+GS静滴qd（抗氧化）、多烯磷脂酰胆碱465mg+GS静滴qd；退黄：腺苷蛋氨酸1g+GS 100ml静滴qd、乙酰半胱氨酸4g+GS 250ml静滴（重症肝损）、熊去氧胆酸口服；改善肝微循环：前列地尔10μg+NS静推qd；肝性脑病：门冬氨酸鸟氨酸（瑞甘）7.5-15g+GS 250ml静滴qd-bid、乳果糖口服/灌肠；腹水：螺内酯40mg bid-tid+呋塞米20mg qd（或利尿合剂多巴胺+呋塞米泵入）；静脉曲张出血/门脉高压：生长抑素3mg泵入q12h或奥曲肽50μg静推后25-50μg/h泵入+PPI（埃索美拉唑80mg泵入q12h）8%去甲肾上腺素口服/胃管局部止血+凝血酶口服。"],"oral_medication":["乙肝抗病毒：恩替卡韦0.5mg qd（一线，高效低耐药）、替诺福韦/丙酚替诺福韦（注意肾功能）、替比夫定600mg qd、拉米夫定0.1g qd（耐药率高）、阿德福韦酯10mg qd（注意肾损）；保肝口服：双环醇片25-50mg tid、五酯片、复方甘草酸苷胶囊、九味肝泰胶囊、复方灵芝颗粒；退黄：熊去氧胆酸0.25g tid；乳果糖10-30ml tid（肝性脑病与通便）；门冬氨酸鸟氨酸颗粒3g tid。"],"treatment":["1.慢性乙肝：依据DNA与肝功能启动抗病毒，首选ETV/TDF/TAF长期治疗，监测耐药（拉米夫定耐药者换用或加阿德福韦等）；2.肝功能异常：停用/避免肝损药物与饮酒，按转氨酶黄疸程度保肝降酶退黄；3.肝硬化腹水：限钠+螺内酯/呋塞米阶梯利尿，大量放腹水者输白蛋白（每放1L输白蛋白6-8g）；4.静脉曲张出血：按消化道大出血流程（生长抑素/奥曲肽+PPI+抗生素预防+内镜套扎/硬化，三腔二囊管备用）；5.肝性脑病：去除诱因（出血、感染、电解质、便秘、高蛋白），乳果糖+门冬氨酸鸟氨酸，限制蛋白视情况；6.自发性腹膜炎：诊断性腹穿，经验性三代头孢/哌拉西林他唑巴坦；7.肝硬化合并肝癌者抗肿瘤辅助用药（艾迪、复方斑蝥等，参照肿瘤科条）；8.失代偿者评估肝移植。"],"management":["监测肝功能、凝血、血氨、腹围体重出入量；抗病毒者规律服药防耐药与停药反弹；出血高危者软食；记录利尿反应与体重。"],"notes":["恩替卡韦孕妇慎用（首选TAF/TDF备孕者咨询）；阿德福韦酯与替诺福韦注意肾小管毒性；核苷类似物不可随意停药（防肝炎暴发）；利尿剂致低钾可诱发肝性脑病，注意补钾；静脉曲张出血禁食并警惕再出血。"],"emergency":["食管静脉曲张大出血（呕血黑便休克）按消化道大出血急症流程；急性肝衰竭（黄疸进行性、凝血恶化、肝性脑病）转肝病中心评估肝移植；肝性脑病昏迷防误吸。"],"pinyin":"ganrankechangyongyaowu","icd10":"B99","physical_exam":"黄疸、肝掌蜘蛛痣、腹水（移动性浊音）、脾大、扑翼样震颤（肝性脑病）、意识状态。","lab_tests":"肝功能、凝血功能、血氨、HBV-DNA/HCV-RNA、乙肝三系、甲胎蛋白、腹部超声、电解质（腹水利尿时）、肾功能。","nursing":"观察呕吐物大便颜色（出血）、意识行为（脑病）、腹围体重（腹水）；口腔护理；防跌倒（低钾/脑病）；输液观察肝损药物不良反应。","diet":"肝硬化低盐软食防出血；肝性脑病急性期限制蛋白（缓解后渐加）；禁酒；腹水限制水钠。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1218},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c322fe7cd0ffa8f5e3bd3cd0b49fe6480a74e4c21d258ec4f2f3bb9e78508ffc","pinyin":"ganrankechangyongyaowu","initials":"grkcyyw","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","慢性乙肝/丙肝抗病毒管理、肝功能异常（转氨酶升高、黄疸）、肝硬化腹水、食管胃底静脉曲张出血、肝性脑病、感染发热等。",60],["摘要","感染科（肝炎/肝硬化/发热待查等）夜班常用药物：乙肝抗病毒核苷类似物、保肝降酶退黄、肝硬化门脉高压并发症（出血/腹水/肝性脑病）用药、免疫调节与肝病相关止血药物。",30],["疾病编码","B99",30],["原首字母","ganrankechangyongyaowu",60]]},{"id":"orders-f0c2cf66c6a7015bbfc9","key":"v1-c9ccc21dfe2a3058|orders-f0c2cf66c6a7015bbfc9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"ICU常用药物","category":"夜班科室用药","raw":{"name":"ICU常用药物","category":"夜班科室用药","summary":"重症监护病房夜班常用药物：肠内外营养、镇静镇痛、脑保护与循环改善、血管活性与电解质、广谱抗感染、脱水利尿止血等支持治疗药物。","symptoms":["危重患者营养支持、镇静镇痛、脑卒中/颅脑损伤脑保护、休克、感染、电解质紊乱、出血等ICU常见场景用药。"],"diagnosis":["按器官功能评估用药：血流动力学（血压CVP/乳酸）、意识与镇静评分（RASS）、营养风险、感染证据、电解质与凝血。"],"infusion":["营养：肠内营养乳剂TPF（瑞先）500ml胃注/口服、能全力TPF、水解蛋白5g胃注tid、复方氨基酸（乐凡命/丰诺安）静滴、脂溶性+水溶性维生素、多种微量元素；镇静：丙泊酚（0.5mg/kg诱导，泵注维持）、咪达唑仑、右美托咪定；镇痛：芬太尼/舒芬太尼50μg+NS 50ml泵入、吗啡；脑保护：神经节苷脂20mg+NS静滴、长春西汀30mg+NS静滴、脑苷肌肽、鼠神经生长因子30μg肌注qd；改善循环：血塞通（络泰）0.2g+GS 250ml静滴qd、前列地尔10μg+NS静推qd、琥珀酰明胶500ml（容量复苏）；抗凝：低分子肝素钙6000IU皮下qd、依诺肝素4000IU皮下qd、肝素钠（有创监测冲管/抗凝）泵入；血管活性：去甲肾上腺素（体重×0.3mg+GS 50ml泵入，1ml/h≈0.1μg/(kg·min)）、多巴胺；广谱抗感染：哌拉西林他唑巴坦4.5g q8h、头孢吡肟2g bid、头孢他啶1-2g q8h、万古霉素1g q12h（监测谷浓度）、亚胺培南500mg q8h-q6h、异帕米星400mg qd；脱水利尿：甘露醇25g q12h静滴、呋塞米；止血：卡络磺钠、巴曲亭、酚磺乙胺、维生素K1 10mg、氨甲环酸；电解质：葡萄糖酸钙3g泵入（低钙/过敏/镁氟中毒）、复合磷酸氢钾、氯化钾、门冬氨酸钾镁、浓氯化钠（低钠）、碳酸氢钠。"],"oral_medication":["能口服/胃注者：阿托品0.3mg胃注q8h、氨茶碱100mg胃注q8h、果糖二磷酸口服液1g tid（营养心肌）、乳果糖/益生菌（肠道）、艾司唑仑（按需）。"],"treatment":["1.血流动力学支持：先容量复苏（晶体/胶体）再血管活性药（去甲肾上腺素一线），目标MAP≥65mmHg、乳酸下降；2.镇静镇痛按目标评分滴定（浅镇静），每日唤醒评估，防镇静过深与蓄积；3.机械通气按肺保护策略（ARDS：小潮气量6ml/kg、平台压≤30cmH2O），人机对抗加镇静必要时肌松；4.感染：尽早抗感染，按部位/耐药危险分层选药并降阶梯，动态培养；5.营养：入ICU24-48小时启动肠内营养（血流动力学稳定后），不耐受者肠外营养过渡；6.脑保护/ICP管理：抬高头位、甘露醇/高渗盐、控制体温与血糖；7.预防：VTE（出血稳定后低分子肝素）、应激性溃疡（PPI）、院内感染；8.电解质与酸碱动态纠正，CRRT指征明确者尽早实施。"],"management":["每小时评估生命体征、镇静评分、出入量、血糖乳酸；呼吸机与CRRT参数记录；每日停镇静评估与自主呼吸试验；家属沟通病情。"],"notes":["血管活性药经中心静脉泵入防外渗（去甲外渗酚妥拉明封闭）；丙泊酚长期大量注意高甘油三酯与丙泊酚输注综合征；万古霉素/氨基糖苷监测血药浓度与肾功能；甘露醇注意肾损与反跳；镇静药联合阿片注意呼吸抑制。"],"emergency":["心跳骤停按CPR/ACLS；严重休克/低氧/难治性颅内高压等按相应流程即时处理并呼叫上级。"],"pinyin":"ICUchangyongyaowu","icd10":"Z03.9","physical_exam":"意识镇静深度、呼吸机参数与气道、心肺、腹部、灌注（肢端、尿量）、水肿。","lab_tests":"血气乳酸、电解质、血糖、凝血、肝肾功能、感染指标；药敏（培养后）。","nursing":"严格交接班（泵速、镇静评分、气道、引流）；导管（CVC/气管插管/CRRT）护理；皮肤压疮预防；每日唤醒时观察配合度；记录出入量与血糖。","diet":"优先肠内营养，监测胃残余量防误吸；喂养不耐受者调整速度或空肠喂养；血糖控制于目标范围。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1219},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b7b9d12b40ee712767bb0d6f1db1ca884138d56dbba923c6f974f940d8504d61","pinyin":"ICUchangyongyaowu","initials":"Icyyw","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","危重患者营养支持、镇静镇痛、脑卒中/颅脑损伤脑保护、休克、感染、电解质紊乱、出血等ICU常见场景用药。",60],["摘要","重症监护病房夜班常用药物：肠内外营养、镇静镇痛、脑保护与循环改善、血管活性与电解质、广谱抗感染、脱水利尿止血等支持治疗药物。",30],["疾病编码","Z03.9",30],["原首字母","ICUchangyongyaowu",60]]},{"id":"orders-1962612c80fa63bf8bb0","key":"v1-c9ccc21dfe2a3058|orders-1962612c80fa63bf8bb0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班接诊回应与医患沟通第一印象","category":"夜班临床经验","raw":{"name":"夜班接诊回应与医患沟通第一印象","category":"夜班临床经验","summary":"夜班被呼叫后如何给患者家属留下专业可靠的第一印象并妥善沟通：立即回应、先了解病人背景再处置、言行着装得体、不与家属争辩、不随意贬低白班与主管医生。","symptoms":["家属夜间呼叫、对年轻医生能力不信任、情绪急躁等常见场景。"],"diagnosis":["判断家属呼叫的紧急程度，快速决定先查看还是先了解背景；区分主管医生已交代事宜与突发新问题。"],"infusion":["无特殊输液，按病情需要执行医嘱。"],"oral_medication":["无特殊口服药，按病情需要。"],"treatment":["1.接到呼叫立即回应\"马上到\"，记清床号；2.除抢救外先快速浏览患者一般信息（诊断、手术、术后天数、主管组）再到达床边；3.先做处理再简短解释，解释口径与主管医生保持一致，不清楚的表示请主管医生沟通；4.面对情绪激动的家属不与争辩，可表达歉意并提出请示上级/主管医生意见；5.查看病人时穿白大衣、带听诊器并规范查体，让患者与家属感到被认真对待；6.对不是自己主管的患者态度平和专业，避免介入其与主管医生之间的是非；7.不表露\"什么都能处理\"的自负，留出余地。"],"management":["接诊后回访反馈；把可疑矛盾或纠纷苗头及时告知总住院医师/科主任。"],"notes":["第一印象决定家属信任度：立即回应、了解背景、着装规范、态度专业诚恳；不要当着家属说白班/别的医生的不是；处理与解释分开进行可减少误解。"],"emergency":["紧急呼叫涉及窒息、抽搐、大出血、心跳呼吸骤停等立即放下其他工作赶往并呼救。"],"pinyin":"yebanjiezhenhuiyingyuyihuangoutongdiyiyinxiang","icd10":"Z00-Z99","physical_exam":"查房与接诊时随身携带听诊器，规范体检建立信任；着装整洁（穿白大衣），不穿拖鞋。","lab_tests":"先查看病历系统：诊断、手术方式、术后天数、主管医生与既往处理，再决定是否需要急查检验。","nursing":"与值班护士建立良好配合，护理呼叫信息及时互通。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1220},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"54ff25e467f0866c7af2e7940dd26c3979cadc8733c232ec44e3cb802eb2b0d2","pinyin":"yebanjiezhenhuiyingyuyihuangoutongdiyiyinxiang","initials":"ybjzhyyyhgtdyyx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","家属夜间呼叫、对年轻医生能力不信任、情绪急躁等常见场景。",60],["摘要","夜班被呼叫后如何给患者家属留下专业可靠的第一印象并妥善沟通：立即回应、先了解病人背景再处置、言行着装得体、不与家属争辩、不随意贬低白班与主管医生。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanjiezhenhuiyingyuyihuangoutongdiyiyinxiang",60]]},{"id":"orders-e9f492217b94c0f5125e","key":"v1-c9ccc21dfe2a3058|orders-e9f492217b94c0f5125e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班用药前问诊与常见医嘱陷阱","category":"夜班临床经验","raw":{"name":"夜班用药前问诊与常见医嘱陷阱","category":"夜班临床经验","summary":"夜班开药/用药前必须问清的既往史与常见用药陷阱：老年男性慎用解痉药（尿潴留）、用药前问过敏史与禁忌、发现不合理医嘱只处理少议论等。","symptoms":["夜间临时用药场景：疼痛、痉挛、失眠、镇静、退热等。"],"diagnosis":["开药前确认：以前有什么病（前列腺增生、青光眼、心律失常、COPD、糖尿病）、哪些药不能用（过敏史、禁忌）、现用药物与相互作用。"],"infusion":["老年男性腹痛解痉避免山莨菪碱等抗胆碱药（易致尿潴留、加重前列腺增生，夜间反复呼叫）；确需解痉者评估后选择。"],"oral_medication":["开任何药前口头确认过敏史与既往禁忌；新开药与现有医嘱核对（重复给药、相互作用）。"],"treatment":["1.先问再开：以前什么病、什么药过敏、什么药不能用——护士配药后患者说\"这药不能用\"会造成退药纠纷与风险；2.老年男性避免抗胆碱能解痉药；COPD患者避免镇静剂过深；有心律失常风险者避免三环类等；3.发现白班/他组医嘱不合理（如氧管脱落没人发现、尿管夹闭不开放尿）——只处理纠正，不当着患者或护士指责开医嘱者；4.夜间新加药尽量从低剂量开始并说明目的；5.开药后告知护士观察要点。"],"management":["把新加药与患者既往禁忌核对并记录；次日交班时提醒白班评估长期用药。"],"notes":["夜间开药最忌不了解病人：禁忌药、过敏史、相互作用是三条底线；能口服不注射、能观察先观察，减少无效用药与退药纠纷。"],"emergency":["用药后出现过敏反应、呼吸抑制、低血压等按过敏/抢救流程处理。"],"pinyin":"yebanyongyaoqianwenzhenyuchangjianyizhuxianjing","icd10":"Z00-Z99","physical_exam":"按主诉重点查体（如腹痛部位、胸部心肺、意识等）后再决定用药。","lab_tests":"根据症状需要查血糖、电解质、心电图等排除可纠正病因（低血糖、高钾等）再对症。","nursing":"给药前执行三查七对并复述患者过敏史；用药后观察生命体征与不良反应。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1221},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"de227aac0443aa078d880ba4619af15e0b3463f3806afe1f3fa07e54b079a20d","pinyin":"yebanyongyaoqianwenzhenyuchangjianyizhuxianjing","initials":"ybyyqwzycjyzxj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜间临时用药场景：疼痛、痉挛、失眠、镇静、退热等。",60],["摘要","夜班开药/用药前必须问清的既往史与常见用药陷阱：老年男性慎用解痉药（尿潴留）、用药前问过敏史与禁忌、发现不合理医嘱只处理少议论等。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanyongyaoqianwenzhenyuchangjianyizhuxianjing",60]]},{"id":"orders-945ffcb4cb951f302715","key":"v1-c9ccc21dfe2a3058|orders-945ffcb4cb951f302715","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"抢救配合与上级沟通技巧","category":"夜班临床经验","raw":{"name":"抢救配合与上级沟通技巧","category":"夜班临床经验","summary":"抢救与呼叫上级时的沟通要点：不要说\"药没有了\"，主动提供替代方案；平时与麻醉、ICU、护士建立良好关系，危机关头能互相支援。","symptoms":["抢救现场、需要紧急用药或上级指导的场景。"],"diagnosis":["迅速判断病情需要的抢救措施与药物，评估科室现有条件。"],"infusion":["汇报用药时以\"目前科里有的替代品\"为先：如肾上腺素缺货可说\"主任，阿托品/多巴胺先上多少\"；建立通畅静脉通路。"],"oral_medication":["无特殊（抢救以静脉给药为主）。"],"treatment":["1.抢救时明确分工（按压、气道、静脉、记录各有人），指定指挥者；2.上级要药时不在病人面前说\"没有/用完了\"，用可替代方案回应，稳定现场；3.呼叫上级/SOS要及时：自己拿不准、病情超出预计或从未遇过的情况不硬撑，病人的生命胜过面子；4.与麻醉科、ICU保持良好协作关系——危重插管、会诊、转科时他们可能是救命关键；5.与护士团队配合好（她们熟悉床位与病情，交接与用药最清楚）；6.抢救后补记抢救记录（6小时内），如实记录。"],"management":["抢救结束清点药品器材补齐；向上级口头汇报全过程；家属沟通由年资合适者进行。"],"notes":["会哭的孩子有奶吃但要分轻重——无关痛痒的事反复打扰上级会变成\"狼来了\"，真急症时反而延误；遇到紧急情况宁可被责备也要及时呼叫。"],"emergency":["任何心跳呼吸骤停、休克、窒息、抽搐持续等情况立即启动抢救小组并呼叫总住院/上级。"],"pinyin":"qiangjiupeiheyushangjigoutongjiqiao","icd10":"Z00-Z99","physical_exam":"抢救时配合查体与监护数据快速汇报。","lab_tests":"抢救时同步送检（血气、电解质、血糖、血常规、凝血等）。","nursing":"抢救车药品定位管理，定期检查补齐；配合执行口头医嘱复述确认。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1222},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4e18d6816fa41f3580eab2a822ec491ede4ced78b5d0f2b0cfdfd8e9cad435d3","pinyin":"qiangjiupeiheyushangjigoutongjiqiao","initials":"qjphysjgtjq","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","抢救现场、需要紧急用药或上级指导的场景。",60],["摘要","抢救与呼叫上级时的沟通要点：不要说\"药没有了\"，主动提供替代方案；平时与麻醉、ICU、护士建立良好关系，危机关头能互相支援。",30],["疾病编码","Z00-Z99",30],["原首字母","qiangjiupeiheyushangjigoutongjiqiao",60]]},{"id":"orders-dc7a8f1a0874d2dcbf0b","key":"v1-c9ccc21dfe2a3058|orders-dc7a8f1a0874d2dcbf0b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急诊夜班诊疗基本思路","category":"夜班临床经验","raw":{"name":"急诊夜班诊疗基本思路","category":"夜班临床经验","summary":"急诊/值班诊疗的核心思路：先处理威胁生命的问题再追究诊断（先开枪后瞄准）；任何病人先看生命体征；保持清醒冷静比技术更重要；及时求助不是丢人。","symptoms":["急症患者接诊：胸痛、呼吸困难、休克、意识改变、急腹症等。"],"diagnosis":["快速按\"生命体征→一般状况→病史→查体→辅助检查\"的顺序评估；对不能立刻明确的危重病先按最危险的可能处理。"],"infusion":["危重患者立即建立静脉通路，据床旁血糖决定以糖水或盐水开路。"],"oral_medication":["无特殊。"],"treatment":["1.牢记基本思路：值班与急诊的区别在于独立决断——首要目标是及时发现并干预威胁生命的急症，而不是先弄清所有细节；2.先看生命体征再看病人一般状况，病房以病史为主、急诊以状态体征优先；3.精力管理：白天找时间睡觉，保证夜班反应敏捷；4.掌握对时间敏感的致命急症（ACS、心衰、肺栓塞、主动脉夹层、气胸、脑卒中、脑膜炎、休克等）的识别与处置；5.没把握及时请教上级、及时会诊——你是全院几百名医生之一，善用单位资源；6.任何检查结果都要亲自核对（看片、看化验原始值），与临床不符时追查到底。"],"management":["危重病人在检查与转运前充分评估风险，缩短脱离监护时间，转运中持续监测；及时与家属沟通病情与下一步。"],"notes":["清醒和冷静的头脑有时比技术更可靠；不要什么都试图在几个小时内查清——做该做的，超过能力及时上交；夜间能做的检查有限，留好退路减少纠纷。"],"emergency":["生命体征不稳定者立即进入抢救流程，同时呼叫支援。"],"pinyin":"jizhenyebanzhenliaojibensilu","icd10":"Z00-Z99","physical_exam":"接诊任何病人先看生命体征（血压、心率、呼吸、SpO2、体温），再一般状况，再做针对性查体。","lab_tests":"危重者同步抽血（血常规、生化、凝血、肌钙蛋白、血气、乳酸等）并床旁血糖心电图。","nursing":"配合快速完成监护、采血、输液建立与记录。","diet":"按病种处理（昏迷禁食，疑中毒留胃内容物送检等）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1223},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"de5480b9bd0b9c6ca41ed31a20b4e2d5c7ca65a3c2e31553cd3998c22509873f","pinyin":"jizhenyebanzhenliaojibensilu","initials":"jzybzljbsl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急症患者接诊：胸痛、呼吸困难、休克、意识改变、急腹症等。",60],["摘要","急诊/值班诊疗的核心思路：先处理威胁生命的问题再追究诊断（先开枪后瞄准）；任何病人先看生命体征；保持清醒冷静比技术更重要；及时求助不是丢人。",30],["疾病编码","Z00-Z99",30],["原首字母","jizhenyebanzhenliaojibensilu",60]]},{"id":"orders-046fe7972244bc7a5125","key":"v1-c9ccc21dfe2a3058|orders-046fe7972244bc7a5125","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"易漏诊的致命疾病警惕清单","category":"夜班临床经验","raw":{"name":"易漏诊的致命疾病警惕清单","category":"夜班临床经验","summary":"心中常备\"会死人的病\"清单以防漏诊：心肌梗死、心肌炎、急性胰腺炎、阑尾炎、宫外孕、肺栓塞、主动脉夹层、各类中毒等，遇到不典型表现主动排除。","symptoms":["不典型胸痛、腹痛、头晕、乏力、烦躁等易被低估的症状。"],"diagnosis":["思路要宽，不要按教科书年龄套病：年轻人也可能心梗/夹层，老人腹痛要警惕胆源性胰腺炎，育龄女性腹痛必查妊娠；症状\"四面不靠\"时考虑血管性疾病。"],"infusion":["可疑危重病尽早建立静脉通路，勿因等待确诊延误。"],"oral_medication":["无特殊。"],"treatment":["1.胸痛：ACS、主动脉夹层（双上肢血压差异/撕裂痛/放射性）、肺栓塞、气胸都要考虑，心电图动态对比；2.腹痛：胆绞痛肾绞痛多在夜间发作，初发者警惕阑尾炎，育龄女性一律排除宫外孕，老年+腹胀明显+症状体征不吻合考虑肠系膜血管病；3.意识改变/抽搐：立即测血糖；不明原因跌倒、反复问同一问题的创伤患者警惕颅脑损伤；4.有纹身者的心跳骤停想到毒品中毒，口唇红润的呼吸心跳停止想到氰化物中毒；5.静脉输头孢后饮酒发病——双硫仑样反应；6.头痛伴颈强直、新发神经体征按卒中/脑膜感染流程；7.把这张\"致命清单\"放在桌面或手机，随时提醒自己。"],"management":["对高度怀疑而暂无确诊依据的危重病，宁可多查多留观，交代复诊；记录鉴别诊断与排除依据。"],"notes":["漏诊多源于\"没想到\"——保持对致命疾病的高度敏感；症状解释不通时质疑自己的诊断；创伤后、术后、肿瘤患者注意肺栓塞；持续腹痛无固定压痛查肠系膜血管。"],"emergency":["出现休克、意识障碍、呼吸困难等不稳定征象立即按相应危重病流程抢救。"],"pinyin":"yilouzhendezhimingjibingjingtiqingdan","icd10":"Z00-Z99","physical_exam":"疼痛部位与性质的追问；颈静脉、双上肢血压、血管杂音、腹部压痛反跳痛、盆腔体征等。","lab_tests":"胸腹痛常规：心电图（动态复查）、肌钙蛋白、淀粉酶脂肪酶、D-二聚体、血HCG（育龄女性）、血气、乳酸等；影像按需。","nursing":"观察并报告疼痛性质变化、意识与生命体征波动。","diet":"疑消化道梗阻/胰腺炎禁食；疑中毒留取标本。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1224},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"151ff26324f511501941c95ca776740eb8d42a96f0ca6ce4ba45368695e18e8c","pinyin":"yilouzhendezhimingjibingjingtiqingdan","initials":"ylzdzmjbjtqd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","不典型胸痛、腹痛、头晕、乏力、烦躁等易被低估的症状。",60],["摘要","心中常备\"会死人的病\"清单以防漏诊：心肌梗死、心肌炎、急性胰腺炎、阑尾炎、宫外孕、肺栓塞、主动脉夹层、各类中毒等，遇到不典型表现主动排除。",30],["疾病编码","Z00-Z99",30],["原首字母","yilouzhendezhimingjibingjingtiqingdan",60]]},{"id":"orders-3f0623b563c155909db5","key":"v1-c9ccc21dfe2a3058|orders-3f0623b563c155909db5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"特殊人群与辅助检查细节","category":"夜班临床经验","raw":{"name":"特殊人群与辅助检查细节","category":"夜班临床经验","summary":"接诊特殊人群（青少年、育龄女性、老年人）与使用辅助检查的细节经验：确认年龄与禁忌、询问月经与妊娠、亲自读片对化验、勤做心电图。","symptoms":["年轻患者症状不典型、女性腹痛、老年人胸痛不典型、化验与临床不符等。"],"diagnosis":["年轻患者确认出生年月（18岁以下禁用喹诺酮），注意毒品/兴奋剂可能；所有育龄女性问末次月经并排除妊娠（见过13岁怀孕者，有家长陪同更不会说）；老年人+糖尿病者心梗可无胸痛。"],"infusion":["生命体征异常者建立静脉通路（血压>180或<90、心率>100、呼吸>30）。"],"oral_medication":["按年龄调整用药并核查禁忌（18岁以下喹诺酮、老年慎用抗胆碱药等）。"],"treatment":["1.年轻患者：确认真实年龄与身份信息，观察是否有毒品/兴奋剂相关表现并追问；2.女性：一律问月经史与妊娠可能，尤其腹痛者查HCG；3.勤做心电图（宁可错杀三千）：胸痛胸闷呼吸困难、生命体征异常（收缩压>180或<90、心率>100、呼吸>30）、发热者与老年患者必做，动态对比；4.亲自读影像原片与化验原始值，与报告不符主动和影像科/检验科沟通；5.老年人症状迟钝，胸痛不明显也按急性心梗流程排查；6.外伤后X线阴性也交代复查（肋骨、踝腕隐性骨折）。"],"management":["可疑结果复查与追踪；特殊人群（未成年人、妊娠可能）涉及知情同意与用药安全，记录清楚。"],"notes":["不要因为患者年轻或症状轻就跳过心电图与妊娠排查——这些是夜班最常见的漏诊来源；看片比看报告更能发现真相。"],"emergency":["老年/妊娠相关急症（心梗、宫外孕破裂等）立即按流程处理并呼叫相关专科。"],"pinyin":"teshurenqunyufuzhujianchaxijie","icd10":"Z00-Z99","physical_exam":"全面细致体检避免漏诊：皮肤痛觉过敏考虑带状疱疹早期，外伤者查脊柱压痛，女性腹痛查盆腔。","lab_tests":"化验结果与临床不符必须追查（如恶心呕吐却血钾高→查肾功发现肾衰）；影像学一定要自己看片不能只看报告，与影像科沟通。","nursing":"协助采集信息（如女性患者月经史由护士单独询问更易获得真实答案）。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1225},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"27b2dd16f264c88511c002d42bbc0fd4db894bcd3228743169a13203fb72eb60","pinyin":"teshurenqunyufuzhujianchaxijie","initials":"tsrqyfzjcxj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","年轻患者症状不典型、女性腹痛、老年人胸痛不典型、化验与临床不符等。",60],["摘要","接诊特殊人群（青少年、育龄女性、老年人）与使用辅助检查的细节经验：确认年龄与禁忌、询问月经与妊娠、亲自读片对化验、勤做心电图。",30],["疾病编码","Z00-Z99",30],["原首字母","teshurenqunyufuzhujianchaxijie",60]]},{"id":"orders-2df40b82aeb96040fa9d","key":"v1-c9ccc21dfe2a3058|orders-2df40b82aeb96040fa9d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"病历记录与病情交代沟通要点","category":"夜班临床经验","raw":{"name":"病历记录与病情交代沟通要点","category":"夜班临床经验","summary":"夜班病历记录与家属沟通的经验：勤记录病情变化、想在前面说在前面、充分告知不说过头话、细节医嘱（禁食水、侧卧等）要交代清楚并书面化。","symptoms":["夜间病情变化、危重告知、家属询问病情、知情同意等场景。"],"diagnosis":["梳理\"可能是什么病、可能出现什么问题、是否危重\"，据此决定告知内容与记录深度。"],"infusion":["心衰者记录24小时出入量并控制输液速度。"],"oral_medication":["给患者的服药与饮食医嘱逐条交代清楚（如禁食水者不能经口）。"],"treatment":["1.勤写病历：患者任何病情变化及时记录，\"好记性不如烂笔头\"；急诊记录要更勤快；2.想在前面说在前面：危重病人简单查体后即与家属沟通\"大概考虑什么、可能出现什么问题、是否危重\"，取得理解与信任（前提是专业过硬，否则容易打脸）；3.告知病情保持耐心，绝不对患者说\"你没病\"，逐条交代病情描述、诊疗计划并书面记录；4.细节医嘱不遗漏：肠梗阻/胰腺炎/消化道出血禁食水，尿路感染多喝水多排尿，心衰记出入量，昏迷/呕血/咯血者侧卧防窒息，并交代到护士与家属；5.知情同意书：操作/治疗前让患者认真阅读并解释关键风险，签好字再执行；6.病情告知与抢救同步，不因沟通延误抢救；7.面对质疑保持冷静，必要时请上级出面。"],"management":["抢救记录6小时内补记完整；死亡病例完善死亡记录与证明并通知太平间与家属；有纠纷苗头及时上报总住院。"],"notes":["家属要的是\"最明确的诊断和最好的治疗\"，做不到就坦诚并建议更合适机构/转诊，越早交代越少纠纷；告知内容与记录一致，避免前后矛盾。"],"emergency":["病情恶化或抢救时一边处置一边由专人向家属传递真实信息（按分阶段告知）。"],"pinyin":"binglijiluyubingqingjiaodaigoutongyaodian","icd10":"Z00-Z99","physical_exam":"每次评估生命体征与专科体征并即时记录。","lab_tests":"病情变化后及时复查关键指标（血气、血常规、电解质、心肌损伤标志物等）。","nursing":"护理记录与医嘱执行同步，病情变化第一时间报告医生并记录。","diet":"按病种交代禁食/饮食（同治疗要点）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1226},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"365791971ca74907e588e80400b8adb1c3d2233560d824b64c8e22757fe4e7b8","pinyin":"binglijiluyubingqingjiaodaigoutongyaodian","initials":"bljlybqjdgtyd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜间病情变化、危重告知、家属询问病情、知情同意等场景。",60],["摘要","夜班病历记录与家属沟通的经验：勤记录病情变化、想在前面说在前面、充分告知不说过头话、细节医嘱（禁食水、侧卧等）要交代清楚并书面化。",30],["疾病编码","Z00-Z99",30],["原首字母","binglijiluyubingqingjiaodaigoutongyaodian",60]]},{"id":"orders-d7b2d550897778ef0ad0","key":"v1-c9ccc21dfe2a3058|orders-d7b2d550897778ef0ad0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危重患者处理总流程与转院决策","category":"夜班临床经验","raw":{"name":"危重患者处理总流程与转院决策","category":"夜班临床经验","summary":"危重（可能危重）患者的标准处理步骤与转院决策：进抢救室→监护吸氧采血输液→动态评估与复查→能处理的处理、超出能力明确转院并交代风险。","symptoms":["意识障碍、休克、呼吸困难、剧烈胸腹痛、大出血等危重表现。"],"diagnosis":["按流程快速建立基本评估：生命体征、血糖、心电图、血气、常规血检，先稳定再确诊。"],"infusion":["开通静脉（按血糖决定盐水/糖水开路）；休克者快速补液（心衰/容量超负荷者审慎）；按流程给相应药物。"],"oral_medication":["不能口服者经胃管或静脉；按病种医嘱执行。"],"treatment":["1.可能危重者直接进抢救室：吸氧（百草枯中毒等禁忌除外）、监护、心电、床旁血糖、采血常规生化凝血肌钙蛋白血气、开静脉；2.血气几分钟出结果，据此调氧与判断酸碱/乳酸；呼吸衰竭先检查是否痰堵（颈部听诊、吸痰）；3.心电图有异常或症状为胸痛胸闷者反复复查动态对比；4.不同危重病有相应流程（胸痛、呼吸困难、急腹症、头痛、昏迷、高血压、休克等），把流程放桌面/手机随时查阅；5.及时处理症状与不平稳指标，动态复查异常结果；6.超出预计或需进一步检查治疗而本单位条件不足（如夜间无法做血管造影、不能处理心梗夹层）→和家属沟通并转上级医院（即使自己已是顶级也要如实告知）；7.注意力始终放在最危重者身上，必要时先转移次要工作。"],"management":["制定本院急危重症处理流程并培训；疑难重症组织多科会诊；记录处理时间线（door-to-…）。"],"notes":["你不是钢铁侠——急诊只是全院几十个科室之一，超过能力范围及时上报转诊并不丢人；家属要求\"最明确诊断最好治疗\"做不到时坦诚并引导到能提供该条件的机构。"],"emergency":["随时准备气管插管、除颤、心肺复苏并按流程呼叫支援。"],"pinyin":"weizhonghuanzhechulizongliuchengyuzhuanyuanjuece","icd10":"Z00-Z99","physical_exam":"气道呼吸循环快速评估，意识与瞳孔，胸腹重点查体。","lab_tests":"常规+生化+凝血+肌钙蛋白+BNP+血气+乳酸；床旁血糖心电图即刻完成。","nursing":"抢救站位分工明确；准备抢救车与仪器；记录医嘱执行与时间。","diet":"按病情（昏迷禁食等）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1227},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"928f03aa2ea5eed871a2e3c5820a13a9a69f20d214d588795b766ee0c73def19","pinyin":"weizhonghuanzhechulizongliuchengyuzhuanyuanjuece","initials":"wzhzclzlcyzyjc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","意识障碍、休克、呼吸困难、剧烈胸腹痛、大出血等危重表现。",60],["摘要","危重（可能危重）患者的标准处理步骤与转院决策：进抢救室→监护吸氧采血输液→动态评估与复查→能处理的处理、超出能力明确转院并交代风险。",30],["疾病编码","Z00-Z99",30],["原首字母","weizhonghuanzhechulizongliuchengyuzhuanyuanjuece",60]]},{"id":"orders-d45435b2fd63cacca384","key":"v1-c9ccc21dfe2a3058|orders-d45435b2fd63cacca384","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班前准备、睡眠与精力管理","category":"夜班临床经验","raw":{"name":"夜班前准备、睡眠与精力管理","category":"夜班临床经验","summary":"夜班前的身体与物资准备及夜班后恢复经验：还清睡眠债务、吃好营养、适度咖啡因、夜班前了解病人、下夜班认真补觉恢复。","symptoms":["夜班疲劳、注意力下降、下夜班后入睡困难等。"],"diagnosis":["认识睡眠不足对判断力的影响，主动管理作息。"],"infusion":["无特殊。"],"oral_medication":["夜班前可适量咖啡浓茶提神，夜班后半程避免刺激性饮料以免下夜班睡不着。"],"treatment":["1.上夜班前还清睡眠债务，勿仗年轻透支；2.吃好：高蛋白、高维生素、水果坚果奶制品谷物，别空肚熬夜；3.咖啡因管理：前半程适量，后半程停；4.接夜班时认真交班：病人诊断、状态、特殊要求、床号，重点掌握从ICU转回的患者（最可能夜间出状况）；5.趁夜间空档了解危重患者病情，做到心中有数，随时能第一时间处置；6.夜班睡眠：能睡就睡透（拉好窗帘、告知不要打扰），避免忽醒忽睡增加心脏负担；7.该出手就出手，同时清楚能力边界，不会的就求助；8.下夜班务必睡觉补觉，不要透支身体去娱乐。"],"management":["科室可建立夜班支持与轮休制度，保障医师休息与健康。"],"notes":["健康是第一位的——反复熬夜不补觉可致心血管风险增高；睡眠债务要及时偿还；夜班前把生活安排妥当（通知家人不要打扰补觉）。"],"emergency":["夜班期间突发身体不适（心慌胸痛晕厥等）立即求助同事代班并就医。"],"pinyin":"yebanqianzhunbei、shuimianyujingliguanli","icd10":"Z00-Z99","physical_exam":"无特殊（自我健康监测：持续疲劳/心悸不适及时体检）。","lab_tests":"无特殊。","nursing":"医护共同关注值班健康，互相提醒补觉与轮换。","diet":"夜班加餐清淡均衡，避免高糖油炸；多饮水（\"多喝热水\"也是提神护胃的实在办法）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1228},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9feb18ff917ac4b0b2ab2330089a84e9e8b2590c76f7cac386fbbd3f9df566f0","pinyin":"yebanqianzhunbei、shuimianyujingliguanli","initials":"ybqzb、smyjlgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜班疲劳、注意力下降、下夜班后入睡困难等。",60],["摘要","夜班前的身体与物资准备及夜班后恢复经验：还清睡眠债务、吃好营养、适度咖啡因、夜班前了解病人、下夜班认真补觉恢复。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanqianzhunbei、shuimianyujingliguanli",60]]},{"id":"orders-d3529387a6fd9cc03c6b","key":"v1-c9ccc21dfe2a3058|orders-d3529387a6fd9cc03c6b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"值班协作与求助时机","category":"夜班临床经验","raw":{"name":"值班协作与求助时机","category":"夜班临床经验","summary":"夜班工作中与同事（麻醉、ICU、护士、影像检验）协作及把握求助时机的经验：关系是救命的资源，交班是安心的前提，求助要分清轻重急缓。","symptoms":["夜班需要会诊、插管、转科、上级指导等协作场景。"],"diagnosis":["评估问题是否超出自身能力与科室资源，判断是否立即求助。"],"infusion":["无特殊。"],"oral_medication":["无特殊。"],"treatment":["1.平时与麻醉科、ICU搞好关系：危机关头插管、抢救、收治可能决定病人生死；2.与值班护士多沟通病情与床位安排，护理观察是夜间最早发现变化的眼睛；3.交班要细致：把病情、状态、特殊要求、行迹了然于胸，尤其ICU转回与手术后患者；4.求助时机：自己不会的、没见过的、病情超出预计的、反复处理无效的都要及时求助，病人的生命胜过面子；5.求助前整理好资料与问题，让上级高效决策；6.别因琐事反复打扰（会成\"狼来了\"），但急症要立即呼叫不管面子上级是否在休息；7.能分担的互相帮一把，形成团队默契。"],"management":["建立值班通信录与支援流程；会诊与转科有记录；次日交班延续处理。"],"notes":["夜班不是一个人的战斗——善用医院资源与团队；求助不是能力差的表现，硬撑才是隐患。"],"emergency":["遇重大抢救或突发公共卫生事件立即启动应急预案并通知总值班。"],"pinyin":"zhibanxiezuoyuqiuzhushiji","icd10":"Z00-Z99","physical_exam":"求助前先做基本查体与检查，让上级/会诊医生来了就能决策。","lab_tests":"呼叫会诊前先完成可及的检查（心电图、血常规、影像等）提高效率。","nursing":"医护信息互通：护士发现异常立即通知并协助评估。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1229},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"93961492c86873f6e915a0bc88ffaa8d98a73b3ab758d398251a5a16cc58f8f4","pinyin":"zhibanxiezuoyuqiuzhushiji","initials":"zbxzyqzsj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜班需要会诊、插管、转科、上级指导等协作场景。",60],["摘要","夜班工作中与同事（麻醉、ICU、护士、影像检验）协作及把握求助时机的经验：关系是救命的资源，交班是安心的前提，求助要分清轻重急缓。",30],["疾病编码","Z00-Z99",30],["原首字母","zhibanxiezuoyuqiuzhushiji",60]]},{"id":"orders-eb19e77838956c5757b1","key":"v1-c9ccc21dfe2a3058|orders-eb19e77838956c5757b1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班医疗安全与风险防范","category":"夜班工作管理","raw":{"name":"夜班医疗安全与风险防范","category":"夜班工作管理","summary":"夜班期间医疗安全与风险防范要点：执行核心制度（查对、交接、请示汇报）、合理用药防差错、规范操作防院感、识别纠纷苗头及时上报、做好自身职业防护。","symptoms":["夜班独自面对危重病人、用药用械环节多、医护人手少、潜在医疗纠纷等风险场景。"],"diagnosis":["识别高风险环节：新入院/术后/ICU转回/高龄/多病共存患者，抗凝、胰岛素、血管活性药等高危药物使用，气管插管与中心静脉等有创操作。"],"infusion":["静脉用药严格执行三查七对与双人核对（高危药品尤其）；泵入药物标注名称浓度时间并定时核对泵速。"],"oral_medication":["口服药发药核对姓名床号药名剂量；新开药与既往医嘱核对相互作用与重复给药。"],"treatment":["1.严格落实交接班制度：床旁交接危重/新入/手术/特殊检查患者，交病情、交治疗、交代办事项，双方确认；2.请示汇报制度：危重、疑难、诊断不明或处置效果不好及时请示总住院/上级，重大抢救与突发情况上报总值班；3.查对制度：医嘱执行、输血、手术等均双人核对；4.合理用药：按剂量适应症给药，特殊人群（老年、肾功不全、孕产）调量，警惕双硫仑、药物相互作用；5.无菌操作与院感防控：手卫生、无菌置管、导管管理、耐药菌隔离；6.高危患者管理：防跌倒坠床、约束规范记录、压疮预防、深静脉血栓预防；7.纠纷防范：及时规范记录、充分告知、避免推诿，纠纷苗头第一时间上报并保留证据；8.自身防护：锐器伤、血源性暴露处理流程熟知，必要时暴露后预防。"],"management":["科室建立夜班风险清单与应急预案（抢救、停电、火灾、突发公共卫生事件）；不良事件及时上报分析，改进流程。"],"notes":["医疗安全靠制度不靠记性：查对、交接、请示是夜班三条生命线；记录是保护患者也是保护自己；职业暴露重在预防与及时规范处置。"],"emergency":["重大抢救、群体伤、突发公共卫生事件立即启动应急预案并上报；纠纷升级冲突报警并请安保介入。"],"pinyin":"yebanyiliaoanquanyufengxianfangfan","icd10":"Z00-Z99","physical_exam":"操作前核对患者身份与部位；用药前核对剂量、途径、过敏史。","lab_tests":"高危药物（华法林、肝素、氨基糖苷等）按需监测INR、APTT、血药浓度与肾功能；电解质血糖按需复查。","nursing":"医护共同执行查对与交接；护理观察异常第一时间反馈医生并记录。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1230},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"079b480efb8510bba839843d49ba4cd75aafb8f0374fcf25ca94bbcd7f612474","pinyin":"yebanyiliaoanquanyufengxianfangfan","initials":"ybylaqyfxff","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜班独自面对危重病人、用药用械环节多、医护人手少、潜在医疗纠纷等风险场景。",60],["摘要","夜班期间医疗安全与风险防范要点：执行核心制度（查对、交接、请示汇报）、合理用药防差错、规范操作防院感、识别纠纷苗头及时上报、做好自身职业防护。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanyiliaoanquanyufengxianfangfan",60]]},{"id":"orders-25c63e43cfc9409c6816","key":"v1-c9ccc21dfe2a3058|orders-25c63e43cfc9409c6816","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜间病情告知与知情同意","category":"夜班工作管理","raw":{"name":"夜间病情告知与知情同意","category":"夜班工作管理","summary":"夜间向患者/家属交代病情与签署知情同意的规范流程：全面了解病情后再告知、分阶段告知坏消息、知情同意书认真讲解签字、死亡与尸检告知等。","symptoms":["夜间需告知病情、手术/有创操作需知情同意、患者去世需告知家属等场景。"],"diagnosis":["告知前先全面掌握病情（诊断、检查结果、治疗方案与预后），评估家属理解能力与心理准备。"],"infusion":["无特殊。"],"oral_medication":["无特殊。"],"treatment":["1.交代病情前必须全面了解患者病情（未经培训者先观察学习），避免一问三不知激化矛盾；2.在合适、安静、不被打扰的环境告知，语言通俗，先讲重点（诊断与风险）再讲计划；3.坏消息分阶段措辞，给家属心理缓冲：（1）病情较重正在积极处理→（2）效果不佳风险较大→（3）正做最后努力→（4）已经离世；4.允许家属宣泄情绪但控制局面，人多时安排部分家属协助安抚；5.知情同意书：让患者/家属认真阅读，逐条讲解操作目的、过程、风险与替代方案，确认理解后签字，注明时间；6.抢救性操作（气管插管、深静脉等）紧急时口头知情并补记；7.死亡患者：规范宣布死亡、清理管路、填写死亡记录与证明，通知太平间，动员尸体解剖并尊重家属意见；8.告知后提供力所能及的帮助，解答疑问；涉及潜在纠纷及时通知总住院。"],"management":["记录告知内容、时间与在场人员；重大决策（放弃抢救、DNR）以文字形式记录并家属签字；安排后续沟通与善后。"],"notes":["知情同意的本质是让患者明明白白选择，签字前讲解比签字本身重要；告知与记录要一致，避免家属事后对质时前后矛盾；善后处理（死亡证明、太平间）流程提前熟悉。"],"emergency":["紧急有创抢救需立即实施时口头告知家属并同步操作，事后补知情与记录。"],"pinyin":"yejianbingqinggaozhiyuzhiqingtongyi","icd10":"Z00-Z99","physical_exam":"告知前完成必要的查体与复核，确保信息准确。","lab_tests":"拿到关键检查结果（影像、化验）核对无误再行告知。","nursing":"协助通知与安抚家属，见证签字过程；死亡料理按规范配合。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1231},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3a5d03cd0113be2c55bd1fd5c4c0380de3c0f40436992cf5665c966f085c9628","pinyin":"yejianbingqinggaozhiyuzhiqingtongyi","initials":"yjbqgzyzqty","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","夜间需告知病情、手术/有创操作需知情同意、患者去世需告知家属等场景。",60],["摘要","夜间向患者/家属交代病情与签署知情同意的规范流程：全面了解病情后再告知、分阶段告知坏消息、知情同意书认真讲解签字、死亡与尸检告知等。",30],["疾病编码","Z00-Z99",30],["原首字母","yejianbingqinggaozhiyuzhiqingtongyi",60]]},{"id":"orders-a40beccefb4160c6c16f","key":"v1-c9ccc21dfe2a3058|orders-a40beccefb4160c6c16f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"低血容量性休克处理流程","category":"夜班急症流程","raw":{"name":"低血容量性休克处理流程","category":"夜班急症流程","summary":"因大量出血或体液丢失（失血、呕吐腹泻、烧伤、第三间隙）致有效循环血量锐减的休克处理：快速评估、尽快建立通路快速补液、配血输血、处理出血原因并监测复苏指标。","symptoms":["面色苍白、表情淡漠或烦躁、口渴、皮肤湿冷、脉搏细速、脉压减小、血压下降、尿量减少。"],"diagnosis":["结合病史（出血/丢失）与体征诊断；血压下降较晚（代偿期脉快尿少皮肤冷先出现）；注意隐性失血（腹腔、腹膜后、骨折）；血细胞比容<0.25或Hb<60g/L时需补红细胞。"],"infusion":["快速补液：首个半小时平衡液1500ml，可加快；失血者尽早输红细胞（Hb<70g/L或休克持续），大量输血按1:1:1补红细胞/血浆/血小板并防低钙低体温；可用羟乙基淀粉/右旋糖酐或白蛋白（量有限）扩容，但晶体为首选。"],"oral_medication":["无（休克期禁食水）。"],"treatment":["1.平卧或低半卧位、保暖、吸氧、心电监护、建立两条以上大口径静脉通路；2.立即评估并快速补液（生理盐水或平衡液500-1000ml快速静滴）——先快后慢，CVP与血压回升后减慢（CVP<6cmH2O提示容量不足）；3.失血性休克寻找并控制出血（加压包扎、骨盆带、手术/介入止血、内镜等）；4.每15-30分钟评估血压心率尿量CVP与乳酸调整输液；5.血压持续不升且已充分补液者可加血管活性药（去甲肾上腺素0.05-0.5μg/kg/min静滴泵入）过渡，但勿用血管活性药替代补液；6.纠正电解质酸碱与低体温，防稀释性凝血病；7.处理原发病（消化道出血、创伤、烧伤、感染等）；8.转运途中持续监护。"],"management":["留置导尿记录每小时尿量（目标>0.5ml/(kg·h)）；动态Hb/乳酸/CVP；重症转ICU或手术室。"],"notes":["补液不足是低血容量休克最常见死因，但心功能不全者快速补液需监测肺水肿；血管活性药不能替代容量复苏；警惕失血被低估（年轻人代偿强）。"],"emergency":["血压测不到、意识丧失、活动性大出血→立即快速补液输血并止血，必要时按压/止血带同时呼救手术团队。"],"pinyin":"dixuerongliangxingxiukechuliliucheng","icd10":"R57.1","physical_exam":"神志、心率血压脉压、皮肤弹性温度、毛细血管充盈、尿量、腹部与骨折等出血来源、CVP。","lab_tests":"血常规动态、血型交叉配血、凝血、电解质、肾功能、血气乳酸（评估灌注）；急诊超声（游离液）；出血来源影像按需。","nursing":"保暖防寒战；记录出入量与尿量每小时；观察皮肤色泽温度与末梢循环；配血与输血护理（核对、观察反应）；协助止血包扎。","diet":"休克期禁食水；意识恢复后可饮水，防误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1232},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"85dba70cacda962967d9e6372b7d6882747f0fbc4de6da56dd173d6c5efe6841","pinyin":"dixuerongliangxingxiukechuliliucheng","initials":"dxrlxxkcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","面色苍白、表情淡漠或烦躁、口渴、皮肤湿冷、脉搏细速、脉压减小、血压下降、尿量减少。",60],["摘要","因大量出血或体液丢失（失血、呕吐腹泻、烧伤、第三间隙）致有效循环血量锐减的休克处理：快速评估、尽快建立通路快速补液、配血输血、处理出血原因并监测复苏指标。",30],["疾病编码","R57.1",30],["原首字母","dixuerongliangxingxiukechuliliucheng",60]]},{"id":"orders-1e4d9ba73e77d9dcbefb","key":"v1-c9ccc21dfe2a3058|orders-1e4d9ba73e77d9dcbefb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"心源性休克处理流程","category":"夜班急症流程","raw":{"name":"心源性休克处理流程","category":"夜班急症流程","summary":"心脏泵功能衰竭致心输出量下降、组织低灌注的休克（多继发急性心梗）：去枕平卧、监护、强心升压与病因再灌注治疗，机械循环支持评估。","symptoms":["焦虑烦躁、表情淡漠或嗜睡、面色苍白、四肢湿冷、脉搏细速、尿量<30ml/h、收缩压<80-90mmHg、脉压<20mmHg、呼吸急促；有原发心脏病（急性心梗最常见）。"],"diagnosis":["根据低血压+组织低灌注+原发心脏病（心梗/心肌病/瓣膜病/心包填塞等）诊断；心电图与肌钙蛋白明确心梗；超声评估左室功能、有无机械并发症（乳头肌断裂、室间隔穿孔）与心包积液。"],"infusion":["补液需谨慎：无肺淤血者可先小量试补（250-500ml），有肺水肿者避免扩容而予利尿；升压：去甲肾上腺素（缩血管维持灌注）或多巴胺；正性肌力：多巴酚丁胺（2.5-10μg/(kg·min)）、米力农（低血压者慎用）等；利尿：呋塞米（容量负荷重者）。"],"oral_medication":["血流动力学稳定后序贯口服心衰药物；急性期以静脉为主（停用负性肌力药）。"],"treatment":["1.去枕平卧、吸氧、心电监护，建立静脉通路；2.明确并解除可逆病因：急性心梗尽早再灌注（PCI首选，溶栓备选）、心包填塞穿刺引流、快速心律失常复律、严重心动过缓起搏、瓣膜/机械并发症手术评估；3.药物支持：先用去甲肾上腺素0.05-0.5μg/kg/min或多巴胺5-20μg/kg/min静滴泵入维持MAP≥65mmHg，心输出量仍低加多巴酚丁胺2-20μg/kg/min静滴；4.容量管理：按有无淤血个体化，CVP/超声指导；5.机械循环支持：药物难治者评估主动脉内球囊反搏（IABP）或ECMO（有条件的中心）；6.纠正电解质酸中毒、控制血糖；7.镇痛镇静、防心律失常；8.请心内科/ICU会诊，评估转有介入条件医院。"],"management":["ICU监护：血压（有创）、心率心律、尿量、CVP/肺动脉楔压、乳酸与血气动态；超声随访；记录用药泵速。"],"notes":["心源性休克补液过度比不足更危险（易肺水肿），小量试补+监测；正性肌力药增加氧耗，剂量个体化；去甲肾上腺素在灌注压低时可维持冠脉灌注；血管活性药仅是桥接，根本在再灌注与病因处理。"],"emergency":["血压骤降、室速室颤→按ACLS流程并准备机械循环支持与再灌注。"],"pinyin":"xinyuanxingxiukechuliliucheng","icd10":"R57.0","physical_exam":"神志、血压心率、颈静脉怒张（右心/肺水肿）、肺部啰音、奔马律、心包摩擦音、四肢温度、尿量。","lab_tests":"心肌损伤标志物、BNP、血气乳酸、电解质、肾功能、血常规；心电图动态、床旁超声、胸片。","nursing":"严格卧床减少心肌耗氧；持续心电血压监护；记录出入量尿量；观察末梢循环与神志；输液泵管理；防压疮。","diet":"急性期禁食或少食（防呕吐误吸），稳定后低盐低脂心衰饮食。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1233},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e7a16e9ad6160d4ac30f9443e8da44c37016b7610cad8319efdccea8630fea51","pinyin":"xinyuanxingxiukechuliliucheng","initials":"xyxxkcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","焦虑烦躁、表情淡漠或嗜睡、面色苍白、四肢湿冷、脉搏细速、尿量<30ml/h、收缩压<80-90mmHg、脉压<20mmHg、呼吸急促；有原发心脏病（急性心梗最常见）。",60],["摘要","心脏泵功能衰竭致心输出量下降、组织低灌注的休克（多继发急性心梗）：去枕平卧、监护、强心升压与病因再灌注治疗，机械循环支持评估。",30],["疾病编码","R57.0",30],["原首字母","xinyuanxingxiukechuliliucheng",60]]},{"id":"orders-a0c620da70a8c628d4fb","key":"v1-c9ccc21dfe2a3058|orders-a0c620da70a8c628d4fb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"感染性休克处理流程","category":"夜班急症流程","raw":{"name":"感染性休克处理流程","category":"夜班急症流程","summary":"脓毒症伴循环衰竭（MAP<65mmHg、乳酸升高）的早期目标导向处理：1小时内完成乳酸、血培养与广谱抗生素，快速补液，去甲肾上腺素为一线升压，按EGDT目标动态调整并处理感染灶。","symptoms":["感染基础（发热>39℃或不升、畏寒寒战）或低体温、皮肤湿冷或花斑、嗜睡躁动、脉搏细速、脉压减小、血压下降、尿量减少；重者意识障碍。"],"diagnosis":["疑似感染+SOFA/qSOFA恶化或乳酸>2mmol/L+需要升压维持MAP≥65mmHg（充分液体复苏后）；积极寻找感染灶（肺、腹腔、泌尿、导管、皮肤软组织）。"],"infusion":["补液：3小时内晶体液（平衡液/生理盐水）30ml/kg快速补液（心肾不全者个体化），持续评估（被动抬腿试验、超声/乳酸）；升压：去甲肾上腺素为首选（经中心静脉泵入，0.05-0.5μg/(kg·min)起调，目标MAP≥65mmHg），效果不佳可加用血管加压素或肾上腺素；多巴酚丁胺用于心输出量低而血压可维持者。"],"oral_medication":["无（休克期静脉为主，能口服者按病情）。"],"treatment":["1.第1小时集束化：测乳酸→血培养→广谱抗生素（覆盖革兰阴性菌，结合部位与耐药史）→开始液体复苏；2.充分补液后再评估MAP，<65mmHg启动去甲肾上腺素；3.目标：MAP≥65mmHg、乳酸下降、尿量>0.5ml/(kg·h)、ScvO2≥70%（低者考虑输血至Hct>30%与多巴酚丁胺）；4.控制感染源：脓肿引流、导管拔除、腹腔感染手术等尽早进行；5.呼吸：低氧或呼吸窘迫者放宽气管插管指征（无创/有创通气，肺保护策略）；6.严重代谢性酸中毒多在改善灌注后纠正，仍不能纠正考虑血液滤过（CVVH）；7.糖皮质激素：充分补液升压后仍依赖大剂量升压药者予氢化可的松200-300mg/d（分次）；8.凝血问题（DIC、血小板减少）按DIC处理；9.血糖控制、预防应激性溃疡与VTE。"],"management":["每30-60分钟评估MAP、乳酸、尿量；持续监测CVP/ScvO2（EGDT早期）；重症转ICU；记录复苏时间线（1/3/6小时集束化）。"],"notes":["先补液后升压，但勿因补液无限延误升压——两者可同步；经验性抗生素越早越好，1小时内是金标准；去甲肾上腺素相比多巴胺心律失常更少、疗效可能更优；每日评估感染源与降阶梯。"],"emergency":["严重休克、呼吸衰竭、难治性低血压→强化复苏并转ICU，必要时机械循环/CRRT支持。"],"pinyin":"ganranxingxiukechuliliucheng","icd10":"R57.2","physical_exam":"神志、体温、血压（MAP）、心率呼吸、皮肤灌注与花斑、尿量、感染灶体征（肺部啰音、腹部压痛、导管入口）。","lab_tests":"血乳酸（动态）、血培养（抗生素前双瓶）、血常规、CRP/PCT、凝血DIC筛查、肝肾功电解质、血气、影像（胸片/超声/CT）定位感染灶。","nursing":"保暖或物理降温按体温；记录出入量与每小时尿量；中心静脉导管护理；采集血培养（抗生素前）；观察皮肤花斑与肢端温度。","diet":"休克期暂禁食（肠内营养在血流动力学稳定后尽早启动）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1234},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ba6ee29ca2b2ccd9050f9c7343e1e188c4cd049c0d9dc1a80d0a9f897d376b0d","pinyin":"ganranxingxiukechuliliucheng","initials":"grxxkcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","感染基础（发热>39℃或不升、畏寒寒战）或低体温、皮肤湿冷或花斑、嗜睡躁动、脉搏细速、脉压减小、血压下降、尿量减少；重者意识障碍。",60],["摘要","脓毒症伴循环衰竭（MAP<65mmHg、乳酸升高）的早期目标导向处理：1小时内完成乳酸、血培养与广谱抗生素，快速补液，去甲肾上腺素为一线升压，按EGDT目标动态调整并处理感染灶。",30],["疾病编码","R57.2",30],["原首字母","ganranxingxiukechuliliucheng",60]]},{"id":"orders-78b8381ceda4b9c90252","key":"v1-c9ccc21dfe2a3058|orders-78b8381ceda4b9c90252","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"输血反应处理流程","category":"夜班急症流程","raw":{"name":"输血反应处理流程","category":"夜班急症流程","summary":"输血中或输血后出现的发热、过敏、溶血、循环超负荷等反应的处理：立即停止输血并保留血袋与标本，评估类型（发热/过敏/急性溶血/TACO/TRALI），按类型处理并上报。","symptoms":["输血中出现发热寒战、恶心呕吐、头痛、脉速（发热反应）；或皮肤瘙痒荨麻疹、喉头水肿、支气管痉挛（过敏）；腰痛、酱油色尿、血压骤降（急性溶血）；胸闷气促、咳粉红色痰、肺水肿（循环超负荷/TRALI）。"],"diagnosis":["立即判断反应类型：发热反应（常见，T≥38℃伴寒战）；过敏反应（皮疹荨麻疹，重者过敏性休克）；急性溶血反应（最凶险：腰痛、发热、低血压、DIC、肾功能衰竭）；循环超负荷（快速大量输注+心肺基础）；输血相关急性肺损伤（TRALI：输血6小时内低氧双肺浸润）。"],"infusion":["发热反应：可予物理降温与抗组胺/解热（避免抑制体温掩盖溶血）；过敏：苯海拉明、激素，重者肾上腺素（0.5mg肌注）并按过敏性休克处理；急性溶血：立即停止输血、碱化利尿（碳酸氢钠、呋塞米）、补液维持尿量、按DIC与肾衰处理、换血考虑。"],"oral_medication":["按反应类型对症给药（抗组胺口服用于轻过敏等）。"],"treatment":["1.怀疑输血反应立即停止输血（保留静脉通路换输生理盐水），保留剩余血液与输血器、血袋送检，抽血复查血型交叉与相关化验；2.通知输血科与上级，核对供受者信息（错误输注最常见原因）；3.发热反应：减慢/停输（轻度可对症后继续严密观察），寒战时保暖；4.过敏反应：轻症抗组胺（苯海拉明25-50mg肌注或静推）；重症按过敏性休克（肾上腺素0.3-0.5mg肌注、甲泼尼龙40-80mg静推、补液、气道支持）；5.急性溶血性反应：停输、积极补液利尿、碱化尿液保护肾功、纠正DIC、必要时血液净化；6.循环超负荷（TACO）：停止/减速输血、利尿（呋塞米20-40mg静推）、半坐位、吸氧，必要时无创通气；7.TRALI：按ARDS肺保护通气支持；8.记录并填写输血不良反应回报表，追踪原因（细菌污染、Rh不合等）。"],"management":["输血全过程监护（开始15分钟最慢速观察）；反应发生后连续监测尿量尿色、肾功能与凝血；输血科调查回报。"],"notes":["预防为主：严格核对身份血型、慢速开始观察；发热反应很常见但必须首先排除溶血（溶血可伴发热）；TRALI与TACO鉴别（TRALI无容量超负荷但低氧明显）；任何反应都要留标本与记录。"],"emergency":["急性溶血、过敏性休克、TRALI呼吸衰竭时立即按相应抢救流程并呼叫支援。"],"pinyin":"shuxuefanyingchuliliucheng","icd10":"T80.0","physical_exam":"生命体征、皮肤（皮疹荨麻疹）、心肺（啰音肺水肿）、腰痛与尿色、神志。","lab_tests":"立即复查血型与交叉配血（原标本+新采血）、血常规（Hb、血小板）、血浆游离血红蛋白、直接抗球蛋白试验（Coombs）、尿常规（血红蛋白尿）、凝血（DIC）、肾功能、血气；核对输血记录。","nursing":"输血前双人核对并测体温；开始15分钟慢速并观察；记录输血时间、量与反应时间；反应时保留血袋血标本；安慰患者。","diet":"无特殊。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1235},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"15b9cfc150d7d7ca50ece40b293b05b4850c9d91996472b2cda98bd0718a90a4","pinyin":"shuxuefanyingchuliliucheng","initials":"sxfycllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","输血中出现发热寒战、恶心呕吐、头痛、脉速（发热反应）；或皮肤瘙痒荨麻疹、喉头水肿、支气管痉挛（过敏）；腰痛、酱油色尿、血压骤降（急性溶血）；胸闷气促、咳粉红色痰、肺水肿（循环超负荷/TRALI）。",60],["摘要","输血中或输血后出现的发热、过敏、溶血、循环超负荷等反应的处理：立即停止输血并保留血袋与标本，评估类型（发热/过敏/急性溶血/TACO/TRALI），按类型处理并上报。",30],["疾病编码","T80.0",30],["原首字母","shuxuefanyingchuliliucheng",60]]},{"id":"orders-81c90ea6d6baaf3eee1f","key":"v1-c9ccc21dfe2a3058|orders-81c90ea6d6baaf3eee1f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"空气栓塞处理流程","category":"夜班急症流程","raw":{"name":"空气栓塞处理流程","category":"夜班急症流程","summary":"输液/输血或中心静脉操作时空气进入循环所致急症：突发胸痛、呼吸困难、发绀、循环衰竭，处理为立即关闭通路、左侧卧位头低足高、吸氧与对症支持。","symptoms":["输液/输血或中心静脉置管拔管时突发胸部不适、呼吸困难、严重发绀、血压下降、心率快，听诊心前区可闻响亮持续的水泡样杂音（车轮样杂音）；大者致循环骤停。"],"diagnosis":["根据操作背景与典型症状听诊诊断；可查超声/影像辅助；需紧急处理勿等待确诊。"],"infusion":["立即停止输注并关闭输液/输血通路；改为左侧卧位头低足高位（使气泡停留右心/防入肺动脉）；高浓度吸氧；必要时中心静脉抽吸右心气体。"],"oral_medication":["按症状给予镇静、解痉等对症（严格遵医嘱）。"],"treatment":["1.立即关闭输液/输血通路（同时保留静脉通路以备给药）；2.左侧卧位、头低足高位（Durant体位）减少空气进入肺循环；3.高流量吸氧（纯氧）促进气栓吸收；4.心电监护、快速评估（必要时呼气末正压通气）；5.症状明显者可由中心静脉导管尝试抽吸右心房气体；6.对症：呼吸抑制者气管插管机械通气、低血压者补液升压、惊厥者抗惊厥；7.重症转高压氧舱治疗（气体栓塞有效手段，有条件时）；8.观察神经症状（脑气栓）并请专科。"],"management":["持续监护生命体征与SpO2；记录发生时间、进气量估计与处理；重症随访神经功能。"],"notes":["重在预防：输液器排尽管内空气、中心静脉置管/拔管规范（呼气相拔管按压穿刺点、Trendelenburg位）、加压输注时专人看守；一旦发生保持镇静按流程处理。"],"emergency":["循环骤停立即CPR；严重低氧呼吸衰竭气管插管并呼救高压氧。"],"pinyin":"kongqishuansaichuliliucheng","icd10":"T80.0","physical_exam":"生命体征与SpO2、心肺听诊（心前区水泡音）、神志、发绀程度。","lab_tests":"血气（低氧）、心电图；床旁超声可能见心腔内气泡；处理优先于检查。","nursing":"发现异常立即夹闭输液并呼叫医生；协助摆左侧头低足高位；监测血氧与神志。","diet":"无特殊（监护期禁食）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1236},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ebc6bc16b436ef045b02a63b3f4f028c66644f042d0a4f7b032d4fbdd03c85ba","pinyin":"kongqishuansechuliliucheng","initials":"kqsscllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","输液/输血或中心静脉置管拔管时突发胸部不适、呼吸困难、严重发绀、血压下降、心率快，听诊心前区可闻响亮持续的水泡样杂音（车轮样杂音）；大者致循环骤停。",60],["摘要","输液/输血或中心静脉操作时空气进入循环所致急症：突发胸痛、呼吸困难、发绀、循环衰竭，处理为立即关闭通路、左侧卧位头低足高、吸氧与对症支持。",30],["疾病编码","T80.0",30],["原首字母","kongqishuansaichuliliucheng",60]]},{"id":"orders-12ce5cc9431725cfcd02","key":"v1-c9ccc21dfe2a3058|orders-12ce5cc9431725cfcd02","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"高钾血症处理流程","category":"夜班急症流程","raw":{"name":"高钾血症处理流程","category":"夜班急症流程","summary":"血清钾>5.5mmol/L（严重者>6.5mmol/L）伴心电图改变的紧急处理：稳定心肌（钙剂）、促钾内移（胰岛素+葡萄糖、碳酸氢钠、β2激动剂）、促钾排出（利尿、树脂、透析）三步走，寻找并处理病因。","symptoms":["肌无力呈上行性（四肢→躯干→呼吸肌）、肢端麻木、乏力、恶心、心率慢或心律失常；可无症状仅化验发现；心电图示T波高尖、P波消失、QRS增宽，严重者心脏停搏。"],"diagnosis":["根据血钾（血清钾>5.5mmol/L）与心电图诊断；严重程度分级：轻度5.5-6.0、中度6.0-6.5、重度>6.5或伴心电图改变；寻找病因：肾功能衰竭、保钾利尿剂/ACEI/ARB/NSAIDs、酸中毒、横纹肌溶解、溶血、大量输血、补钾过量、醛固酮减少等。"],"infusion":["稳定心肌：10%葡萄糖酸钙10-20ml缓慢静推（2-5分钟，心电监护，洋地黄者慎）；促内移：胰岛素10U+50%葡萄糖50ml静滴（监测血糖）或25%葡萄糖250ml+胰岛素；碳酸氢钠5% 125-250ml静滴（酸中毒者）；β2激动剂雾化（沙丁胺醇）辅助；促排钾：呋塞米20-40mg静推（肾功能好者）、聚苯乙烯磺酸钠（树脂）口服/灌肠（效果慢，肠梗阻者慎）。"],"oral_medication":["树脂口服降钾（口服后数小时起效）、利尿剂口服（轻症）。"],"treatment":["1.立即停用一切钾制剂与保钾药物，心电监护；2.分三步：①稳定心肌膜电位——有心电图改变或重度高钾立即静脉葡萄糖酸钙（10%葡萄糖酸钙10-20ml静推，作用数分钟）；②促钾进入细胞内——胰岛素+葡萄糖（胰岛素10U加50%葡萄糖50ml静推）、碱剂（酸中毒时）、β2激动剂（沙丁胺醇10-20mg雾化，作用30-60分钟起效，仅临时降低血钾）；③促钾排出体外——袢利尿剂（呋塞米20-40mg静推）、树脂、最重要是透析（肾功能不全或重度/顽固高钾）；3.同时纠正诱因（酸中毒、缺血）与低钙低钠（加重钾毒性）；4.动态监测血钾（治疗后每1-2小时）与心电图直至正常；5.慢性高钾管理：限钾饮食、调整ACEI/ARB/保钾药、泻药/树脂维持、评估原发病；6.准备好透析（血透最有效，CRRT用于血流动力学不稳定者）。"],"management":["重症入监护：持续心电监护、反复血钾心电图、记录出入量；透析患者及时安排。"],"notes":["钙剂只\"保护心脏\"不降血钾，30-60分钟内必须继以内移/排钾措施；胰岛素+葡萄糖后常规监测低血糖；假性高钾（抽血溶血、白细胞血小板极高）需复查确认再过度治疗；洋地黄中毒者静推钙剂可能致心律失常——换用葡萄糖酸钙慢速或避免。"],"emergency":["血钾>6.5mmol/L或心电图QRS增宽/心律失常/心脏停搏——立即钙剂+胰岛素葡萄糖并准备紧急透析，必要时CPR。"],"pinyin":"gaojiaxuezhengchuliliucheng","icd10":"E87.5","physical_exam":"肌力、腱反射、心率心律、血压、心电图动态。","lab_tests":"血钾（复查确认——排除溶血假性升高）、肾功能、血气（酸中毒）、血糖、尿常规（排钾）、心电图反复。","nursing":"心电监护观察T波QRS变化；静脉给药观察（钙剂外渗致组织坏死）；胰岛素治疗监测血糖；记录尿量；饮食宣教（避免香蕉橙子等高钾食物）。","diet":"严格限钾饮食：避免香蕉、橙子、土豆、坚果、浓汤、中药等高钾食物。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1237},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7b24a6c7ebfcf669e64d9bbbc78844a3c752d8ed5d6acb7d42ddbd34e6f29621","pinyin":"gaojiaxuezhengchuliliucheng","initials":"gjxzcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肌无力呈上行性（四肢→躯干→呼吸肌）、肢端麻木、乏力、恶心、心率慢或心律失常；可无症状仅化验发现；心电图示T波高尖、P波消失、QRS增宽，严重者心脏停搏。",60],["摘要","血清钾>5.5mmol/L（严重者>6.5mmol/L）伴心电图改变的紧急处理：稳定心肌（钙剂）、促钾内移（胰岛素+葡萄糖、碳酸氢钠、β2激动剂）、促钾排出（利尿、树脂、透析）三步走，寻找并处理病因。",30],["疾病编码","E87.5",30],["原首字母","gaojiaxuezhengchuliliucheng",60]]},{"id":"orders-4aaf48665819c70af948","key":"v1-c9ccc21dfe2a3058|orders-4aaf48665819c70af948","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"低钾血症处理流程","category":"夜班急症流程","raw":{"name":"低钾血症处理流程","category":"夜班急症流程","summary":"血清钾<3.5mmol/L（严重<2.5-3.0mmol/L）的处理：评估紧急程度（心电图、心律失常、肌无力），静脉补钾指征与速度、口服补钾优先、监测心电图与血钾，纠正诱因。","symptoms":["肌无力、软瘫甚至呼吸肌麻痹、烦躁嗜睡、食欲不振、恶心呕吐、腹胀（肠麻痹）；心悸（早搏/心动过速）；心电图T波低平倒置、ST段下降、u波、QT延长。"],"diagnosis":["根据血钾与心电图/症状诊断；寻找病因：摄入不足、丢失过多（呕吐腹泻、利尿剂、醛固酮增多、低镁）、钾内移（胰岛素、β2激动剂、周期性麻痹）；严重程度按血钾与症状划分。"],"infusion":["静脉补钾适应证：血钾<2.5-3.0mmol/L、有症状/心电图改变、不能口服者；外周静脉浓度≤0.3%（10%KCl 15ml+500ml液体），必要时中心静脉高浓度补（需监护）；速度一般≤20mmol/h（10%KCl 1g≈13.4mmol），严重者可达40mmol/h（监护下）；尿量>30ml/h再补钾。"],"oral_medication":["轻中度首选口服：氯化钾缓释片0.5-1g tid或10%氯化钾口服液10-20ml tid（饭后稀释服）、枸橼酸钾颗粒2g tid；补镁：硫酸镁口服或静滴（低镁并存时）。"],"treatment":["1.评估紧急程度：血钾<2.5-3.0mmol/L、心电图异常、心律失常、严重肌无力（含呼吸肌）→静脉补钾（监护下）；2.轻中度口服为主；3.补钾原则：能口服不静脉、见尿补钾、浓度速度限制（外周≤0.3%、≤20mmol/h）、监测心电图（快速或高浓度时）；4.低镁并存必须补镁（否则血钾难升）；5.纠正酸碱失衡：代碱者补氯（氯化钾优于枸橼酸钾）、代酸者在纠酸同时防血钾再降；6.减少丢失：调整利尿剂（改用保钾利尿）、处理呕吐腹泻；7.需要利尿者优先考虑保钾利尿剂；8.治疗原发病（甲亢、醛固酮增多症等）并鼓励含钾饮食。"],"management":["反复复查血钾（开始补钾后2-4小时）与心电图直至稳定；记录出入量；严重者心电监护。"],"notes":["外周静脉补钾浓度过高刺激疼痛与静脉炎；快速补钾必须心电监护；尿少者先评估肾功能再补钾；不要与含钾液体同通道；洋地黄中毒低钾者补钾尤其重要（低钾加重洋地黄毒性）。"],"emergency":["呼吸肌麻痹、严重心律失常、血钾<2.5mmol/L→紧急静脉补钾并监护，必要时呼吸支持。"],"pinyin":"dijiaxuezhengchuliliucheng","icd10":"E87.6","physical_exam":"肌力肌张力、腱反射、肠鸣音与腹胀、心率心律、血压。","lab_tests":"血钾（动态）、血气（酸碱：代碱常伴低钾）、镁（低镁需同补否则难纠）、肾功能、血糖、尿钾（鉴别肾性丢失）；心电图动态。","nursing":"心电监护观察ST-T与心律失常；静脉补钾浓度速度核对；观察静脉炎与外渗；鼓励高钾饮食（香蕉橙子土豆菠菜等）；监测血糖（胰岛素相关低钾）。","diet":"鼓励含钾丰富饮食：香蕉、橙子、柑橘、土豆、西红柿、菠菜、豆类；低盐（代盐含钾需告知）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1238},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f1b38ebe8bfee2b04ec518dfedfb0a7d1eb54b589f1b3539706d15cdf60567e4","pinyin":"dijiaxuezhengchuliliucheng","initials":"djxzcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肌无力、软瘫甚至呼吸肌麻痹、烦躁嗜睡、食欲不振、恶心呕吐、腹胀（肠麻痹）；心悸（早搏/心动过速）；心电图T波低平倒置、ST段下降、u波、QT延长。",60],["摘要","血清钾<3.5mmol/L（严重<2.5-3.0mmol/L）的处理：评估紧急程度（心电图、心律失常、肌无力），静脉补钾指征与速度、口服补钾优先、监测心电图与血钾，纠正诱因。",30],["疾病编码","E87.6",30],["原首字母","dijiaxuezhengchuliliucheng",60]]},{"id":"orders-7e8b3ba9ef16b0ac654a","key":"v1-c9ccc21dfe2a3058|orders-7e8b3ba9ef16b0ac654a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"ARDS处理流程","category":"夜班急症流程","raw":{"name":"ARDS处理流程","category":"夜班急症流程","summary":"急性呼吸窘迫综合征（急性起病低氧、双肺弥漫渗出、非心源性肺水肿）的机械通气与综合管理：肺保护性通气（小潮气量+平台压控制）、PEEP滴定、俯卧位、液体管理与病因治疗。","symptoms":["急性起病的严重呼吸困难和低氧（多在肺炎、脓毒症、创伤、误吸等诱因后1周内），呼吸急促、发绀、烦躁；胸片/CT双肺弥漫性渗出影；无左房高压证据（PCWP<18mmHg）。"],"diagnosis":["Berlin标准：1周内急性起病+双肺浸润影不能用积液/肺不张/结节完全解释+非心源性（无左心衰证据）+氧合障碍：PaO2/FiO2≤300为轻度（200-300）、100-200中度、<100重度（PEEP≥5cmH2O）。"],"infusion":["液体管理：限制性液体策略（保守液体，避免肺水肿加重），每日液体平衡趋向负平衡（尿量目标>0.5ml/(kg·h)），必要时利尿（呋塞米）或CRRT；容量不足者先复苏再限液。"],"oral_medication":["镇静镇痛：丙泊酚/咪达唑仑/右美托咪定+芬太尼/吗啡泵入（目标浅镇静RASS-1~0，必要时肌松——中重度早期短程）；神经肌肉阻滞剂（顺阿曲库铵）用于人机对抗或难治低氧（早期48小时）。"],"treatment":["1.机械通气核心——肺保护通气：初始潮气量8ml/kg理想体重，之后每1-2小时减至6ml/kg（可低至4-6），平台压≤30cmH2O，驱动压尽量<15；2.PEEP滴定（轻度5-10、中重度按肺可复张性调高10-20cmH2O，目标SpO2 88%-95%）；3.中重度（PaO2/FiO2<150）俯卧位通气≥12-16小时/天（需人员熟练、防压疮导管脱出）；4.难治性低氧考虑肺复张、吸入一氧化氮（短期桥接）、ECMO（有条件的中心）；5.镇静镇痛目标化并每日唤醒，避免过度镇静；6.病因治疗：感染性（抗感染）、创伤、误吸、胰腺炎、大量输血等；7.液体保守管理；8.预防并发症：VAP（床头抬高、口腔护理）、VTE、应激性溃疡、导管感染；9.营养支持（早期肠内）；10.脱机评估：原发病好转、自主呼吸试验成功、FiO2与PEEP下降后尽早脱机。"],"management":["ICU管理：呼吸机参数与血气每日/每日多次评估；平台压与驱动压监测；俯卧位期间专人护理；动态胸片/超声；多学科协作。"],"notes":["勿用大潮气量——肺保护是ARDS治疗的基石；俯卧位与PEEP同样重要；排除心源性肺水肿（BNP/超声）是诊断关键；镇静过深增加VAP与住院时间。"],"emergency":["SpO2进行性下降、平台压超标、气胸（呼吸机相关）突发——立即评估处理（张力性气胸减压）并呼救ECMO团队。"],"pinyin":"ARDSchuliliucheng","icd10":"J80","physical_exam":"呼吸频率与辅助呼吸肌、双肺湿啰音、发绀、SpO2、心率血压、意识。","lab_tests":"血气分析（动态）、乳酸、BNP（鉴别心源性）、感染指标、血培养（病因）、胸片/胸部CT、超声（心功能评估）。","nursing":"机械通气护理（气道、气囊压、湿化吸痰）；俯卧位护理；镇静评分与每日唤醒；口腔护理防VAP；皮肤压疮预防；记录液体出入量。","diet":"早期肠内营养（血流动力学稳定后24-48小时），监测喂养耐受；血糖管理。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1239},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"33d61d717a7112c7b5015b60ada4840d609af069354b6a3004af05b5ea3796bf","pinyin":"ARDSchuliliucheng","initials":"Acllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性起病的严重呼吸困难和低氧（多在肺炎、脓毒症、创伤、误吸等诱因后1周内），呼吸急促、发绀、烦躁；胸片/CT双肺弥漫性渗出影；无左房高压证据（PCWP<18mmHg）。",60],["摘要","急性呼吸窘迫综合征（急性起病低氧、双肺弥漫渗出、非心源性肺水肿）的机械通气与综合管理：肺保护性通气（小潮气量+平台压控制）、PEEP滴定、俯卧位、液体管理与病因治疗。",30],["疾病编码","J80",30],["原首字母","ARDSchuliliucheng",60]]},{"id":"orders-82d5a9b0a7080837233a","key":"v1-c9ccc21dfe2a3058|orders-82d5a9b0a7080837233a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班肠外营养处理","category":"值班宝典","raw":{"name":"夜班肠外营养处理","category":"值班宝典","summary":"定义：肠外营养是通过静脉途径提供葡萄糖、氨基酸、脂肪乳、电解质、维生素与微量元素，使无法经胃肠道摄取足够营养的患者获得代谢支持。适用于肠梗阻、短肠综合征、高流量肠瘘、重度麻痹性肠梗阻、严重呕吐腹泻及重症高分解代谢状态。\n夜班目标：先判断肠内营养是否可行，再核对配方、输注速度与通路，重点防再喂养综合征、高血糖、容量过负荷与导管相关感染；同时关注肠道功能恢复。","symptoms":["需要肠外营养的情形：长期不能进食（预计禁食>5~7天）、进食后呕吐或严重腹泻、肠梗阻与重度腹胀、短肠或高流量肠瘘、重症创伤与烧伤后高分解代谢。","代谢并发症表现：口渴多尿与意识改变（高血糖）、心悸与肌无力（低钾、低镁、低磷）、手足麻木与抽搐（低镁、低钙）、呼吸费力与水肿（容量过负荷或脂肪输注过多）。","肠道动力不足表现：肠鸣音减弱（肠鸣音<3次/分）、腹胀、停止排气排便。","再喂养综合征危险人群：长期饥饿、体重明显下降、酒精依赖与慢性消耗性疾病者。"],"diagnosis":["营养评估：近期体重变化与下降速度、进食量、血清白蛋白与前白蛋白、肌力与皮褶厚度，判断营养不良程度。","指征核对：肠道是否可用（梗阻、穿孔、重度麻痹性肠梗阻、短肠、高流量肠瘘、严重消化道出血）、预计禁食时间是否超过5~7天、肠内营养是否有禁忌。","风险核对：血糖与电解质基线（尤其磷、钾、镁）、肝肾功能、甘油三酯、容量状态、有无中心静脉通路与既往导管感染史。","鉴别方向：区分需要肠外营养与可通过口服营养补充或管饲解决的问题，避免过度使用。"],"infusion":["结构脂肪乳250mL与复方氨基酸500mL配伍静滴，每日1次，按本院规范配成全合一或分瓶输注。","输注方式：经中心静脉按20~24小时匀速输注，起始热量按15~20kcal/kg/d、蛋白质按1.0~1.5g/kg/d评估后逐步递增。","胃肠功能保护：注射用奥美拉唑40mg静脉推注，每12小时1次，首剂加倍，用于应激性溃疡预防。","促胃肠动力（肠鸣音<3次/分时启用）：新斯的明注射液0.5mg肌内注射，每12小时1次；机械性肠梗阻与心动过缓者禁用。","血糖管理：胰岛素按1:4~1:10加入营养液，血糖>13.9mmol/L时改用胰岛素泵或皮下注射方案。"],"oral_medication":["肠外营养期间原则上经口不进食或仅少量温水，具体由主管医师决定；能经口进食者应尽早过渡到肠内营养。","可口服补充：维生素B1片、复合维生素与微量元素制剂，按缺什么补什么的原则，不能替代肠外营养。","禁忌：机械性肠梗阻患者禁用新斯的明；意识不清、呕吐或消化道出血者禁食禁水，不口服任何药物与食物。"],"treatment":["首要：评估并纠正危及生命的电解质紊乱与容量不足，确认气道、呼吸与循环稳定，核对肠内营养是否有禁忌。\n其次：启动肠外营养，从低热量起步并逐步递增，同时补充维生素B1（100mg静注/静滴）与磷，防止再喂养综合征；必要时按规范联合促胃肠动力治疗（甲氧氯普胺10mg静推）以促进肠功能恢复。\n随后：每日评估能量与蛋白质是否达标，监测血糖、肝肾功能、甘油三酯与出入量，评估导管相关并发症。\n最后：一旦肠道功能恢复并能耐受肠内喂养，尽早减少并停止肠外营养，避免长期依赖。"],"management":["复评频率：每4~6小时测血糖，每日查电解质、肾功能与体重，每周评估肝肾功能、甘油三酯与营养指标。","观察要点：再喂养综合征表现（血磷、血钾、血镁下降）、容量过负荷（体重快速增加、肺部啰音、水肿）、导管相关感染与静脉炎、肝功能异常与胆汁淤积、肠鸣音是否恢复。","用药与通路管理：营养袋现配现用，输注超过24小时的营养液应废弃；输液速度不可随意加快；导管穿刺处按规范换药并记录。","收治标准：需长期肠外营养、反复导管感染、严重电解质紊乱或再喂养综合征高危者收入院并在营养支持小组指导下治疗。"],"notes":["以本院规范为准：肠外营养配方组成、热量与氮量计算、胰岛素加入比例、输注速度与监测频率按本院营养支持流程执行。","避免与禁忌：机械性肠梗阻与心动过缓者禁用新斯的明；不因进食困难就直接给全量肠外营养（易诱发再喂养综合征）；严重电解质紊乱与酸碱失衡未纠正前不宜启动营养。","提醒：长期完全肠外营养须补充维生素与微量元素；慢性消耗或长期饥饿患者启动营养时必须先补维生素B1与磷并密切监测电解质。"],"emergency":["立即升级：血磷<0.3mmol/L或血钾<3.0mmol/L或血镁<0.5mmol/L伴心律失常 → 暂停营养输注、静脉补充电解质并转监护病房。","血糖相关：血糖>16.7mmol/L或出现意识改变与脱水 → 按高血糖急症处理并调整胰岛素方案。","感染相关：输注中突发寒战高热、血压下降 → 立即停输、留取血培养并按导管相关血流感染处理，必要时拔除导管。","容量相关：突发呼吸困难、SpO2<92%或肺部大量啰音 → 减慢输注速度并按急性心衰处理。"],"pinyin":"yebanchangwaiyingyangchuli","icd10":"Z93.9","physical_exam":"容量与营养状态：体重、皮肤弹性、皮下脂肪与肌肉厚度、颈静脉充盈、下肢与骶部水肿、肺部啰音。\n代谢与神经肌肉：肌力、腱反射、心率与心律、意识状态、有无抽搐与震颤。\n腹部与导管：肠鸣音频率与音调、腹胀程度；中心静脉置管处有无红肿渗液与压痛，锁骨下、颈部与上肢有无肿胀，警惕静脉血栓与气胸。","lab_tests":"必查：床旁血糖（每日至少2~4次）、电解质（钾、钠、镁、磷、钙）、肾功能、肝功能、血常规、甘油三酯。\n按需：动脉血气与乳酸、凝血功能、尿量与尿糖、导管尖端培养与血培养（疑导管感染）、维生素与微量元素检测、腹部影像、间接测热法评估能量需求。","nursing":"导管护理：中心静脉导管穿刺处每日评估，按规范换药，三通与输液管路保持无菌并标注更换日期，不随意经营养通路推注其他药物。\n监测：记录24小时出入量与每日体重，按医嘱时间测血糖与复查电解质，输注速度不可自行调整。\n记录：营养液配方、输注起止时间、血糖与电解质结果、有无输注反应与导管并发症。\n安全：防止管路脱落、打折与空气进入，输注泵报警及时处理；卧床患者注意翻身与血栓预防。","diet":"肠道有功能者鼓励少量经口进食或管饲，维护肠黏膜屏障。\n可进米汤、藕粉等清流质，逐步过渡到半流质与软食；肠梗阻与重症胰腺炎急性期须禁食。\n禁高糖饮料与高脂食物，防止血糖与血脂波动。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1240},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4daeaa9259a8f6f986e678787e0547551f3a0efa3a4ae8825b1691b67f81ae4f","pinyin":"yebanchangwaiyingyangchuli","initials":"ybcwyycl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","需要肠外营养的情形：长期不能进食（预计禁食>5~7天）、进食后呕吐或严重腹泻、肠梗阻与重度腹胀、短肠或高流量肠瘘、重症创伤与烧伤后高分解代谢。\\n代谢并发症表现：口渴多尿与意识改变（高血糖）、心悸与肌无力（低钾、低镁、低磷）、手足麻木与抽搐（低镁、低钙）、呼吸费力与水肿（容量过负荷或脂肪输注过多）。\\n肠道动力不足表现：肠鸣音减弱（肠鸣音<3次/分）、腹胀、停止排气排便。\\n再喂养综合征危险人群：长期饥饿、体重明显下降、酒精依赖与慢性消耗性疾病者。",60],["摘要","定义：肠外营养是通过静脉途径提供葡萄糖、氨基酸、脂肪乳、电解质、维生素与微量元素，使无法经胃肠道摄取足够营养的患者获得代谢支持。适用于肠梗阻、短肠综合征、高流量肠瘘、重度麻痹性肠梗阻、严重呕吐腹泻及重症高分解代谢状态。\n夜班目标：先判断肠内营养是否可行，再核对配方、输注速度与通路，重点防再喂养综合征、高血糖、容量过负荷与导管相关感染；同时关注肠道功能恢复。",30],["疾病编码","Z93.9",30],["原首字母","yebanchangwaiyingyangchuli",60]]},{"id":"orders-8ea53e89540390a78bff","key":"v1-c9ccc21dfe2a3058|orders-8ea53e89540390a78bff","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班临床鉴别陷阱要诀","category":"夜班临床经验","raw":{"name":"夜班临床鉴别陷阱要诀","category":"夜班临床经验","summary":"夜班临床高年资医师总结的鉴别诊断要诀（经归纳整理）：哪些症状必须警惕哪些致命病、哪些检查不能省、哪些表现提示特殊中毒——胸痛/腹痛/意识改变/外伤等场景的一线\"陷阱清单\"。","symptoms":["胸痛、腹痛、头痛、头晕、意识改变、抽搐、四肢无力、外伤、心悸等多种常见主诉中易被低估的情形。"],"diagnosis":["坚持\"症状解释不通就怀疑诊断\"：一个诊断必须能解释全部症状体征与检查结果；思路不要局限于本专业（头痛可能是青光眼、腹痛可能是宫外孕）。"],"infusion":["判断可能不稳定的患者立即建立静脉通道；休克或大出血者快速补液。"],"oral_medication":["顽固性咳嗽先问是否服ACEI（卡托普利等）再排查其他；夜间呼吸困难而心脏彩超正常者考虑胃食管反流（可试用抑酸治疗）。"],"treatment":["1.胸痛警惕四大致命病：心梗（心电图动态对比、肌钙蛋白）、主动脉夹层（撕裂痛+双上肢血压差+背痛/腹痛/臀部痛放射、辗转不安伴心率血压波动先排除夹层）、肺栓塞（术后/卧床/肿瘤者、PCI术后活动后突发胸闷大汗低血压）、张力性气胸（突发胸痛呼吸困难，患侧呼吸音消失）；2.腹痛：成年女性一律排除宫外孕（16岁以上腹痛必查HCG，无论月经史）；中老年急腹症症状体征\"四面不靠\"、腹胀明显→考虑血管因素（肠系膜缺血）；持续腹痛无固定压痛、辅助检查阴性→仍警惕肠系膜血管病；夜间初发腹痛警惕急性阑尾炎；老年腹痛警惕胆源性胰腺炎；3.意识/抽搐：任何突发意识改变先测血糖；有纹身者心跳呼吸骤停考虑毒品中毒；呼吸心跳停止后口唇仍红润考虑氰化物中毒；4.用药与中毒：静脉用头孢后饮酒发病→双硫仑样反应；青霉素过敏注意其\"潜伏期\"再发；急性下壁心梗加做右胸导联（V3R-V5R）防漏右室梗死；5.外伤：胸外伤开放伤口多需手术探查（肋间血管损伤可致失血性休克）；X线阴性也要交代复查（肋骨、踝腕隐性骨折）；腹部外伤超声正常仍需留观复查；异物刺伤必拍片；6.其它：突发腰背痛伴发热黄疸→警惕溶血危象；夜间心衰/呼困难鉴反流性食管炎；有心脏病史的外伤患者一律做心电图；头颅外伤伴反复问同一问题考虑颅内出血。"],"management":["对怀疑但无确诊的危重病宁可多查多留观；记录鉴别诊断过程与告知；把握不住及时请上级。"],"notes":["教科书\"好发年龄\"只是统计，临床不要按年龄套病；相信自己看到的查到的，患者提供的病史可能隐瞒或误导；不要依赖影像报告，自己看片；异常辅助检查必要时复查。"],"emergency":["夹层、心梗、肺栓塞、张力性气胸、宫外孕破裂、脑出血等按相应流程立即处理并呼救。"],"pinyin":"yebanlinchuangjianbiexianjingyaojue","icd10":"Z00-Z99","physical_exam":"全面细致查体防漏诊：皮肤痛觉过敏想到早期带状疱疹；否认受伤却反复问同一问题的创伤患者多颅脑有问题；急性四肢无力查肌力腱反射并查血钾；考虑脊髓病变必查脊柱压痛；外伤者查脊柱与骨盆。","lab_tests":"头痛/头晕/昏迷一律查血糖；抽搐病人查血糖；急性四肢无力查血钾和心电图；女性腹痛查尿/血HCG；疑溶血查胆红素、血红蛋白尿与LDH；顽固咳嗽问ACEI类药物史。","nursing":"观察并向医生报告疼痛性质变化、意识与生命体征波动。","diet":"按病种处理（疑肠梗阻/胰腺炎/出血禁食等）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1241},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"053c0d2f6db577f870ddeca76ad487a4db8cd548b2c7c0ab16f57862636461b1","pinyin":"yebanlinchuangjianbiexianjingyaojue","initials":"yblcjbxjyj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","胸痛、腹痛、头痛、头晕、意识改变、抽搐、四肢无力、外伤、心悸等多种常见主诉中易被低估的情形。",60],["摘要","夜班临床高年资医师总结的鉴别诊断要诀（经归纳整理）：哪些症状必须警惕哪些致命病、哪些检查不能省、哪些表现提示特殊中毒——胸痛/腹痛/意识改变/外伤等场景的一线\"陷阱清单\"。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanlinchuangjianbiexianjingyaojue",60]]},{"id":"orders-d047ac10ca127cc0e028","key":"v1-c9ccc21dfe2a3058|orders-d047ac10ca127cc0e028","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班危重患者常用医嘱模板","category":"夜班工作管理","raw":{"name":"夜班危重患者常用医嘱模板","category":"夜班工作管理","summary":"危重（休克/心衰/呼吸衰竭等）患者入院或抢救时的常用医嘱框架：长期医嘱（护理级别、病危、监护、吸氧、深静脉/尿管等）与临时医嘱（急查化验、心电图、影像、建立通路），供值班快速开立、减少遗漏。","symptoms":["休克、急性心衰、呼吸衰竭、意识障碍、大出血等危重患者需快速建立全面医嘱的场景。"],"diagnosis":["明确主要危重诊断后按系统补齐医嘱：监护级别、生命支持、监测项目、化验与影像、对症与病因用药。"],"infusion":["建立静脉通路（危重者两条或深静脉）；按病因给药：休克者快速补液；急性心衰者利尿扩血管；出血者配血备血；输液种类与速度按床旁血糖与容量状态调整。"],"oral_medication":["意识障碍者禁食水（如需给药经胃管）。"],"treatment":["1.长期医嘱模板：内科/外科护理常规+一级护理+病危/病重通知；心电、血压、血氧饱和度监护；吸氧；记录24小时出入量；必要时留置导尿管（记每小时尿量）、中心静脉置管（测CVP/给药）、胃管；防压疮与VTE医嘱（气压泵/低分子肝素如依诺肝素40mg皮下qd，按出血风险评估）；2.临时医嘱：立即抽急查（见lab_tests）→心电图、床旁血糖→建立静脉通道→按流程给首剂药物（血管活性药如去甲肾上腺素0.05-0.5μg/kg/min泵入、抗心律失常、利尿、止血等）；3.病危患者须同时开具\"病危通知\"并履行告知；4.按病因开立具体治疗医嘱（参考各急症流程条目），并预约复查时间（血气、电解质、乳酸等动态）；5.抢救后6小时内补记抢救记录；6.完善知情（有创操作、输血）。"],"management":["各班次床旁交接危重患者医嘱执行情况；护理按医嘱执行并记录生命体征、出入量、用药反应。"],"notes":["医嘱要成体系防遗漏：监护级别、通路、监测化验、对症、病因、并发症预防各占一条；危重患者\"病危通知\"和家属告知不可省；血管活性药物经深静脉并标注泵速。"],"emergency":["休克/呼吸衰竭/心脏骤停等先执行急救流程再补全医嘱；重要医嘱（病危通知、输血、有创操作）须及时落实并记录时间。"],"pinyin":"yebanweizhonghuanzhechangyongyizhumoban","icd10":"Z00-Z99","physical_exam":"入室即刻评估气道呼吸循环与意识，开放气道、给氧、建立监测。","lab_tests":"临时医嘱常规组合：血常规、肝肾功电解质、血气、乳酸、血糖、凝血、心肌损伤标志物/BNP（按需）、血培养（发热/感染）、心电图、胸片；按病种加做（CT、超声等）。","nursing":"按医嘱落实监护、吸氧、尿管胃管与深静脉护理；每小时记录生命体征与尿量；及时反馈病情变化。","diet":"危重期禁食或按病种（胃肠减压者禁食）；能肠内者早期营养支持。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1242},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9296f908de7c3779ade8df1f7c0e0b298048b617453d9d546a9978bdc561d46e","pinyin":"yebanweizhonghuanzhechangyongyizhumuban","initials":"ybwzhzcyyzmb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","休克、急性心衰、呼吸衰竭、意识障碍、大出血等危重患者需快速建立全面医嘱的场景。",60],["摘要","危重（休克/心衰/呼吸衰竭等）患者入院或抢救时的常用医嘱框架：长期医嘱（护理级别、病危、监护、吸氧、深静脉/尿管等）与临时医嘱（急查化验、心电图、影像、建立通路），供值班快速开立、减少遗漏。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanweizhonghuanzhechangyongyizhumoban",60]]},{"id":"orders-67730ec8d518e14a7751","key":"v1-c9ccc21dfe2a3058|orders-67730ec8d518e14a7751","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胸痛急症快速评估流程","category":"夜班急症流程","raw":{"name":"胸痛急症快速评估流程","category":"夜班急症流程","summary":"夜班胸痛患者的快速评估流程：首要排除致命性胸痛（急性心梗、主动脉夹层、肺栓塞、张力性气胸），边问病史边做心电图并动态对比，稳定后系统检查，按病因处理。","symptoms":["胸痛/胸闷（压榨、撕裂、针刺、胸膜性等不同性质），可伴放射痛、呼吸困难、大汗、心悸、晕厥；需问清部位、性质、持续时间、诱因缓解因素与既往史。"],"diagnosis":["第一步立即查生命体征与心电图（一边问诊一边做ECG，和既往心电图对比）；致命病因线索：心梗（压榨痛、出汗、肌钙蛋白升高、心电图动态演变）；主动脉夹层（撕裂样痛向后背/腹部/臀部放射、双上肢血压差、纵隔增宽）；肺栓塞（突发、与体位无关、D-二聚体/CTPA）；张力性气胸（突发胸痛+呼吸困难+患侧呼吸音消失/气管移位）。"],"infusion":["建立静脉通路；明确ACS者按ACS流程（阿司匹林负荷、肝素/抗血小板、再灌注评估）；夹层者控制心率血压（β阻滞剂+必要时硝普钠）；PE按危险分层抗凝/溶栓。"],"oral_medication":["按病因用药：ACS双联抗血小板+他汀等；反流性胸痛可试用抑酸（排除致命病因后）。"],"treatment":["1.立即评估生命体征与心电图（必须，勿等病史问完）；2.快速排除致命性胸痛：心梗、夹层、肺栓塞、气胸——尤其注意①既往高血压突发胸背痛→夹层（量双上肢血压、勿仅按心梗处理，抗血小板/溶栓禁忌）；②术后/卧床/肿瘤患者突发胸痛气促→肺栓塞；③突发胸痛伴呼吸困难患侧呼吸音消失→气胸（张力性者立即减压）；3.查看交班与病程，注意和以前心电图对比；4.稳定者系统问诊查体后按病因收治或留观：ACS（心电监测、双抗、再灌注）、心包炎、肺栓塞、气胸、胸膜炎、肋软骨炎、消化道疾病（食管痉挛/反流）与焦虑等；5.动态复查心电图与心肌损伤标志物（症状反复或高危者）；6.请心内科/胸外科/呼吸科会诊按需。"],"management":["胸痛患者入观察室/心电监护，动态复查；记录疼痛变化；通知家属。"],"notes":["宁可\"错杀\"勿漏致命胸痛——心电图该做就做、动态做；夹层误用抗凝溶栓是灾难性错误，先鉴别再用药；老年与糖尿病患者心梗可无典型胸痛（仅胸闷/气促/乏力），发热者与生命体征异常者也做心电图。"],"emergency":["血流动力学不稳定、心电图明确STEMI、疑夹层/张力性气胸立即启动相应抢救流程（除颤、再灌注、减压）并呼救。"],"pinyin":"xiongtongjizhengkuaisupingguliucheng","icd10":"R07.9","physical_exam":"生命体征与双上肢血压、颈静脉、心肺听诊（心音、摩擦音、呼吸音）、腹部（夹层累及）、下肢（DVT）。","lab_tests":"心电图（立即+动态对比）、肌钙蛋白（动态）、BNP、D-二聚体、血气、胸片；按怀疑方向选CTA（夹层/肺栓塞）、床旁超声（心包积液、室壁运动）、心肌损伤标志物。","nursing":"立即协助心电图与监护；观察疼痛性质变化、出汗、血压波动；建立通路配合抽血。","diet":"急性期禁食（考虑再灌注/急诊PCI者）；排除急性病因后低脂饮食。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1243},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d51eeabfa5c8e3a50f70d6629d31fb2d4c64f45ac0d6dbd324e9ad3154ec92dd","pinyin":"xiongtongjizhengkuaisupingguliucheng","initials":"xtjzkspglc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","胸痛/胸闷（压榨、撕裂、针刺、胸膜性等不同性质），可伴放射痛、呼吸困难、大汗、心悸、晕厥；需问清部位、性质、持续时间、诱因缓解因素与既往史。",60],["摘要","夜班胸痛患者的快速评估流程：首要排除致命性胸痛（急性心梗、主动脉夹层、肺栓塞、张力性气胸），边问病史边做心电图并动态对比，稳定后系统检查，按病因处理。",30],["疾病编码","R07.9",30],["原首字母","xiongtongjizhengkuaisupingguliucheng",60]]},{"id":"orders-f473373be4907d7348b6","key":"v1-c9ccc21dfe2a3058|orders-f473373be4907d7348b6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"气胸处理流程","category":"夜班急症流程","raw":{"name":"气胸处理流程","category":"夜班急症流程","summary":"气胸（自发性、创伤性、医源性）的分级处理：识别并紧急处理张力性气胸（立即穿刺减压），按肺压缩程度选择观察/穿刺抽气/胸腔闭式引流，处理原发病并评估复发风险。","symptoms":["突发一侧胸痛、呼吸困难、干咳；张力性气胸表现为进行性呼吸困难、发绀、烦躁、低血压，患侧呼吸音消失、叩诊鼓音、气管向健侧移位；瘦高体型、肺大泡者易发（原发性）。"],"diagnosis":["胸片（立位）示肺压缩与胸膜线可确诊并估算压缩比例（>30%需置管）；张力性气胸按临床体征紧急判断（勿等影像）；CT更精确并评估肺大泡；查病因（外伤、穿刺/锁骨下静脉置管等医源、慢阻肺继发）。"],"infusion":["建立静脉通路；张力性气胸立即用粗针在患侧第2肋间锁骨中线穿刺排气（或针头接水封瓶），随后置管闭式引流；疼痛明显者可镇痛。"],"oral_medication":["对症镇痛（避免抑制呼吸）；原发病用药（如COPD者扩张支气管）。"],"treatment":["1.评估呼吸与循环：张力性气胸（气管移位、严重低氧、低血压）为急症——立即第2肋间锁骨中线粗针穿刺减压，再接胸腔闭式引流（接水封瓶），勿先拍片；2.非张力性气胸：肺压缩<20-30%且无症状者可观察（高浓度吸氧促进吸收）并复查；3.肺压缩>30%或有症状、继发性气胸、张力性、双侧或复杂性气胸→胸腔闭式引流（锁骨中线第2肋间或腋前线第4-5肋间置管，接水封瓶负压吸引必要时）；4.持续漏气超过3-5天或肺不复张→胸外科评估（胸腔镜修补/胸膜固定）；5.医源性气胸（穿刺、中心静脉置管后）：小量观察、量大引流；6.处理后复查胸片确认肺复张，拔管指征（无漏气、肺复张24小时）；7.处理基础病（COPD、肺大泡）并宣教复发风险（吸烟者戒烟）。"],"management":["闭式引流者每日观察水封瓶气泡（漏气）、液面波动与引流量，必要时接负压；复查胸片；转运时注意引流管固定与夹闭。"],"notes":["张力性气胸是临床诊断，见体征立即减压不等影像；瘦高体型年轻男性自发气胸复发率高；穿刺与中心静脉置管后常规听诊或胸片排除气胸；机械通气患者气胸进展快，一旦疑诊尽快引流。"],"emergency":["张力性气胸（呼吸困难急剧加重+气管移位+循环恶化）立即穿刺减压；双侧气胸、连枷胸合并者转ICU。"],"pinyin":"qixiongchuliliucheng","icd10":"J93.9","physical_exam":"生命体征与SpO2、气管位置、患侧呼吸音（减弱/消失）、叩诊（鼓音）、皮下气肿（捻发感）、颈静脉怒张。","lab_tests":"胸片（首选）、血气（重症）、血常规（外伤/感染）；CT（疑难或评估肺大泡）。","nursing":"半卧位减轻呼吸困难；观察呼吸频率SpO2与胸痛；水封瓶护理（液面在瓶下60cm、记录气泡与引流量、瓶低于胸部防倒流）；引流管固定防脱管；翻身拍背轻柔。","diet":"普通饮食（避免剧烈用力与屏气、用力排便），便秘者通便。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1244},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a1d8582d42d5d65c73bab62ac960c4bc03ad0825ae44850e98aeda6c507596d7","pinyin":"qixiongchuliliucheng","initials":"qxcllc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发一侧胸痛、呼吸困难、干咳；张力性气胸表现为进行性呼吸困难、发绀、烦躁、低血压，患侧呼吸音消失、叩诊鼓音、气管向健侧移位；瘦高体型、肺大泡者易发（原发性）。",60],["摘要","气胸（自发性、创伤性、医源性）的分级处理：识别并紧急处理张力性气胸（立即穿刺减压），按肺压缩程度选择观察/穿刺抽气/胸腔闭式引流，处理原发病并评估复发风险。",30],["疾病编码","J93.9",30],["原首字母","qixiongchuliliucheng",60]]},{"id":"orders-ad111e642a49a5047d6f","key":"v1-c9ccc21dfe2a3058|orders-ad111e642a49a5047d6f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班癌痛止痛处理","category":"值班宝典","raw":{"name":"夜班癌痛止痛处理","category":"值班宝典","summary":"定义：癌痛是肿瘤本身、转移灶或抗肿瘤诊疗过程引起的疼痛，按强度分为轻度（1~3分）、中度（4~6分）与重度（7~10分），按机制分为伤害性疼痛（躯体、内脏）与神经病理性疼痛。\n夜班目标：按疼痛强度阶梯给药，及时控制夜间爆发痛，预防阿片类药物的呼吸抑制、过度镇静与便秘；先排除脊髓压迫、病理性骨折等需要急诊处理的病因。","symptoms":["伤害性疼痛：骨转移处持续性钝痛或压痛，活动、翻身与负重后加重；内脏痛多为胀痛、绞痛或牵拉痛，位置较弥漫。","神经病理性疼痛：电击样、烧灼样、针刺样或撕裂样疼痛，可伴麻木、痛觉过敏与触电感。","爆发痛：基础痛控制尚可时突发剧烈疼痛，多在夜间、翻身、换药或排便时出现，持续数分钟至1小时。","危险信号：突发剧痛伴肢体无力或大小便障碍（提示脊髓压迫）、突发局部剧痛伴畸形（病理性骨折）、止痛药需求短期内迅速上升、意识改变与呼吸变慢。"],"diagnosis":["疼痛评估：部位、性质、强度评分、持续时间、加重与缓解因素，以及与活动、体位、进食与排便的关系；区分基础痛与爆发痛。","用药史：既往阿片类药物种类、剂型、剂量、给药间隔与效果、不良反应，是否自行减量或停药。","危险排查：有无骨转移与病理性骨折、脊髓压迫、脑转移所致颅高压、空腔脏器穿孔或梗阻、肿瘤急症（上腔静脉综合征、高钙血症）。","鉴别方向：与治疗相关疼痛（术后、放疗后、化疗所致周围神经病）、感染、深静脉血栓与便秘所致腹痛。"],"infusion":["急性重度疼痛：吗啡注射液5~10mg皮下注射或2~5mg缓慢静推，按本院规范；重复给药前必须评估呼吸频率与意识。","持续泵入：吗啡或氢吗啡酮按规范经患者自控镇痛泵或持续皮下泵入，需设定锁定时限与单次剂量上限。","辅助用药：地塞米松5~10mg静滴，用于骨转移痛、神经压迫与颅高压相关疼痛。","骨转移：按规范使用双膦酸盐或地舒单抗，注意水化与肾功能，警惕低钙血症。"],"oral_medication":["轻度疼痛：对乙酰氨基酚0.5g口服，每6小时按需，24小时不超过4次；或布洛芬0.2~0.4g口服每8小时，注意消化道与肾功能。","中度疼痛：曲马多50~100mg口服，每6~8小时1次；或可待因按规范剂量口服。","重度疼痛：吗啡缓释片10~30mg口服每12小时，或羟考酮缓释片10mg口服每12小时，按本院规范滴定。","爆发痛：即释吗啡片按日总量的10%~15%口服，两次间隔不少于1小时。","辅助与预防：加巴喷丁或普瑞巴林用于神经病理性疼痛；预防便秘用乳果糖或聚乙二醇；恶心者加甲氧氯普胺。","禁忌：吞咽困难、频繁呕吐或意识不清者不口服给药，改用注射或透皮贴剂。"],"treatment":["首要：立即评估疼痛强度与生命体征，对剧痛患者尽快给药，同时排查脊髓压迫、病理性骨折、穿孔与梗阻等需要急症处理的病因。","其次：按阶梯原则选药——轻中度用非阿片类或弱阿片类，重度用强阿片类，神经病理性疼痛加用辅助药物；同时预防性处理便秘、恶心与瘙痒。","随后：确立“缓释剂定时给药加即释剂处理爆发痛”的方案，记录疗效与不良反应，评估是否需要请疼痛科或姑息治疗团队会诊。","最后：疼痛控制稳定后评估阿片类药物的减量与转换方案，避免突然停药导致戒断。"],"management":["复评频率：给药后30~60分钟评估疼痛评分、镇静程度与呼吸频率；稳定后每4小时评估一次，记录爆发痛次数。","观察要点：呼吸频率与深度、意识水平、瞳孔、排便情况与尿潴留；有无恶心呕吐、皮肤瘙痒与贴剂部位反应。","用药管理：记录阿片类药物的种类、剂量、途径与时间，缓释剂不可掰开或碾碎服用；透皮贴剂需记录贴敷与更换时间。","随访与收治：疼痛评分持续≥7分或需反复追加注射剂者，请疼痛科会诊并考虑收入院调整方案。"],"notes":["以本院规范为准：阿片类药物的起始剂量、滴定方法、患者自控镇痛泵参数设置与纳洛酮使用指征按本院疼痛管理流程执行。","避免与禁忌：不按需长期单用肌内注射阿片类替代口服缓释方案；不使用安慰剂或不含镇痛成分的注射；肾功能不全者慎用吗啡（活性代谢产物蓄积），宜按规范选芬太尼类或羟考酮；不因担心成瘾而不足量镇痛。","提醒：癌痛治疗需同时处理便秘、恶心与失眠，提前预防比事后补救更重要。"],"emergency":["立即升级：呼吸频率<8次/分或SpO2<90%伴嗜睡 → 停用阿片类、给氧，按本院规范使用纳洛酮并呼叫上级。","肿瘤急症：疼痛评分≥7分且给药后不缓解、出现新发下肢无力或大小便障碍 → 急诊磁共振并请神经外科与放疗科会诊。","其他：突发局部剧痛伴畸形（病理性骨折） → 制动、镇痛并请骨科会诊；意识改变伴高钙血症 → 补液与降钙治疗。"],"pinyin":"yebanaitongzhitongchuli","icd10":"R52","physical_exam":"疼痛部位：压痛、叩击痛、关节活动度、有无畸形与肿胀、脊柱压痛与棘突叩击痛、局部皮温与颜色。\n神经系统：肌力、感觉分布、腱反射、病理反射、鞍区感觉与肛门括约肌张力（疑脊髓压迫时必查）。\n全身状态：意识水平、呼吸频率与深度、瞳孔大小、血压与心率，评估阿片类药物的作用与不良反应；口腔黏膜、腹部（便秘与肠鸣音）与贴剂部位皮肤。","lab_tests":"必查：血常规、肝肾功能、电解质、血钙、血糖。\n按需：疼痛部位影像学（X线、CT，疑脊髓压迫时磁共振优先并应尽快完成）、肿瘤标志物、凝血功能、尿常规、粪隐血（使用非甾体抗炎药前）、骨扫描或正电子发射断层显像、血药浓度（阿片类中毒或剂量调整困难时）。","nursing":"安全防护：评估跌倒风险，起夜需协助，床栏保护；阿片类用药期间注意防坠床与防跌倒。\n监测与记录：用药后观察呼吸、意识与疼痛评分，记录爆发痛次数、缓解程度与不良反应。\n排泄与口腔护理：鼓励饮水与适当活动，观察排便，便秘者按医嘱用缓泻剂；口腔干燥者加强口腔护理。\n宣教：告知按时服药的重要性与不自行增减剂量的原因，说明阿片类药物的正确储存与剩余药物处置。","diet":"通则：进高蛋白、高维生素、易消化饮食，少量多餐。\n便秘：增加水分与膳食纤维（蔬菜、水果、粗粮），必要时用缓泻剂。\n恶心呕吐：进清淡温凉流质，避免油腻与刺激性食物。\n禁忌：禁酒，避免与阿片类同服加重呼吸抑制。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1245},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d5f920d761d52073269372998b96c8dc030092f2581895366ba91cad2a174605","pinyin":"yebanaitongzhitongchuli","initials":"ybatztcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","伤害性疼痛：骨转移处持续性钝痛或压痛，活动、翻身与负重后加重；内脏痛多为胀痛、绞痛或牵拉痛，位置较弥漫。\\n神经病理性疼痛：电击样、烧灼样、针刺样或撕裂样疼痛，可伴麻木、痛觉过敏与触电感。\\n爆发痛：基础痛控制尚可时突发剧烈疼痛，多在夜间、翻身、换药或排便时出现，持续数分钟至1小时。\\n危险信号：突发剧痛伴肢体无力或大小便障碍（提示脊髓压迫）、突发局部剧痛伴畸形（病理性骨折）、止痛药需求短期内迅速上升、意识改变与呼吸变慢。",60],["摘要","定义：癌痛是肿瘤本身、转移灶或抗肿瘤诊疗过程引起的疼痛，按强度分为轻度（1~3分）、中度（4~6分）与重度（7~10分），按机制分为伤害性疼痛（躯体、内脏）与神经病理性疼痛。\n夜班目标：按疼痛强度阶梯给药，及时控制夜间爆发痛，预防阿片类药物的呼吸抑制、过度镇静与便秘；先排除脊髓压迫、病理性骨折等需要急诊处理的病因。",30],["疾病编码","R52",30],["原首字母","yebanaitongzhitongchuli",60]]},{"id":"orders-55ab4d4198af301f1cbc","key":"v1-c9ccc21dfe2a3058|orders-55ab4d4198af301f1cbc","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班危重患者安全转运要点","category":"夜班工作管理","raw":{"name":"夜班危重患者安全转运要点","category":"夜班工作管理","summary":"危重患者外出检查/转科/转院的安全转运流程：转运前评估风险与准备（人员设备药品）、途中持续监测、交接清楚，最大限度缩短脱离监护与抢救设备的时间。","symptoms":["需外出CT/MRI、介入、手术或转科/转院的重症患者，转运中存在病情恶化风险。"],"diagnosis":["转运前评估：生命体征是否稳定（血压、氧合、意识）、气道与血管通路、携带设备能力；不稳定者先就地稳定再转运，能床旁检查者优先床旁。"],"infusion":["确保静脉通路通畅并备足液体/泵药；携带血管活性药物泵与备用电池，泵药者尽量不断药。"],"oral_medication":["按医嘱给药，转运中带齐当班药物。"],"treatment":["1.转运前评估（是否非转不可）：能床旁检查的先床旁；评估风险并通知接收科室做好接应；2.人员：危重者由医师+护士陪同（生命体征不稳定/气管插管/泵入血管活性药者必备），必要时总住院/上级同往；3.物品：便携监护（心电/血压/SpO2）、氧气（足够全程并有余量）、简易呼吸球囊、除颤/抢救包、急救药品（肾上腺素 0.5-1mg 静推，必要时 3-5min 重复）、输液泵电池；4.途中：持续监护生命体征，观察气道与管路（气管插管位置、引流、输液），记录途中情况；5.时间管理：减少等待，缩短脱离监护与氧气时间；6.返回病房/到达后立即接上病房监护并交接：途中情况、用药调整、检查结果回报与下一步安排；7.转运途中病情恶化→就地抢救并呼叫支援，勿强行继续。"],"management":["建立危重患者转运交接单；科室间与影像/介入等部门协调绿色通道；记录转运时间与途中事件。"],"notes":["评估转运风险宁可保守：不稳定患者先稳定；气管插管者备好气囊与吸痰；带呼吸机/泵药者备电池电量；家属知情并陪同可协助安抚。"],"emergency":["途中出现心跳呼吸骤停、严重低氧、休克→立即原地CPR/抢救并呼叫就近支援。"],"pinyin":"yebanweizhonghuanzheanquanzhuanyunyaodian","icd10":"Z00-Z99","physical_exam":"转运前复核气道、呼吸、循环、意识与GCS、输液泵与管路固定。","lab_tests":"出发前复查关键指标（血气、血糖、血氧）并携带结果；途中按需携带便携监护与急救药品。","nursing":"转运前清点物品与管路固定；途中观察面色SpO2与泵药；到达交接清楚。","diet":"按医嘱（检查要求禁食者提前通知）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1246},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"967235db24a9bf85162644e1048ec755287450c0ba78b4d45e095f3297e34435","pinyin":"yebanweizhonghuanzheanquanzhuanyunyaodian","initials":"ybwzhzaqzyyd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","需外出CT/MRI、介入、手术或转科/转院的重症患者，转运中存在病情恶化风险。",60],["摘要","危重患者外出检查/转科/转院的安全转运流程：转运前评估风险与准备（人员设备药品）、途中持续监测、交接清楚，最大限度缩短脱离监护与抢救设备的时间。",30],["疾病编码","Z00-Z99",30],["原首字母","yebanweizhonghuanzheanquanzhuanyunyaodian",60]]},{"id":"orders-4adff89506903f1d034a","key":"v1-c9ccc21dfe2a3058|orders-4adff89506903f1d034a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"夜班代谢性酸碱失衡处理","category":"值班宝典","raw":{"name":"夜班代谢性酸碱失衡处理","category":"值班宝典","summary":"定义：代谢性酸碱失衡是以碳酸氢根原发性降低（代谢性酸中毒）或升高（代谢性碱中毒）为特征、伴不同程度呼吸代偿的酸碱紊乱，常合并钾、镁、钙等电解质异常，多见于休克、糖尿病急症、肾功能不全、呕吐腹泻与利尿剂使用。\n夜班目标：快速判读动脉血气并结合临床对应，先处理原发病与危及生命的酸血症、碱血症，动态复查电解质，不盲目大量补碱。","symptoms":["代谢性酸中毒：深大呼吸（Kussmaul呼吸）、乏力、恶心呕吐、头痛、嗜睡，重者低血压、心律失常与意识障碍；酮症酸中毒者呼气有烂苹果味。","代谢性碱中毒：呼吸浅慢、手足麻木与搐搦、肌无力、腹胀、心律失常，常伴低钾与低氯。","诱因线索：腹泻、呕吐、胃肠减压、糖尿病、肾衰竭与透析、休克与组织低灌注、利尿剂与碳酸氢钠使用、大量输注生理盐水、酒精中毒。","危险信号：意识改变、抽搐、心率>120次/分或<50次/分、血压下降、呼吸深快。"],"diagnosis":["血气判读：先看pH、二氧化碳分压与碳酸氢根，再用代偿公式判断是单纯型还是混合型紊乱；注意是否合并呼吸性成分。","阴离子间隙：以钠离子减去氯离子与碳酸氢根计算；升高提示酮症酸中毒、乳酸酸中毒、尿毒症或中毒（甲醇、乙二醇、水杨酸）。","病史与用药：腹泻与呕吐量、糖尿病与肾功能、利尿剂与碱性药物、静脉输液种类与量、饮酒与用药史。","鉴别方向：呼吸性酸中毒或碱中毒的混合存在、水杨酸中毒、酒精性酮症、低白蛋白血症对阴离子间隙的干扰。"],"infusion":["严重酸血症（pH<7.1且碳酸氢根<8mmol/L）：5%碳酸氢钠注射液按本院规范缓慢静滴（示例配方：5%碳酸氢钠84mL加0.9%氯化钠注射液200mL，输注速度200mL/h，45~60分钟内输完），纠正目标以pH回升为宜，避免过量与快速输注；补碱后1小时复查动脉血气，目标pH>7.0；pH≥7.0时不再补碱。","补钾：伴低钾者按规范静脉补钾（示例：0.9%氯化钠注射液500mL加10%氯化钾10~30mL静滴，速度≤20mmol/h），注意外周静脉浓度与速度上限并心电监护；每84mL碳酸氢钠需联合补氯化钾10mL。","补液与容量：脱水或休克者先用0.9%氯化钠注射液或平衡盐溶液恢复有效循环血量，再评估是否加碱。","碱中毒：以0.9%氯化钠注射液补充氯与容量，联合补钾、补镁，停用利尿剂与胃肠减压，按本院规范必要时使用盐酸精氨酸等酸性药物（血钠>155mmol/L时停用含钠制剂）。"],"oral_medication":["轻中度代谢性酸中毒且能口服者：碳酸氢钠片0.5~1.0g口服，每日3次，按血气结果调整。","代谢性碱中毒：氯化钾缓释片按缺钾程度口服补充；低氯者可口服氯化钠。","禁忌：意识不清、频繁呕吐、消化道出血或需急诊手术者不口服给药。"],"treatment":["首要：处理原发病——控制感染与休克、改善组织灌注、治疗糖尿病急症、停用致病药物、解除呕吐与腹泻原因。","其次：纠正电解质紊乱，尤其是钾、镁与钙；低钾不纠正则碱中毒难以改善，低磷与低镁也需同步处理。","随后：仅在严重酸血症（pH<7.1且碳酸氢根<8mmol/L）或特定中毒（水杨酸、甲醇、乙二醇）时考虑补碱或血液净化，按本院规范执行。","最后：每2~4小时复查血气与电解质，动态评估疗效，记录补碱量与输液种类。"],"management":["复评频率：急性期每2~4小时复查血气与电解质，稳定后每日1~2次；使用碳酸氢钠后必须复查血气与血钾、血钠。","观察要点：意识、呼吸频率与深度、尿量、心律与血压；手足搐搦与抽搐；有无容量过负荷与高钠血症。","用药管理：记录补碱量、补钾浓度与速度、利尿剂用量与胃肠减压引流量。","收治标准：pH<7.2、碳酸氢根<10mmol/L、伴意识改变或不稳定心律失常、需血液净化者收入监护病房。"],"notes":["以本院规范为准：碳酸氢钠的浓度、输注速度与目标pH，补钾浓度与速度，以及血液净化指征与时机按本院流程执行。","避免与禁忌：不常规大剂量补碱，尤其在乳酸酸中毒、容量过负荷与高钠血症时；不在未纠正低钾时快速补碱（可加重低钾与抽搐）；pH≥7.0时不补碱（增加脑水肿风险）；碳酸氢钠不与含钙溶液同一通路混输。","提醒：血气判读要结合白蛋白与电解质，单看碳酸氢根容易误判混合型紊乱；不明原因的意识改变与抽搐需同时排除低血糖与低钙。"],"emergency":["立即升级：pH<7.1、碳酸氢根<8mmol/L、血钾>6.0mmol/L或<2.5mmol/L、意识改变、持续心律失常 → 立即请上级与肾内科会诊评估血液净化指征。","碱中毒警示：碳酸氢根>40mmol/L或pH>7.55、抽搐或呼吸抑制 → 监护治疗并积极纠正低钾与低氯。","透析指征：严重酸血症伴少尿、容量过负荷、尿毒症或可透析毒物中毒 → 尽快安排血液净化。","高钾紧急处理：10%葡萄糖酸钙注射液10mL静推（>2分钟）并立即复查血钾与心电图。"],"pinyin":"yebandaixiexingsuanjianshihengchuli","icd10":"E87.2","physical_exam":"呼吸：频率与深度（深大呼吸提示严重酸中毒）、有无烂苹果味与呼吸抑制。\n容量与循环：皮肤弹性、口唇与舌干燥、颈静脉充盈、血压、心率、毛细血管再充盈、尿量。\n神经肌肉：意识水平、肌力、腱反射、手足搐搦与Chvostek征、Trousseau征、心律失常与心音改变。","lab_tests":"必查：动脉血气、电解质（钾、钠、氯、钙、镁）、肾功能与尿素氮、血糖、血酮或β-羟丁酸、乳酸、血常规、血清白蛋白。\n按需：尿常规与尿pH、肝功能、血浆渗透压、毒物筛查（甲醇、乙二醇、水杨酸）、心电图、床旁血糖、胸部影像（评估呼吸因素）。","nursing":"监测：按医嘱时间复查血气与电解质，持续心电监护者记录心律变化（T波高尖提示高钾、U波提示低钾）。\n通路安全：外周静脉输注碳酸氢钠时防止外渗造成组织坏死，必要时经中心静脉给药；补钾通路注意速度与局部疼痛。\n记录：出入量、每日体重、利尿剂与碱性药物使用量、胃肠减压引流量。\n安全：意识改变者加床栏、防误吸；抽搐时保护肢体与头部，不强行按压肢体。","diet":"酸中毒：糖尿病酮症者禁含糖饮食，清醒且无呕吐时进糖尿病流质并注意补钾。\n碱中毒：鼓励口服含氯含钾液体，适量进食香蕉、橙汁等富钾食物配合补钾。\n通用：呕吐腹泻者短期禁食，缓解后进温凉流质逐步过渡；肾功能不全者限钾限磷，忌咖啡浓茶与酒精。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1247},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9c3cb61871eb43d9e6969c62b5fd889e5f46256811cf8b7b3d1862f5658ae572","pinyin":"yebandaixiexingsuanjianshihengchuli","initials":"ybdxxsjshcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","代谢性酸中毒：深大呼吸（Kussmaul呼吸）、乏力、恶心呕吐、头痛、嗜睡，重者低血压、心律失常与意识障碍；酮症酸中毒者呼气有烂苹果味。\\n代谢性碱中毒：呼吸浅慢、手足麻木与搐搦、肌无力、腹胀、心律失常，常伴低钾与低氯。\\n诱因线索：腹泻、呕吐、胃肠减压、糖尿病、肾衰竭与透析、休克与组织低灌注、利尿剂与碳酸氢钠使用、大量输注生理盐水、酒精中毒。\\n危险信号：意识改变、抽搐、心率>120次/分或<50次/分、血压下降、呼吸深快。",60],["摘要","定义：代谢性酸碱失衡是以碳酸氢根原发性降低（代谢性酸中毒）或升高（代谢性碱中毒）为特征、伴不同程度呼吸代偿的酸碱紊乱，常合并钾、镁、钙等电解质异常，多见于休克、糖尿病急症、肾功能不全、呕吐腹泻与利尿剂使用。\n夜班目标：快速判读动脉血气并结合临床对应，先处理原发病与危及生命的酸血症、碱血症，动态复查电解质，不盲目大量补碱。",30],["疾病编码","E87.2",30],["原首字母","yebandaixiexingsuanjianshihengchuli",60]]},{"id":"orders-43b0a37657000c1a53c1","key":"v1-c9ccc21dfe2a3058|orders-43b0a37657000c1a53c1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值管理与处理总则","category":"内科危急值","raw":{"name":"危急值管理与处理总则","category":"内科危急值","summary":"危急值指检验/检查结果提示患者可能处于生命危险边缘，需医师立即获取信息并迅速干预。总体要求：即时识别与通知、值班医师尽快确认处置、规范记录、复查评估；护理可先行监护与建立通路。","symptoms":["接到检验科/仪器危急值报告时，涉及血糖、血钾、钠钙、酸碱、血气、血常规凝血、心肌损伤标志物等异常。"],"diagnosis":["接报后先复核结果（疑假性者复查），判断危急值与患者病情的相关性，排除抽血/标本/检测干扰后立即评估患者。"],"infusion":["按危急值类型处置：护理可先行建立静脉通路、采血备血、心电监护（无需等书面医嘱）。"],"oral_medication":["按危急值类型用药（口服或静脉由医师决定）。"],"treatment":["1.结果审核后尽快（一般5-10分钟内）通知值班医师并确认接收；2.值班医师立即查看患者并评估生命体征；3.按项目危急值流程处置（见各危急值条目）；4.使用危急值病程记录模板记录：时间、报告项目与数值、患者评估、处置措施、复查计划；5.处理30分钟内评估效果，无改善升级呼叫上级/ICU；6.24小时内复查相关项目并闭环；7.值班期间无法处理的疑难情况上报总住院/科室主任。"],"management":["危急值接报、处置、复查、关闭全流程记录在案；交接班时交接未闭环的危急值。"],"notes":["依据《内科常见危急值及详细处理》整理；实际阈值与处置请以本院危急值报告制度和最新指南为准。危急值处理核心是\"快\"：快速复核、快速评估、快速处置、快速记录、及时复查；勿因等待书面医嘱延误护理同步监护与备血。"],"emergency":["任何危急值伴生命体征不稳定、意识障碍或可能立即危及生命者，立即启动抢救流程并呼叫支援。"],"pinyin":"weijizhiguanliyuchulizongze","icd10":"Z00-Z99","physical_exam":"立即查看患者：意识、生命体征（血压心率呼吸SpO2）、重点体征，评估是否需要紧急干预。","lab_tests":"复核异常项目，按需要复查并加做相关项目（如电解质异常查肾功能心电图、D-二聚体高查CTPA等）。","nursing":"接报后核对患者并立即通知医师；按护理常规监测生命体征并记录；执行危急值处置医嘱并观察反应。","diet":"按原发病与危急值类型执行（如低血糖者意识清醒即口服糖水等）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1248},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6fc378d19df46412be66f7e42c31973dcf3de988e35be50deb687a400254377f","pinyin":"weijizhiguanliyuchulizongze","initials":"wjzglyclzz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","接到检验科/仪器危急值报告时，涉及血糖、血钾、钠钙、酸碱、血气、血常规凝血、心肌损伤标志物等异常。",60],["摘要","危急值指检验/检查结果提示患者可能处于生命危险边缘，需医师立即获取信息并迅速干预。总体要求：即时识别与通知、值班医师尽快确认处置、规范记录、复查评估；护理可先行监护与建立通路。",30],["疾病编码","Z00-Z99",30],["原首字母","weijizhiguanliyuchulizongze",60]]},{"id":"orders-7d407b469cf36e47c7e7","key":"v1-c9ccc21dfe2a3058|orders-7d407b469cf36e47c7e7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：动脉血pH≤7.20（重度酸血症）","category":"内科危急值","raw":{"name":"危急值：动脉血pH≤7.20（重度酸血症）","category":"内科危急值","summary":"动脉血pH≤7.20为重度失代偿性酸中毒，可致心肌收缩力下降、低血压、心律失常与意识障碍；同步乳酸>5mmol/L提示更危重。需紧急区分呼吸性/代谢性并针对性干预。","symptoms":["呼吸深快、意识障碍、低血压、心率快或心律失常、乏力嗜睡；可伴原发病表现（Kussmaul呼吸等）。"],"diagnosis":["复查血气确认pH；查阴离子间隙AG、乳酸、酮体、肾功能、电解质与血糖，区分呼吸性/代谢性、AG增高/正常型酸中毒及病因（DKA、乳酸酸中毒、尿毒症、中毒、腹泻等）。"],"infusion":["呼吸性酸中毒：增加分钟通气量——无创通气（BiPAP：IPAP 10-20cmH2O、EPAP 4-8cmH2O）或气管插管机械通气（VT 6-8ml/kg，调整RR至pH>7.25）；代谢性AG增高型：按病因（DKA胰岛素+补液、乳酸酸中毒改善灌注、尿毒症透析）；AG正常型且HCO3<12mmol/L可补碱：所需NaHCO3(mmol)=0.3×体重(kg)×(目标HCO3-实测HCO3)，分次缓慢补充。"],"oral_medication":["按病因口服用药（糖尿病、肾衰等长期治疗药物）。"],"treatment":["1.立即ABC评估并心电监护、SpO2监测；2.复查血气并查AG/乳酸/酮体/肾功能区分类型；3.呼吸性→加强通气（无创/有创），纠正通气不足；4.代谢性AG增高→针对病因（DKA、休克乳酸酸中毒、尿毒症、中毒）；5.代谢性AG正常（HCO3丢失型）→必要时补碱；6.15-30分钟后复查血气评估疗效并调整；7.同时纠正电解质紊乱，注意酸中毒纠正后出现低钾、低钙（补碱后钾内移），动态复查；8.处理原发病并防治并发症（心律失常、脑水肿）。"],"management":["重症入监护，动态血气与电解质；记录处置与复查时间。"],"notes":["补碱需把握指征避免过快（防低钾、脑脊液反常酸化、容量过负荷）；乳酸酸中毒重在改善灌注与病因而非单纯补碱；通气纠正需防CO2排出过快。"],"emergency":["pH持续<7.0、血压难维持、意识恶化、心律失常→紧急处理并呼叫ICU/相应专科，必要时透析/CRRT。"],"pinyin":"weijizhi：dongmaixuepH≤7.20（zhongdusuanxuezheng）","icd10":"E87.2","physical_exam":"ABC评估：气道、呼吸（频率深度、呼吸肌）、循环（血压、心率、灌注）、意识；观察皮肤黏膜与脱水。","lab_tests":"动脉血气（复查）、电解质（钾氯）、乳酸、血糖、酮体、肾功能、AG；心电图（高钾等）。","nursing":"心电监护观察心律；协助血气复查；记录呼吸频率与意识；静脉用药观察（补碱外渗）。","diet":"按原发病（糖尿病、肾病等）饮食管理。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1249},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2103eac75d3a64759b71a90d7e416319983f9616419264ff4fcaf01e2e307272","pinyin":"weijizhi：dongmaixuepH≤7.20（zhongdusuanxuezheng）","initials":"wjz：dmxpzdsxz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呼吸深快、意识障碍、低血压、心率快或心律失常、乏力嗜睡；可伴原发病表现（Kussmaul呼吸等）。",60],["摘要","动脉血pH≤7.20为重度失代偿性酸中毒，可致心肌收缩力下降、低血压、心律失常与意识障碍；同步乳酸>5mmol/L提示更危重。需紧急区分呼吸性/代谢性并针对性干预。",30],["疾病编码","E87.2",30],["原首字母","weijizhi：dongmaixuepH≤7.20（zhongdusuanxuezheng）",60]]},{"id":"orders-a6551db68c8a757d2a7d","key":"v1-c9ccc21dfe2a3058|orders-a6551db68c8a757d2a7d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：动脉血pH≥7.60（重度碱血症）","category":"内科危急值","raw":{"name":"危急值：动脉血pH≥7.60（重度碱血症）","category":"内科危急值","summary":"动脉血pH≥7.60为重度失代偿性碱中毒，可致脑血管收缩、意识障碍、抽搐、手足搐搦（游离钙下降）与心律失常（低钾）。需区分呼吸性/代谢性并紧急纠正。","symptoms":["意识模糊、眩晕、抽搐、手足麻木与搐搦、心律失常；呼吸性者呼吸深快（过度通气）。"],"diagnosis":["复查血气确认；查电解质（钾氯）、容量状态，区分呼吸性（过度通气：低氧、肺栓塞、中枢病变、焦虑）与代谢性（呕吐、利尿剂、低钾低氯、容量不足）碱中毒。"],"infusion":["代谢性碱中毒：生理盐水扩容+补钾补氯（常合并低钾低氯，目标血钾>4.0mmol/L）；严重代谢性碱中毒（pH>7.55且补液无效）可予乙酰唑胺250-500mg静滴q12-24h；极重度（pH>7.60仍无效）考虑稀盐酸经中心静脉缓慢输注（需有经验者执行）。"],"oral_medication":["补钾口服或静脉（氯化钾）；呕吐者止吐并停用/减利尿剂。"],"treatment":["1.评估通气与容量，区分呼吸性/代谢性；2.呼吸性：寻找并纠正过度通气原因（低氧→氧疗；肺栓塞→抗凝；焦虑→安抚，必要时重复呼吸面罩/镇静），病因治疗；3.代谢性：纠正病因（止吐、减停利尿剂、补钾补氯、补液扩容）；4.补钾补氯直到血钾>4.0mmol/L、血氯正常；5.顽固性代谢性碱中毒用乙酰唑胺或稀盐酸；6.监测血气与电解质q4-6h；7.同时处理低钙（搐搦时补钙，先纠碱）。"],"management":["动态血气电解质监测；呼吸性者持续观察呼吸与神志。"],"notes":["碱中毒纠正过快可诱发低钾与心律失常；补钾补氯前先保证尿量；代谢性碱中毒几乎都合并低钾低氯，别只纠碱不补钾。"],"emergency":["抽搐持续、意识障碍加重、严重心律失常→急查血电解质与血气并按急症处理（补钾补钙、必要时镇静）。"],"pinyin":"weijizhi：dongmaixuepH≥7.60（zhongdujianxuezheng）","icd10":"E87.3","physical_exam":"呼吸频率与模式、意识、Trousseau/Chvostek征（低钙）、皮肤黏膜脱水、血压。","lab_tests":"血气动态、电解质（钾氯钙镁）、肾功能、尿氯（鉴别氯敏感/抵抗）；心电图。","nursing":"观察呼吸、神志与手足搐搦；心电监护；静脉补钾浓度速度核对。","diet":"正常饮食（呕吐者防误吸）；鼓励含钾食物。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1250},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8923fa37200a11f225c7ac990602e4f5cebae0bd8bea5402d630e5cd80b29241","pinyin":"weijizhi：dongmaixuepH≥7.60（zhongdujianxuezheng）","initials":"wjz：dmxpzdjxz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","意识模糊、眩晕、抽搐、手足麻木与搐搦、心律失常；呼吸性者呼吸深快（过度通气）。",60],["摘要","动脉血pH≥7.60为重度失代偿性碱中毒，可致脑血管收缩、意识障碍、抽搐、手足搐搦（游离钙下降）与心律失常（低钾）。需区分呼吸性/代谢性并紧急纠正。",30],["疾病编码","E87.3",30],["原首字母","weijizhi：dongmaixuepH≥7.60（zhongdujianxuezheng）",60]]},{"id":"orders-bd9eec41448820dca905","key":"v1-c9ccc21dfe2a3058|orders-bd9eec41448820dca905","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：PaO2<40mmHg（重度低氧血症）","category":"内科危急值","raw":{"name":"危急值：PaO2<40mmHg（重度低氧血症）","category":"内科危急值","summary":"动脉血PaO2<40mmHg（对应SpO2约<75%）为重度低氧血症，属呼吸衰竭与紧急气管插管指征之一，可迅速进展为多器官功能障碍；需立即高流量氧疗并查找低氧原因。","symptoms":["严重呼吸困难、发绀、烦躁或意识障碍、呼吸急促、大汗；可伴原发疾病表现（肺炎、肺水肿、肺栓塞等）。"],"diagnosis":["复查血气确认；按PaCO2区分I型（PaCO2正常或低）与II型（PaCO2>50mmHg）呼吸衰竭；胸片/CT、心电图、BNP等查找病因（肺炎、ARDS、肺栓塞、气胸、心源性肺水肿、气道梗阻）。"],"infusion":["立即高流量吸氧：储氧非再呼吸面罩10-15L/min，目标SpO2≥92%（COPD患者88%-92%）；不能维持→无创通气（CPAP/BiPAP）或高流量鼻导管氧疗（30-60L/min，FiO2 0.5-1.0）；仍无效或意识恶化→气管插管机械通气（VT 6-8ml/kg，PEEP 5-10cmH2O，FiO2初始1.0后下调）。"],"oral_medication":["按病因给药（抗感染、利尿等，多数经静脉）。"],"treatment":["1.立即高流量氧疗并评估意识与呼吸肌做功；2.常规氧疗不达标→无创通气或HFNC；3.无效或意识障碍加重→气管插管有创通气；4.查找并治疗病因：重症肺炎抗感染、ARDS肺保护通气、肺栓塞抗凝/溶栓、气胸引流、心源性肺水肿利尿+扩血管+正性肌力；5.顽固性低氧（PaO2/FiO2<150）评估俯卧位通气、肌松、ECMO；6.持续SpO2与血气监测（稳定前q30min，稳定后q2-4h）并随访乳酸与血流动力学。"],"management":["重症入ICU；动态血气与呼吸机参数管理；查找并处理可逆病因。"],"notes":["COPD患者避免高浓度氧致CO2潴留（目标SpO2 88%-92%）；PaO2<40mmHg必须按紧急插管指征评估；氧疗同时不放松病因诊断。"],"emergency":["意识障碍、呼吸衰竭进行性加重、SpO2无法维持→立即气管插管并呼救。"],"pinyin":"weijizhi：PaO2<40mmHg（zhongdudiyangxuezheng）","icd10":"J96.9","physical_exam":"气道通畅性、呼吸频率与呼吸肌做功、发绀、双肺呼吸音（减弱/啰音/哮鸣）、气管位置、颈静脉、血压心率意识。","lab_tests":"动脉血气（动态）、乳酸、血常规、D-二聚体、肌钙蛋白/BNP、胸片（必要时CT/CTPA）、心电图。","nursing":"高流量吸氧/无创通气护理（面罩贴合、湿化）；监测SpO2与血气；协助体位（半卧位/俯卧位）；气道护理与吸痰。","diet":"呼吸困难期半流质少食多餐，进食抬高床头防误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1251},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b55df755f4a143256e0aa79e0f90e0fac27f1f083d2dc75d46118ca0f26dee50","pinyin":"weijizhi：PaO2<40mmHg（zhongdudiyangxuezheng）","initials":"wjz：zddyxz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","严重呼吸困难、发绀、烦躁或意识障碍、呼吸急促、大汗；可伴原发疾病表现（肺炎、肺水肿、肺栓塞等）。",60],["摘要","动脉血PaO2<40mmHg（对应SpO2约<75%）为重度低氧血症，属呼吸衰竭与紧急气管插管指征之一，可迅速进展为多器官功能障碍；需立即高流量氧疗并查找低氧原因。",30],["疾病编码","J96.9",30],["原首字母","weijizhi：PaO2<40mmHg（zhongdudiyangxuezheng）",60]]},{"id":"orders-fb85c8340d80d541ced1","key":"v1-c9ccc21dfe2a3058|orders-fb85c8340d80d541ced1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：PaCO2>70mmHg（重度高碳酸血症）","category":"内科危急值","raw":{"name":"危急值：PaCO2>70mmHg（重度高碳酸血症）","category":"内科危急值","summary":"动脉血PaCO2>70mmHg伴pH下降为急性呼吸性酸中毒，可致\"CO2麻醉\"（头痛、意识模糊、嗜睡至昏迷）；慢性COPD可耐受较高PaCO2，但急性升高仍为危急值，需评估气道并加强通气。","symptoms":["头痛、意识模糊、扑翼样震颤、嗜睡→昏迷、呼吸浅慢或费力、皮肤潮红多汗（CO2潴留）。"],"diagnosis":["复查血气：PaCO2>70mmHg伴pH下降为急性；结合基础病判断（AECOPD、哮喘急性发作、镇静剂过量、神经肌肉疾病、中枢抑制）。"],"infusion":["GCS>8且气道可保护→无创通气（BiPAP ST：IPAP 10-20cmH2O、EPAP 4-6cmH2O、备用频率12-15次/min）；GCS≤8或呼吸肌疲劳/暂停→气管插管机械通气；注意控制PaCO2下降速度<10-15mmHg/h，避免过快致碱中毒与脑血流骤降。"],"oral_medication":["镇静剂过量者予纳洛酮（静脉）；AECOPD/哮喘按原发病给药。"],"treatment":["1.评估意识与气道保护能力；2.选无创或有创通气加强通气；3.治疗原发病：AECOPD（支气管扩张剂+激素+抗生素）、哮喘急性发作（速效β2激动剂+ICS+全身激素）、镇静剂过量（纳洛酮 0.4-2mg 静推/肌注，必要时每 2-3min 重复，总量≤10mg）、神经肌肉病（病因治疗）；4.PaCO2持续不降→查找低通气原因（气道阻塞、呼吸肌无力、中枢抑制、死腔增加）；5.动态血气与意识监测，避免CO2下降过快。"],"management":["监测血气q30-60min至稳定、意识状态与呼吸力学；COPD者注意氧疗浓度与FiO2滴定。"],"notes":["避免高浓度氧掩盖并加重CO2潴留（COPD目标SpO2 88%-92%）；过快纠正高碳酸血症可致脑血流骤减与心律问题，PaCO2降速宜<10-15mmHg/h。"],"emergency":["意识进行性下降、呼吸暂停、pH<7.2且无创通气无效→立即气管插管并呼救。"],"pinyin":"weijizhi：PaCO2>70mmHg（zhongdugaotansuanxuezheng）","icd10":"J96.9","physical_exam":"意识（GCS）、气道保护能力、呼吸频率与呼吸肌（疲劳/矛盾呼吸）、瞳孔、皮肤潮红。","lab_tests":"动脉血气动态、血常规、电解质、胸片、血培养等（按病因）；意识差者排除镇静剂/中毒（血药浓度）。","nursing":"无创通气护理（面罩、漏气、人机配合）；意识监测；吸痰与气道护理。","diet":"按原发病（进食抬高床头防误吸）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1252},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9174ba8dd77bf661fa639421e9f2bd60df55d84e784d4521ebeb7ab974775a21","pinyin":"weijizhi：PaCO2>70mmHg（zhongdugaotansuanxuezheng）","initials":"wjz：zdgtsxz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","头痛、意识模糊、扑翼样震颤、嗜睡→昏迷、呼吸浅慢或费力、皮肤潮红多汗（CO2潴留）。",60],["摘要","动脉血PaCO2>70mmHg伴pH下降为急性呼吸性酸中毒，可致\"CO2麻醉\"（头痛、意识模糊、嗜睡至昏迷）；慢性COPD可耐受较高PaCO2，但急性升高仍为危急值，需评估气道并加强通气。",30],["疾病编码","J96.9",30],["原首字母","weijizhi：PaCO2>70mmHg（zhongdugaotansuanxuezheng）",60]]},{"id":"orders-2d7a3c22918e942c320f","key":"v1-c9ccc21dfe2a3058|orders-2d7a3c22918e942c320f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：血乳酸>4mmol/L（高乳酸血症）","category":"内科危急值","raw":{"name":"危急值：血乳酸>4mmol/L（高乳酸血症）","category":"内科危急值","summary":"血乳酸>4mmol/L提示组织低灌注/缺氧（A级），病死率显著升高（约30%-50%）；乳酸清除率是复苏效果核心指标。需评估灌注、查找六大类病因并针对性治疗。","symptoms":["原发疾病表现：发热休克（脓毒症）、胸痛心衰（心源性）、失血脱水（低血容量）、突发呼吸困难（肺栓塞）、腹痛（肠系膜缺血）；灌注不足体征（皮肤花斑、末梢凉、尿少、意识改变）。"],"diagnosis":["复查乳酸确认；评估灌注（毛细血管充盈>3s、皮肤花斑、尿量<0.5ml/(kg·h)、意识、肢端温度）；查找病因：脓毒症、心源性、低血容量性、梗阻性（PE/心包填塞）、局部缺血（肠系膜/肢体）、药物毒物（二甲双胍、甲醇、氰化物）。"],"infusion":["脓毒症按1小时集束化处理：血培养→广谱抗生素→液体复苏30ml/kg→血管活性药；心源性→正性肌力+血管活性药+冠脉再灌注；低血容量→积极补液（晶体/血液制品）；肠系膜缺血→急诊造影/手术。"],"oral_medication":["停用可能致乳酸升高的药物（二甲双胍等）并评估。"],"treatment":["1.评估组织灌注并寻找病因（六类）；2.病因治疗是核心（脓毒症抗感染复苏、心源性改善心功能与再灌注、低血容量补液、梗阻性解除梗阻、肠缺血手术、药物停用与解毒）；3.30分钟内复查乳酸，计算乳酸清除率=（初值-复测）/初值×100%，6小时清除率<10%提示预后不良需调整策略；4.持续监测乳酸q2-4h、血气与血流动力学；5.维持灌注目标：MAP≥65mmHg、尿量≥0.5ml/(kg·h)、乳酸下降。"],"management":["重症转ICU；记录液体复苏与乳酸趋势；多学科处理病因。"],"notes":["乳酸酸中毒关键在于病因与灌注而非单纯补碱；二甲双胍相关乳酸酸中毒停二甲双胍并考虑透析；肿瘤/肝病等非缺氧性乳酸升高需鉴别。"],"emergency":["休克、难治性低灌注、乳酸持续升高→强化复苏并呼救（必要时CRRT等）。"],"pinyin":"weijizhi：xuerusuan>4mmol/L（gaorusuanxuezheng）","icd10":"E87.2","physical_exam":"生命体征与MAP、皮肤灌注与花斑、毛细血管再充盈、尿量、心肺与腹部（压痛、肠鸣音）、肢端。","lab_tests":"乳酸（复查）、血气、血常规、肝肾功能电解质、CRP/PCT、血培养、心肌损伤标志物、D-二聚体、影像（胸片/CT/血管造影按需）。","nursing":"记录尿量、皮肤灌注、乳酸复查时间；输液复苏观察心肺负荷。","diet":"按原发病（休克期禁食）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1253},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9b1942a49b391a530b5802e8d87f4234d07c2f01eb9e48db43f065c1c83ebbd9","pinyin":"weijizhi：xuerusuan>4mmol/L（gaorusuanxuezheng）","initials":"wjz：xrs>grsxz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","原发疾病表现：发热休克（脓毒症）、胸痛心衰（心源性）、失血脱水（低血容量）、突发呼吸困难（肺栓塞）、腹痛（肠系膜缺血）；灌注不足体征（皮肤花斑、末梢凉、尿少、意识改变）。",60],["摘要","血乳酸>4mmol/L提示组织低灌注/缺氧（A级），病死率显著升高（约30%-50%）；乳酸清除率是复苏效果核心指标。需评估灌注、查找六大类病因并针对性治疗。",30],["疾病编码","E87.2",30],["原首字母","weijizhi：xuerusuan>4mmol/L（gaorusuanxuezheng）",60]]},{"id":"orders-46dbe5e900c2a27060e7","key":"v1-c9ccc21dfe2a3058|orders-46dbe5e900c2a27060e7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：D-二聚体>5.0μg/mL（高血栓负荷）","category":"内科危急值","raw":{"name":"危急值：D-二聚体>5.0μg/mL（高血栓负荷）","category":"内科危急值","summary":"D-二聚体显著升高（>5.0μg/mL）强烈提示急性血栓事件（大面积/次大面积肺栓塞、DIC、主动脉夹层、深静脉血栓、恶性肿瘤等），需结合临床紧急排查与抗凝/再灌注处理。","symptoms":["突发胸痛、呼吸困难、咯血、晕厥（PE）；下肢肿痛（DVT）；多部位出血（DIC）；胸背撕裂痛（夹层）等。"],"diagnosis":["评估生命体征与PE危险分层（sPESI）；血流动力学稳定者CTPA确诊PE并抗凝；不稳定者（SBP<90mmHg或下降≥40mmHg持续15分钟）疑大面积PE，考虑溶栓/介入；同时排查主动脉夹层（增强CT/CTA）、DIC（ISTH评分）、恶性肿瘤。"],"infusion":["大面积PE（休克）：rt-PA 100mg静滴2h（或半量50mg）溶栓，溶栓禁忌→导管介入或外科取栓；初始普通肝素80U/kg负荷后18U/(kg·h)泵入（APTT 1.5-2.5×正常）；次大面积：低分子肝素（依诺肝素1mg/kg皮下q12h）或磺达肝癸钠。"],"oral_medication":["病情稳定后过渡口服抗凝：华法林（重叠肝素至INR 2-3）或NOAC（利伐沙班15mg bid×3周后20mg qd等）。"],"treatment":["1.评估生命体征与PE严重度；2.血流动力学不稳定→再灌注（溶栓/导管/手术）+抗凝；3.稳定但sPESI≥1（次大面积）→CTPA确诊后治疗性抗凝并密切监测（血压SpO2心功能），恶化升级；4.绝对卧床、吸氧（SpO2≥92%）、心电监护；5.排查夹层/DIC/肿瘤等病因；6.长期抗凝≥3-6个月并查找易栓因素；7.中高危PE可考虑导管定向溶栓（按最新指南）。"],"management":["心电监护，心超评估右室（RV/LV>0.9提示右心功能不全）；抗凝期间监测出血。"],"notes":["D-二聚体阴性不能完全排除PE（低临床概率时排除价值大），>5.0μg/mL特异性较高必须重视；溶栓前评估出血禁忌。"],"emergency":["休克、晕厥、心跳骤停→按大面积PE/ACLS流程并尽快再灌注。"],"pinyin":"weijizhi：D-erjuti>5.0μg/mL（gaoxueshuanfuhe）","icd10":"I26.9","physical_exam":"生命体征与SpO2、右心衰体征（颈静脉怒张、P2亢进）、下肢不对称肿胀（DVT）、出血点瘀斑（DIC）。","lab_tests":"D-二聚体复查、血气、肌钙蛋白、BNP、凝血与DIC全套、心电图、胸片；CTPA或CTA；下肢静脉超声。","nursing":"绝对卧床防再栓塞；吸氧监护；观察出血征象（黑便、血尿、皮肤黏膜）；DVT患肢抬高勿按摩。","diet":"抗凝期间饮食相对稳定（华法林注意含维生素K食物）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1254},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e7b088fff9f221a3ac59985542f3f4f81bbf4a0110bc085c64a8c18b3be3d688","pinyin":"weijizhi：D-erjuti>5.0μg/mL（gaoxueshuanfuhe）","initials":"wjz：ejt>gxsfh）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发胸痛、呼吸困难、咯血、晕厥（PE）；下肢肿痛（DVT）；多部位出血（DIC）；胸背撕裂痛（夹层）等。",60],["摘要","D-二聚体显著升高（>5.0μg/mL）强烈提示急性血栓事件（大面积/次大面积肺栓塞、DIC、主动脉夹层、深静脉血栓、恶性肿瘤等），需结合临床紧急排查与抗凝/再灌注处理。",30],["疾病编码","I26.9",30],["原首字母","weijizhi：D-erjuti>5.0μg/mL（gaoxueshuanfuhe）",60]]},{"id":"orders-8991c77af2f2b705b615","key":"v1-c9ccc21dfe2a3058|orders-8991c77af2f2b705b615","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：张力性气胸","category":"内科危急值","raw":{"name":"危急值：张力性气胸","category":"内科危急值","summary":"张力性气胸因胸腔内正压压迫纵隔与健侧肺、阻碍静脉回流，可迅速致低血压休克，数分钟内致命——临床体征明显时立即穿刺减压，不等影像。","symptoms":["突发进行性呼吸困难、剧烈胸痛、发绀、烦躁；查体患侧呼吸音消失、叩诊鼓音、气管向健侧偏移、颈静脉怒张、低血压。"],"diagnosis":["主要靠临床体征紧急判断（勿等待影像延误）；床旁超声/胸片可见肺压缩与纵隔移位可证实；注意机械通气患者发生气胸进展更快。"],"infusion":["紧急减压：14-16G粗针头于第2肋间锁骨中线（或第4-5肋间腋前线）穿刺排气（垂直进针至落空、有气体逸出）；随后第4-5肋间腋中线/腋前线置胸腔闭式引流管接水封瓶（-10~-20cmH2O负压）；首次排气放气勿过快防复张性肺水肿。"],"oral_medication":["镇痛（避免抑制呼吸）；按需抗生素（引流相关）。"],"treatment":["1.临床确诊张力性气胸立即穿刺减压（不等待影像）；2.减压后放置胸腔闭式引流；3.呼吸机相关气胸→立即降低通气压力（PEEP降至0、降低VT）；4.影像确认引流管位置与肺复张；5.持续漏气>3-5天请胸外科（肺大疱切除/胸膜固定）；6.拔管指征：漏气停止24小时+胸片肺复张良好+夹管6-24小时无复发；7.处理基础肺病并预防复发（戒烟、避免屏气）。"],"management":["引流期间每日观察气泡、液面波动与引流量；定期胸片；转运固定引流管。"],"notes":["张力性气胸是临床急症，见典型体征立即减压，绝不因等影像延误；减压后仍低氧低血压须复查排除血气胸或复张失败。"],"emergency":["呼吸循环迅速恶化、双侧气胸、引流无效→立即再评估并加强减压（第二针/另置管）并呼救。"],"pinyin":"weijizhi：zhanglixingqixiong","icd10":"J93.0","physical_exam":"生命体征与SpO2、气管位置、患侧叩诊（鼓音）与呼吸音（减弱/消失）、皮下气肿、颈静脉怒张。","lab_tests":"血气（重症）、胸片（处理后证实与评估）、CT（复杂/评估肺大疱）。","nursing":"半卧位吸氧；观察呼吸SpO2与气管位置；水封瓶护理（位置低于胸部、记录气泡）；引流管固定防脱管。","diet":"正常饮食，避免用力屏气与便秘用力。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1255},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"26133e8f5526c9d42a2b6dea4278fb867f9d8dcac0ca2be8eb96e08f90fe9e68","pinyin":"weijizhi：zhanglixingqixiong","initials":"wjz：zlxqx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发进行性呼吸困难、剧烈胸痛、发绀、烦躁；查体患侧呼吸音消失、叩诊鼓音、气管向健侧偏移、颈静脉怒张、低血压。",60],["摘要","张力性气胸因胸腔内正压压迫纵隔与健侧肺、阻碍静脉回流，可迅速致低血压休克，数分钟内致命——临床体征明显时立即穿刺减压，不等影像。",30],["疾病编码","J93.0",30],["原首字母","weijizhi：zhanglixingqixiong",60]]},{"id":"orders-aed169ccbdb274a29590","key":"v1-c9ccc21dfe2a3058|orders-aed169ccbdb274a29590","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：大面积肺栓塞（高危PE）","category":"内科危急值","raw":{"name":"危急值：大面积肺栓塞（高危PE）","category":"内科危急值","summary":"CTPA示主肺动脉/左右肺动脉主干/多叶段充盈缺损，伴持续低血压（SBP<90mmHg>15分钟）为高危（大面积）PE，30天死亡率15%-30%，需立即再灌注治疗；无休克但右心功能不全者预后亦差。","symptoms":["突发呼吸困难、胸痛、咯血、晕厥；低血压/休克、发绀、右心衰表现；常有DVT/制动/肿瘤/术后等背景。"],"diagnosis":["CTPA确诊；血流动力学不稳定（SBP<90mmHg持续>15min或下降≥40mmHg）为高危；稳定但心超RV/LV>0.9+肌钙蛋白升高为中高危；动态心电图、血气辅助。"],"infusion":["高危伴休克：rt-PA 100mg静滴2h（出血风险高可选半量50mg）；溶栓禁忌→导管介入（碎栓+局部溶栓/吸栓）或外科取栓；初始抗凝：普通肝素80U/kg负荷→18U/(kg·h)泵入（APTT 1.5-2.5×正常）。"],"oral_medication":["稳定后过渡口服抗凝（华法林或NOAC），疗程≥3-6个月。"],"treatment":["1.确认血流动力学状态；2.高危→立即再灌注（溶栓/导管/手术）+抗凝，同时绝对卧床、吸氧（SpO2≥92%）、心电监护；3.中高危→治疗性抗凝（低分子肝素 依诺肝素 1mg/kg 皮下 q12h，或磺达肝癸钠 7.5mg 皮下 qd，体重<50kg 用 5mg）并密切监测，恶化升级溶栓；4.低血压者液体谨慎（右心衰者过量补液有害，首剂负荷≤500ml），可予血管活性药（去甲肾上腺素 0.05-0.5μg/kg/min 静滴）；5.查找易栓因素（遗传/获得性）并制定长期抗凝疗程；6.中高危者按最新指南评估导管定向溶栓。"],"management":["入ICU/监护：血压SpO2心电与心功能动态评估；抗凝监测与出血观察。"],"notes":["大面积PE病情凶险，再灌注决策要快；溶栓需权衡出血风险（近期手术、活动性出血、颅内病变为禁忌）；右心衰竭者避免过度补液。"],"emergency":["心跳骤停（大块PE）→CPR并按需溶栓/手术取栓；休克持续→紧急再灌注并呼救。"],"pinyin":"weijizhi：damianjifeishuansai（gaoweiPE）","icd10":"I26.0","physical_exam":"血压心率呼吸SpO2、颈静脉怒张、P2亢进、三尖瓣反流杂音、下肢DVT体征、发绀休克。","lab_tests":"血气、肌钙蛋白、BNP/NT-proBNP、D-二聚体、凝血、心超（RV/LV）、CTPA、DVT超声。","nursing":"绝对卧床；高流量吸氧监护；观察血压心律与出血征象；DVT患肢抬高制动。","diet":"抗凝期间饮食相对稳定。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1256},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"30473eb44385bc54b6e47333bd7e0bae41f15030b155e0759bd378b33c101c7e","pinyin":"weijizhi：damianjifeishuanse（gaoweiPE）","initials":"wjz：dmjfss（gwP","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发呼吸困难、胸痛、咯血、晕厥；低血压/休克、发绀、右心衰表现；常有DVT/制动/肿瘤/术后等背景。",60],["摘要","CTPA示主肺动脉/左右肺动脉主干/多叶段充盈缺损，伴持续低血压（SBP<90mmHg>15分钟）为高危（大面积）PE，30天死亡率15%-30%，需立即再灌注治疗；无休克但右心功能不全者预后亦差。",30],["疾病编码","I26.0",30],["原首字母","weijizhi：damianjifeishuansai（gaoweiPE）",60]]},{"id":"orders-da75b09cd3dfb7f1dc9d","key":"v1-c9ccc21dfe2a3058|orders-da75b09cd3dfb7f1dc9d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：高钾血症（血钾≥6.5mmol/L）","category":"内科危急值","raw":{"name":"危急值：高钾血症（血钾≥6.5mmol/L）","category":"内科危急值","summary":"血钾≥6.5mmol/L（或任意血钾伴心电图改变）为高钾危急值，可致传导阻滞、缓慢性心律失常甚至室颤/停搏；心电图可无典型改变（约半数），勿依赖ECG判断严重度。处理按\"降钾三步法\"：稳定心肌→促内移→促排出。","symptoms":["可无症状（化验发现）或肌无力、肢端麻木、心率慢、心悸；ECG可示T波高尖、P波消失、QRS增宽、正弦波。"],"diagnosis":["复查血钾确认（排除溶血假性升高）；查肾功能、血气（酸中毒）、用药史（ACEI/ARB、保钾利尿剂、补钾）；按血钾与心电图分级。"],"infusion":["①膜稳定：10%葡萄糖酸钙10-30ml（或10%氯化钙5-10ml）缓慢静推2-5min，心电监护，必要时5-10min重复一次；②促内移：胰岛素10U+50%葡萄糖50ml静滴（监测血糖≥12h），可联合沙丁胺醇10-20mg雾化；合并代酸者5%碳酸氢钠100-250ml；③促排出：呋塞米20-40mg静推（有残余肾功能）、环硅酸锆钠10g口服/鼻饲（1h起效）。"],"oral_medication":["聚苯乙烯磺酸钠等树脂口服（起效慢）、环硅酸锆钠口服；慢性期管理用patiromer等。"],"treatment":["1.立即停用钾制剂与保钾药并心电监护；2.三步降钾（钙剂→胰岛素+葡萄糖→排钾）；3.紧急透析指征：血钾≥7.0mmol/L、药物治疗无效、严重肾衰无尿；4.处理诱因（酸中毒、缺血、肾衰）；5.动态复查血钾与心电图（治疗后每1-2小时）。"],"management":["持续心电监护观察T波/QRS；记录出入量；透析协调。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。钙剂只保护心肌不降血钾，必须继以内移与排钾；心脏骤停时钙剂不推荐常规给予（2025更新）；洋地黄中毒者钙剂慎用。"],"emergency":["血钾>6.5伴ECG改变、>7.0mmol/L、无尿或药物无效→立即钙剂+促内移并准备紧急透析；心脏停搏（高钾）按ACLS（钙剂选择性使用）。"],"pinyin":"weijizhi：gaojiaxuezheng（xuejia≥6.5mmol/L）","icd10":"E87.5","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1257},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"77a945f4729d84c2c6f47c0c4feafb52b852b301568830ad69b4adba0414d358","pinyin":"weijizhi：gaojiaxuezheng（xuejia≥6.5mmol/L）","initials":"wjz：gjxz（xj≥","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","可无症状（化验发现）或肌无力、肢端麻木、心率慢、心悸；ECG可示T波高尖、P波消失、QRS增宽、正弦波。",60],["摘要","血钾≥6.5mmol/L（或任意血钾伴心电图改变）为高钾危急值，可致传导阻滞、缓慢性心律失常甚至室颤/停搏；心电图可无典型改变（约半数），勿依赖ECG判断严重度。处理按\"降钾三步法\"：稳定心肌→促内移→促排出。",30],["疾病编码","E87.5",30],["原首字母","weijizhi：gaojiaxuezheng（xuejia≥6.5mmol/L）",60]]},{"id":"orders-bb0185fca3d5f19055e9","key":"v1-c9ccc21dfe2a3058|orders-bb0185fca3d5f19055e9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：低钾血症（血钾≤2.8mmol/L）","category":"内科危急值","raw":{"name":"危急值：低钾血症（血钾≤2.8mmol/L）","category":"内科危急值","summary":"血钾≤2.8mmol/L为低钾危急值；<2.5mmol/L或伴心电图改变/肌无力/心律失常者为重症。可致恶性心律失常（尖端扭转型室速、室颤）、呼吸肌麻痹、横纹肌溶解、肠麻痹；同步补镁。","symptoms":["乏力、软瘫、腹胀、心悸、多尿；重者呼吸无力、恶性心律失常、意识改变；ECG示T波低平、u波、ST压低、QT延长。"],"diagnosis":["复查血钾；查血气与镁、肾功能；评估严重度与病因（利尿剂、腹泻呕吐、醛固酮增多、肾小管酸中毒、低镁、药物）。"],"infusion":["重度（<3.0mmol/L或有症状/ECG改变）：10%KCl 10-20ml+NS 500ml经中心静脉泵入20-40ml/h；外周静脉浓度≤0.3%（10%KCl 15ml+NS 500ml）、速度≤10mmol/h；中心静脉≤20mmol/h；同步补镁：25%硫酸镁2-4g加入液体缓慢静滴>30min。"],"oral_medication":["轻中度口服氯化钾缓释片1-2g tid或10%氯化钾口服液；枸橼酸钾颗粒口服。"],"treatment":["1.建立静脉通路+持续心电监护（QT监测）；2.按严重度选择口服或静脉补钾；3.同步补镁（低镁是难治性低钾常见原因）；4.监测血钾q2-4h目标>3.5mmol/L；5.查找并对因治疗（停/减利尿剂、处理腹泻呕吐、纠正碱中毒与低镁、治疗原发内分泌病）；6.鼓励含钾饮食。"],"management":["心电监护观察心律失常；反复血钾心电图；记录出入量。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。补钾前提是尿量（>30ml/h）；外周浓度速度受限防静脉炎与高钾反弹；低镁不同步补血钾难升；洋地黄中毒者低钾加重毒性必须尽快纠正。"],"emergency":["血钾<2.5mmol/L、呼吸肌麻痹、严重心律失常（尖端扭转型室速）→紧急静脉补钾+补镁并监护，必要时呼吸支持。"],"pinyin":"weijizhi：dijiaxuezheng（xuejia≤2.8mmol/L）","icd10":"E87.6","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1258},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"58046c41c98d12687b1630d6f800cc3a196273b7b9ac6c2b32d8b630ee92b71e","pinyin":"weijizhi：dijiaxuezheng（xuejia≤2.8mmol/L）","initials":"wjz：djxz（xj≤","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、软瘫、腹胀、心悸、多尿；重者呼吸无力、恶性心律失常、意识改变；ECG示T波低平、u波、ST压低、QT延长。",60],["摘要","血钾≤2.8mmol/L为低钾危急值；<2.5mmol/L或伴心电图改变/肌无力/心律失常者为重症。可致恶性心律失常（尖端扭转型室速、室颤）、呼吸肌麻痹、横纹肌溶解、肠麻痹；同步补镁。",30],["疾病编码","E87.6",30],["原首字母","weijizhi：dijiaxuezheng（xuejia≤2.8mmol/L）",60]]},{"id":"orders-126ea914eccc61a2e671","key":"v1-c9ccc21dfe2a3058|orders-126ea914eccc61a2e671","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性ST段抬高型心肌梗死（STEMI）","category":"内科危急值","raw":{"name":"危急值：急性ST段抬高型心肌梗死（STEMI）","category":"内科危急值","summary":"心肌损伤标志物升高+心电图ST段抬高（≥2个相邻导联）+典型症状。时间就是心肌：首诊10min内完成并判读ECG，优先急诊PCI（D2B≤90min）；不能及时PCI者溶栓后转诊。","symptoms":["持续胸痛/胸闷（压榨感、可放射至左臂颈颌）、大汗、恶心、呼吸困难；老年与糖尿病患者可表现不典型。"],"diagnosis":["10min内12/18导联ECG并判读（J点抬高标准），动态复查（症状持续每15-30min）；高敏肌钙蛋白；评估右室/后壁梗死与休克风险。"],"infusion":["抗血小板：阿司匹林300mg嚼服+替格瑞洛180mg（或氯吡格雷600mg）；抗凝：普通肝素70-100U/kg负荷（或依诺肝素0.5mg/kg+SC、比伐卢定）；再灌注：首选急诊PCI，预计延误>120min者先溶栓（替奈普酶30-50mg或阿替普酶方案）后3-24h造影。"],"oral_medication":["他汀（阿托伐他汀40-80mg）、美托洛尔25-50mg bid（血流动力学稳定后）、ACEI/ARB（血压稳定后24h内启用）、双联抗血小板维持。"],"treatment":["1.首诊10min内ECG并启动导管室；2.抗血小板+抗凝；3.再灌注优先PCI，延误>120min先溶栓；4.硝酸酯（持续性胸痛/高血压，下壁+右室心梗慎用）；5.β阻滞剂静注（HR>60、SBP>100、无心衰者）；6.心电监护24-48h，监测心律失常、心衰、心源性休克与机械并发症；7.处理电解质血糖并完善危险分层。"],"management":["CCU/监护病房：持续心电血压监护、出入量；每15-30分钟复查ECG（再灌注评估）；观察出血（抗凝抗血小板）。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。再灌注每延迟30分钟1年死亡率增加约7.5%；溶栓禁忌与指征严格把握（发病<3h最佳）；抗血小板咀嚼阿司匹林（非肠溶）。"],"emergency":["室颤/无脉性室速→立即除颤CPR；心源性休克→IABP/ECMO与再灌注；机械并发症（室间隔穿孔、乳头肌断裂）→急诊手术评估。"],"pinyin":"weijizhi：jixingSTduantaigaoxingxinjigengsi（STEMI）","icd10":"I21.0","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1259},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4d783d2af5f76af4212010fd0278540b12ff381e469a1496f3cf8808bfb7b348","pinyin":"weijizhi：jixingSTduantaigaoxingxinjigengsi（STEMI）","initials":"wjz：jxSdtgxxjgs（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续胸痛/胸闷（压榨感、可放射至左臂颈颌）、大汗、恶心、呼吸困难；老年与糖尿病患者可表现不典型。",60],["摘要","心肌损伤标志物升高+心电图ST段抬高（≥2个相邻导联）+典型症状。时间就是心肌：首诊10min内完成并判读ECG，优先急诊PCI（D2B≤90min）；不能及时PCI者溶栓后转诊。",30],["疾病编码","I21.0",30],["原首字母","weijizhi：jixingSTduantaigaoxingxinjigengsi（STEMI）",60]]},{"id":"orders-7a916315b1e4dd66d46f","key":"v1-c9ccc21dfe2a3058|orders-7a916315b1e4dd66d46f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：室颤/无脉性室速（心脏骤停）","category":"内科危急值","raw":{"name":"危急值：室颤/无脉性室速（心脏骤停）","category":"内科危急值","summary":"ECG/监护示室颤或无脉性室速伴意识丧失为心脏骤停。高质量CPR+尽早除颤是唯一有效治疗（每延迟1分钟除颤生存率下降7%-10%）；按ACLS流程除颤、肾上腺素、胺碘酮并纠可逆病因。","symptoms":["意识丧失、无呼吸或叹息样呼吸、无大动脉搏动、瞳孔散大、发绀；监护示VF/无脉VT。"],"diagnosis":["临床判断（无反应+无呼吸/异常呼吸+无脉搏）立即启动；心电监护/除颤仪判心律。"],"infusion":["肾上腺素1mg静脉/骨内q3-5min；除颤3次后抗心律失常：胺碘酮300mg静推（可再150mg）或利多卡因1-1.5mg/kg（胺碘酮不可用时）；尖端扭转型室速用硫酸镁1-2g。"],"oral_medication":["无（复苏期静脉给药为主）。"],"treatment":["1.BLS：高质量CPR（按压5-6cm、100-120次/min、充分回弹、中断<10s，30:2），尽早除颤（双相200J，除颤后立即CPR 2min再评估）；2.每2min评估心律，VF/VT持续再次除颤；3.肾上腺素 1mg 静推 q3-5min，第3次除颤后加抗心律失常药（胺碘酮 300mg 静推，必要时 150mg 重复）；4.建立高级气道后持续按压+6次/min通气；5.查找可逆病因（5H5T：低氧、低血容量、低/高钾、低温、低糖酸碱、张力性气胸、心包填塞、中毒、肺栓塞、冠脉血栓）；6.ROSC后：目标体温管理32-36℃≥24h、评估冠脉造影、控制性氧疗（SpO2 92%-98%）、MAP≥65mmHg（去甲肾上腺素 0.05-0.5μg/kg/min 静滴）、血糖管理。"],"management":["记录按压除颤时间节点；ROSC后入ICU继续TTM与病因管理。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。除颤前保持CPR不中断；肾上腺素时机按流程（首剂可在第二次除颤后）；钙剂不推荐常规用于心脏骤停。"],"emergency":["无脉即CPR+除颤，勿延误；多形性室速/电风暴考虑胺碘酮、补镁、β阻滞剂与超速起搏。"],"pinyin":"weijizhi：shichan/wumaixingshisu（xinzangzhouting）","icd10":"I49.0","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1260},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"86c474c25a17b7fda445fdc542d31bfd3a2d66e50dca13c5eab85a23020419a0","pinyin":"weijizhi：shichan/wumaixingshisu（xinzangzhouting）","initials":"wjz：sc/wmxss（xzzt）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","意识丧失、无呼吸或叹息样呼吸、无大动脉搏动、瞳孔散大、发绀；监护示VF/无脉VT。",60],["摘要","ECG/监护示室颤或无脉性室速伴意识丧失为心脏骤停。高质量CPR+尽早除颤是唯一有效治疗（每延迟1分钟除颤生存率下降7%-10%）；按ACLS流程除颤、肾上腺素、胺碘酮并纠可逆病因。",30],["疾病编码","I49.0",30],["原首字母","weijizhi：shichan/wumaixingshisu（xinzangzhouting）",60]]},{"id":"orders-307c7a571f2126dfd450","key":"v1-c9ccc21dfe2a3058|orders-307c7a571f2126dfd450","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：三度房室传导阻滞（完全性心脏传导阻滞）","category":"内科危急值","raw":{"name":"危急值：三度房室传导阻滞（完全性心脏传导阻滞）","category":"内科危急值","summary":"ECG示P波与QRS完全分离、房室脱节，心室率常<40次/min，可致低血压、晕厥（阿-斯）、心衰甚至心脏骤停；不稳定者紧急临时起搏，药物桥接并查病因。","symptoms":["乏力、头晕、晕厥、胸闷；心率慢（<40次/分），可有心衰与低灌注表现；急性心梗者病情更重。"],"diagnosis":["12导联ECG：P与QRS无关、心房率>心室率；观察逸搏QRS宽窄（窄QRS逸搏40-60次/min；宽QRS逸搏<40次/min提示结下阻滞）；评估血流动力学。"],"infusion":["药物桥接（准备起搏期间）：阿托品0.5-1mg静推q3-5min（最大3mg，仅窄QRS逸搏有效）；异丙肾上腺素1-4μg/min泵入（增逸搏心率，冠心病慎用）；低血压者多巴胺/肾上腺素。"],"oral_medication":["停用可能致病的β阻滞剂、钙拮抗剂、地高辛、胺碘酮等（评估）。"],"treatment":["1.评估血流动力学（BP、HR、神志、灌注）；2.不稳定（SBP<90mmHg、晕厥、心衰肺水肿）→紧急临时起搏（首选经静脉右室起搏，等待期间可经皮起搏）；3.药物桥接维持心率；4.查病因：急性心梗→急诊血运重建；高钾→降钾；药物中毒→停药与解毒；心肌炎/Lyme病等病因治疗；5.不可逆/症状性三度AVB→永久起搏器评估。"],"management":["持续心电监护；起搏导管护理；观察逸搏心率与再发晕厥。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。宽QRS逸搏（结下阻滞）对阿托品无效，勿延误起搏；急性下壁心梗房室结缺血可为一过性，前壁心梗新发三度AVB提示广泛坏死预后差。"],"emergency":["晕厥反复、室速停搏、急性心梗合并新发三度AVB→立即临时起搏并呼救心内科。"],"pinyin":"weijizhi：sandufangshichuandaozuzhi（wanquanxingxinzangchuandaozuzhi）","icd10":"I44.2","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1261},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f053f35b2adc61f5f4fb0be071067cde4aafc0f9dd6fc3353fb50dfba5e7dcd3","pinyin":"weijizhi：sandufangshichuandaozuzhi（wanquanxingxinzangchuandaozuzhi）","initials":"wjz：sdfscdzz（wqxxzcdzz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、头晕、晕厥、胸闷；心率慢（<40次/分），可有心衰与低灌注表现；急性心梗者病情更重。",60],["摘要","ECG示P波与QRS完全分离、房室脱节，心室率常<40次/min，可致低血压、晕厥（阿-斯）、心衰甚至心脏骤停；不稳定者紧急临时起搏，药物桥接并查病因。",30],["疾病编码","I44.2",30],["原首字母","weijizhi：sandufangshichuandaozuzhi（wanquanxingxinzangchuandaozuzhi）",60]]},{"id":"orders-0dfb65bc2d69d639ad2c","key":"v1-c9ccc21dfe2a3058|orders-0dfb65bc2d69d639ad2c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：主动脉夹层（Stanford A型）","category":"内科危急值","raw":{"name":"危急值：主动脉夹层（Stanford A型）","category":"内科危急值","summary":"CTA/MRI确诊主动脉内膜撕裂+真假腔。Stanford A型（累及升主动脉）每小时死亡率约增加1%-2%，需紧急手术；B型复杂者TEVAR、不复杂者药物保守。确诊即启动\"心率+血压双控制\"。","symptoms":["突发剧烈撕裂样胸/背痛、高血压、双上肢血压差或脉搏不对称；不典型表现：晕厥、心包填塞、心梗/主动脉瓣反流/心肌缺血。"],"diagnosis":["临床高度怀疑即按夹层处理；CTA为金标准；床旁超声（心包积液/主动脉扩张）辅助；注意与ACS鉴别（夹层禁用抗凝溶栓）。"],"infusion":["绝对卧床、镇静镇痛（吗啡5-10mg静推）；双通路+有创动脉压+心电监护；控心率（目标50-60次/min）：艾司洛尔负荷0.5mg/kg后0.05-0.2mg/(kg·min)泵入或美托洛尔静推；控血压（SBP 100-120mmHg）：先用β阻滞剂再用硝普钠0.25-5μg/(kg·min)（防反射性心动过速）或尼卡地平泵入。"],"oral_medication":["稳定后β阻滞剂+钙拮抗剂等口服降压维持。"],"treatment":["1.高度怀疑即启动双控制（不等待CTA）；2.CTA确诊并分型；3.Stanford A型→紧急胸外科手术（升主动脉置换±瓣膜处理），术前转ICU；4.Stanford B型复杂（破裂/灌注不良/血压难控/持续疼痛）→TEVAR；B型不复杂→药物保守+影像随访；5.监测双上肢血压、疼痛变化、神经体征、尿量肾功能与乳酸。"],"management":["ICU监护；严格卧床；记录疼痛评分与血压心率变化。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。扩张血管药前必须先用β阻滞剂防心率反射性增快增加剪切力；A型夹层手术指征明确勿因等待而延误。"],"emergency":["血压骤降、心包填塞表现、意识改变、破裂征象→急诊手术并呼救。"],"pinyin":"weijizhi：zhudongmaijiaceng（StanfordAxing）","icd10":"I71.0","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1262},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"85688ca3d84e97ccb63d65b180e6a4ec845d78f0e1d51d0250df267cfd860fd9","pinyin":"weijizhi：zhudongmaijiaceng（Stanford Axing）","initials":"wjz：zdmjc（x）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发剧烈撕裂样胸/背痛、高血压、双上肢血压差或脉搏不对称；不典型表现：晕厥、心包填塞、心梗/主动脉瓣反流/心肌缺血。",60],["摘要","CTA/MRI确诊主动脉内膜撕裂+真假腔。Stanford A型（累及升主动脉）每小时死亡率约增加1%-2%，需紧急手术；B型复杂者TEVAR、不复杂者药物保守。确诊即启动\"心率+血压双控制\"。",30],["疾病编码","I71.0",30],["原首字母","weijizhi：zhudongmaijiaceng（StanfordAxing）",60]]},{"id":"orders-94d22b7d5ebfa389f182","key":"v1-c9ccc21dfe2a3058|orders-94d22b7d5ebfa389f182","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性心包填塞（超声确认）","category":"内科危急值","raw":{"name":"危急值：急性心包填塞（超声确认）","category":"内科危急值","summary":"超声示舒张期右房/右室塌陷、下腔静脉增宽（呼吸变异<50%）、房室瓣血流呼吸变异增大提示心包填塞；心包腔内压升高致梗阻性休克。处理：先扩容代偿，紧急心包穿刺引流并查病因。","symptoms":["胸痛、呼吸困难、端坐呼吸；低血压、心率快、颈静脉怒张、心音遥远（Beck三联征仅约30%出现）；重者休克。"],"diagnosis":["床旁超声确诊并估量；查病因（创伤、感染/结核、肿瘤、尿毒症、自身免疫病、抗凝相关出血）；ECG可示低电压/电交替。"],"infusion":["紧急扩容：快速输注晶体液500-1000ml维持前负荷（暂时代偿）；超声引导下心包穿刺引流（剑突下/心尖入路），留置引流管缓慢引流（首次<1000ml防右室扩张与复张性肺水肿）。"],"oral_medication":["按病因治疗（结核抗结核、肿瘤化疗等，遵医嘱）。"],"treatment":["1.扩容同时准备穿刺；2.超声引导心包穿刺置管引流；3.引流液送检（常规、生化、涂片培养、病理细胞学、ADA/肿瘤标志物）；4.病因治疗：创伤→手术；感染→抗感染/抗结核；肿瘤→心包内用药+全身治疗；尿毒症→强化透析；自身免疫→激素+免疫抑制剂；5.停用抗凝（在使用者）并监测凝血。"],"management":["引流管护理记录引流量；观察血压心率与呼吸；反复超声评估。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。穿刺前后监测ECG（损伤电流提示触及心包/心肌）；首次引流勿过快过多。"],"emergency":["梗阻性休克、意识改变→紧急穿刺减压（无条件时盲穿剑突下）并呼救心外科。"],"pinyin":"weijizhi：jixingxinbaotiansai（chaoshengqueren）","icd10":"I31.9","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1263},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3533ff44d03cc2a069efc3b4359c9930c08f6b698cce2c7219e5c8b5f23441a0","pinyin":"weijizhi：jixingxinbaotianse（chaoshengqueren）","initials":"wjz：jxxbts（csqr）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","胸痛、呼吸困难、端坐呼吸；低血压、心率快、颈静脉怒张、心音遥远（Beck三联征仅约30%出现）；重者休克。",60],["摘要","超声示舒张期右房/右室塌陷、下腔静脉增宽（呼吸变异<50%）、房室瓣血流呼吸变异增大提示心包填塞；心包腔内压升高致梗阻性休克。处理：先扩容代偿，紧急心包穿刺引流并查病因。",30],["疾病编码","I31.9",30],["原首字母","weijizhi：jixingxinbaotiansai（chaoshengqueren）",60]]},{"id":"orders-a580d33e5f8884ff28b9","key":"v1-c9ccc21dfe2a3058|orders-a580d33e5f8884ff28b9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性心力衰竭（BNP/NT-proBNP显著升高）","category":"内科危急值","raw":{"name":"危急值：急性心力衰竭（BNP/NT-proBNP显著升高）","category":"内科危急值","summary":"BNP>400pg/mL或NT-proBNP显著升高（按年龄分层>450/900/1800pg/mL）结合急性起病呼吸困难与心衰体征提示急性失代偿心衰。处理：体位、氧疗/无创通气、利尿、扩血管、正性肌力（低灌注时）与病因治疗。","symptoms":["突发严重呼吸困难、端坐呼吸、咳粉红色泡沫痰（肺水肿）、大汗、水肿、少尿；可低血压（心源性休克）。"],"diagnosis":["典型症状体征+BNP/NT-proBNP显著升高；超声评估EF（HFrEF/HFpEF）；排除COPD/肺栓塞/肾衰导致的BNP升高；查ECG、肌钙蛋白、肾功能电解质。"],"infusion":["利尿：呋塞米20-80mg静推首剂（参考既往用量，可加倍），目标尿量>100ml/h，或托拉塞米10-20mg；扩血管（SBP>110mmHg）：硝酸甘油0.25-5μg/(kg·min)泵入或硝普钠；正性肌力（低灌注+SBP<90mmHg）：多巴酚丁胺2-20μg/(kg·min)、米力农或左西孟旦泵入；休克时去甲肾上腺素（MAP≥65mmHg）。"],"oral_medication":["稳定后按心衰药物（ACEI/ARB/ARNI、β阻滞剂稳定后、螺内酯等）管理。"],"treatment":["1.半卧位/坐位双腿下垂；2.面罩吸氧或HFNC（SpO2≥95%），严重低氧用无创通气（CPAP/BiPAP）；3.心电血压监护、出入量；4.利尿减轻容量负荷；5.血压高/正常者扩血管减负荷；6.低心排+低血压者正性肌力/升压（警惕增加死亡率）；7.病因治疗：ACS再灌注、高血压急症控压、心律失常处理、瓣膜病手术评估、感染抗感染；8.监测血气电解质肾功能与体重。"],"management":["监测出入量与体重、血压心电、肺部啰音；必要时转ICU。"],"notes":["依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。呋塞米剂量参考既往用药（未用利尿剂者20-40mg起始）；正性肌力药仅用于低灌注并密切监测。"],"emergency":["肺水肿严重低氧、心源性休克、意识障碍→无创/有创通气并呼救，必要时机械循环支持。"],"pinyin":"weijizhi：jixingxinlishuaijie（BNP/NT-proBNPxianzhushenggao）","icd10":"I50.9","physical_exam":"","lab_tests":"","nursing":"","diet":""},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1264},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3dffb3db3143956e57be194c4d25955f32ccb0953636c0c1a62e9a8cf4bda9a7","pinyin":"weijizhi：jixingxinlishuaijie（BNP/NT-proBNPxianzhushenggao）","initials":"wjz：jxxlsj（xzsg）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发严重呼吸困难、端坐呼吸、咳粉红色泡沫痰（肺水肿）、大汗、水肿、少尿；可低血压（心源性休克）。",60],["摘要","BNP>400pg/mL或NT-proBNP显著升高（按年龄分层>450/900/1800pg/mL）结合急性起病呼吸困难与心衰体征提示急性失代偿心衰。处理：体位、氧疗/无创通气、利尿、扩血管、正性肌力（低灌注时）与病因治疗。",30],["疾病编码","I50.9",30],["原首字母","weijizhi：jixingxinlishuaijie（BNP/NT-proBNPxianzhushenggao）",60]]},{"id":"orders-1b346a66723df1c0482a","key":"v1-c9ccc21dfe2a3058|orders-1b346a66723df1c0482a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性上消化道出血","category":"内科危急值","raw":{"name":"危急值：急性上消化道出血","category":"内科危急值","summary":"危急阈值：呕血/咖啡色呕吐物/黑便，伴收缩压<90mmHg、心率>100次/分等血流动力学不稳定，或Hb较基础下降≥20g/L。临床意义：年发病率约100-150/10万，病死率5%-10%；GBS≥1分须住院，高危(GBS≥12或Rockall≥5)需紧急干预。","symptoms":["呕血(鲜红/咖啡渣样)、柏油样黑便，伴头晕、心悸、冷汗、面色苍白；重者晕厥、四肢湿冷、少尿等休克表现。"],"diagnosis":["据呕血/黑便及Hb动态识别出血；入院行Glasgow-Blatchford评分(GBS)分层，内镜后行完整Rockall评分；低危(GBS 0-1分)可门诊2周内胃镜；急诊胃镜明确出血部位与病因(溃疡、静脉曲张等)并镜下止血。"],"infusion":["双静脉通路(16-18G)；复苏优先平衡液/乳酸林格液，避免大量生理盐水，大出血维持收缩压>100mmHg。限制性输血目标Hb 70-80g/L：活动性大出血伴循环不稳定输红细胞2-4U，缺血性心脏病Hb<90g/L时输，稳定者Hb<70g/L输1-2U；INR>1.5输新鲜冰冻血浆，纤维蛋白原<1.0g/L输冷沉淀10-12U，血小板<50×10⁹/L活动性出血时输注。疑静脉曲张出血：特利加压素2mg静注q6h或生长抑素250μg静注后250μg/h泵入，头孢曲松1g静注qd(5-7天)。内镜见高危征象后埃索美拉唑80mg静注→8mg/h泵入72h；红霉素250mg静注改善胃镜视野。"],"oral_medication":["出血停止后口服PPI；幽门螺杆菌阳性予根除；出院前口服铁剂。"],"treatment":["按识别→复苏→评估→治疗→内镜→复查流程：液体复苏与GBS/Rockall分层；疑静脉曲张出血尽早血管活性药+预防性抗感染，非静脉曲张出血不常规内镜前PPI(防掩盖病灶)；不稳定/高危者复苏后立即内镜(<12h、理想<6h)，稳定中低危24h内胃镜止血；复查Hb、管理抗血栓药、根除幽门螺杆菌。"],"management":["Hb每12-24h复查至稳定。即刻内镜指征：活动性呕血、收缩压<90mmHg、心率>120次/分、GBS≥12分。抗血栓药：阿司匹林二级预防继续(大出血除外)；双抗停P2Y12抑制剂保留阿司匹林；抗凝药权衡后重启。"],"notes":["内镜前常规PPI可能掩盖病灶延误诊断，仅大出血可高剂量PPI且不延误内镜时机。"],"emergency":["活动性呕血、收缩压<90mmHg、心率>120次/分、GBS≥12分或疑静脉曲张出血：立即复苏并急诊内镜。"],"pinyin":"weijizhi：jixingshangxiaohuadaochuxue","icd10":"K92.2","physical_exam":"生命体征及体位性低血压；贫血貌、皮肤苍白湿冷；腹部压痛、肠鸣音亢进；直肠指检见柏油样便。","lab_tests":"血常规及Hb动态、血型交叉配血、凝血(PT/INR、纤维蛋白原)、肝肾功能、电解质；溃疡出血者查幽门螺杆菌。","nursing":"出血期卧床、头偏一侧防误吸；监测血压心率呼吸尿量及呕血/黑便量色；胃管观察引流液；记录出入量、注意保暖口腔护理。","diet":"出血期禁食；停止24-48h后温凉流质→半流质→软食；避免过烫粗糙辛辣刺激食物及烟酒。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1265},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1ac99c1ff95f52f41786a33c85e26d56bfa5e96487117c037de4bc10be051587","pinyin":"weijizhi：jixingshangxiaohuadaochuxie","initials":"wjz：jxsxhdcx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呕血(鲜红/咖啡渣样)、柏油样黑便，伴头晕、心悸、冷汗、面色苍白；重者晕厥、四肢湿冷、少尿等休克表现。",60],["摘要","危急阈值：呕血/咖啡色呕吐物/黑便，伴收缩压<90mmHg、心率>100次/分等血流动力学不稳定，或Hb较基础下降≥20g/L。临床意义：年发病率约100-150/10万，病死率5%-10%；GBS≥1分须住院，高危(GBS≥12或Rockall≥5)需紧急干预。",30],["疾病编码","K92.2",30],["原首字母","weijizhi：jixingshangxiaohuadaochuxue",60]]},{"id":"orders-47f1668f473741b61693","key":"v1-c9ccc21dfe2a3058|orders-47f1668f473741b61693","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：食管胃底静脉曲张破裂出血","category":"内科危急值","raw":{"name":"危急值：食管胃底静脉曲张破裂出血","category":"内科危急值","summary":"危急阈值：内镜见食管/胃底曲张静脉活动性出血(喷射或渗血)，或表面白色乳头征、血凝块附着；6周死亡率15%-25%，Child-Pugh C级可达50%。临床意义：门脉高压最致命并发症，约30%发生于无出血史者，疑似即按高危处理。","symptoms":["突发大量呕血(暗红或鲜血)、黑便，迅速出现心悸、头晕、大汗、血压下降等休克表现，常伴肝硬化体征。"],"diagnosis":["肝硬化/门脉高压者上消化道出血即高度疑诊，不等内镜确认即启用血管活性药；急诊内镜确诊活动性出血并区分食管/胃底曲张；结合Child-Pugh分级评估预后。"],"infusion":["血管活性药(3-5天)：特利加压素2mg静注后继2mg q4-6h，或生长抑素250μg静注后250μg/h泵入，或奥曲肽50μg静注后50μg/h泵入；预防性抗生素头孢曲松1g静注qd(5-7天)。限制性输血，Hb目标70-80g/L，避免容量过负荷升高门脉压。内镜治疗后予PPI静注(埃索美拉唑80mg→8mg/h泵入)降低套扎溃疡出血。"],"oral_medication":["替代抗感染可口服诺氟沙星400mg bid；防再出血用卡维地洛12.5-25mg qd或普萘洛尔(目标心率55-60次/分)；口服PPI。"],"treatment":["收入ICU/监护病房、限制性输血复苏；疑似即血管活性药+抗生素；内镜治疗：食管曲张行套扎术EVL(用药后12h内)，胃底曲张注射组织粘合剂/氰基丙烯酸酯；顽固性出血：三腔二囊管填塞≤24h临时控制，或72h内TIPS，TIPS失败/禁忌时外科分流断流；防再出血用NSBB+EVL序贯。"],"management":["监测生命体征、Hb、出入量并记录出血量；警惕肝性脑病(行为改变、扑翼样震颤、血氨升高)；三腔二囊管护理：维持压力、定时放气，床旁备剪刀防窒息。"],"notes":["止血后需NSBB+EVL序贯防再出血；避免过度输血致门脉压升高再出血；PPI可降低EVL术后溃疡出血风险。"],"emergency":["大呕血伴休克：立即复苏并静注特利加压素或生长抑素，急诊内镜套扎/粘合剂注射；内镜失败或高危(Child-Pugh C)考虑72h内TIPS。"],"pinyin":"weijizhi：shiguanweidijingmaiquzhangpoliechuxue","icd10":"I85.0","physical_exam":"慢性肝病体征：黄疸、肝掌、蜘蛛痣、脾大、腹水、腹壁静脉曲张；低血压、心动过速等休克征象。","lab_tests":"血常规(Hb、血小板)、肝功能、凝血(PT/INR)、肾功能、电解质、血型交叉配血；肝炎病毒标志物。","nursing":"绝对卧床、头偏一侧防误吸；禁食、胃肠减压观察；每1-2h测生命体征与神志；记录出血量与尿量；三腔二囊管护理，防压疮、坠积性肺炎。","diet":"出血期禁食；止血后流质→软食并限钠；肝性脑病倾向者限制蛋白；禁酒。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1266},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0544dad5c466366aa6abc78d9d008e8a9ac9d4ed2c4a75cf428662009ab7cf5e","pinyin":"weijizhi：shiguanweidijingmaiquzhangpoliechuxie","initials":"wjz：sgwdjmqzplcx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发大量呕血(暗红或鲜血)、黑便，迅速出现心悸、头晕、大汗、血压下降等休克表现，常伴肝硬化体征。",60],["摘要","危急阈值：内镜见食管/胃底曲张静脉活动性出血(喷射或渗血)，或表面白色乳头征、血凝块附着；6周死亡率15%-25%，Child-Pugh C级可达50%。临床意义：门脉高压最致命并发症，约30%发生于无出血史者，疑似即按高危处理。",30],["疾病编码","I85.0",30],["原首字母","weijizhi：shiguanweidijingmaiquzhangpoliechuxue",60]]},{"id":"orders-0de76ff9931892308638","key":"v1-c9ccc21dfe2a3058|orders-0de76ff9931892308638","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：重症急性胰腺炎","category":"内科危急值","raw":{"name":"危急值：重症急性胰腺炎","category":"内科危急值","summary":"危急阈值：血淀粉酶/脂肪酶>正常上限3倍+持续器官衰竭>48h(改良Marshall≥2分)+增强CT示胰腺坏死；Ranson≥3或APACHEⅡ≥8提示重症。临床意义：急性胰腺炎约15%-20%为重症，病死率20%-30%；主要死因SIRS致多器官功能障碍，感染性坏死为晚期主要死因。","symptoms":["突发持续剧烈上腹痛放射至腰背，恶心呕吐、腹胀；重症见发热、呼吸困难、少尿、低血压休克及腹膜炎体征，偶见Grey-Turner征、Cullen征。"],"diagnosis":["典型腹痛+淀粉酶/脂肪酶≥3倍上限+增强CT(坏死/气泡征)可诊断；用改良Marshall、Ranson、APACHEⅡ、SIRS评分评估严重度，明确病因分型(胆源性/高脂血症性/酒精性等)。"],"infusion":["早期目标指导性复苏：首选乳酸林格液，5-10ml/kg/h，首24h总量2500-4000ml，目标HCT 35%-44%、BUN下降、尿量>0.5ml/kg/h、MAP>65mmHg，警惕过度复苏。不推荐预防性抗生素；确诊感染坏死(气泡征或穿刺培养阳性)后予覆盖G⁻杆菌+厌氧菌抗生素(碳青霉烯类或喹诺酮+甲硝唑)；高脂血症性行血浆置换。"],"oral_medication":["恢复进食后口服降脂药维持TG<5.6mmol/L(高脂血症性)；酒精性者戒酒并补维生素B1。"],"treatment":["①病因治疗：胆源性ERCP+EST(≤72h，伴胆管炎更紧急)；高脂血症性血浆置换+降脂；酒精性戒酒补硫胺素；药物性停药。②营养：24-48h内经鼻空肠管肠内营养，不耐受者肠外营养，避免长期禁食。③感染：仅明确感染坏死时抗感染+介入/手术引流，坏死清除延迟至发病4周包裹后。④器官支持。"],"management":["收治ICU指征：持续器官衰竭/Marshall≥2分/Cr≥177μmol/L/PaO₂<60mmHg/收缩压<90mmHg。监测SIRS评分、CRP(48h>150mg/L提示重症)、乳酸、血气、电解质、血糖血钙、腹内压与尿量。"],"notes":["过度复苏有害(腹内压升高、肺水肿)；预防性抗生素无益，仅用于明确感染坏死；监测腹内压。"],"emergency":["持续器官衰竭、休克或呼吸衰竭者紧急入ICU；合并急性胆管炎尽快ERCP；感染坏死征象出现及时引流。"],"pinyin":"weijizhi：zhongzhengjixingyixianyan","icd10":"K85.9","physical_exam":"上腹压痛、反跳痛、肌紧张，腹胀、肠鸣音减弱或消失；Grey-Turner征、Cullen征；发热、心动过速、低血压。","lab_tests":"血淀粉酶/脂肪酶、血常规、CRP、血糖、血钙、血脂(TG)、肝肾功能、电解质、乳酸、血气及HCT动态；必要时腹穿液淀粉酶。","nursing":"重症入ICU，监测生命体征、出入量、尿量与腹围；胃肠减压及镇痛；协助翻身防压疮、预防深静脉血栓；心理疏导。","diet":"24-48h内尽早鼻空肠管肠内营养；肠功能恢复后逐步恢复低脂流质饮食；忌油腻、饮酒；高脂血症性者低脂饮食并控血脂。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1267},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5dda57cfb41fda768ca8f076a5090344fa06bcf6d89089abc679edae8d5883db","pinyin":"weijizhi：zhongzhengjixingyixianyan","initials":"wjz：zzjxyxy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发持续剧烈上腹痛放射至腰背，恶心呕吐、腹胀；重症见发热、呼吸困难、少尿、低血压休克及腹膜炎体征，偶见Grey-Turner征、Cullen征。",60],["摘要","危急阈值：血淀粉酶/脂肪酶>正常上限3倍+持续器官衰竭>48h(改良Marshall≥2分)+增强CT示胰腺坏死；Ranson≥3或APACHEⅡ≥8提示重症。临床意义：急性胰腺炎约15%-20%为重症，病死率20%-30%；主要死因SIRS致多器官功能障碍，感染性坏死为晚期主要死因。",30],["疾病编码","K85.9",30],["原首字母","weijizhi：zhongzhengjixingyixianyan",60]]},{"id":"orders-fab3952162ca8a9cb37f","key":"v1-c9ccc21dfe2a3058|orders-fab3952162ca8a9cb37f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性肝功能衰竭","category":"内科危急值","raw":{"name":"危急值：急性肝功能衰竭","category":"内科危急值","summary":"危急阈值：INR≥1.5+任何程度肝性脑病+病程<26周且无基础肝硬化；AFP降低伴高胆红素提示预后不良(King's College标准)。临床意义：进展迅速，存活率25%-60%(依病因及移植时机)，死因首位脑水肿/颅内高压(>50%)，次为多器官衰竭、感染、出血。","symptoms":["进行性乏力、恶心，黄疸迅速加深，瘀斑、牙龈出血；肝性脑病：性格行为改变、定向障碍、扑翼样震颤，进展至昏睡昏迷。"],"diagnosis":["符合INR≥1.5+肝性脑病、病程<26周且无肝硬化即诊断；查病因：药物史(尤其对乙酰氨基酚)、HAV/HBV/HEV标志物、自身免疫抗体、铜蓝蛋白(Wilson病)。"],"infusion":["对乙酰氨基酚过量：N-乙酰半胱氨酸首剂150mg/kg静注(>15min)→50mg/kg×4h→100mg/kg×16h，非APAP相关亦获益。自身免疫性肝炎：甲泼尼龙40-60mg/d静注。降颅压：甘露醇0.5-1g/kg静注或3%高渗盐水250ml(监测血浆渗透压<320mOsm/L)。凝血支持：维生素K₁10mg皮下连用3天；活动性出血按凝血参数输血浆/冷沉淀/血小板。"],"oral_medication":["HBV：恩替卡韦0.5mg qd或替诺福韦300mg qd；肝性脑病：乳果糖30-45ml q1h至排便后tid-qid(目标2-3次/天)，联用利福昔明550mg bid。"],"treatment":["①病因治疗：APAP过量用NAC（150mg/kg 静滴 1h，后 50mg/kg 4h，再 100mg/kg 16h），HBV用核苷类似物（恩替卡韦 0.5mg 口服 qd，不能口服者 0.5mg 静滴 qd），HAV/HEV支持，药物性停药+NAC，自身免疫性用糖皮质激素（泼尼松 40-60mg 口服 qd），Wilson病评估移植。②脑水肿/颅高压：床头抬高30°、头正中位；GCS≤8分插管；Ⅲ-Ⅳ级HE等移植者行ICP监测；甘露醇 0.5-1g/kg 静滴 q4-6h/高渗盐水（3% 100-150ml 静滴）降颅压、短期过度通气(PaCO₂30-35mmHg)桥接。③达King's College标准者评估肝移植，人工肝(MARS/血浆置换)桥接。"],"management":["重症监护：定时评估GCS、瞳孔、生命体征、血糖、血氨、电解质及出入量；观察出血与感染征象；颅高压危象(瞳孔异常、呼吸改变)紧急处理。"],"notes":["INR不能良好预测出血风险(凝血再平衡)；Wilson病对药物不敏感，应直接评估移植。"],"emergency":["出现脑疝征象(瞳孔不等大、呼吸节律异常)或Ⅲ-Ⅳ级肝性脑病：紧急气管插管、甘露醇/高渗盐水降颅压并联系移植中心。"],"pinyin":"weijizhi：jixinggangongnengshuaijie","icd10":"K72.0","physical_exam":"重度黄疸、肝臭；扑翼样震颤、意识定向障碍；瞳孔改变及病理征(颅高压)；瘀斑出血点、腹水、肝浊音界变化。","lab_tests":"血常规、肝功能全套、凝血(PT/INR)、血氨、血糖、电解质、肾功能、血气分析；病因学：APAP血药浓度、病毒标志物、自身抗体、铜蓝蛋白、AFP。","nursing":"ICU护理：定时评GCS与瞳孔，床头抬高30°；记录出入量；意识障碍者防误吸、压疮、肺炎，躁动上护栏；监测血糖，口腔导管护理轻柔。","diet":"急性期限蛋白<60g/d(肝性脑病遵医嘱再限)，恢复期逐步增加；低钠，据腹水水肿限水；不能经口者予肠外营养并监测血糖。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1268},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4500b8bbcfa2c8a236eb4f4d7e10b40e51771dc85bfbb3dff9b0664a1896bec3","pinyin":"weijizhi：jixinggangongnengshuaijie","initials":"wjz：jxggnsj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","进行性乏力、恶心，黄疸迅速加深，瘀斑、牙龈出血；肝性脑病：性格行为改变、定向障碍、扑翼样震颤，进展至昏睡昏迷。",60],["摘要","危急阈值：INR≥1.5+任何程度肝性脑病+病程<26周且无基础肝硬化；AFP降低伴高胆红素提示预后不良(King's College标准)。临床意义：进展迅速，存活率25%-60%(依病因及移植时机)，死因首位脑水肿/颅内高压(>50%)，次为多器官衰竭、感染、出血。",30],["疾病编码","K72.0",30],["原首字母","weijizhi：jixinggangongnengshuaijie",60]]},{"id":"orders-8d0ff73e736a474f1bb3","key":"v1-c9ccc21dfe2a3058|orders-8d0ff73e736a474f1bb3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性肾损伤（AKI）","category":"内科危急值","raw":{"name":"危急值：急性肾损伤（AKI）","category":"内科危急值","summary":"危急阈值（KDIGO）：48h内血肌酐升高≥26.5μmol/L（0.3mg/dL），或7d内升至基线1.5倍以上，或尿量<0.5ml/kg/h持续>6h。临床意义：住院患者发生率达10%-15%，ICU中>50%，显著增加住院死亡率、住院时间与CKD进展风险，需早期识别并分级处理。","symptoms":["尿量减少（少尿/无尿）或尿量正常、乏力、恶心呕吐、食欲减退、水肿；重症可有意识改变，可伴原发病（脓毒症、低灌注等）表现。"],"diagnosis":["按KDIGO标准诊断；评估容量状态：尿钠<20mmol/L、FENa<1%、BUN/Cr>20提示肾前性；尿钠增高、血尿蛋白尿倾向肾性。超声排查肾积水、膀胱残余尿（肾后性）；必要时肾活检鉴别ATN、AIN、肾小球肾炎、血管炎、HUS/TTP；NGAL、CysC等生物标志物辅助早期识别。"],"infusion":["容量不足（低血压、心动过速、皮肤弹性差）：以平衡晶体液补液并监测血流动力学反应；容量评估困难时行被动抬腿试验或IVC超声评估容量反应性；容量正常/过多者不以补液为主，予利尿治疗。"],"oral_medication":["暂停或减量ACEI/ARB、SGLT2抑制剂、二甲双胍、地高辛；其余经肾排泄口服药按肌酐清除率调整剂量。"],"treatment":["①停用肾毒性药物：NSAIDs、氨基糖苷类、两性霉素B、造影剂。②容量过负荷（水肿、肺啰音、JVP升高、CVP>12mmHg）：呋塞米40-200mg IV，可递增。③纠正低血容量、低心排、脓毒症等病因。④肾脏替代治疗（RRT）绝对指征（AEIOU）：严重酸中毒pH<7.15、血钾>6.5mmol/L、中毒（乙二醇/甲醇/锂）、容量过负荷致肺水肿、尿毒症症状/心包炎；相对指征：BUN>35.7mmol/L、Cr持续升高、KDIGO 3期。血流动力学不稳定选CRRT，稳定者可用IHD。"],"management":["每日监测体重、尿量、SCr、BUN、电解质、血气；AKI后3个月、6个月、1年随访，评估肾功能恢复与CKD转化风险。"],"notes":["KDIGO不建议常规早期启动RRT，仅在出现传统指征时启动；全程避免肾毒性药物再暴露。"],"emergency":["出现AEIOU绝对指征（严重酸中毒、血钾>6.5mmol/L、药物中毒、肺水肿、尿毒症症状/心包炎）时需紧急启动肾脏替代治疗。"],"pinyin":"weijizhi：jixingshensunshang（AKI）","icd10":"N17.9（急性肾衰竭，未特指）","physical_exam":"血压、心率、皮肤弹性、外周水肿、肺部啰音、颈静脉怒张、心包摩擦音、神志状态。","lab_tests":"血Cr、BUN、电解质、血气分析、血常规、尿常规、尿钠、FENa；必要时查血锂、乙二醇、甲醇浓度。","nursing":"准确记录出入量与每小时尿量、每日体重；输液泵管理；预防皮肤破损与感染。","diet":"按分期限制蛋白质并保证热卡，限制钾、钠、磷摄入，控制液体入量。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1269},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"74ea2e9d22f1f09552749454fd4951b6a749e76e9d6b447d23e148ddc2dbddb8","pinyin":"weijizhi：jixingshensunshang（AKI）","initials":"wjz：jxsss（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","尿量减少（少尿/无尿）或尿量正常、乏力、恶心呕吐、食欲减退、水肿；重症可有意识改变，可伴原发病（脓毒症、低灌注等）表现。",60],["摘要","危急阈值（KDIGO）：48h内血肌酐升高≥26.5μmol/L（0.3mg/dL），或7d内升至基线1.5倍以上，或尿量<0.5ml/kg/h持续>6h。临床意义：住院患者发生率达10%-15%，ICU中>50%，显著增加住院死亡率、住院时间与CKD进展风险，需早期识别并分级处理。",30],["疾病编码","N17.9（急性肾衰竭，未特指）",30],["原首字母","weijizhi：jixingshensunshang（AKI）",60]]},{"id":"orders-02f806c6430653a53139","key":"v1-c9ccc21dfe2a3058|orders-02f806c6430653a53139","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：肾性高钾血症","category":"内科危急值","raw":{"name":"危急值：肾性高钾血症","category":"内科危急值","summary":"危急阈值：血钾≥6.5mmol/L（慢性肾病/终末期肾病可放宽至≥6.0mmol/L）需紧急处理。临床意义：肾衰竭排钾能力下降，叠加ACEI/ARB、螺内酯等药物与代谢性酸中毒作用，高钾顽固、易反复、药物反应差，可致恶性心律失常甚至猝死。","symptoms":["乏力、肢端与口周麻木、肌肉无力、腱反射减弱、心动过缓或传导阻滞，严重者心脏骤停；部分患者可无症状。"],"diagnosis":["血钾≥6.0-6.5mmol/L结合肾功能、血气判断；心电图见T波高尖、PR间期延长、QRS增宽、P波低平乃至正弦波为高危表现。"],"infusion":["10%葡萄糖酸钙10ml缓慢IV（肾衰患者易高钙，钙剂用量宜偏小）；促钾内移：短效胰岛素10U+50%葡萄糖50ml IV，肾衰患者低血糖风险高，需监测。"],"oral_medication":["环硅酸锆钠（SZC）10g tid，肾性高钾尤其适用，不影响肾功能，可长期口服维持。"],"treatment":["三步法：钙剂稳定心肌膜→促钾内移（胰岛素+葡萄糖、沙丁胺醇雾化，后者不影响肾功能可联合）→促排出：呋塞米100-200mg IV（有残余肾功能者）或SZC 10g tid，必要时血液透析。紧急透析指征：血钾≥7.0mmol/L或药物治疗无效。"],"management":["持续心电监护直至血钾降至安全范围；透析后血钾1-2h内可下降1-2mmol/L，透析后4-6h易反跳需复查血钾；监测血糖至少12h；复查心电图。"],"notes":["肾性高钾对药物治疗反应较差，反复发作者常需维持性透析或长期口服SZC控制。"],"emergency":["血钾≥7.0mmol/L、或伴明显心电图异常而药物无效者，立即安排紧急血液透析。"],"pinyin":"weijizhi：shenxinggaojiaxuezheng","icd10":"E87.5（高钾血症）","physical_exam":"心率心律、肌力、腱反射、呼吸节律（酸中毒代偿表现）。","lab_tests":"血钾、肾功能（BUN/Cr）、血气分析、血糖、心电图。","nursing":"持续心电监护；规范复查血钾与血糖；观察静脉钙剂外渗；宣教避免高钾食物。","diet":"低钾饮食：避免香蕉、橙子、土豆、菌菇等高钾食物及含钾低钠盐。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1270},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"fb6f69c4b0e804e36c821e5a7dbe2135b74049d8d67eac0edd56a723308b5410","pinyin":"weijizhi：shenxinggaojiaxuezheng","initials":"wjz：sxgjxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、肢端与口周麻木、肌肉无力、腱反射减弱、心动过缓或传导阻滞，严重者心脏骤停；部分患者可无症状。",60],["摘要","危急阈值：血钾≥6.5mmol/L（慢性肾病/终末期肾病可放宽至≥6.0mmol/L）需紧急处理。临床意义：肾衰竭排钾能力下降，叠加ACEI/ARB、螺内酯等药物与代谢性酸中毒作用，高钾顽固、易反复、药物反应差，可致恶性心律失常甚至猝死。",30],["疾病编码","E87.5（高钾血症）",30],["原首字母","weijizhi：shenxinggaojiaxuezheng",60]]},{"id":"orders-da43720b0e5cacba5649","key":"v1-c9ccc21dfe2a3058|orders-da43720b0e5cacba5649","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：严重低钠血症","category":"内科危急值","raw":{"name":"危急值：严重低钠血症","category":"内科危急值","summary":"危急阈值：血钠≤120mmol/L（重度），或任意血钠水平伴严重症状（癫痫、昏迷）。临床意义：住院患者中发生率15%-30%；严重低钠致细胞外低渗、水进入脑细胞引起脑水肿、颅内高压、抽搐、昏迷甚至脑疝；纠正过快可致渗透性脱髓鞘综合征（CPM/ODS），纠正速度须严格控制。","symptoms":["恶心呕吐、头痛、乏力、食欲差、意识模糊、抽搐、昏迷、GCS下降。"],"diagnosis":["先测血浆渗透压分型：Posm<275mOsm/kg为低渗性（真性低钠）；等渗性提示假性低钠（高脂血症、高蛋白血症）；高渗性见于高血糖、甘露醇。低渗性再按容量分：低容量、等容量（多为SIADH）、高容量（心衰、肝硬化、肾衰）。"],"infusion":["严重症状者：3%NaCl 100ml IV 10-20min，间隔10-15min可重复1-2次，目标前1h血钠升高5-6mmol/L以控制症状即可；症状控制后停高渗液。过度纠正回调：D5W 5ml/kg IV或去氨加压素2μg IV。"],"oral_medication":["SIADH难治者可用托伐普坦（需限水并密切监测血钠）；轻症可口服盐片补钠。"],"treatment":["低容量性：0.9%NaCl补液；等容量性（SIADH）：限水<1000ml/d＋盐片＋呋塞米，难治加托伐普坦；高容量性：限水限钠＋呋塞米利尿。纠正速度（核心安全要求）：首24h血钠升高≤10mmol/L，之后每24h≤8mmol/L，直至血钠达130mmol/L安全水平；高风险患者（严重低钠合并酒精中毒、营养不良、肝病）更严格限≤6-8mmol/L/24h。"],"management":["症状期每20min复查血钠并评估神经症状；定期复查电解质，记录出入量与体重。"],"notes":["渗透性脱髓鞘（CPM/ODS）重在预防，纠正宁慢勿快，避免过度纠正。"],"emergency":["抽搐、昏迷或GCS改变者立即予3%NaCl快速纠正，不必等待完整化验结果。"],"pinyin":"weijizhi：yanzhongdinaxuezheng","icd10":"E87.1（低钠血症）","physical_exam":"意识与GCS、病理征、皮肤弹性与血压（容量评估）、体重。","lab_tests":"血钠、血浆渗透压、尿渗透压与尿钠（SIADH鉴别）、血糖、血脂、血清蛋白。","nursing":"严格按泵控速输注高渗钠、频繁复查血钠、抽搐发作的安全防护。","diet":"按容量分型执行限水或补钠：SIADH限水<1000ml/d，高容量者限水限钠。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1271},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5f60ab773a13b36bfab8f04b192f37495fa10e185f42664d3a18f7b123d1d001","pinyin":"weijizhi：yanzhongdinaxuezheng","initials":"wjz：yzdnxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","恶心呕吐、头痛、乏力、食欲差、意识模糊、抽搐、昏迷、GCS下降。",60],["摘要","危急阈值：血钠≤120mmol/L（重度），或任意血钠水平伴严重症状（癫痫、昏迷）。临床意义：住院患者中发生率15%-30%；严重低钠致细胞外低渗、水进入脑细胞引起脑水肿、颅内高压、抽搐、昏迷甚至脑疝；纠正过快可致渗透性脱髓鞘综合征（CPM/ODS），纠正速度须严格控制。",30],["疾病编码","E87.1（低钠血症）",30],["原首字母","weijizhi：yanzhongdinaxuezheng",60]]},{"id":"orders-33d8ca37ecd6e6c9a03e","key":"v1-c9ccc21dfe2a3058|orders-33d8ca37ecd6e6c9a03e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：严重高钠血症","category":"内科危急值","raw":{"name":"危急值：严重高钠血症","category":"内科危急值","summary":"危急阈值：血钠≥160mmol/L，或任意血钠水平伴意识障碍。临床意义：高钠致细胞内脱水、脑细胞皱缩与脑萎缩，易诱发颅内出血（硬膜下、蛛网膜下腔、脑实质出血）；多见于尿崩症（中枢性/肾性）、高渗性脱水与钠负荷过多，意识障碍程度与血钠升高速率相关。","symptoms":["烦渴、多饮多尿或尿少、乏力、嗜睡、烦躁、惊厥、昏迷、皮肤黏膜干燥。"],"diagnosis":["先评估容量状态（低容量、等容量、高容量）定位病因；鉴别中枢性尿崩症、肾性尿崩症、高渗性脱水、钠负荷过多；查尿渗透压、尿比重、尿钠，必要时禁水/加压素试验。"],"infusion":["计算自由水缺乏量：FWD=0.6×体重(kg)×(1-140/血Na⁺)；低/等容量首选D5W或5%葡萄糖，亦可用0.45%NaCl；高容量用D5W＋呋塞米利尿。纠正速度：首24h血钠下降≤10mmol/L（10-12mmol/L为最大上限），首8h速率≤0.5mmol/L/h，其后可适当加快但≤1mmol/L/h。"],"oral_medication":["肾性尿崩症：噻嗪类利尿剂＋限盐＋NSAIDs（如吲哚美辛）以减少尿量。"],"treatment":["中枢性尿崩症：去氨加压素（DDAVP）1-2μg IV或10-20μg鼻吸入q8-12h；肾性尿崩症：噻嗪类利尿剂＋限盐＋吲哚美辛；高渗性脱水：充分补液并纠正病因；钠负荷过多：补充自由水并利尿排钠。"],"management":["监测血钠（首日每1-2h）至稳定、出入量与体重、意识与神经系统体征；防止纠正过快诱发脑水肿。"],"notes":["慢性（>48h）高钠患者脑细胞已发生适应，纠正须更缓慢稳妥，按上限执行。"],"emergency":["血钠≥160mmol/L伴意识障碍为内科急症，立即评估容量状态并开始缓慢补液。"],"pinyin":"weijizhi：yanzhonggaonaxuezheng","icd10":"E87.0（高钠血症）","physical_exam":"皮肤黏膜弹性与干燥程度、眼窝凹陷、血压心率、神志及神经定位体征。","lab_tests":"血钠、血浆渗透压、尿渗透压、尿钠、尿量与比重、血糖。","nursing":"按计算速率精确输注低渗液、记录出入量、每小时观察神志与抽搐、防液体外渗。","diet":"鼓励按口渴饮水（意识障碍者经管饲补充），高容量者限钠限水。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1272},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5c319c251187dc44194313b51f6dc6d53c25eb700e10ada25c2ba44fefd503cf","pinyin":"weijizhi：yanzhonggaonaxuezheng","initials":"wjz：yzgnxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","烦渴、多饮多尿或尿少、乏力、嗜睡、烦躁、惊厥、昏迷、皮肤黏膜干燥。",60],["摘要","危急阈值：血钠≥160mmol/L，或任意血钠水平伴意识障碍。临床意义：高钠致细胞内脱水、脑细胞皱缩与脑萎缩，易诱发颅内出血（硬膜下、蛛网膜下腔、脑实质出血）；多见于尿崩症（中枢性/肾性）、高渗性脱水与钠负荷过多，意识障碍程度与血钠升高速率相关。",30],["疾病编码","E87.0（高钠血症）",30],["原首字母","weijizhi：yanzhonggaonaxuezheng",60]]},{"id":"orders-7eb3b57997ecf514f8ce","key":"v1-c9ccc21dfe2a3058|orders-7eb3b57997ecf514f8ce","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：高钙危象","category":"内科危急值","raw":{"name":"危急值：高钙危象","category":"内科危急值","summary":"危急阈值：校正后血钙≥3.5mmol/L（14mg/dL）。校正钙＝测定钙＋0.02×(40-白蛋白g/L)。临床意义：可致急性肾损伤（肾血管收缩、尿浓缩功能障碍、肾钙质沉积）、QT间期缩短与心律失常、意识改变至昏迷；最常见病因为恶性肿瘤（约70%）与原发性甲旁亢（约20%）。","symptoms":["多饮多尿、恶心呕吐、便秘、食欲减退、肌无力、嗜睡、意识模糊、昏迷、心悸。"],"diagnosis":["按校正公式计算血钙；查血PTH（甲旁亢升高）、血磷、25-(OH)D、血清蛋白电泳及肿瘤相关检查以明确病因。"],"infusion":["积极补液最关键：0.9%NaCl 200-500ml/h，首24h总量3-4L，根据心功能与容量状态调整，严密监测出入量与心肺体征防容量过负荷。"],"oral_medication":["泼尼松40-60mg/d口服（适用于血液系统恶性肿瘤、维生素D中毒、结节病相关）；甲旁亢相关难治病例可予西那卡塞（cinacalcet）。"],"treatment":["①补液扩容促尿钙排泄。②降钙素4-8U/kg IM或SC q6-12h，4-6h快速起效，但24-48h后出现耐受。③双膦酸盐（一线持久降钙药）：唑来膦酸4mg IV（15-30min输注），2-4天达峰、维持2-4周；或帕米膦酸二钠60-90mg IV（2-4h输注）。④糖皮质激素（血液系统肿瘤、VitD中毒、结节病相关）。⑤严重/难治/肾衰竭：低钙透析液血液透析。⑥病因治疗：甲旁亢评估甲状旁腺切除术，恶性肿瘤行抗肿瘤治疗。"],"management":["心电监护QT间期与心律；每6-12h监测血钙；监测肾功能与出入量；心衰或老年人注意控制补液速度防肺水肿。"],"notes":["双膦酸盐起效慢，急性期依靠补液＋降钙素控制，双膦酸盐负责中期维持；肾功能不全者需调整剂量。"],"emergency":["高钙危象伴意识改变、心律失常或急性肾损伤为急症，立即补液并联合降钙治疗。"],"pinyin":"weijizhi：gaogaiweixiang","icd10":"E83.5（钙代谢紊乱，高钙血症）","physical_exam":"神志状态、脱水体征、心律心率、肌力与腱反射。","lab_tests":"血钙（校正值）、白蛋白、PTH、血磷、血镁、肾功能、心电图。","nursing":"监测出入量与心肺体征、防跌倒、双膦酸盐输注防外渗、记录神志变化。","diet":"鼓励饮水促进钙排泄；低钙饮食，视病因停用维生素D与噻嗪类利尿剂。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1273},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d772d6e932439243a5fec8123f7f1d1d1612f1802e42921947a4cef8e6d9e287","pinyin":"weijizhi：gaogaiweixiang","initials":"wjz：ggwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多饮多尿、恶心呕吐、便秘、食欲减退、肌无力、嗜睡、意识模糊、昏迷、心悸。",60],["摘要","危急阈值：校正后血钙≥3.5mmol/L（14mg/dL）。校正钙＝测定钙＋0.02×(40-白蛋白g/L)。临床意义：可致急性肾损伤（肾血管收缩、尿浓缩功能障碍、肾钙质沉积）、QT间期缩短与心律失常、意识改变至昏迷；最常见病因为恶性肿瘤（约70%）与原发性甲旁亢（约20%）。",30],["疾病编码","E83.5（钙代谢紊乱，高钙血症）",30],["原首字母","weijizhi：gaogaiweixiang",60]]},{"id":"orders-0bda3a18eb900b965d4d","key":"v1-c9ccc21dfe2a3058|orders-0bda3a18eb900b965d4d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：严重低钙血症","category":"内科危急值","raw":{"name":"危急值：严重低钙血症","category":"内科危急值","summary":"危急阈值：校正后血钙≤1.5mmol/L（6mg/dL），或任意血钙水平伴症状（手足搐搦、喉痉挛、癫痫）。临床意义：临床表现取决于血钙下降速度与程度；急性严重低钙可致喉痉挛（气道急症）、癫痫发作、QT间期延长，有尖端扭转型室速风险。","symptoms":["四肢末端与口周麻木、手足搐搦、肌肉痉挛、喉鸣与呼吸困难、癫痫发作、乏力。"],"diagnosis":["计算校正血钙；同步查血镁、血磷、PTH、25-(OH)D；鉴别低镁血症、甲状旁腺功能减退、维生素D缺乏、肾衰竭、横纹肌溶解/肿瘤溶解等病因。"],"infusion":["有症状者：10%葡萄糖酸钙10-20ml缓慢IV（>10min，经大静脉），可重复；症状持续：10%葡萄糖酸钙40-80ml＋D5W 500ml持续泵入，自10-20ml/h起调整；同步补镁：硫酸镁2-4g IV（顽固性低钙常合并低镁，镁不纠正则补钙效果差）。"],"oral_medication":["慢性期口服碳酸钙或枸橼酸钙1-2g/d分次；骨化三醇0.25-1μg/d或维生素D₂ 50000IU/周。"],"treatment":["急性症状性低钙：立即静脉补钙＋同步补镁＋心电监护（监测QT间期）；慢性管理：口服钙剂＋活性维生素D；病因治疗：甲旁减用PTH(1-84)替代，维生素D缺乏大剂量补充，肾衰竭用活性VitD（骨化三醇），横纹肌溶解/肿瘤溶解纠正原发病并防高磷血症。"],"management":["持续心电监护观察QT间期与心律失常；监测血钙、镁、磷水平；静脉补钙严防外渗（可致组织坏死）。"],"notes":["低镁血症是顽固性低钙的常见原因，必须同步纠正低镁；补钙经大静脉缓慢推注或泵入。"],"emergency":["喉痉挛（气道梗阻）或癫痫发作为急症：保持气道通畅，立即静脉补钙并补镁。"],"pinyin":"weijizhi：yanzhongdigaixuezheng","icd10":"E83.5（低钙血症）","physical_exam":"Chvostek征、Trousseau征、喉鸣与呼吸状态、心律、神志。","lab_tests":"校正血钙、血镁、血磷、PTH、25-(OH)D、肾功能、心电图（QT间期）。","nursing":"心电监护；观察钙剂输注部位防渗漏；抽搐与喉痉挛的急救配合；防跌倒。","diet":"高钙饮食（乳制品）；依病因限磷或补充维生素D；避免过量草酸食物影响钙吸收。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1274},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"706c267a7437b62e338e45c1f9c3b6015ce55d67d4f5a9687ef92e8aec7496b4","pinyin":"weijizhi：yanzhongdigaixuezheng","initials":"wjz：yzdgxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","四肢末端与口周麻木、手足搐搦、肌肉痉挛、喉鸣与呼吸困难、癫痫发作、乏力。",60],["摘要","危急阈值：校正后血钙≤1.5mmol/L（6mg/dL），或任意血钙水平伴症状（手足搐搦、喉痉挛、癫痫）。临床意义：临床表现取决于血钙下降速度与程度；急性严重低钙可致喉痉挛（气道急症）、癫痫发作、QT间期延长，有尖端扭转型室速风险。",30],["疾病编码","E83.5（低钙血症）",30],["原首字母","weijizhi：yanzhongdigaixuezheng",60]]},{"id":"orders-eb46085aaff9e11994bd","key":"v1-c9ccc21dfe2a3058|orders-eb46085aaff9e11994bd","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：尿毒症紧急并发症（脑病/心包炎）","category":"内科危急值","raw":{"name":"危急值：尿毒症紧急并发症（脑病/心包炎）","category":"内科危急值","summary":"危急阈值：血Cr显著升高＋BUN>35.7mmol/L（100mg/dL）＋尿毒症症状（恶心呕吐、意识改变、心包摩擦音、出血倾向）。临床意义：提示肾衰竭已达需紧急启动/强化透析阶段；尿毒症心包炎可致心包填塞，尿毒症脑病晚期可昏迷，均属急诊指征。","symptoms":["恶心呕吐、纳差、乏力、注意力不集中、睡眠倒错、扑翼样震颤、意识模糊至昏迷；胸痛、呼吸困难（心包炎表现）；皮肤瘀点瘀斑、牙龈出血等出血倾向。"],"diagnosis":["结合血Cr/BUN显著升高与典型症状；急查电解质、血气；心包炎行心电图与超声心动图（心包积液、填塞征象）；排除其他代谢性或器质性脑病。"],"infusion":["以紧急透析为核心；首次透析预防失衡综合征：短时透析（2-3h）、低血流量（150-200ml/min）、小面积透析器。"],"oral_medication":["降压药、促红素/铁剂、磷结合剂等按肾功能调整；止吐药（甲氧氯普胺/昂丹司琼）口服或静脉给药。"],"treatment":["①紧急启动/强化透析（血液透析或CRRT）；尿毒症心包炎应强化透析并避免全身抗凝（改用无肝素或枸橼酸抗凝）。②控制症状：恶心呕吐予甲氧氯普胺/昂丹司琼；出血倾向予DDAVP 0.3μg/kg IV；纠正高钾与代谢性酸中毒。③血管通路：临时行中心静脉置管（颈内/股静脉），长期尽早建立AVF或AVG。④血压、贫血、钙磷代谢综合管理。"],"management":["透析前后监测生命体征、意识与神经症状；警惕心包填塞征象（低血压、奇脉、颈静脉怒张）；处理失衡综合征（头痛、恶心、抽搐）。"],"notes":["心包积液伴血流动力学不稳定提示心包填塞，需紧急心包穿刺引流。"],"emergency":["心包填塞（低血压、奇脉）→紧急心包穿刺引流；重度尿毒症脑病/昏迷伴BUN极高→紧急透析。"],"pinyin":"weijizhi：niaoduzhengjinjibingfazheng（naobing/xinbaoyan）","icd10":"N19（尿毒症）","physical_exam":"心包摩擦音、扑翼样震颤、意识与GCS、血压、颈静脉、皮肤出血点。","lab_tests":"血Cr、BUN、血钾、电解质、血气分析、血常规与凝血功能、心电图、超声心动图。","nursing":"透析前后护理与血管通路保护、心电监护、出血患者延长压迫止血时间、昏迷者气道与皮肤护理。","diet":"优质低蛋白饮食，严格低钾、低磷、低盐，控制液体入量并监测体重。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1275},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e9b1090c9f1602968a8473daabc341fe618b7894c08077319fe58a980b99b9b5","pinyin":"weijizhi：niaoduzhengjinjibingfazheng（naobing/xinbaoyan）","initials":"wjz：ndzjjbfz（nb/xby）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","恶心呕吐、纳差、乏力、注意力不集中、睡眠倒错、扑翼样震颤、意识模糊至昏迷；胸痛、呼吸困难（心包炎表现）；皮肤瘀点瘀斑、牙龈出血等出血倾向。",60],["摘要","危急阈值：血Cr显著升高＋BUN>35.7mmol/L（100mg/dL）＋尿毒症症状（恶心呕吐、意识改变、心包摩擦音、出血倾向）。临床意义：提示肾衰竭已达需紧急启动/强化透析阶段；尿毒症心包炎可致心包填塞，尿毒症脑病晚期可昏迷，均属急诊指征。",30],["疾病编码","N19（尿毒症）",30],["原首字母","weijizhi：niaoduzhengjinjibingfazheng（naobing/xinbaoyan）",60]]},{"id":"orders-f2656538fe5e1460662e","key":"v1-c9ccc21dfe2a3058|orders-f2656538fe5e1460662e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：重度贫血","category":"内科危急值","raw":{"name":"危急值：重度贫血","category":"内科危急值","summary":"危急阈值：血红蛋白(Hb)≤60g/L；活动性出血时可放宽至Hb<70-80g/L即需输血。临床意义：严重贫血致组织供氧不足、代偿性心输出量增加，可诱发心肌缺血与心力衰竭（原有心脏病者尤甚）；慢性贫血耐受性较好，而急性失血/溶血致Hb骤降者耐受差，需积极干预。","symptoms":["头晕、乏力、面色苍白、活动后心悸气促、胸痛；体位性低血压、心率增快提示血容量不足或缺氧失代偿；心衰者可现端坐呼吸、下肢水肿；溶血性者有黄疸、酱油色尿。"],"diagnosis":["血常规示Hb≤60g/L即达危急值。评估血流动力学与缺氧症状（胸痛、气促、头晕、体位性低血压、心衰征象）。病因筛查：急性失血→急诊内镜/影像学定位出血灶；溶血→Coombs试验、LDH、胆红素、结合珠蛋白；骨髓造血障碍→骨髓穿刺/活检；营养缺乏→铁蛋白、叶酸、维生素B12。无症状且Hb<50g/L者个体化评估：年轻无基础病可观察，老年/心脏病者放宽输血指征。"],"infusion":["有症状或急性失血：输注ABO同型+交叉配血悬浮红细胞2-4U；急性失血可加压快速输注，慢性贫血缓慢输注（每次1U、>2h）；心衰患者每次输注1U，输注中监测心肺体征，必要时同时给予呋塞米利尿减轻容量负荷。"],"oral_medication":["按病因补充：缺铁性贫血予铁剂，巨幼细胞贫血予叶酸、维生素B12；慢性肾病/慢性病贫血在医生指导下评估EPO等促红素治疗（非急症首选）。"],"treatment":["核心为病因治疗：急性失血→止血（急诊内镜、介入或手术）；自身免疫性溶血→糖皮质激素等免疫抑制；骨髓衰竭→促造血治疗或成分支持。输血期间监测输血反应（发热、过敏、溶血、循环超负荷TACO）。"],"management":["监测生命体征、血氧、尿量；心衰者控制输液速度并记录出入量；定期复查血常规评估Hb动态；输血前后严格核对血型及交叉配血结果；观察有无输血反应并及时处理。"],"notes":["慢性贫血患者对较低Hb耐受性较好，不必一律按阈值输血；急性Hb骤降者即使数值略高也可明显不耐受，需放宽输血指征、个体化决策。"],"emergency":["输血反应（尤其急性溶血反应、TACO）一旦发生立即停止输注、换用生理盐水维持通路，溶血反应查血尿游离血红蛋白、复查血型与交叉配血，TACO予利尿、减慢输液；失血性休克者在配血完成前先以晶体液复苏并启用O型或同型红细胞紧急抢救。"],"pinyin":"weijizhi：zhongdupinxue","icd10":"D64.9","physical_exam":"皮肤黏膜苍白、心率增快、血压下降或体位性低血压；心衰时肺底湿啰音、颈静脉充盈、下肢水肿；溶血性者巩膜皮肤黄染、脾大。","lab_tests":"血常规+网织红细胞计数、外周血涂片；铁蛋白、叶酸、维生素B12；LDH、胆红素、结合珠蛋白、Coombs试验；肝肾功能；心电图评估心肌缺血。","nursing":"卧床休息、减少耗氧与活动；防跌倒坠床；心衰者控制输液速度、准确记录出入量；注意保暖；观察输血过程反应。","diet":"高蛋白、富含铁、叶酸与维生素B12饮食（瘦肉、动物肝脏、绿叶蔬菜）；溶血急性期清淡易消化。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1276},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8521766b893f24ee61d914cd25b7286a1f65b0ebfb17f4f3ccedc0c246f4525d","pinyin":"weijizhi：zhongdupinxue","initials":"wjz：zdpx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","头晕、乏力、面色苍白、活动后心悸气促、胸痛；体位性低血压、心率增快提示血容量不足或缺氧失代偿；心衰者可现端坐呼吸、下肢水肿；溶血性者有黄疸、酱油色尿。",60],["摘要","危急阈值：血红蛋白(Hb)≤60g/L；活动性出血时可放宽至Hb<70-80g/L即需输血。临床意义：严重贫血致组织供氧不足、代偿性心输出量增加，可诱发心肌缺血与心力衰竭（原有心脏病者尤甚）；慢性贫血耐受性较好，而急性失血/溶血致Hb骤降者耐受差，需积极干预。",30],["疾病编码","D64.9",30],["原首字母","weijizhi：zhongdupinxue",60]]},{"id":"orders-61c341c16ea9e4c3866d","key":"v1-c9ccc21dfe2a3058|orders-61c341c16ea9e4c3866d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：重度血小板减少症","category":"内科危急值","raw":{"name":"危急值：重度血小板减少症","category":"内科危急值","summary":"危急阈值：血小板(PLT)≤20×10⁹/L，最常见于重症免疫性血小板减少症(ITP)与化疗后骨髓抑制。临床意义：PLT<50×10⁹/L外伤/手术出血风险增加；<20×10⁹/L可自发皮肤黏膜出血；<10×10⁹/L内脏及颅内出血风险显著升高，需预防性输注血小板。","symptoms":["皮肤瘀点瘀斑、牙龈出血、鼻出血、口腔血疱；血便/血尿提示消化道或泌尿道出血；突发剧烈头痛、呕吐、意识改变提示颅内出血（最危急）。"],"diagnosis":["血常规示PLT≤20×10⁹/L并经外周血涂片复核（排除EDTA依赖性假性减少）。评估出血迹象（皮肤黏膜、眼底、消化道、泌尿道、中枢）。病因鉴别：ITP（血小板相关抗体）、TTP（ADAMTS13、破碎红细胞、LDH）、HIT（肝素暴露史+PF4抗体）、再障/白血病（骨髓检查）。"],"infusion":["输血指征：①活动性出血→输注血小板1-2个治疗量（成人1个治疗量约提升PLT 20-30×10⁹/L）；②PLT<10×10⁹/L无出血→预防性输注，尤其合并发热/感染/抗凝时；③PLT<50×10⁹/L需侵入性操作→操作前输注；④ITP血小板被快速破坏、输注疗效差，仅用于致命性出血。"],"oral_medication":["ITP：地塞米松40mg/d口服×4天或泼尼松1mg/kg/d；化疗后骨髓抑制：艾曲泊帕、阿伐曲泊帕等口服TPO-RA；禁服阿司匹林等抗血小板药与抗凝药。"],"treatment":["病因治疗：ITP→糖皮质激素+IVIG 1g/kg（急救/术前）；TTP→血浆置换+激素；HIT→停肝素、换比伐卢定或阿加曲班；再障→免疫抑制或移植评估；化疗后骨髓抑制→TPO-RA（罗米司亭/艾曲泊帕/阿伐曲泊帕）。严重出血可加抗纤溶药氨甲环酸1g IV q8h，尿路出血禁用（血凝块可致梗阻）。"],"management":["严密观察皮肤黏膜、眼底、消化道、泌尿道及中枢出血迹象；输注后复查血小板评价疗效；避免肌内注射、硬毛牙刷、牙龈刺激及不必要有创操作；使用抗纤溶药者监测血栓风险。"],"notes":["ITP输注血小板疗效短暂，仅限致命性出血时使用；PLT<10×10⁹/L合并发热/感染/抗凝是预防性输注的强化指征；氨甲环酸禁用于尿路出血。"],"emergency":["颅内或内脏大出血：紧急输注血小板（可多单位）、大剂量糖皮质激素冲击、IVIG 1g/kg，必要时重组人凝血因子Ⅶa，请血液科会诊并转ICU；同步头颅CT明确颅内出血。"],"pinyin":"weijizhi：zhongduxuexiaobanjianshaozheng","icd10":"D69.6","physical_exam":"皮肤瘀点瘀斑、口腔黏膜血疱、牙龈渗血、眼底出血、鼻腔出血；疑颅内出血者查神志、瞳孔与神经系统体征。","lab_tests":"血常规+血涂片、凝血功能、血小板抗体、肝肾功能；疑DIC查D-二聚体/纤维蛋白原；疑TTP查LDH、破碎红细胞、ADAMTS13；疑HIT查PF4抗体。","nursing":"急性期卧床休息、减少活动防碰撞跌倒；用软毛牙刷或纱布清洁口腔；观察并记录大小便颜色、痰液及呕吐物有无血性；静脉穿刺后按压5-10分钟以上；避免肌注与灌肠。","diet":"温凉软食，避免过热、坚硬、粗糙及带骨刺食物，防止划伤消化道黏膜。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1277},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7b383929bba044657eae664781222ec4548bdc45e377cbcea758dae739ff0ac6","pinyin":"weijizhi：zhongduxuexiaobanjianshaozheng","initials":"wjz：zdxxbjsz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤瘀点瘀斑、牙龈出血、鼻出血、口腔血疱；血便/血尿提示消化道或泌尿道出血；突发剧烈头痛、呕吐、意识改变提示颅内出血（最危急）。",60],["摘要","危急阈值：血小板(PLT)≤20×10⁹/L，最常见于重症免疫性血小板减少症(ITP)与化疗后骨髓抑制。临床意义：PLT<50×10⁹/L外伤/手术出血风险增加；<20×10⁹/L可自发皮肤黏膜出血；<10×10⁹/L内脏及颅内出血风险显著升高，需预防性输注血小板。",30],["疾病编码","D69.6",30],["原首字母","weijizhi：zhongduxuexiaobanjianshaozheng",60]]},{"id":"orders-997fb2886fa72e9cc209","key":"v1-c9ccc21dfe2a3058|orders-997fb2886fa72e9cc209","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：粒细胞缺乏症","category":"内科危急值","raw":{"name":"危急值：粒细胞缺乏症","category":"内科危急值","summary":"危急阈值：中性粒细胞绝对计数(ANC)≤0.5×10⁹/L为重度粒细胞缺乏；≤0.1×10⁹/L为极重度，感染风险极高。临床意义：ANC<0.5×10⁹/L感染风险显著升高，因炎症反应减弱，发热常是感染唯一早期表现，病情可迅速进展为脓毒性休克，须按急症处理。","symptoms":["发热（可为唯一表现）、寒战；咽痛、口腔溃疡/黏膜炎、咳嗽、皮肤软组织红肿、肛周疼痛、导管部位红肿；进展期低血压、心率增快、意识改变提示脓毒性休克；无发热者也须全面排查感染。"],"diagnosis":["血常规示ANC≤0.5×10⁹/L；粒缺伴发热即按急症处理。全面评估感染：详细体格检查（口腔、咽喉、肺部、皮肤、肛周、导管部位）；查血常规+CRP/PCT、血培养（双部位）、痰/尿/便培养、胸部CT。病因筛查：化疗、药物、自身免疫、骨髓病变（再障/白血病）等。"],"infusion":["经验性广谱抗生素须静脉给药（见treatment）；发热伴低血压者予液体复苏；口腔黏膜炎重者加强静脉补液与营养支持，不常规静脉输注IVIG。"],"oral_medication":["G-CSF（粒细胞集落刺激因子）5μg/kg/d皮下注射，缩短粒细胞恢复时间；粒缺发热期抗生素以静脉为主，口服药仅作序贯或辅助。"],"treatment":["经验性广谱抗生素须在1小时内使用（延迟增加死亡率）：标准方案为抗假单胞菌β-内酰胺类——头孢吡肟2g IV q8h或哌拉西林他唑巴坦4.5g IV q6h或美罗培南1g IV q8h；血流动力学不稳定/高危者加氨基糖苷类（庆大霉素5-7mg/kg IV q24h）或万古霉素（MRSA高危、导管感染、严重黏膜炎时）；持续发热>72h评估真菌感染，加伏立康唑、卡泊芬净或两性霉素B脂质体；并查找病因（化疗、药物、自身免疫、骨髓病变、白血病）对因治疗。"],"management":["立即保护性隔离（层流病房/单间+严格手卫生+低菌饮食）；每日详细体格检查重点查口腔、咽喉、肺部、皮肤、肛周及导管部位；监测体温q4h与感染征象；复查血常规观察ANC动态。"],"notes":["粒缺患者炎症反应减弱，感染灶体征可不典型，发热是重要警报；经验性抗生素务必在发热后1小时内启用，先留培养再用药或与用药同步；退热不等于感染控制，需完成疗程并评估ANC恢复。"],"emergency":["出现脓毒性休克（低血压、组织灌注不足、意识改变）：快速液体复苏+广谱抗生素+血管活性药物，转ICU监护，尽早留血培养。"],"pinyin":"weijizhi：lixibaoquefazheng","icd10":"D70.9","physical_exam":"口腔黏膜炎/溃疡、咽部充血、肺部啰音、皮肤疖肿或蜂窝织炎、肛周红肿、导管穿刺点红肿渗液。","lab_tests":"血常规+白细胞分类计数（ANC）、CRP、PCT、血培养（双部位）、痰/尿/便培养、胸部CT；持续发热>72h者行G试验/GM试验等真菌学检查。","nursing":"严格落实保护性隔离与手卫生；软毛刷或棉签口腔护理、漱口液含漱；肛周每日清洁观察防感染；导管部位无菌换药；q4h测体温并记录；宣教低菌饮食。","diet":"低菌（无菌）饮食：食物充分加热煮熟，禁食生冷蔬果、隔夜及不洁食物。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1278},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"45fac66bc276d8eb2f970c764e14807515ec72744545456016fffe682202bb23","pinyin":"weijizhi：lixibaoquefazheng","initials":"wjz：lxbqfz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（可为唯一表现）、寒战；咽痛、口腔溃疡/黏膜炎、咳嗽、皮肤软组织红肿、肛周疼痛、导管部位红肿；进展期低血压、心率增快、意识改变提示脓毒性休克；无发热者也须全面排查感染。",60],["摘要","危急阈值：中性粒细胞绝对计数(ANC)≤0.5×10⁹/L为重度粒细胞缺乏；≤0.1×10⁹/L为极重度，感染风险极高。临床意义：ANC<0.5×10⁹/L感染风险显著升高，因炎症反应减弱，发热常是感染唯一早期表现，病情可迅速进展为脓毒性休克，须按急症处理。",30],["疾病编码","D70.9",30],["原首字母","weijizhi：lixibaoquefazheng",60]]},{"id":"orders-7d75a2e46c7a4b78fffb","key":"v1-c9ccc21dfe2a3058|orders-7d75a2e46c7a4b78fffb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：白细胞淤滞症","category":"内科危急值","raw":{"name":"危急值：白细胞淤滞症","category":"内科危急值","summary":"危急阈值：白细胞(WBC)≥100×10⁹/L，见于急性白血病或慢性粒细胞白血病急变期；WBC>200×10⁹/L时症状显著增加。临床意义：白血病原始细胞体积大、变形能力差，在微循环中形成白细胞栓子导致组织缺血/出血，最常累及肺（呼吸困难、低氧、ARDS）和脑（头痛、视力模糊、卒中、意识改变），属血液科急症。","symptoms":["肺受累：呼吸困难、低氧血症、ARDS样表现；脑受累：头痛、视力模糊、耳鸣、卒中、意识改变；出血倾向：鼻出血、视网膜出血；男性慢粒患者可现阴茎异常勃起（白细胞淤滞所致）。"],"diagnosis":["血常规示WBC≥100×10⁹/L，外周血涂片见大量原始细胞；骨髓穿刺/活检+流式免疫分型、细胞遗传学确定白血病类型；查血尿酸、电解质、肾功能、LDH评估肿瘤溶解风险；血气分析及胸片/CT评估肺受累，头颅影像评估脑缺血或出血。"],"infusion":["积极水化3L/m²/d（或约200-300ml/h）以稀释血液、改善微循环；碱化尿液使尿pH≥7.0；记录出入量、结合心功能调整补液速度。"],"oral_medication":["别嘌醇300mg/m²/d口服（或300mg qd，按CrCl调整）预防肿瘤溶解综合征；尿酸已升高者改用拉布立酶（见treatment）。"],"treatment":["①紧急白细胞单采术（LLL），单次可降低WBC 30%-50%，为最快速手段；②原发病化疗：急性早幼粒细胞白血病(APL)用全反式维甲酸(ATRA)并警惕分化综合征，其他急性白血病用诱导化疗方案；③高尿酸血症：尿酸≥8mg/dL时予拉布立酶（雷布立酶）0.2mg/kg IV qd快速降尿酸；④化疗期间注意TLS风险，不推荐预防性血小板输注（白细胞降低后PLT可能反跳）。"],"management":["监测q6h血常规、尿酸、K⁺、Ca²⁺、PO₄³⁻、Cr、LDH；密切观察呼吸频率、血氧及神志瞳孔变化；动态评估血栓、出血与TLS征象；APL化疗期监测分化综合征（发热、肺浸润、低血压）。"],"notes":["症状与白细胞升高的速度关系更大，慢性期白血病（如慢粒慢性期）WBC很高时症状常不明显，勿单凭数值急症化；预防性血小板输注可能加重微循环淤滞，且降白细胞后血小板可反跳，故不推荐。"],"emergency":["出现呼吸衰竭、卒中、颅内出血或意识障碍：紧急行白细胞单采术并启动原发病治疗，转ICU；颅内出血者尽早请神经外科评估手术指征。"],"pinyin":"weijizhi：baixibaoyuzhizheng","icd10":"C95.0","physical_exam":"神志与瞳孔、眼底检查（视网膜出血/静脉迂曲充盈）、呼吸频率与血氧、皮肤黏膜出血点、肝脾肿大（慢粒急变者脾大明显）。","lab_tests":"血常规+血涂片（原始细胞比例）、骨髓细胞学/流式/遗传学、血尿酸、K⁺、Ca²⁺、PO₄³⁻、肌酐、LDH、凝血功能、动脉血气分析。","nursing":"卧床休息、避免剧烈活动；监测神志、瞳孔、呼吸与血氧；准确记录出入量、维持足够尿量；意识障碍者防跌倒坠床；宣教并观察出血征象。","diet":"保证饮水摄入（补液以静脉为主），饮食清淡易消化。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1279},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e577b2518260584c8d8ca92b6efe99c65edf9e2f18d73658fc1023b2b5b2e33f","pinyin":"weijizhi：baixibaoyuzhizheng","initials":"wjz：bxbyzz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肺受累：呼吸困难、低氧血症、ARDS样表现；脑受累：头痛、视力模糊、耳鸣、卒中、意识改变；出血倾向：鼻出血、视网膜出血；男性慢粒患者可现阴茎异常勃起（白细胞淤滞所致）。",60],["摘要","危急阈值：白细胞(WBC)≥100×10⁹/L，见于急性白血病或慢性粒细胞白血病急变期；WBC>200×10⁹/L时症状显著增加。临床意义：白血病原始细胞体积大、变形能力差，在微循环中形成白细胞栓子导致组织缺血/出血，最常累及肺（呼吸困难、低氧、ARDS）和脑（头痛、视力模糊、卒中、意识改变），属血液科急症。",30],["疾病编码","C95.0",30],["原首字母","weijizhi：baixibaoyuzhizheng",60]]},{"id":"orders-a4c31b79d103efc980be","key":"v1-c9ccc21dfe2a3058|orders-a4c31b79d103efc980be","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：弥散性血管内凝血","category":"内科危急值","raw":{"name":"危急值：弥散性血管内凝血","category":"内科危急值","summary":"危急阈值：ISTH SSC评分≥5分可诊断DIC（血小板↓、D-二聚体↑>3-7倍正常上限、PT延长、纤维蛋白原↓）；2025年ISTH SSC定义强调内皮损伤+纤溶失调，并提出脓毒症诱导凝血病(SIC)等早期DIC。临床意义：DIC是脓毒症、创伤、恶性肿瘤、产科并发症等危重疾病的共同通路，微血管血栓致器官功能障碍，同时凝血物质消耗致严重出血——“血栓与出血并存”。","symptoms":["皮肤瘀点瘀斑、穿刺点/伤口渗血不止、黏膜出血、消化道出血（黑便/呕血）、血尿；血栓表现：肢端发绀、少尿、呼吸困难；重症低血压休克。"],"diagnosis":["存在DIC相关原发病（脓毒症、创伤、恶性肿瘤、产科并发症等）+实验室指标：血小板进行性下降、D-二聚体升高（>3-7倍正常上限）、PT/APTT延长、纤维蛋白原下降，按ISTH SSC评分≥5分诊断；动态复查指标并监测器官功能，与原发纤溶亢进鉴别。"],"infusion":["出血为主者：PLT<50×10⁹/L伴出血→输注血小板1-2个治疗量；纤维蛋白原<1.0g/L→输冷沉淀10-12U或纤维蛋白原浓缩剂；PT/APTT显著延长伴出血→新鲜冰冻血浆(FFP)15ml/kg；活动性大出血采用大量输血方案，PRBC:FFP:PLT≈1:1:1。"],"oral_medication":["以静脉病因与支持治疗为主，口服药用于原发病处理（抗生素、抗肿瘤药等）；需抗凝（低分子肝素）时皮下注射给药，不口服。"],"treatment":["治疗原发病为最核心：脓毒症→抗生素+感染源控制；创伤/手术→止血+复苏；恶性肿瘤→化疗/靶向治疗；产科→排空子宫+宫缩药物。出血为主者按输注原则补充成分。血栓/器官功能障碍为主且无大出血者用低分子肝素；脓毒症DIC（日本2025指南）予ATⅢ浓缩物1500-3000U/d及重组人血栓调节蛋白(rhTM)380U/kg/d×6天（1B级推荐）。"],"management":["监测q6-12h血常规、PT/APTT、D-二聚体、纤维蛋白原及器官功能；动态DIC评分评估疗效；严密观察出血与血栓征象。"],"notes":["出血与血栓并存，抗凝与补充治疗需权衡；原发病不控制则凝血消耗持续，输注血制品前务必同步处理原发病；不主张无指征经验性肝素抗凝。"],"emergency":["活动性大出血按大量输血方案（PRBC:FFP:PLT≈1:1:1）紧急抢救并维持循环；颅内出血或休克者转ICU；纤维蛋白原极低时优先冷沉淀/纤维蛋白原浓缩剂补充后再复查。"],"pinyin":"weijizhi：misanxingxueguanneiningxue","icd10":"D65","physical_exam":"皮肤瘀点瘀斑、伤口及穿刺点渗血、口腔/鼻腔出血、肢端发绀、血压下降、心率增快；器官受累（少尿、呼吸困难、意识障碍）。","lab_tests":"血常规（血小板进行性下降）、PT/APTT延长、D-二聚体升高、纤维蛋白原下降、外周血涂片破碎红细胞；肝肾功能、血乳酸、血气分析动态监测。","nursing":"严密观察各部位出血（皮肤、黏膜、穿刺点、引流液、尿便）并记录；穿刺后充分按压；监测生命体征与尿量；注意保暖、防压疮；口腔护理动作轻柔防黏膜破损出血。","diet":"依原发病调整；出血活动期予温凉流质/半流质，减少黏膜刺激。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1280},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"61ac94e2ad43f0edbcffdd7c39a2f0b5c87fd36a2ee685a2260b695cded4b108","pinyin":"weijizhi：misanxingxueguanneiningxue","initials":"wjz：msxxgnnx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤瘀点瘀斑、穿刺点/伤口渗血不止、黏膜出血、消化道出血（黑便/呕血）、血尿；血栓表现：肢端发绀、少尿、呼吸困难；重症低血压休克。",60],["摘要","危急阈值：ISTH SSC评分≥5分可诊断DIC（血小板↓、D-二聚体↑>3-7倍正常上限、PT延长、纤维蛋白原↓）；2025年ISTH SSC定义强调内皮损伤+纤溶失调，并提出脓毒症诱导凝血病(SIC)等早期DIC。临床意义：DIC是脓毒症、创伤、恶性肿瘤、产科并发症等危重疾病的共同通路，微血管血栓致器官功能障碍，同时凝血物质消耗致严重出血——“血栓与出血并存”。",30],["疾病编码","D65",30],["原首字母","weijizhi：misanxingxueguanneiningxue",60]]},{"id":"orders-9c2d3bb63c76e086c761","key":"v1-c9ccc21dfe2a3058|orders-9c2d3bb63c76e086c761","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：严重凝血功能障碍","category":"内科危急值","raw":{"name":"危急值：严重凝血功能障碍","category":"内科危急值","summary":"危急阈值：INR≥4.5（或APTT显著延长）且合并活动性出血或大出血高风险。临床意义：INR显著延长常见于华法林过量、肝衰竭、DIC、维生素K缺乏，华法林相关出血最常见；合并颅内/后腹膜/消化道等出血时须紧急逆转。","symptoms":["皮肤瘀斑、牙龈出血、鼻出血、血尿、黑便/呕血；颅内出血：剧烈头痛、呕吐、意识改变、肢体无力；后腹膜出血：腹痛、腰背痛伴血压下降；伤口及穿刺点渗血不止。"],"diagnosis":["凝血功能示INR≥4.5或APTT显著延长；追问抗凝药史（华法林/DOAC/肝素）及肝病营养状况；查肝肾功能、血小板、D-二聚体、纤维蛋白原；头颅CT/腹部影像定位出血；评估血流动力学。"],"infusion":["活动性出血（尤其颅内/后腹膜/胃肠道）：维生素K1 5-10mg缓慢静脉注射+四因子凝血酶原复合物(PCC)25-50U/kg；无PCC时用FFP 15-30ml/kg（纠正慢、容量负荷大）；按凝血参数与出血部位补充FFP/冷沉淀/血小板。"],"oral_medication":["维生素K1口服：INR>4.5且<10、无出血者予2.5-5mg po；INR>10、无出血者予5-10mg po，24小时复查INR。出血控制后重新评估是否恢复抗凝及剂量。"],"treatment":["①停用抗凝药并评估出血部位与严重度；②华法林相关：按INR分级口服/静脉维生素K1，活动性大出血加四因子PCC 25-50U/kg（纠正快、容量负荷小，优于FFP）；③DOAC相关出血：达比加群→依达赛珠单抗5g IV（推注+持续输注）；利伐沙班/阿哌沙班→Andexanet alfa（IV负荷+持续输注）或PCC 25-50U/kg；④肝素相关出血→鱼精蛋白1mg/100U肝素（停药后每30分钟半量递减）；⑤病因：肝病→VitK1+FFP；营养缺乏→补VitK1；抗磷脂综合征→调整抗凝。"],"management":["停用抗凝药后动态复查INR/APTT评估逆转效果；颅内/后腹膜出血请神经外科会诊并转ICU；监测生命体征与出血量；出血停止后评估抗凝恢复指征与时机。"],"notes":["FFP纠正慢且容量负荷大，活动性大出血优先用PCC；VitK1静注须缓慢，快速输注可致过敏样反应；INR>10者无论有无出血均须紧急处理。"],"emergency":["颅内出血（最危急）：立即维生素K1 10mg IV+四因子PCC 25-50U/kg，同步头颅CT并请神经外科会诊；大出血伴血流动力学不稳定按大量输血方案复苏并转ICU。"],"pinyin":"weijizhi：yanzhongningxuegongnengzhangai","icd10":"D68.4","physical_exam":"皮肤瘀斑、伤口/穿刺点渗血、口腔黏膜出血；血压心率变化提示低血容量；腹部膨隆压痛（后腹膜出血）；神志瞳孔及神经体征（颅内出血）。","lab_tests":"PT/INR、APTT、纤维蛋白原、D-二聚体、血小板、肝肾功能；必要时测抗凝药血药浓度；影像学定位出血（头颅/腹部CT等）。","nursing":"减少搬动与有创操作；穿刺后充分按压（5-10分钟以上）；观察并记录引流液、尿液、粪便颜色及神志、瞳孔、血压变化；预防跌倒。","diet":"少渣易消化饮食，避免粗糙坚硬食物；肝病患者按其饮食原则调整。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1281},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7e46016e45a53549e1704b2dfb79284f05af6a78d9e4cc699536bae707b5ae68","pinyin":"weijizhi：yanzhongningxuegongnengzhangai","initials":"wjz：yznxgnza","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤瘀斑、牙龈出血、鼻出血、血尿、黑便/呕血；颅内出血：剧烈头痛、呕吐、意识改变、肢体无力；后腹膜出血：腹痛、腰背痛伴血压下降；伤口及穿刺点渗血不止。",60],["摘要","危急阈值：INR≥4.5（或APTT显著延长）且合并活动性出血或大出血高风险。临床意义：INR显著延长常见于华法林过量、肝衰竭、DIC、维生素K缺乏，华法林相关出血最常见；合并颅内/后腹膜/消化道等出血时须紧急逆转。",30],["疾病编码","D68.4",30],["原首字母","weijizhi：yanzhongningxuegongnengzhangai",60]]},{"id":"orders-a2afc87a2a0008c4ca6a","key":"v1-c9ccc21dfe2a3058|orders-a2afc87a2a0008c4ca6a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：肿瘤溶解综合征","category":"内科危急值","raw":{"name":"危急值：肿瘤溶解综合征","category":"内科危急值","summary":"危急阈值：Cairo-Bishop分级≥2级（实验室TLS：尿酸↑、K⁺↑、PO₄³⁻↑、Ca²⁺↓；临床TLS：Cr↑、心律失常/猝死、癫痫）。临床意义：TLS是肿瘤治疗中大量细胞溶解释放细胞内成分（尿酸、K⁺、PO₄³⁻）入血的代谢急症，高发于急性白血病（尤其ALL）、Burkitt淋巴瘤等；严重者可致急性肾损伤（尿酸结晶+磷酸钙沉积）、高钾心律失常甚至猝死。","symptoms":["恶心呕吐、乏力；少尿/无尿提示急性肾损伤；肌肉痉挛、手足麻木、抽搐（低钙）；心悸、晕厥提示高钾心律失常；癫痫、意识改变见于严重电解质紊乱。"],"diagnosis":["高危条件：高增殖、高肿瘤负荷、化疗高度敏感的肿瘤。化疗启动后查血尿酸↑、K⁺↑、PO₄³⁻↑、Ca²⁺↓、LDH显著升高、肌酐↑，按Cairo-Bishop标准分级；据风险分层（低/中/高/极高危）决定预防强度；治疗前评估基线肾功能与尿酸。"],"infusion":["强化水化3L/m²/d或200-300ml/h（平衡液或0.45%NaCl），监测出入量、维持足够尿量以冲刷尿酸与磷酸盐；心肾功能不全者调整补液速度，尿量充足时可加利尿剂维持尿量。"],"oral_medication":["别嘌醇300mg/m²/d口服用于预防（对已升高的尿酸作用慢）；高磷血症予磷酸盐结合剂随餐口服：碳酸镧750mg tid或司维拉姆800mg tid。"],"treatment":["降尿酸：已出现高尿酸或中/高危TLS首选拉布立酶（雷布立酶）0.2mg/kg IV qd，1-2小时内降至正常（G6PD缺乏者禁用，用前筛查）；高钾（见心内科章）：静脉钙剂+胰岛素葡萄糖+利尿等，必要时透析；低钙：无症状不处理（防磷酸钙沉积加重），有症状予葡萄糖酸钙；严重肾损伤（Cr↑、少尿、药物无效）→血液透析。"],"management":["化疗前后q6h监测血常规、尿酸、K⁺、Ca²⁺、PO₄³⁻、Cr、LDH，高危者持续3-7天；记录出入量维持尿量；据风险分层决定预防强度（水化、别嘌醇或拉布立酶）。"],"notes":["拉布立酶禁用于G6PD缺乏者（可致溶血），用药前必须筛查；别嘌醇对已升高的尿酸作用缓慢，已确诊高尿酸时优先拉布立酶；无症状低钙不补钙，以免磷酸钙沉积加重肾损伤。"],"emergency":["高钾致恶性心律失常（心电图T波高尖、QRS增宽、室速/室颤）：立即静脉钙剂+胰岛素葡萄糖等紧急降钾并持续心电监护，转ICU；少尿性急性肾衰经药物治疗无效→紧急血液透析。"],"pinyin":"weijizhi：zhongliurongjiezonghezheng","icd10":"E88.8","physical_exam":"神志、皮肤弹性与脱水表现、心率心律、水肿；低钙体征（Chvostek征、Trousseau征）；记录尿量。","lab_tests":"血尿酸、K⁺、Ca²⁺、PO₄³⁻、肌酐、LDH、血常规动态监测（q6h）；血气分析；持续心电监护观察高钾心电图改变。","nursing":"心电监护并观察心律失常；准确记录24小时出入量、维持尿量；静脉补液执行与巡视（防液体过负荷）；宣教低钾饮食；观察抽搐、手足麻木与神志变化。","diet":"限钾饮食（少食香蕉、柑橘、土豆、绿叶菜等富钾食物）；限磷饮食（少食乳制品、坚果、加工食品）；治疗期以静脉补液为主。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1282},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7f2fe9ff03316f40841b7d160e09a5f728a6ab3d44c8d908c75509ebe02717ab","pinyin":"weijizhi：zhongliurongjiezonghezheng","initials":"wjz：zlrjzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","恶心呕吐、乏力；少尿/无尿提示急性肾损伤；肌肉痉挛、手足麻木、抽搐（低钙）；心悸、晕厥提示高钾心律失常；癫痫、意识改变见于严重电解质紊乱。",60],["摘要","危急阈值：Cairo-Bishop分级≥2级（实验室TLS：尿酸↑、K⁺↑、PO₄³⁻↑、Ca²⁺↓；临床TLS：Cr↑、心律失常/猝死、癫痫）。临床意义：TLS是肿瘤治疗中大量细胞溶解释放细胞内成分（尿酸、K⁺、PO₄³⁻）入血的代谢急症，高发于急性白血病（尤其ALL）、Burkitt淋巴瘤等；严重者可致急性肾损伤（尿酸结晶+磷酸钙沉积）、高钾心律失常甚至猝死。",30],["疾病编码","E88.8",30],["原首字母","weijizhi：zhongliurongjiezonghezheng",60]]},{"id":"orders-ac3cdddb2ca58bb54471","key":"v1-c9ccc21dfe2a3058|orders-ac3cdddb2ca58bb54471","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：系统性红斑狼疮危象","category":"内科危急值","raw":{"name":"危急值：系统性红斑狼疮危象","category":"内科危急值","summary":"识别要点：SLEDAI-2K≥12分或重要脏器受累（狼疮肾炎、中枢狼疮、重症血细胞减少、肺泡出血）即狼疮危象。意义：重度SLE可累及任何器官，肾最常见、中枢最紧急、肺泡出血最致命，须立即强化治疗。","symptoms":["高热、面部皮疹、口腔溃疡、关节炎、浆膜炎；肾受累见水肿、泡沫尿、血尿、高血压；中枢受累见抽搐、精神异常、意识障碍；肺出血见咯血、呼吸困难。"],"diagnosis":["查ANA、抗dsDNA、抗Sm、抗磷脂抗体、补体、血尿常规、肝肾功能、24h尿蛋白及尿沉渣；肾受累行活检分型；中枢症状行脑MRI+腰穿排除感染等病因；肺行HRCT、心行超声。"],"infusion":["甲泼尼龙500-1000mg/d×3天冲击；环磷酰胺0.5-1g/m²（按CrCl调）；利妥昔单抗375mg/m²/周×4；均缓慢滴注并监护血压与过敏。"],"oral_medication":["泼尼松（冲击后0.5-1mg/kg/d递减）；MMF 1.5-3g/d；羟氯喹200-400mg/d；钙+维生素D；复方新诺明防PJP；抗磷脂抗体阳性伴血栓史者华法林INR2-3；肾炎加ACEI/ARB。"],"treatment":["甲泼尼龙500-1000mg/d冲击3天（>30min滴注），继以泼尼松0.5-1mg/kg/d并于4-6周减至≤7.5mg/d；联合环磷酰胺0.5-1g/m²（按CrCl调，每月×6）或MMF 1.5-3g/d（Ⅲ/Ⅳ型肾炎首选，维持≤2g/d）；难治/复发加贝利木单抗、利妥昔单抗或阿尼鲁单抗，剂量按EULAR/ACR及国内共识执行；冲击期监护血压、血糖、电解质与感染；环磷酰胺防骨髓抑制与出血性膀胱炎。"],"management":["收风湿病房或监护室；动态监测血尿常规、肾功能、24h尿蛋白、补体；防感染、血栓及应激性溃疡；冲击期控血糖血压；防日晒并随访减药。"],"notes":["延误激素冲击是狼疮危象最常见失误；激素依赖者尽早加生物制剂；活动期避孕。"],"emergency":["评估受累脏器（尿蛋白、肾功能、脑MRI+腰穿、HRCT、心超）后即刻甲泼尼龙大剂量冲击诱导缓解，口服激素衔接并同步加免疫抑制剂；肺泡出血、癫痫持续、急进性肾炎按专科流程强化，必要时入监护室。"],"pinyin":"weijizhi：xitongxinghongbanlangchuangweixiang","icd10":"M32.1","physical_exam":"面部皮疹、口腔溃疡、关节肿痛、浆膜摩擦音或胸腹水、水肿、血压升高；中枢受累见意识改变、抽搐。","lab_tests":"ANA、抗dsDNA、抗Sm、抗磷脂抗体、补体C3/C4、血尿常规、肝肾功能、24h尿蛋白、尿沉渣；必要时脑脊液、MRI、肾活检。","nursing":"冲击期心电血压监护并测血糖；抽搐或意识障碍者加床栏；记录出入量与尿量、规范留尿；宣教避日晒、防感染。","diet":"低盐低脂；肾病者限蛋白限水防高钾；激素期控糖；补钙与维生素D。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1283},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"171bbf02ad79f4e67095b427d2b0ac2c5f2a689f5f2d85de1a2c3730aa471efa","pinyin":"weijizhi：xitongxinghongbanlangchuangweixiang","initials":"wjz：xtxhblcwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","高热、面部皮疹、口腔溃疡、关节炎、浆膜炎；肾受累见水肿、泡沫尿、血尿、高血压；中枢受累见抽搐、精神异常、意识障碍；肺出血见咯血、呼吸困难。",60],["摘要","识别要点：SLEDAI-2K≥12分或重要脏器受累（狼疮肾炎、中枢狼疮、重症血细胞减少、肺泡出血）即狼疮危象。意义：重度SLE可累及任何器官，肾最常见、中枢最紧急、肺泡出血最致命，须立即强化治疗。",30],["疾病编码","M32.1",30],["原首字母","weijizhi：xitongxinghongbanlangchuangweixiang",60]]},{"id":"orders-5fbd286030d5d53559cd","key":"v1-c9ccc21dfe2a3058|orders-5fbd286030d5d53559cd","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：中枢神经系统狼疮（NPSLE）","category":"内科危急值","raw":{"name":"危急值：中枢神经系统狼疮（NPSLE）","category":"内科危急值","summary":"识别要点：SLE患者新发癫痫、精神异常、横贯性脊髓炎、无菌性脑膜炎，须排除感染、代谢、药物与脑血管病后诊断。意义：为SLE最严重并发症之一，可致永久神经损伤，认知障碍最常见，需及早抢救。","symptoms":["认知障碍（最常见）、癫痫、精神行为异常、头痛；脊髓炎见截瘫、感觉平面、二便障碍；无菌性脑膜炎见头痛颈强；可有意识下降。"],"diagnosis":["排除性诊断：腰穿查细胞数、蛋白、糖、培养、病毒PCR及自身抗体（ANA/抗dsDNA/抗Ro/抗La等）；脑MRI+增强排除感染、脱髓鞘、血管炎与卒中；EEG查痫性活动；与中枢感染、精神疾病、激素性精神病鉴别。"],"infusion":["甲泼尼龙500-1000mg/d×3天（>30min滴注）；环磷酰胺0.5-1g/m²；利妥昔单抗375mg/m²/周×4；按肾功能调整、缓慢输注。"],"oral_medication":["泼尼松（冲击后递减）；抗癫痫首选左乙拉西坦500-2000mg/d；精神症状用奥氮平2.5-10mg/d或利培酮0.5-6mg/d；抑郁选SSRI、避免MAOI；羟氯喹200-400mg/d。"],"treatment":["重症NPSLE：甲泼尼龙500-1000mg/d冲击3天，环磷酰胺0.5-1g/m²（按肾功能调，可每月×6）；难治者利妥昔单抗375mg/m²/周×4，或环孢素A联合霉酚酸酯。剂量按EULAR/ACR及国内共识执行；冲击期监护血压、血糖、电解质、感染及心电图。"],"management":["神经科协作：癫痫防护（床栏、防舌咬伤）、动态评估意识与神经体征；防吸入性肺炎与血栓；复查脑脊液、MRI及血常规肝肾功能，调整用药。"],"notes":["用激素前务必留病原学排除感染；左乙拉西坦为抗癫痫首选；激素相关精神症状需与NPSLE鉴别。"],"emergency":["癫痫持续、脊髓炎或弥漫重症：先稳定气道与生命体征并控制抽搐，同步腰穿+MRI排除感染并留病原学；重症即大剂量激素冲击+环磷酰胺，难治者升阶利妥昔单抗；严重精神行为异常予防护镇静并请精神科。"],"pinyin":"weijizhi：zhongshushenjingxitonglangchuang（NPSLE）","icd10":"M32.1","physical_exam":"意识障碍或嗜睡、认知减退、精神行为异常、抽搐、脑膜刺激征、截瘫与感觉平面、病理征阳性。","lab_tests":"ANA、抗dsDNA、抗磷脂抗体、补体；CSF细胞数、蛋白、糖、培养、病毒PCR、自身抗体；脑MRI+增强、EEG。","nursing":"床栏防坠床，抽搐防舌咬伤误吸；监测意识、瞳孔与生命体征；防压疮血栓；记录发作与用药；心理安抚。","diet":"均衡营养；吞咽障碍者防误吸、必要时管饲。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1284},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"7248400af8cf939fe5a3fd9a949c428b12f7e90ae6fa59be8cd2e5bfab32b30f","pinyin":"weijizhi：zhongshushenjingxitonglangchuang（NPSLE）","initials":"wjz：zssjxtlc（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","认知障碍（最常见）、癫痫、精神行为异常、头痛；脊髓炎见截瘫、感觉平面、二便障碍；无菌性脑膜炎见头痛颈强；可有意识下降。",60],["摘要","识别要点：SLE患者新发癫痫、精神异常、横贯性脊髓炎、无菌性脑膜炎，须排除感染、代谢、药物与脑血管病后诊断。意义：为SLE最严重并发症之一，可致永久神经损伤，认知障碍最常见，需及早抢救。",30],["疾病编码","M32.1",30],["原首字母","weijizhi：zhongshushenjingxitonglangchuang（NPSLE）",60]]},{"id":"orders-952aa0421f5a23b482a6","key":"v1-c9ccc21dfe2a3058|orders-952aa0421f5a23b482a6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：风湿病相关快速进展性间质性肺病","category":"内科危急值","raw":{"name":"危急值：风湿病相关快速进展性间质性肺病","category":"内科危急值","summary":"识别要点：风湿病患者呼吸困难加重伴低氧（PaO₂<60mmHg或SpO₂<90%），HRCT示弥漫性间质性肺炎、机化性肺炎或弥漫性肺泡损伤。意义：CTD-ILD为风湿病主要死因之一，抗MDA5阳性皮肌炎RP-ILD病死率40%-60%，需紧急三联免疫抑制。","symptoms":["进行性呼吸困难、干咳、发热、乏力，重者静息低氧、发绀；皮肌炎伴皮疹肌无力，硬皮病伴皮肤硬化；咯血提示肺泡出血。"],"diagnosis":["血气分析明确低氧；HRCT判定病变模式；查肌炎抗体谱（尤其抗MDA5）与ANA/ENA谱确立基础病；肺功能、心超评估严重度；必要时支气管镜灌洗排除感染；与感染性肺炎、心衰鉴别。"],"infusion":["甲泼尼龙500-1000mg/d×3天冲击；环磷酰胺0.5-1g/m²每2-4周；难治/特定类型用利妥昔单抗或托珠单抗；输注监护生命体征与过敏。"],"oral_medication":["泼尼松（0.5-1mg/kg/d递减）；他克莫司0.05-0.15mg/kg/d；霉酚酸酯1.5-3g/d（SSc-ILD可联尼达尼布）；尼达尼布150mg bid或吡非尼酮；复方新诺明防PJP。"],"treatment":["甲泼尼龙500-1000mg/d冲击3天，继以泼尼松0.5-1mg/kg/d递减；抗MDA5阳性RP-ILD立即联合他克莫司0.05-0.15mg/kg/d（谷浓度5-15ng/mL）与环磷酰胺0.5-1g/m²（每2-4周×6）；难治/非MDA5加利妥昔单抗或托珠单抗；SSc-ILD早期联尼达尼布150mg bid（FVC下降≥5%启用）或吡非尼酮。剂量按CTD-ILD共识/指南执行；冲击期监护血压血糖电解质与感染；他克莫司监测浓度与肾功能。"],"management":["呼吸科或监护室协作：动态血气与SpO₂监测、呼吸支持阶梯递进（HFNC/无创至气管插管）；警惕感染、气胸、肺栓塞；缓解后复查肺功能与HRCT。"],"notes":["抗MDA5阳性RP-ILD进展极快，激素单药不足应尽早三联；强化免疫抑制前排除感染；尼达尼布注意肝功与腹泻。"],"emergency":["即刻纠正低氧：鼻导管→HFNC/无创通气，必要时气管插管机械通气；先留病原学再强化免疫抑制；抗MDA5阳性RP-ILD立即启动激素+他克莫司+环磷酰胺三联方案。"],"pinyin":"weijizhi：fengshibingxiangguankuaisujinzhanxingjianzhixingfeibing","icd10":"J99.1","physical_exam":"呼吸急促、三凹征、双肺底爆裂音、发绀；皮肌炎见Gottron丘疹与近端肌无力；硬皮病皮肤硬化、雷诺现象。","lab_tests":"动脉血气、HRCT、肺功能、肌炎抗体谱（抗MDA5等）、ANA/ENA、CK、炎症指标；痰/灌洗病原学；心超估肺动脉压。","nursing":"半卧位，监测SpO₂与血气趋势；氧疗/无创通气护理防滑脱；防感染、翻身拍背；记录出入量。","diet":"高蛋白易消化；呼吸窘迫者少量多餐；限钠水。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1285},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e27f3e7508eb975bbf474a24f8e7e21d6e8124cd334e2b4d7a5c1c493796a2ed","pinyin":"weijizhi：fengshibingxiangguankuaisujinzhanxingjianzhixingfeibing","initials":"wjz：fsbxgksjzxjzxfb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","进行性呼吸困难、干咳、发热、乏力，重者静息低氧、发绀；皮肌炎伴皮疹肌无力，硬皮病伴皮肤硬化；咯血提示肺泡出血。",60],["摘要","识别要点：风湿病患者呼吸困难加重伴低氧（PaO₂<60mmHg或SpO₂<90%），HRCT示弥漫性间质性肺炎、机化性肺炎或弥漫性肺泡损伤。意义：CTD-ILD为风湿病主要死因之一，抗MDA5阳性皮肌炎RP-ILD病死率40%-60%，需紧急三联免疫抑制。",30],["疾病编码","J99.1",30],["原首字母","weijizhi：fengshibingxiangguankuaisujinzhanxingjianzhixingfeibing",60]]},{"id":"orders-4a5201ea87551b364b50","key":"v1-c9ccc21dfe2a3058|orders-4a5201ea87551b364b50","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：Stevens-Johnson综合征/中毒性表皮坏死松解症","category":"内科危急值","raw":{"name":"危急值：Stevens-Johnson综合征/中毒性表皮坏死松解症","category":"内科危急值","summary":"识别要点：皮疹伴表皮松解剥脱及黏膜受累，体表剥脱≥10%入危象（SJS<10%、重叠10%-30%、TEN>30%），常伴高热。意义：最严重皮肤药物不良反应，死亡率10%-40%，SCORTEN>3分者>30%，须按烧伤重症处置。","symptoms":["前驱发热咽痛后现痛性红斑、水疱、Nikolsky征、大片表皮剥脱；口腔、眼、生殖器、呼吸道、消化道黏膜糜烂；可伴脱水、肝酶升高、心动过速。"],"diagnosis":["依皮疹形态、剥脱面积及黏膜受累分型（SJS/TEN/重叠）；SCORTEN评分（年龄、心率、血糖、碳酸氢盐、肌酐、剥脱面积等）估预后；皮肤活检见全层表皮坏死确诊；追问用药史（别嘌醇、卡马西平、苯妥英、磺胺类、NSAIDs）及HLA-B*15:02/58:01筛查。"],"infusion":["IVIG 2g/kg分3-5天缓慢输注；甲泼尼龙1-2mg/kg/d静脉；补液按烧伤公式并监测尿量电解质。"],"oral_medication":["环孢素A 3-5mg/kg/d（监测血压肾功能）；激素口服递减；镇痛药；口腔黏膜护理与局部抗生素眼膏。"],"treatment":["按指南权衡：进展期甲泼尼龙1-2mg/kg/d；早期足量IVIG 2g/kg分3-5天输注（阻断角质形成细胞凋亡，早用效好）；环孢素A 3-5mg/kg/d降低死亡风险。不主张系统预防性抗生素，创面按需抗感染并维护皮肤屏障；避免交叉致敏药物。"],"management":["单间/层流隔离：保温、无菌换药、防交叉感染，按需而非预防性用抗生素；每日评估创面与液体，复查血常规、肝肾功能、电解质、血糖；多学科随访后遗症。"],"notes":["常见致敏药：别嘌醇、卡马西平、苯妥英、磺胺类、NSAIDs；磺胺嘧啶银可交叉过敏应避免；IVIG越早越好；长期随访眼肺皮肤黏膜后遗症。"],"emergency":["立即停用全部可疑致敏药并记录名单；转烧伤科/ICU按烧伤原则：无菌操作、保温、创面护理（银离子敷料，避免磺胺嘧啶银交叉过敏）、按烧伤公式液体复苏、营养与镇痛；眼部即刻请眼科会诊。"],"pinyin":"weijizhi：Stevens-Johnsonzonghezheng/zhongduxingbiaopihuaisisongjiezheng","icd10":"L51.2","physical_exam":"弥漫痛性红斑、水疱大疱、Nikolsky征、表皮剥脱面（估体表%）、口眼生殖器黏膜糜烂、发热、心动过速、脱水貌。","lab_tests":"血常规、CRP、肝肾功能、电解质、血糖；皮肤活检病理；创面病原学；HLA-B*15:02/58:01筛查。","nursing":"接触隔离无菌操作；换药防粘连，眼睑结膜囊每日分离涂药；疼痛评估镇痛；记录出入量、体温与剥脱面积；心理支持。","diet":"高热量高蛋白；口腔糜烂者流质或半流质，必要时肠内营养。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1286},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"28d86785cceb72e0ea63ad62a7e7ba4b59ab011da2814d82123c602698fb978b","pinyin":"weijizhi：Stevens-Johnsonzonghezheng/zhongduxingbiaopihuaisisongjiezheng","initials":"wjz：zhz/zdxbphssjz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","前驱发热咽痛后现痛性红斑、水疱、Nikolsky征、大片表皮剥脱；口腔、眼、生殖器、呼吸道、消化道黏膜糜烂；可伴脱水、肝酶升高、心动过速。",60],["摘要","识别要点：皮疹伴表皮松解剥脱及黏膜受累，体表剥脱≥10%入危象（SJS<10%、重叠10%-30%、TEN>30%），常伴高热。意义：最严重皮肤药物不良反应，死亡率10%-40%，SCORTEN>3分者>30%，须按烧伤重症处置。",30],["疾病编码","L51.2",30],["原首字母","weijizhi：Stevens-Johnsonzonghezheng/zhongduxingbiaopihuaisisongjiezheng",60]]},{"id":"orders-8fe95a07a05ec7fc8311","key":"v1-c9ccc21dfe2a3058|orders-8fe95a07a05ec7fc8311","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：ANCA相关性血管炎危象","category":"内科危急值","raw":{"name":"危急值：ANCA相关性血管炎危象","category":"内科危急值","summary":"识别要点：GPA/MPA/EGPA等ANCA相关血管炎出现肾脏急进性损害（SCr迅速升高、活动性尿沉渣、新月体肾炎）或肺泡出血（咯血、弥漫浸润、Hb下降）即属危象。意义：急进性肾炎数周可进展至终末期肾病，肺泡出血死亡率高，需紧急诱导缓解。","symptoms":["咯血、呼吸困难、发热、乏力；肾受累见血尿、蛋白尿、少尿、水肿、高血压；GPA可伴鼻窦炎、肺结节或空洞，EGPA伴哮喘及嗜酸性粒细胞增高。"],"diagnosis":["查ANCA亚型（PR3/MPO）；尿沉渣、SCr与eGFR；肾受累行肾活检示寡免疫复合物新月体肾炎；疑肺泡出血行HRCT与支气管镜灌洗（血性渐深），查抗GBM排除抗基底膜病；排除感染。"],"infusion":["甲泼尼龙冲击3天；环磷酰胺按CrCl调量静脉；利妥昔单抗375mg/m²/周×4（维持500mg q6m）；重症血浆置换连做5-7次。"],"oral_medication":["泼尼松（1mg/kg/d后递减至≤5-7.5mg/d）；维持期硫唑嘌呤2mg/kg/d；复方新诺明防PJP；ACEI/ARB；激素期补钙、维生素D、护胃。"],"treatment":["诱导缓解：甲泼尼龙500-1000mg/d冲击3天，继以泼尼松1mg/kg/d递减至≤5-7.5mg/d；环磷酰胺按年龄与CrCl调量，或以利妥昔单抗375mg/m²/周×4替代；缓解后维持硫唑嘌呤2mg/kg/d或利妥昔单抗500mg q6m；剂量按ANCA血管炎管理指南执行；环磷酰胺防骨髓抑制、出血性膀胱炎与感染。"],"management":["肾/呼吸/监护室协作：每日血气、肾功能、电解质，记录咯血与尿量；警惕免疫抑制期感染与血栓；缓解后随访ANCA滴度与肾功能，缓慢减激素。"],"notes":["肺泡出血须呼吸支持+血浆置换抢时间；急进性肾炎尽早诱导缓解是保肾关键；缓解后维持治疗不可缺。"],"emergency":["脏器危象立即诱导缓解：肺泡出血先呼吸支持（必要时气管插管、保护性通气）并尽早血浆置换（连做5-7次）；SCr>500μmol/L需透析、肺泡出血或抗GBM阳性均为血浆置换指征；同步大剂量激素冲击+环磷酰胺或利妥昔单抗。"],"pinyin":"weijizhi：ANCAxiangguanxingxueguanyanweixiang","icd10":"M31.3（GPA）/M31.7（MPA）/M30.1（EGPA）","physical_exam":"发热、肺部啰音或实变、咯血、血尿、水肿、高血压、皮肤紫癜或坏死溃疡。","lab_tests":"ANCA（PR3/MPO）、尿沉渣、SCr/eGFR、血常规及Hb动态、CRP/ESR、痰与灌洗病原学；肾活检、HRCT、抗GBM抗体。","nursing":"咯血者头偏一侧防窒息并备吸引；透析者管路护理；记录出入量、尿量、咯血量；免疫抑制期防感染。","diet":"肾衰水肿者低盐限水、按肾功能调蛋白。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1287},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f2ed176488e0c147773355e286b49e5aa27eba20abd33565b77c15b72ec6ef3f","pinyin":"weijizhi：ANCAxiangguanxingxueguanyanweixiang","initials":"wjz：xgxxgywx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咯血、呼吸困难、发热、乏力；肾受累见血尿、蛋白尿、少尿、水肿、高血压；GPA可伴鼻窦炎、肺结节或空洞，EGPA伴哮喘及嗜酸性粒细胞增高。",60],["摘要","识别要点：GPA/MPA/EGPA等ANCA相关血管炎出现肾脏急进性损害（SCr迅速升高、活动性尿沉渣、新月体肾炎）或肺泡出血（咯血、弥漫浸润、Hb下降）即属危象。意义：急进性肾炎数周可进展至终末期肾病，肺泡出血死亡率高，需紧急诱导缓解。",30],["疾病编码","M31.3（GPA）/M31.7（MPA）/M30.1（EGPA）",30],["原首字母","weijizhi：ANCAxiangguanxingxueguanyanweixiang",60]]},{"id":"orders-b158688aa407179ec735","key":"v1-c9ccc21dfe2a3058|orders-b158688aa407179ec735","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：巨噬细胞活化综合征","category":"内科危急值","raw":{"name":"危急值：巨噬细胞活化综合征","category":"内科危急值","summary":"识别要点：风湿病（sJIA、SLE、成人Still病）基础上持续高热、铁蛋白显著升高（常>10000ng/mL）、≥2系血细胞减少、肝损、脾大，伴sCD25升高、NK活性下降。意义：属继发性HLH，死亡率20%-30%，核心为细胞因子风暴，须按更新标准及早抢救。","symptoms":["弛张或稽留高热不退、肝脾及淋巴结肿大、皮疹；贫血、出血倾向；肝功异常、黄疸、低纤维蛋白原；重症见DIC样凝血障碍、抽搐。"],"diagnosis":["按2025更新分类标准：铁蛋白动态升高（>10000高度提示）、≥2系血细胞减少、肝功异常、甘油三酯升高、纤维蛋白原降低、sCD25升高、NK活性下降；骨髓涂片见噬血现象支持；排除感染相关HLH、败血症、血液肿瘤。"],"infusion":["甲泼尼龙30mg/kg/d（≤1g）静脉脉冲3天；依托泊苷150mg/m²/d×3天（难治，参照HLH-94）；托珠单抗静脉（备选）；输注监护血压、心律与过敏。"],"oral_medication":["环孢素A 2-7mg/kg/d分次口服（维持浓度200-300ng/mL）；激素口服递减衔接；护胃补钙；抗生素按药敏选用。"],"treatment":["甲泼尼龙30mg/kg/d脉冲3天（每日≤1g）→2mg/kg/d静脉→口服递减；环孢素A 2-7mg/kg/d维持谷浓度200-300ng/mL；IL-1靶向：阿那白滞素5-10mg/kg/d皮下（sJIA-MAS首选，起效快、降死亡率）或卡那单抗4mg/kg皮下q4w；难治者用依托泊苷150mg/m²/d×3天或托珠单抗。剂量按MAS国际共识执行；监测骨髓抑制、肝肾毒性及感染。"],"management":["监护室管理：动态监测铁蛋白、血常规、肝肾功能、凝血与甘油三酯评估疗效；按需成分输血；经验性抗感染并追踪培养；警惕DIC、肝衰与中枢受累；治疗原发病防复发。"],"notes":["MAS凶险，易误诊为感染或肝衰竭；铁蛋白动态升高是最实用预警；激素单药常不足，尽早加环孢素与IL-1抑制剂。"],"emergency":["疑诊即启动：甲泼尼龙30mg/kg/d脉冲3天（最大1g/d），继以2mg/kg/d静脉后口服递减；尽早联用环孢素A；sJIA-MAS首选阿那白滞素皮下；发热时经验性抗生素并送培养；按需成分输血与器官支持。"],"pinyin":"weijizhi：jushixibaohuohuazonghezheng","icd10":"D76.1","physical_exam":"持续高热、肝脾淋巴结肿大、皮疹、出血点瘀斑、黄疸；意识障碍或抽搐提示中枢受累。","lab_tests":"铁蛋白（动态）、血常规、肝功能、甘油三酯、纤维蛋白原、sCD25、NK活性、CRP/ESR、凝血；骨髓涂片（噬血细胞）。","nursing":"高热物理降温与补液；观察出血倾向与神志；接触防护防感染；记录出入量与体重；输血护理。","diet":"高热量易消化；肝损者低脂；保证液体。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1288},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"484e5697bcb921dbc822e1043d9a91baf5ffb7d37c56cc846a52619e846f3697","pinyin":"weijizhi：jushixibaohuohuazonghezheng","initials":"wjz：jsxbhhzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","弛张或稽留高热不退、肝脾及淋巴结肿大、皮疹；贫血、出血倾向；肝功异常、黄疸、低纤维蛋白原；重症见DIC样凝血障碍、抽搐。",60],["摘要","识别要点：风湿病（sJIA、SLE、成人Still病）基础上持续高热、铁蛋白显著升高（常>10000ng/mL）、≥2系血细胞减少、肝损、脾大，伴sCD25升高、NK活性下降。意义：属继发性HLH，死亡率20%-30%，核心为细胞因子风暴，须按更新标准及早抢救。",30],["疾病编码","D76.1",30],["原首字母","weijizhi：jushixibaohuohuazonghezheng",60]]},{"id":"orders-14df597007b8e6b30e3b","key":"v1-c9ccc21dfe2a3058|orders-14df597007b8e6b30e3b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：甲状腺危象","category":"内科危急值","raw":{"name":"危急值：甲状腺危象","category":"内科危急值","summary":"危急识别：BWPS评分≥45分即确诊甲状腺危象；或符合JTA标准（甲亢+高热≥38℃+心动过速≥130次/分+CNS表现+心衰或胃肠/肝表现）。临床意义：最凶险的内分泌急症之一，死亡率10%–30%，诊断依赖临床，不可等待甲功结果延误治疗；诱因以感染最常见。","symptoms":["高热≥38℃、大汗、心动过速≥130次/分、烦躁、震颤、谵妄至昏迷；可伴恶心呕吐、腹泻、黄疸及心悸、心衰等表现。"],"diagnosis":["临床诊断为主：BWPS≥45分或JTA标准具备即诊断，勿等甲功结果。支持检查：TSH降低、FT₃/FT₄升高；血常规、电解质、血糖、肝功能；疑感染送血培养。"],"infusion":["静脉补液维持水电解质与血糖。血流动力学不稳定者：艾司洛尔0.5mg/kg静注负荷后0.05–0.2mg/kg/min泵入；不能口服碘剂时予碘化钠1g静滴q8–12h。剂量按说明书/指南调整。"],"oral_medication":["丙硫氧嘧啶（PTU）600–1000mg口服/鼻饲负荷→200–250mg q4h；或甲巯咪唑20–30mg q4–6h。抗甲状腺药后1h给碘剂：复方碘溶液（Lugol's）4–8滴q6–8h或SSKI 5滴q6h。普萘洛尔60–80mg po q4–6h；对乙酰氨基酚500–1000mg q4–6h退热。剂量按说明书/指南调整。"],"treatment":["序贯抢救：①抑制合成：PTU负荷后维持或甲巯咪唑；②抑制释放：抗甲状腺药后≥1h才给碘剂（过早给药Jod-Basedow效应反增激素合成）；③控制交感：首选普萘洛尔，血流动力学不稳者用艾司洛尔（0.5mg/kg负荷后泵入），哮喘/心衰等禁忌者用地尔硫卓/维拉帕米；④氢化可的松100mg静注q8h或地塞米松2mg静注q6h，连用3–5天；⑤退热支持：物理降温为主，对乙酰氨基酚辅助，禁用阿司匹林；⑥顽固或伴意识障碍者：考来烯胺、血浆置换，药物无效且危及生命时紧急甲状腺切除。剂量按说明书/指南调整。"],"management":["ICU监护生命体征、心率心律、意识、体温与心功能；查找并处理诱因，感染最常见，行血培养并予广谱抗生素。"],"notes":["诊断勿等甲功结果；禁用阿司匹林退热；碘剂须在抗甲状腺药后1h以上给予，避免Jod-Basedow效应；对乙酰氨基酚注意肝毒性。"],"emergency":["确诊即抢救：PTU负荷→间隔1h后碘剂→普萘洛尔（或艾司洛尔）→氢化可的松100mg静注q8h→物理降温；恶化时血浆置换或紧急甲状腺切除术。"],"pinyin":"weijizhi：jiazhuangxianweixiang","icd10":"E05.5","physical_exam":"高热、皮肤湿热大汗、心动过速；手细颤、腱反射亢进；甲状腺肿大可伴血管杂音；心衰者肺部湿啰音、下肢水肿。","lab_tests":"甲状腺功能（TSH、FT₃、FT₄）；血常规、电解质、血糖、肝功能、血气；心电图、胸片；疑感染送血/尿培养。","nursing":"持续心电与生命体征监护；按序给药并记录（抗甲状腺药→间隔1h后碘剂）；物理降温防寒战；监测意识与出入量；鼻饲给药防误吸；口腔皮肤护理。","diet":"高热量、高蛋白、高维生素饮食，保证饮水；不能进食者静脉营养；避免含碘食物及浓茶、咖啡等兴奋饮品。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1289},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a1ebf82a4d0afbdf091818aa6e4b5fa77f2668d3687d0441c32c1982cdf5db38","pinyin":"weijizhi：jiazhuangxianweixiang","initials":"wjz：jzxwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","高热≥38℃、大汗、心动过速≥130次/分、烦躁、震颤、谵妄至昏迷；可伴恶心呕吐、腹泻、黄疸及心悸、心衰等表现。",60],["摘要","危急识别：BWPS评分≥45分即确诊甲状腺危象；或符合JTA标准（甲亢+高热≥38℃+心动过速≥130次/分+CNS表现+心衰或胃肠/肝表现）。临床意义：最凶险的内分泌急症之一，死亡率10%–30%，诊断依赖临床，不可等待甲功结果延误治疗；诱因以感染最常见。",30],["疾病编码","E05.5",30],["原首字母","weijizhi：jiazhuangxianweixiang",60]]},{"id":"orders-ceb33345417aabc1a579","key":"v1-c9ccc21dfe2a3058|orders-ceb33345417aabc1a579","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：黏液性水肿昏迷","category":"内科危急值","raw":{"name":"危急值：黏液性水肿昏迷","category":"内科危急值","summary":"危急识别：严重甲减（TSH升高、FT₄降低）基础上出现低体温（<35℃）伴意识障碍或意识水平下降，多有感染、寒冷、药物、创伤等诱因。临床意义：甲减最致命并发症，死亡率20%–60%；核心原则——氢化可的松必须先于甲状腺素（约50%合并肾上腺皮质功能不全，单补甲状腺素可诱发肾上腺危象）。","symptoms":["进行性嗜睡、反应迟钝至昏迷；低体温<35℃；黏液水肿面容、皮肤干冷、非凹陷性水肿；心动过缓、低血压；可伴低钠血症、低血糖、CO₂潴留。"],"diagnosis":["临床诊断：甲减表现+低体温+意识障碍+诱因即高度疑诊，治疗勿等实验室结果。实验室支持：TSH升高、FT₄降低；血气示低氧/高碳酸血症；可有低钠、低血糖；心电图示心动过缓、低电压、QT延长。"],"infusion":["等渗晶体液约3–4L补液，监测心功能防容量过负荷，老年及心衰者酌情减量；低血糖者静脉补糖。具体量按说明书/指南调整。"],"oral_medication":["待可口服后过渡至左甲状腺素口服维持；老年或冠心病者小剂量起始、缓慢加量以防心脏事件，方案按说明书/指南个体化。"],"treatment":["①最关键：给甲状腺素前先予氢化可的松100mg静注首剂→100mg静注q8h，直至排除肾上腺皮质功能不全；②左甲状腺素200–400μg静注负荷→50–100μg静注qd；重症且预计恢复慢者加T₃ 5–20μg静注负荷→2.5–10μg静注q8h（起效快但心脏风险更高）；老年/冠心病减量；③支持：气道评估（GCS<7或PaCO₂>50mmHg考虑插管，注意插管困难）、被动复温（禁用主动复温）、补液、经验性广谱抗生素、停用中枢抑制药、连续心电监护。剂量按说明书/指南调整。"],"management":["ICU监护：连续心电（QT延长、室速、房颤高发）；以体温回升、意识好转为临床改善指标；TSH与游离T₄每1–2日复查；治疗感染等诱因。"],"notes":["糖皮质激素必须先于甲状腺素，否则诱发肾上腺危象；禁用主动复温（外周血管扩张致循环衰竭）；中枢抑制药易蓄积中毒应停用；插管困难，由经验丰富者操作。"],"emergency":["立即氢化可的松100mg静注首剂，随后左甲状腺素200–400μg静注负荷并按日维持，必要时加T₃；同时气道保护、被动复温、纠正低血糖低钠、经验性抗感染。"],"pinyin":"weijizhi：nianyexingshuizhonghunmi","icd10":"E03.5","physical_exam":"低体温（<35℃）、心动过缓、低血压；黏液水肿面容、皮肤干燥粗糙、非凹陷性水肿、毛发稀疏、腱反射迟缓；反应迟钝至昏迷。","lab_tests":"甲状腺功能（TSH、FT₄，治疗前留取）；动脉血气；电解质（尤其血钠）、血糖；心电图；胸片及血培养查找感染诱因。","nursing":"被动复温护理（加盖被褥/暖毯、提高室温），严禁热水袋等主动复温；持续监测体温、意识、心电与生命体征；气道吸痰护理并备插管预案；记录出入量防容量过负荷；皮肤护理防压疮。","diet":"昏迷期禁食，予肠内或肠外营养；恢复进食后高蛋白、易消化饮食，入液量依心功能调整；按甲状腺素方案管理碘摄入。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1290},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"565a0b9e515d74dc58080e3a8ef6f39dbdd2684f4072e303b49134de38941bbc","pinyin":"weijizhi：nianyexingshuizhonghunmi","initials":"wjz：nyxszhm","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","进行性嗜睡、反应迟钝至昏迷；低体温<35℃；黏液水肿面容、皮肤干冷、非凹陷性水肿；心动过缓、低血压；可伴低钠血症、低血糖、CO₂潴留。",60],["摘要","危急识别：严重甲减（TSH升高、FT₄降低）基础上出现低体温（<35℃）伴意识障碍或意识水平下降，多有感染、寒冷、药物、创伤等诱因。临床意义：甲减最致命并发症，死亡率20%–60%；核心原则——氢化可的松必须先于甲状腺素（约50%合并肾上腺皮质功能不全，单补甲状腺素可诱发肾上腺危象）。",30],["疾病编码","E03.5",30],["原首字母","weijizhi：nianyexingshuizhonghunmi",60]]},{"id":"orders-5753607a149da52ed625","key":"v1-c9ccc21dfe2a3058|orders-5753607a149da52ed625","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：肾上腺危象","category":"内科危急值","raw":{"name":"危急值：肾上腺危象","category":"内科危急值","summary":"危急识别：Addison病或继发性肾上腺皮质功能不全患者，在感染（最常见）、手术创伤、停用激素等应激下出现低血压休克（对升压药反应差）、低钠血症、高钾血症。临床意义：致命并发症，延迟治疗死亡率极高；停用激素是最常见可避免诱因；疑诊即抢救，勿等生化结果。","symptoms":["低血压至休克、乏力、恶心呕吐、厌食、腹痛；发热或低体温；低血糖表现（出汗、心慌、意识改变）；原发者皮肤黏膜色素沉着。"],"diagnosis":["临床诊断：基础病+应激诱因+低血压/休克即应疑诊并立即治疗。生化三联：低钠、高钾、低血糖；皮质醇低、ACTH高提示原发；条件允许行快速ACTH兴奋试验，并排查感染等诱因。"],"infusion":["氢化可的松100mg静注首剂→100mg静注q6–8h；0.9%氯化钠快速补液：首1小时1000ml，第2–3小时再1000ml，首日总量2000–3000ml；低血糖加5%GS，重度者50%GS 20–40ml静注。量按说明书/指南调整。"],"oral_medication":["稳定后过渡：第2天氢化可的松50mg静注q6–8h，第3天起每日减约50%，至口服维持量20–30mg/d分次（早2/3、午后1/3）；血压/血钠仍低者加氟氢可的松0.05–0.1mg/d口服。剂量按说明书/指南调整。"],"treatment":["①立即激素替代：氢化可的松100mg静注（缓慢推注）→100mg静注q6–8h，首日总量300–400mg；②0.9%氯化钠快速补液，首日2000–3000ml；③低血糖予50%GS 20–40ml静注，高钾按规范处理；④稳定24–48h后阶梯减量过渡口服；⑤治诱因：感染→血/尿培养+胸片+广谱抗生素；出血/创伤→止血、手术评估；停激素→重审方案。剂量按说明书/指南调整。"],"management":["心电血压监护，纠正休克与电解质紊乱；稳定后评估HPA轴功能，制定长期替代及应激剂量方案；宣教随身携带急救卡/医疗警示手环。"],"notes":["勿等生化结果；对升压药反应差的休克须想到本病；首日大剂量氢化可的松已具盐皮质作用，氟氢可的松按血压/血钠加用；低血糖补糖同时必须给激素；警惕Waterhouse-Friderichsen综合征。"],"emergency":["氢化可的松100mg静注→100mg静注q6–8h；同步0.9%氯化钠快速扩容（首小时1000ml）；重度低血糖50%GS 20–40ml静注。"],"pinyin":"weijizhi：shenshangxianweixiang","icd10":"E27.2","physical_exam":"低血压/休克、皮肤黏膜色素沉着（掌纹、乳晕、口腔黏膜）、脱水貌、发热或低体温、心动过速；可腹痛压痛。","lab_tests":"电解质（低钠、高钾）、血糖、肾功能、血气；血/尿皮质醇、ACTH；心电图（高钾改变）；血/尿培养、胸片。","nursing":"休克护理：平卧、保暖、持续心电血压监测；按序执行激素—补液—补糖；记录出入量防过负荷；宣教识别前驱症状、随身急救卡/警示手环、应激剂量原则（发热<39℃激素加倍，手术创伤予50–100mg/d或住院），禁擅自停药。","diet":"急性期呕吐明显者暂禁食补液；稳定后高盐、均衡饮食并保证水分；原发者避免低盐饮食；血糖不稳者规律进餐防低血糖。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1291},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"57d3abea8e843680fa89626439cf840bfd58658bf40d5e521f428ecbe591d468","pinyin":"weijizhi：shenshangxianweixiang","initials":"wjz：ssxwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","低血压至休克、乏力、恶心呕吐、厌食、腹痛；发热或低体温；低血糖表现（出汗、心慌、意识改变）；原发者皮肤黏膜色素沉着。",60],["摘要","危急识别：Addison病或继发性肾上腺皮质功能不全患者，在感染（最常见）、手术创伤、停用激素等应激下出现低血压休克（对升压药反应差）、低钠血症、高钾血症。临床意义：致命并发症，延迟治疗死亡率极高；停用激素是最常见可避免诱因；疑诊即抢救，勿等生化结果。",30],["疾病编码","E27.2",30],["原首字母","weijizhi：shenshangxianweixiang",60]]},{"id":"orders-51bf47a233b42a62b45a","key":"v1-c9ccc21dfe2a3058|orders-51bf47a233b42a62b45a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：垂体卒中/垂体危象","category":"内科危急值","raw":{"name":"危急值：垂体卒中/垂体危象","category":"内科危急值","summary":"危急识别：突发剧烈头痛（常伴恶心呕吐）+视力视野障碍（双颞侧偏盲）+眼肌麻痹（动眼神经最常受累），鞍区MRI示垂体腺瘤出血/梗死即可诊断。临床意义：垂体大腺瘤出血或梗死所致内分泌急症，可致永久性视力丧失和全垂体功能减退（垂体危象），多见于无功能大腺瘤；需评估紧急手术减压，并先以糖皮质激素覆盖预防肾上腺危象。","symptoms":["突发剧烈头痛、恶心呕吐；视力下降、双颞侧偏盲；复视、眼球运动受限；可有意识障碍、脑膜刺激征；肾上腺轴受累见低血压低血糖，后叶受累见多尿。"],"diagnosis":["三联表现（突发头痛+视力视野障碍+眼肌麻痹）高度提示；鞍区MRI平扫+增强示垂体腺瘤出血/梗死为金标准；同时评估垂体各轴功能及水电解质，筛查尿崩。"],"infusion":["氢化可的松100mg静注首剂后100mg静注q8h（或等剂量其他糖皮质激素）；合并低血压/低钠者以0.9%氯化钠等渗补液，量据监测及指南/说明书个体化调整。"],"oral_medication":["保守治疗或术后据垂体功能评估结果个体化替代（氢化可的松口服维持量、左甲状腺素等），由内分泌专科随访调整；急性期以静脉糖皮质激素为主。"],"treatment":["①立即糖皮质激素覆盖（关键，防肾上腺危象）：氢化可的松100mg静注→100mg静注q8h；②眼科紧急会诊评估视力视野；③鞍区MRI平扫+增强；④神经外科会诊：明显视交叉/视神经压迫且症状持续加重者首选经蝶手术（争取24–48h内减压）；无视力障碍或轻度缺损且稳定者保守（激素替代+密切观察+影像随访）；⑤稳定后全面评估垂体各轴及后叶功能；⑥个体化长期激素替代。剂量按说明书/指南调整。"],"management":["神经外科、眼科、内分泌科协同管理；密切监测视力视野、瞳孔、意识、生命体征与电解质（防尿崩/低钠）；经蝶术后注意脑脊液鼻漏、尿崩；糖皮质激素覆盖贯穿全程。"],"notes":["激素覆盖是影像检查、手术等一切处理的前提；进行性视力下降或视野缺损者应尽快手术减压；勿漏评后叶（尿崩）与肾上腺轴功能；剧烈头痛需与动脉瘤破裂、脑膜炎等鉴别。"],"emergency":["疑诊即予氢化可的松100mg静注并q8h维持，稳定血压血糖；立即眼科评估视力视野并行鞍区MRI；有视神经压迫证据者尽快神经外科会诊，24–48h内经蝶手术减压。"],"pinyin":"weijizhi：chuitizuzhong/chuitiweixiang","icd10":"E23.6","physical_exam":"视力下降、双颞侧偏盲（床旁粗测视野）；眼球运动受限/复视（动眼神经麻痹）；可有颈抵抗等脑膜刺激征；低血压、心动过速提示垂体-肾上腺轴受累。","lab_tests":"鞍区MRI平扫+增强（金标准）；皮质醇、ACTH、TSH、FT₄、LH/FSH、泌乳素、GH/IGF-1（视病情择期）；电解质、血糖；尿量及尿比重筛查尿崩；血常规。","nursing":"神经外科重症监护：监测视力、视野、瞳孔与意识；记录出入量与尿量，监测电解质防尿崩/低钠；按时给予糖皮质激素不中断；经蝶术后观察脑脊液鼻漏、鼻出血并防感染。","diet":"急性期呕吐明显者禁食或流质防误吸；稳定后均衡饮食；按尿量与电解质个体化调整钠水摄入（尿崩者保证饮水，低钠者按医嘱管理入液量）。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1292},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c55977a373ae75b85c5aa84dc114b15158c946984ae9e916773f0f779f3c2c5c","pinyin":"weijizhi：chuitizuzhong/chuitiweixiang","initials":"wjz：ctzz/ctwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发剧烈头痛、恶心呕吐；视力下降、双颞侧偏盲；复视、眼球运动受限；可有意识障碍、脑膜刺激征；肾上腺轴受累见低血压低血糖，后叶受累见多尿。",60],["摘要","危急识别：突发剧烈头痛（常伴恶心呕吐）+视力视野障碍（双颞侧偏盲）+眼肌麻痹（动眼神经最常受累），鞍区MRI示垂体腺瘤出血/梗死即可诊断。临床意义：垂体大腺瘤出血或梗死所致内分泌急症，可致永久性视力丧失和全垂体功能减退（垂体危象），多见于无功能大腺瘤；需评估紧急手术减压，并先以糖皮质激素覆盖预防肾上腺危象。",30],["疾病编码","E23.6",30],["原首字母","weijizhi：chuitizuzhong/chuitiweixiang",60]]},{"id":"orders-cc19f54cfca7a1e33618","key":"v1-c9ccc21dfe2a3058|orders-cc19f54cfca7a1e33618","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：脓毒性休克","category":"内科危急值","raw":{"name":"危急值：脓毒性休克","category":"内科危急值","summary":"感染或疑似感染，序贯器官衰竭评估SOFA较基线升高≥2分即脓毒症；充分液体复苏后仍需血管活性药维持MAP≥65mmHg且乳酸>2mmol/L为脓毒性休克。脓毒症是危重症死亡的首要原因，延迟有效抗感染治疗显著增加病死率，须按1小时集束化方案即刻干预。","symptoms":["发热或体温过低、寒战、呼吸急促、心率增快、意识改变（烦躁/嗜睡/昏迷）、少尿、四肢湿冷、皮肤花斑、低血压、毛细血管再充盈时间延长。"],"diagnosis":["感染存在+SOFA≥2分（呼吸、凝血、肝、循环、神经、肾各域计分）；休克=充分液体复苏后仍需血管活性药维持MAP≥65mmHg且乳酸>2mmol/L。筛查可用qSOFA≥2分（呼吸≥22次/分、意识改变、收缩压≤100mmHg）或NEWS2/MEWS。"],"infusion":["1小时内完成：①用药前双部位血培养+乳酸+PCT；②经验性广谱抗生素，β-内酰胺类延长输注（如哌拉西林/他唑巴坦4.5g IV q6-8h或头孢吡肟2g IV q8h，按感染灶及MRSA风险联合万古霉素）；③低血压或乳酸≥4mmol/L者予平衡晶体液30ml/kg（首3h内，颅脑损伤除外）；④去甲肾上腺素泵入维持MAP≥65mmHg，老年患者可个体化降至60-65mmHg。"],"oral_medication":["暂无"],"treatment":["培养药敏回报后降阶梯治疗；以PCT动态变化联合临床评估决定停药时机；以乳酸清除率、毛细血管再充盈时间指导复苏终点；持续依赖升压药者可加用氢化可的松200mg/d静滴（不常规）；重度酸中毒pH<7.15可考虑碳酸氢钠；不推荐常规使用维生素C、免疫球蛋白及血液净化。"],"management":["收入ICU持续监护；采用动态血流动力学评估（被动抬腿试验/每搏变异度）优于静态指标；每2-4小时复查乳酸；积极处理感染源（引流、拔除导管）并按灶复查培养；监测凝血、肝肾功能、血糖与出入量。"],"notes":["每延迟1小时有效抗生素，病死率约增加7.6%，采血培养不应延误用药；仅腹腔、妇科或坏死性感染等高危情况需经验性抗厌氧菌覆盖。"],"emergency":["识别即触发脓毒症快速反应：1小时内完成血培养、广谱抗生素、晶体液30ml/kg复苏及升压药，维持MAP≥65mmHg并复查乳酸。"],"pinyin":"weijizhi：nongduxingxiuke","icd10":"R57.2","physical_exam":"体温、心率、呼吸、血压、SpO2、意识（GCS）、皮肤黏膜（花斑、瘀点、穿刺点）、肺部啰音、腹部体征、末梢灌注与尿量。","lab_tests":"血常规、CRP、PCT、乳酸（动态复查）、血培养×2套（用药前）、血气分析、凝血功能、肝肾功能、电解质、血糖；按感染灶加查尿、痰、引流液等培养。","nursing":"持续心电、血压、血氧及尿量监测；记录出入量；防寒战保暖；升压药经中心或粗大静脉输注防外渗；加强导管与口腔护理降低院内感染；按时采血复查。","diet":"病情允许后尽早肠内营养（高蛋白、易消化），监测血糖；禁食期予静脉营养并维持水电解质平衡。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1293},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9dd704fc77292663d5087de1b4564ddfe6ebb279b639dd3a1c200899272633ec","pinyin":"weijizhi：nongduxingxiuke","initials":"wjz：ndxxk","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热或体温过低、寒战、呼吸急促、心率增快、意识改变（烦躁/嗜睡/昏迷）、少尿、四肢湿冷、皮肤花斑、低血压、毛细血管再充盈时间延长。",60],["摘要","感染或疑似感染，序贯器官衰竭评估SOFA较基线升高≥2分即脓毒症；充分液体复苏后仍需血管活性药维持MAP≥65mmHg且乳酸>2mmol/L为脓毒性休克。脓毒症是危重症死亡的首要原因，延迟有效抗感染治疗显著增加病死率，须按1小时集束化方案即刻干预。",30],["疾病编码","R57.2",30],["原首字母","weijizhi：nongduxingxiuke",60]]},{"id":"orders-f163837be797d1b2ff0e","key":"v1-c9ccc21dfe2a3058|orders-f163837be797d1b2ff0e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：化脓性脑膜炎（急性细菌性脑膜炎）","category":"内科危急值","raw":{"name":"危急值：化脓性脑膜炎（急性细菌性脑膜炎）","category":"内科危急值","summary":"脑脊液白细胞显著升高（>1000×10⁶/L，中性粒细胞为主）、糖降低（<2.2mmol/L或CSF糖/血糖<0.4）、蛋白升高（>0.45g/L）伴病原学或培养阳性。细菌性脑膜炎是感染科最凶险的急症之一，可在数小时内进展至昏迷、脑疝甚至死亡；即使及时治疗病死率仍达10%-30%，约30%幸存者遗留听力下降、认知障碍等后遗症。","symptoms":["高热、剧烈头痛、喷射性呕吐、颈强直、畏光、意识障碍与惊厥；婴幼儿表现为拒食、易激惹、前囟饱满；脑膜炎球菌感染可见瘀点瘀斑。"],"diagnosis":["头颅CT排除占位性病变后尽早腰穿：CSF中性粒细胞为主+糖降低+蛋白升高即高度提示细菌性，革兰涂片、培养明确病原；同步抽血培养与血糖，CSF糖需与同步血糖比较；培养前已用抗生素者可加PCR等分子检测。"],"infusion":["经验性抗生素首剂置于腰穿后30分钟内或腰穿前，不可延误：头孢曲松2g IV q12h（或头孢噻肟2g IV q4-6h）+万古霉素15-20mg/kg IV q8-12h；地塞米松10mg IV q6h，首剂在抗生素之前或同时给予，连用4天；颅内压升高时予甘露醇0.5-1g/kg快速静滴。"],"oral_medication":["脑膜炎球菌密切接触者预防：利福平600mg po q12h×2天，或环丙沙星500mg单次口服。"],"treatment":["年龄≥50岁、免疫抑制或酗酒者加氨苄西林2g IV q4h以覆盖李斯特菌；培养药敏回报后降阶梯并据病原确定疗程（脑膜炎球菌7天、肺炎链球菌10-14天、李斯特菌≥21天）；高度怀疑脑膜炎球菌者在病原明确前持续隔离并加强支持治疗。"],"management":["控制高热、惊厥，纠正水电解质紊乱；严密监测意识与瞳孔，顽固高颅压或脑积水请神经外科会诊（脑室外引流EVD）；病原未明前行飞沫+接触隔离；确诊脑膜炎球菌后上报疾控并安排接触者预防用药。"],"notes":["糖皮质激素对肺炎链球菌性脑膜炎获益最明确，首剂必须早于或同时于抗生素给药方有效；免疫缺陷、颅脑手术等背景患者需注意覆盖少见病原。"],"emergency":["疑似即抽血培养并尽快腰穿，首剂头孢曲松+万古霉素+地塞米松不得因检查流程而延误。"],"pinyin":"weijizhi：huanongxingnaomoyan（jixingxijunxingnaomoyan）","icd10":"G00.9","physical_exam":"生命体征、意识（GCS）、颈抵抗、Kernig征/Brudzinski征、瞳孔与眼底（视乳头水肿）、皮肤瘀点瘀斑、局灶神经体征、婴幼儿前囟张力。","lab_tests":"CSF常规（细胞数及分类）、糖与蛋白及同步血糖、革兰涂片、细菌培养；血培养、血常规、CRP/PCT、凝血功能；头颅CT/MRI。","nursing":"严密监测意识、瞳孔、生命体征与出入量；高颅压者床头抬高30°、避免屏气用力；惊厥发作时做好保护；执行飞沫+接触隔离并落实接触者随访登记。","diet":"神志清楚者予高热量流质或半流质，防误吸；昏迷或频繁呕吐者暂禁食，静脉补液并记录出入量。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1294},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f7863878e0f8a19ef2714a13aec61ad4760cac75d1afef3732186d1f3c6f85bf","pinyin":"weijizhi：huanongxingnaomoyan（jixingxijunxingnaomoyan）","initials":"wjz：hnxnmy（jxxjxnmy）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","高热、剧烈头痛、喷射性呕吐、颈强直、畏光、意识障碍与惊厥；婴幼儿表现为拒食、易激惹、前囟饱满；脑膜炎球菌感染可见瘀点瘀斑。",60],["摘要","脑脊液白细胞显著升高（>1000×10⁶/L，中性粒细胞为主）、糖降低（<2.2mmol/L或CSF糖/血糖<0.4）、蛋白升高（>0.45g/L）伴病原学或培养阳性。细菌性脑膜炎是感染科最凶险的急症之一，可在数小时内进展至昏迷、脑疝甚至死亡；即使及时治疗病死率仍达10%-30%，约30%幸存者遗留听力下降、认知障碍等后遗症。",30],["疾病编码","G00.9",30],["原首字母","weijizhi：huanongxingnaomoyan（jixingxijunxingnaomoyan）",60]]},{"id":"orders-289dc7283c6f7f2d8f0e","key":"v1-c9ccc21dfe2a3058|orders-289dc7283c6f7f2d8f0e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：感染性心内膜炎","category":"内科危急值","raw":{"name":"危急值：感染性心内膜炎","category":"内科危急值","summary":"血培养检出心内膜炎相关病原体+心脏超声示赘生物、脓肿、瓣膜穿孔或人工瓣膜裂开，改良Duke标准达≥2项主要或1项主要+3项次要。总体住院死亡率15%-25%，人工瓣膜、金黄色葡萄球菌感染及合并心衰者更高；主要致死因素为急性心衰、脓毒性栓塞与难以控制的感染。","symptoms":["持续发热（可伴畏寒盗汗、乏力消瘦）；新出现或变化的心脏杂音；栓塞表现：脑卒中、肢体缺血、血尿、脾梗死腹痛、肺栓塞（右心）；皮肤瘀点。"],"diagnosis":["改良Duke标准：主要——≥2次血培养同一致病菌或持续阳性、心超见新赘生物/脓肿/人工瓣膜裂开；次要——易患因素、发热、血管现象、免疫现象、微生物学证据。抗生素前不同部位采血培养3套（间隔>30分钟）；TTE首选，阴性而高度怀疑或人工瓣膜者行TEE。"],"infusion":["经验性治疗（等待培养药敏）：自体瓣膜——万古霉素15-20mg/kg IV q8-12h+头孢曲松2g IV qd；人工瓣膜——万古霉素+头孢吡肟2g IV q8h，早期人工瓣膜感染者联合利福平与庆大霉素（协同剂量），病原确立后立即转靶向治疗。"],"oral_medication":["暂无"],"treatment":["靶向治疗依培养药敏：青霉素敏感链球菌（MIC<0.125mg/L）——青霉素G 1200-2400万U/d持续或分6次IV×4周，或头孢曲松2g IV qd×4周；MSSA——苯唑西林2g IV q4h×6周；MRSA——万古霉素维持谷浓度15-20mg/L×6周（可联合利福平/庆大霉素）；肠球菌——氨苄西林12g/d分6次+庆大霉素3mg/kg/d分3次×4-6周。疗程按瓣膜类型与并发症调整。"],"management":["组建心内科、心外科与感染科多学科团队评估手术指征：急性心衰或瓣膜功能不全、难以控制的感染（持续菌血症、真菌性IE）、反复栓塞（尤其赘生物>10mm伴栓塞事件）、人工瓣膜IE多数需手术；随访血培养至转阴并监测心衰与栓塞并发症。"],"notes":["务必在抗生素前完成血培养，经验治疗后培养常转阴而丧失病原学依据；监测万古霉素肾毒性及谷浓度；详细询问牙科操作、静脉药物使用等暴露史以查找来源。"],"emergency":["疑诊IE合并急性心衰、反复栓塞或血流动力学不稳定者：先采血培养3套，立即经验性万古霉素±头孢曲松（人工瓣膜加头孢吡肟等），并行心超与心外科急诊评估。"],"pinyin":"weijizhi：ganranxingxinneimoyan","icd10":"I33.0","physical_exam":"心脏听诊（杂音出现或变化）、皮肤瘀点、Osler结节、Janeway斑、甲下线状出血、眼底Roth斑、脾大、神经/肢端/腹部栓塞体征、静脉导管或吸毒穿刺点。","lab_tests":"血培养3套（不同部位、间隔>30分钟）、血常规、CRP/ESR/PCT、尿常规（血尿）、肾功能、心电图；TTE/TEE；疑栓塞者加头颅或腹部影像检查。","nursing":"持续心电血压监测，观察急性心衰与栓塞先兆（突发胸腹痛、偏瘫、肢端凉紫）；规范采集与送检血培养；按时静脉给药，监测药物不良反应与肾功能。","diet":"高热量高蛋白易消化饮食；合并心衰者限盐并控制液体入量。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1295},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"017e8cbeeaee2318469fea6ca7b4c0ecf320433342769b62ed7b2a1bcdd7db09","pinyin":"weijizhi：ganranxingxinneimoyan","initials":"wjz：grxxnmy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续发热（可伴畏寒盗汗、乏力消瘦）；新出现或变化的心脏杂音；栓塞表现：脑卒中、肢体缺血、血尿、脾梗死腹痛、肺栓塞（右心）；皮肤瘀点。",60],["摘要","血培养检出心内膜炎相关病原体+心脏超声示赘生物、脓肿、瓣膜穿孔或人工瓣膜裂开，改良Duke标准达≥2项主要或1项主要+3项次要。总体住院死亡率15%-25%，人工瓣膜、金黄色葡萄球菌感染及合并心衰者更高；主要致死因素为急性心衰、脓毒性栓塞与难以控制的感染。",30],["疾病编码","I33.0",30],["原首字母","weijizhi：ganranxingxinneimoyan",60]]},{"id":"orders-fb238174f0d284883bc5","key":"v1-c9ccc21dfe2a3058|orders-fb238174f0d284883bc5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：极高热/超高热危象","category":"内科危急值","raw":{"name":"危急值：极高热/超高热危象","category":"内科危急值","summary":"核心体温>41℃为超高热危象，可致线粒体功能障碍、蛋白变性乃至多器官功能障碍。常见病因包括严重脓毒症、热射病、中枢性高热（脑炎/脑血管病）、恶性高热、5-羟色胺综合征、神经阻滞剂恶性综合征、甲亢危象及药物热；降温同时必须查明并处理病因。","symptoms":["体温>41℃；皮肤干热（热射病）或大汗；意识障碍、谵妄昏迷、惊厥；心动过速、呼吸急促、低血压；肌强直（恶性高热、NMS）、震颤或肌阵挛（5-羟色胺综合征）；少尿、出血倾向等多器官受损表现。"],"diagnosis":["以直肠或核心温度>41℃确认（排除测温误差与假性高温）；结合环境暴露、麻醉与药物史、感染征象及内分泌线索分型鉴别：热射病、恶性高热、中枢性高热、NMS、5-羟色胺综合征、甲亢危象、脓毒症等。"],"infusion":["物理降温是核心措施：冰毯（可编程控温）、冰帽、颈部/腋下/腹股沟冰敷；热射病可予冰盐水胃灌洗或灌肠。禁用酒精或冷水擦浴（诱发寒战产热、血管收缩散热减少）；降温同时注意防寒战。"],"oral_medication":["对乙酰氨基酚500-1000mg po或灌肠 q4-6h（≤4g/d，注意肝损害）；布洛芬200-400mg po q4-6h（注意肾功能与消化道）；5-羟色胺综合征可用赛庚啶口服。"],"treatment":["病因治疗：脓毒症——血培养后予广谱抗生素；热射病——快速降温至核心温度<38.9℃+补液+器官支持；恶性高热——停用触发药物、丹曲林首剂2.5mg/kg IV（可重复，累计不超过10mg/kg）；NMS——停抗精神病药、支持治疗并予溴隐亭/丹曲林；甲亢危象——抗甲状腺药物、β受体阻滞剂、糖皮质激素等（内分泌专科处理）；药物热——停用可疑药物。"],"management":["力争30-60分钟内使核心体温降至<39℃并持续监测；心电、血压、血氧监护，补液并纠正电解质与酸碱紊乱；监测PLT、PT、D-二聚体、纤维蛋白原筛查DIC；多器官功能支持，必要时机械通气与血液净化。"],"notes":["解热镇痛药对热射病等非炎症性高热基本无效，不可依赖而延误物理降温；恶性高热有麻醉触发史且进展极快，须与NMS鉴别；高龄及基础心肺疾病者注意降温过快所致虚脱。"],"emergency":["核心体温>41℃即启动：立即冰毯等物理降温并同步病因排查与处理，监护生命体征、补液及器官支持。"],"pinyin":"weijizhi：jigaore/chaogaoreweixiang","icd10":"R50.9","physical_exam":"核心（直肠）温度、皮肤干湿与色泽、意识与瞳孔、肌张力及震颤、心肺腹体征、尿量；留意神经定位体征与皮疹。","lab_tests":"血常规、CRP/PCT、血培养（疑感染）、血气与乳酸、电解质、血糖、肝肾功能、肌酸激酶与肌红蛋白（恶性高热/NMS）、凝血及D-二聚体、甲状腺功能（甲亢危象）；必要时头颅影像与脑电图。","nursing":"每15-30分钟测核心体温直至平稳；冰毯与冰敷部位皮肤护理防冻伤，注意局部循环；观察寒战并协调保暖；记录出入量、持续心电血压；意识障碍者加强气道管理防误吸。","diet":"降温与复苏期以补液为主；神志恢复后予易消化高热量饮食，昏迷者禁食并予营养支持。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1296},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8ab2e8825431844c827ee4d15e88e17ea5c7de184d5dea0552171e8ed50dc887","pinyin":"weijizhi：jigaore/chaogaoreweixiang","initials":"wjz：jgr/cgrwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","体温>41℃；皮肤干热（热射病）或大汗；意识障碍、谵妄昏迷、惊厥；心动过速、呼吸急促、低血压；肌强直（恶性高热、NMS）、震颤或肌阵挛（5-羟色胺综合征）；少尿、出血倾向等多器官受损表现。",60],["摘要","核心体温>41℃为超高热危象，可致线粒体功能障碍、蛋白变性乃至多器官功能障碍。常见病因包括严重脓毒症、热射病、中枢性高热（脑炎/脑血管病）、恶性高热、5-羟色胺综合征、神经阻滞剂恶性综合征、甲亢危象及药物热；降温同时必须查明并处理病因。",30],["疾病编码","R50.9",30],["原首字母","weijizhi：jigaore/chaogaoreweixiang",60]]},{"id":"orders-8ef389ab0fc5edb89720","key":"v1-c9ccc21dfe2a3058|orders-8ef389ab0fc5edb89720","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：血培养阳性特殊病原体/多重耐药菌","category":"内科危急值","raw":{"name":"危急值：血培养阳性特殊病原体/多重耐药菌","category":"内科危急值","summary":"血或无菌体液培养出MRSA、VRE、CRE、CRPA、ESBL及侵袭性真菌等病原属危急值，需立即启动接触隔离并快速靶向治疗。多重耐药菌感染病死率显著高于敏感菌（CRE病死率可达40%-60%），早期恰当抗感染与感染源控制是预后关键。","symptoms":["发热或低体温、寒战、心动过速、低血压、意识改变等脓毒症样表现；导管、手术部位或植入物相关感染征象；近期住院/ICU、广谱抗生素暴露与耐药菌定植史。"],"diagnosis":["以血培养病原鉴定+MIC药敏为准，注意结合临床排除污染；明确耐药表型及机制（KPC等酶型）指导选药；评估感染源（血管导管、植入物）及转移性感染灶。"],"infusion":["MRSA菌血症：万古霉素负荷25-30mg/kg后15-20mg/kg IV q8-12h（谷浓度15-20mg/L），或达托霉素6-10mg/kg IV qd（MIC高或肾损害时）；CRE（KPC酶型）：头孢他啶/阿维巴坦2.5g IV q8h，或多黏菌素B首剂2-2.5mg/kg后1.25-1.5mg/kg IV q12h为基础的联合方案；CRPA：头孢洛扎/他唑巴坦3g IV q8h或头孢他啶/阿维巴坦。"],"oral_medication":["利奈唑胺600mg po q12h（万古霉素不适用或MRSA肺炎时）；伏立康唑口服200mg bid用于曲霉病序贯维持。"],"treatment":["侵袭性念珠菌病：棘白菌素类首选——卡泊芬净首剂70mg后50mg IV qd，或米卡芬净100mg IV qd，稳定后按药敏降阶梯；曲霉病：伏立康唑首日6mg/kg IV q12h×2次后4mg/kg IV q12h维持；同时处理感染源：拔除可疑导管、引流清创；无并发症且随访血培养阴性者MRSA疗程≥2周，复杂感染4-6周。"],"management":["确诊即执行接触隔离（单间或同类集中、专用器械、严格手卫生）并上报院感与监测；拔除或更换可疑血管内导管并送培养；随访血培养指导疗程与降阶梯；监测万古霉素谷浓度与肾毒性、伏立康唑肝毒性。"],"notes":["培养报阳须结合临床判断污染可能，避免无指征碳青霉烯暴露；CRE常需联合治疗并请感染专科会诊；ESBL产酶菌按药敏选用碳青霉烯或β-内酰胺酶抑制剂复方制剂。"],"emergency":["阳性危急值报告：立即接触隔离，核对临床后按病原经验用药（如万古霉素负荷量），同时评估移除感染源导管。"],"pinyin":"weijizhi：xuepeiyangyangxingteshubingyuanti/duozhongnaiyaojun","icd10":"A49.9","physical_exam":"生命体征与脓毒症征象、各血管导管及穿刺/手术部位、心肺腹体征、皮肤黏膜、意识状态；查找脓肿等引流灶。","lab_tests":"报阳血培养即刻革兰染色回报+快速鉴定与MIC药敏；血常规、CRP/PCT、乳酸、肝肾功能（药代与毒性基线）；随访血培养至转阴；必要时耐药基因检测。","nursing":"落实接触隔离、手卫生与隔离标识；危急值双人核对并登记；按时给药并监测不良反应（万古霉素谷浓度、肾功、肝功）；导管维护与更换时机评估；做好患者及家属宣教。","diet":"高蛋白营养支持以提高抗感染能力，肠内营养优先；不能进食者予肠外营养。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1297},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6009d2b957bb27bd27289866fb254aa2cb7c0609f8c5f5dbae44e65fd7eb701e","pinyin":"weijizhi：xuepeiyangyangxingteshubingyuanti/duozhongnaiyaojun","initials":"wjz：xpyyxtsbyt/dznyj","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热或低体温、寒战、心动过速、低血压、意识改变等脓毒症样表现；导管、手术部位或植入物相关感染征象；近期住院/ICU、广谱抗生素暴露与耐药菌定植史。",60],["摘要","血或无菌体液培养出MRSA、VRE、CRE、CRPA、ESBL及侵袭性真菌等病原属危急值，需立即启动接触隔离并快速靶向治疗。多重耐药菌感染病死率显著高于敏感菌（CRE病死率可达40%-60%），早期恰当抗感染与感染源控制是预后关键。",30],["疾病编码","A49.9",30],["原首字母","weijizhi：xuepeiyangyangxingteshubingyuanti/duozhongnaiyaojun",60]]},{"id":"orders-c3580a521648ee7c7def","key":"v1-c9ccc21dfe2a3058|orders-c3580a521648ee7c7def","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性缺血性脑卒中","category":"内科危急值","raw":{"name":"危急值：急性缺血性脑卒中","category":"内科危急值","summary":"发病<4.5h、NIHSS≥4分或大血管闭塞表现且CT排除出血即属危急值；脑缺血每分钟损失神经元约190万，须尽快再灌注（DNT≤40min、DPT≤90min）。","symptoms":["突发偏瘫、面舌瘫、失语、偏身感觉障碍、凝视、共济失调或视野缺损等局灶缺损，可伴意识障碍；须与低血糖、癫痫后状态鉴别。"],"diagnosis":["确认最后正常时间（醒后卒中按入睡起点计）；CT平扫排除出血，疑大血管闭塞加CTA，6-24h或后循环者以CTP/MRI+DWI筛选灌注；接诊至CT≤25min、CT至溶栓决策≤20min。"],"infusion":["阿替普酶0.9mg/kg（最大90mg）：先10%于1min内静脉推注，余90%输注60min；或替奈普酶0.25mg/kg（最大25mg）5-10s单次推注替代。给药前血压须SBP<185且DBP<110mmHg。"],"oral_medication":["溶栓24h后复查CT无出血转化再启用抗血小板：阿司匹林100-300mg qd；轻型卒中或TIA（ABCD²≥4分）可阿司匹林+氯吡格雷双抗。"],"treatment":["取栓：前循环大血管闭塞<6h直接取栓，6-24h经CTP/MRI筛选；后循环基底动脉<24h依影像评估；首选支架取栓+抽吸联合，尽早开通为关键。"],"management":["启动卒中团队：生命体征、血糖、心电图、NIHSS并确认发病时间；急查血常规、凝血、电解质、肾功能、心肌标志物。再通良好者术后24h内SBP<140mmHg，避免<120mmHg强化降压；收入卒中单元，吞咽评估防误吸并早期康复。"],"notes":["以最后正常时间算时间窗；血压临界者先降压达标再溶栓；活动性出血、近期手术等禁忌个体化权衡，出血转化风险高者慎用抗栓。"],"emergency":["即刻CT平扫排除出血，必要时CTA/CTP；同步NIHSS、血糖、心电图、开放静脉并通知溶栓/取栓团队。"],"pinyin":"weijizhi：jixingquexuexingnaozuzhong","icd10":"I63.9","physical_exam":"NIHSS、GCS、瞳孔、肌力、面舌瘫、病理征、语言及共济；评估气道与生命体征。","lab_tests":"血常规、凝血功能（PT/APTT/INR）、电解质、肾功能、心肌标志物、随机血糖。","nursing":"持续监测生命体征与NIHSS；溶栓中观察头痛呕吐、牙龈及皮肤黏膜渗血；防跌倒、误吸、压疮。","diet":"暂禁食水，吞咽筛查后再进食；吞咽障碍者鼻饲防误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1298},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"54202e16a6db00d4e5e576fc4449f0a2283909b7a7e2982fa8ef35fe74d92a48","pinyin":"weijizhi：jixingquexuexingnaozuzhong","initials":"wjz：jxqxxnzz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发偏瘫、面舌瘫、失语、偏身感觉障碍、凝视、共济失调或视野缺损等局灶缺损，可伴意识障碍；须与低血糖、癫痫后状态鉴别。",60],["摘要","发病<4.5h、NIHSS≥4分或大血管闭塞表现且CT排除出血即属危急值；脑缺血每分钟损失神经元约190万，须尽快再灌注（DNT≤40min、DPT≤90min）。",30],["疾病编码","I63.9",30],["原首字母","weijizhi：jixingquexuexingnaozuzhong",60]]},{"id":"orders-b39dee3ffbe8c58c2460","key":"v1-c9ccc21dfe2a3058|orders-b39dee3ffbe8c58c2460","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：脑出血","category":"内科危急值","raw":{"name":"危急值：脑出血","category":"内科危急值","summary":"CT确诊脑实质或脑室内出血伴急性神经功能缺损即属危急值，30天死亡率30%-50%；发病24h内血肿扩大为预后不良主因，预测因素：发病至CT时间短、CTA斑点征阳性、血肿>25ml、抗凝使用。","symptoms":["突发头痛呕吐、血压显著升高，伴偏瘫、失语或意识障碍；小脑出血以眩晕呕吐共济失调为主，脑干出血深昏迷、生命体征紊乱。"],"diagnosis":["CT确诊并定位、测体积；CTA评估斑点征及动脉瘤/血管畸形；疑凝血障碍查凝血与血小板；动态评估血压与GCS。"],"infusion":["降压目标SBP<140mmHg（1h内达标、维持24h）：尼卡地平5-15mg/h泵入，或乌拉地尔25-50mg IV后4-8mg/h泵入，或拉贝洛尔10-20mg IV q15-30min；ICP>20mmHg持续>5min予甘露醇0.5-1g/kg IV或3%高渗盐水250ml。"],"oral_medication":["急性期不用止血药（氨甲环酸改善结局证据不足）；出院后抗栓依病因与影像评估决定。"],"treatment":["抗凝逆转：华法林→PCC 25-50U/kg+维生素K1 5-10mg IV；达比加群→依达赛珠单抗5g IV；利伐沙班/阿哌沙班→Andexanet alfa（或PCC）；肝素→鱼精蛋白。手术：幕上血肿>30ml且GCS8-15分可微创清除；小脑出血>10ml、脑干受压或脑积水→后颅窝减压；脑室出血/脑积水→脑室外引流±脑室内溶栓。"],"management":["床头抬高30°、镇静镇痛、避免Valsalva；血糖4.4-10mmol/L、避免发热；24-48h后低分子肝素防DVT；动态监测GCS、瞳孔、血压。"],"notes":["降压须1h内达标并持续24h以减少血肿扩大，但勿过度降压；抗凝相关出血先逆转再评估恢复时机。"],"emergency":["CT确诊后同步：1h内血压达标、按用药史抗凝逆转、降颅压及手术评估；急查凝血、血常规、血型、血糖。"],"pinyin":"weijizhi：naochuxue","icd10":"I61.9","physical_exam":"动态观察GCS、瞳孔、偏瘫肌力及病理征；查眼底与脑膜刺激征。","lab_tests":"CT（必要时CTA）、血常规、凝血、血小板、血型、血糖、电解质、肝肾功能。","nursing":"绝对卧床、床头抬高30°，每1-2h评估GCS与瞳孔；防误吸压疮坠床；躁动者镇静约束；脑室外引流者严格无菌并记录引流量。","diet":"急性期暂禁食，吞咽评估后由流质过渡；便秘者通便避免用力；管饲防返流误吸。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1299},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"82a9f54945d3556af16262c833fdf48940a2c9aa468f08e403e74019a6f6b261","pinyin":"weijizhi：naochuxie","initials":"wjz：ncx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发头痛呕吐、血压显著升高，伴偏瘫、失语或意识障碍；小脑出血以眩晕呕吐共济失调为主，脑干出血深昏迷、生命体征紊乱。",60],["摘要","CT确诊脑实质或脑室内出血伴急性神经功能缺损即属危急值，30天死亡率30%-50%；发病24h内血肿扩大为预后不良主因，预测因素：发病至CT时间短、CTA斑点征阳性、血肿>25ml、抗凝使用。",30],["疾病编码","I61.9",30],["原首字母","weijizhi：naochuxue",60]]},{"id":"orders-7cd617ece8dfca8e4abb","key":"v1-c9ccc21dfe2a3058|orders-7cd617ece8dfca8e4abb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：癫痫持续状态","category":"内科危急值","raw":{"name":"危急值：癫痫持续状态","category":"内科危急值","summary":"全面性惊厥发作持续>5min或发作间期意识未恢复即属危急值，死亡率20%-30%；脑损伤与持续时间正相关，早期（0-30min）疗效最好，须按时间窗阶梯升级。","symptoms":["持续或反复全身强直-阵挛且意识不恢复，可伴发绀、咬舌、外伤、尿失禁；非惊厥性发作仅意识或行为异常，需EEG识别。"],"diagnosis":["据抽搐持续与间期意识恢复情况诊断，分早期0-5min、中期5-30min、难治期>30-60min；急查血糖、电解质、血气、肝肾功能、AED血药浓度、毒物筛查、CT；后续MRI、EEG、腰穿及自身免疫抗体排查。"],"infusion":["一线苯二氮卓选一：劳拉西泮4mg IV（2min内推注，可重复1次）或地西泮10mg IV（2-5mg/min）；无静脉通路用地西泮20mg PR或咪达唑仑10mg IM。一线后仍抽搐入二线选一：丙戊酸15-30mg/kg IV>5min、左乙拉西坦40-60mg/kg IV>5min、磷苯妥英15-20mgPE/kg IV>15min（防低血压/心律失常），无效换另一二线。"],"oral_medication":["发作控制后过渡口服抗癫痫药维持，按发作类型选药并监测血药浓度；撤静脉药须衔接。"],"treatment":["难治期（>30-60min）于ICU+连续EEG下行麻醉治疗并滴定至暴发抑制：丙泊酚2mg/kg负荷后5-10mg/kg/h泵入，或咪达唑仑0.2mg/kg负荷后0.1-0.2mg/kg/h泵入；氯胺酮1-3mg/kg/h用于难治者；同时维持一线/二线抗癫痫药。"],"management":["严格按时间窗升级；同步气道保护、给氧、心电监护，纠正低血糖及电解质紊乱等诱因；控制后查治病因（感染、卒中、代谢、戒断等）。"],"notes":["先测血糖，低血糖纠正本身可止抽；苯二氮卓重复使用防呼吸抑制；难治期用EEG识别非惊厥发作；孕妇等特殊人群用药需调整。"],"emergency":["开放气道给氧、心电监护、测血糖、建静脉通路；按0-5/5-30/>30-60min阶梯给药；CT、EEG、腰穿查病因。"],"pinyin":"weijizhi：dianxianchixuzhuangtai","icd10":"G41.9","physical_exam":"记录发作类型与起止时间、GCS、瞳孔、舌咬伤/外伤、体温、脑膜刺激征及局灶体征。","lab_tests":"血糖、电解质、血气、肝肾功能、AED血药浓度、毒物筛查、感染指标；CT/MRI/EEG/腰穿按需。","nursing":"发作时侧卧防误吸、移开危险物、勿强压肢体；记录起止时间与类型；保证静脉通路给氧，观察呼吸抑制。","diet":"发作期禁食；控制后按吞咽由流质过渡，不能进食者管饲并保证经胃管给药。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1300},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"76eea7d707cf56a76f989011f9cdd3da8153fc2ae7773e516021c6d24d8c35a5","pinyin":"weijizhi：dianxianchixuzhuangtai","initials":"wjz：dxcxzt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续或反复全身强直-阵挛且意识不恢复，可伴发绀、咬舌、外伤、尿失禁；非惊厥性发作仅意识或行为异常，需EEG识别。",60],["摘要","全面性惊厥发作持续>5min或发作间期意识未恢复即属危急值，死亡率20%-30%；脑损伤与持续时间正相关，早期（0-30min）疗效最好，须按时间窗阶梯升级。",30],["疾病编码","G41.9",30],["原首字母","weijizhi：dianxianchixuzhuangtai",60]]},{"id":"orders-10dd373313c828693914","key":"v1-c9ccc21dfe2a3058|orders-10dd373313c828693914","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：颅内压增高/脑疝","category":"内科危急值","raw":{"name":"危急值：颅内压增高/脑疝","category":"内科危急值","summary":"ICP>20mmHg持续>5min或出现脑疝征象即属危急，可迅速发展为天幕疝或枕骨大孔疝致脑干衰竭死亡；正常ICP 5-15mmHg，CPP=MAP-ICP正常60-80mmHg，<50mmHg脑缺血不可逆。","symptoms":["头痛进行性加重、喷射性呕吐、视乳头水肿、意识障碍加深；脑疝征象：瞳孔不等大或一侧散大固定、去皮层/去大脑强直、Cushing反应（血压高脉缓呼吸慢）、呼吸节律异常。"],"diagnosis":["结合临床表现与CT/MRI（脑水肿、占位、中线移位、脑室受压）诊断；脑室内导管测压为ICP监测金标准，同时监测CPP与脑组织氧分压（PbtO2）。"],"infusion":["甘露醇0.5-1g/kg于15-30min输注、q4-6h按需，血浆渗透压<320mOsm/L，超则停药/减量；或3%高渗盐水250ml IV，血钠145-155mmol/L，>160停药。短时过度通气使PaCO2 30-35mmHg仅临时桥接（<1h），<25mmHg致脑缺血。"],"oral_medication":["急性期以静脉渗透与原发病处理为主；恢复期依病因（感染、肿瘤、癫痫等）口服维持。"],"treatment":["一般措施：床头抬高30°、头颈中立位；镇静镇痛（丙泊酚/咪达唑仑+芬太尼）；防Valsalva（避免吸痰刺激、通便）；体温36-37°C；维持PaCO2 35-40mmHg防血管扩张。手术：恶性脑水肿/大面积梗死/脑出血ICP难控时去骨瓣减压，脑出血清血肿，脑积水行脑室外引流。目标ICP<20-22mmHg、CPP>60-70mmHg、PbtO2>20mmHg。"],"management":["持续监测ICP/CPP及GCS、瞳孔、生命体征；避免低血压低氧保CPP；防治应激性溃疡、感染与DVT；同步处理原发病。"],"notes":["监测渗透压与血钠，防肾损伤、高钠及甘露醇反跳；过度通气仅限临时；瞳孔不等大或GCS骤降提示脑疝，立即处理并呼叫神经外科。"],"emergency":["疑脑疝即刻快速静滴甘露醇/高渗盐水，必要时插管+过度通气过渡；急查CT明确病因，通知神经外科与ICU。"],"pinyin":"weijizhi：luneiyazenggao/naoshan","icd10":"G93.5","physical_exam":"GCS、瞳孔大小与对光反射、眼底视乳头水肿、肌张力与去脑强直、病理征、呼吸节律及生命体征。","lab_tests":"CT/MRI；血气（PaCO2）；电解质、渗透压、血钠；凝血与感染指标按病因；有创ICP监测。","nursing":"床头抬高30°、头颈中立；定时评估GCS瞳孔；躁动者镇静约束避免Valsalva；吸痰轻柔限时；甘露醇利尿者记录出入量；防压疮坠床。","diet":"急性期禁食或管饲，控液体入量、避免低渗输液；稳定后按吞咽过渡。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1301},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"eddd3714d8df05c0a70de6635648e84b12d2318b503e3a07bfd56be4dd39855b","pinyin":"weijizhi：luneiyazenggao/naoshan","initials":"wjz：lnyzg/ns","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","头痛进行性加重、喷射性呕吐、视乳头水肿、意识障碍加深；脑疝征象：瞳孔不等大或一侧散大固定、去皮层/去大脑强直、Cushing反应（血压高脉缓呼吸慢）、呼吸节律异常。",60],["摘要","ICP>20mmHg持续>5min或出现脑疝征象即属危急，可迅速发展为天幕疝或枕骨大孔疝致脑干衰竭死亡；正常ICP 5-15mmHg，CPP=MAP-ICP正常60-80mmHg，<50mmHg脑缺血不可逆。",30],["疾病编码","G93.5",30],["原首字母","weijizhi：luneiyazenggao/naoshan",60]]},{"id":"orders-da81f4a7719d249f8d5a","key":"v1-c9ccc21dfe2a3058|orders-da81f4a7719d249f8d5a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：重度意识障碍(GCS≤8分)","category":"内科危急值","raw":{"name":"危急值：重度意识障碍(GCS≤8分)","category":"内科危急值","summary":"GCS（睁眼+语言+运动，3-15分）≤8提示重度脑损伤或严重代谢性脑病，为气管插管经典指征；保护性反射消失，误吸与气道梗阻风险高，须立即处理。","symptoms":["呼之不应或仅对疼痛有反应，可伴舌根后坠、鼾式呼吸与分泌物增多；按E/V/M评估意识，观察瞳孔、四肢活动及局灶体征或抽搐。"],"diagnosis":["GCS≤8即诊断；按“由内到外”排查：感染（血培养+腰穿）、卒中（CT/CTA/CTP）、代谢（血糖、电解质、血气、肝肾功能、血氨、甲功、皮质醇）、中毒（毒物筛查）、创伤（头颈胸腹盆CT）、抽搐（EEG排除非惊厥性SE）。"],"infusion":["经验治疗（病因未明）：纳洛酮0.4-2mg IV（疑阿片过量）；50%葡萄糖20-50ml IV（疑低血糖）；硫胺素100mg IV（酒精中毒/Wernicke脑病）；高度疑感染予经验抗生素。"],"oral_medication":["昏迷期经静脉或胃管给药；清醒后依病因过渡口服治疗。"],"treatment":["气道保护：GCS≤8或保护性反射消失/不稳定即快速序贯插管（丙泊酚/依托咪酯+罗库溴铵）；支持目标SpO2≥92%、PaCO2 35-40mmHg、MAP≥80mmHg保CPP；同步病因排查与治疗。"],"management":["插管后机械通气并滴定，镇静镇痛防躁动；维持循环与内环境稳定；动态复查GCS与瞳孔；防呼吸机相关肺炎、压疮、DVT、应激性溃疡；多学科明确病因。"],"notes":["GCS≤8为插管参考，须结合保护性反射个体判断；昏迷≠脑死亡，动态评估；酒精/营养不良者先用硫胺素再给糖防Wernicke脑病。"],"emergency":["立即评估气道准备插管，给氧、心电监护、开放静脉；快速血糖，按线索用纳洛酮等解毒剂；急查CT、血气与毒物筛查。"],"pinyin":"weijizhi：zhongduyishizhangai(GCS≤8fen)","icd10":"R40.2","physical_exam":"GCS（E/V/M）、瞳孔及对光反射、眼底、颈强直、肌力肌张力、病理征、外伤体征、皮疹/针眼、生命体征。","lab_tests":"血糖、电解质、血气、肝肾功能、血氨、甲功、皮质醇、血培养、毒物筛查；CT/MRI/EEG/腰穿按需。","nursing":"侧卧或头偏向一侧防误吸，清理分泌物规范吸痰；监护SpO2与生命体征，动态评估GCS；防压疮、坠床与非计划拔管；记录出入量。","diet":"昏迷期禁食，允许时尽早鼻饲肠内营养，监测胃潴留与血糖；吞咽恢复后评估经口进食。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1302},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"02dbce2147352f11b0c6f3e14cb260006a63e61cb9dd36aca0d410af0451d78c","pinyin":"weijizhi：zhongduyishizhangai(GCS≤8fen)","initials":"wjz：zdysza(f)","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呼之不应或仅对疼痛有反应，可伴舌根后坠、鼾式呼吸与分泌物增多；按E/V/M评估意识，观察瞳孔、四肢活动及局灶体征或抽搐。",60],["摘要","GCS（睁眼+语言+运动，3-15分）≤8提示重度脑损伤或严重代谢性脑病，为气管插管经典指征；保护性反射消失，误吸与气道梗阻风险高，须立即处理。",30],["疾病编码","R40.2",30],["原首字母","weijizhi：zhongduyishizhangai(GCS≤8fen)",60]]},{"id":"orders-9aaf63d1c44655c0ba34","key":"v1-c9ccc21dfe2a3058|orders-9aaf63d1c44655c0ba34","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：心脏骤停","category":"内科危急值","raw":{"name":"危急值：心脏骤停","category":"内科危急值","summary":"危急值界定：无脉+无呼吸+意识丧失。心脏骤停是临床最紧急事件，预后取决于生存链：早期识别呼救→高质量CPR→快速除颤→高级生命支持(ACLS)→复苏后管理；院外存活出院率约10%-20%，院内约15%-25%。","symptoms":["意识丧失、呼之不应；无自主呼吸或仅叹息样呼吸；大动脉搏动消失；皮肤苍白发绀、瞳孔散大；可先有胸痛、心悸、呼吸困难等前驱表现，部分以抽搐起病。"],"diagnosis":["临床诊断，勿等辅助检查：无反应+无呼吸+大动脉搏动消失即确诊并立即CPR；心电监护明确心律（VF/无脉性VT、PEA、停搏）以决定除颤，不因查因而延误按压。"],"infusion":["首选肘前外周静脉建立IV/IO，复苏期以给药为主不常规快速补液；ROSC后低血压予晶体液及去甲肾上腺素等维持血压；TTM期间注意容量与电解质平衡。"],"oral_medication":["急性期无口服途径；ROSC后按心律失常类型与基础病由医师过渡口服二级预防药物。"],"treatment":["1.无反应无呼吸→立即呼救、启动应急系统，检查与按压同步；2.高质量CPR：按压深度5-6cm、频率100-120次/min、胸廓充分回弹、中断<10s；未建立高级气道按30:2按压/通气，建立后持续按压+约6次/min通气；3.尽早除颤：VF/无脉性VT双相波200J→CPR 2min→再评估，可重复并递增能量；4.IV/IO后肾上腺素1mg每3-5min；第3次除颤后胺碘酮300mg→追加150mg，或利多卡因1-1.5mg/kg→0.5-0.75mg/kg；5.置高级气道（中断按压<10s），全程排查可逆病因(5H5T)；6.ROSC后TTM 32-36℃维持≥24h、评估冠脉造影、控制性氧疗SpO2 92%-98%、管理血压血糖。"],"management":["复苏成功后转ICU/CCU持续监护，规范记录抢救时间线与用药；执行低温治疗与复温；多学科评估病因与预后。"],"notes":["按压质量与除颤时机决定预后，一切操作不得长时间中断按压，每2分钟轮换按压者防疲劳；避免过度通气；TTM需权衡获益与并发症。"],"emergency":["VF/无脉性VT反复→复除颤并续用肾上腺素；PEA/停搏→高质量CPR+肾上腺素并快速排查5H5T；ROSC后循环不稳定者持续监护并呼救上级/ICU支援。"],"pinyin":"weijizhi：xinzangzhouting","icd10":"I46.9","physical_exam":"评估意识、呼吸有无与形式、颈动脉搏动、皮肤颜色灌注；按压中核查深度回弹；识别ROSC征象（脉搏恢复、血压回升、呼气末CO2骤升）。","lab_tests":"复苏中及ROSC后查血气乳酸、血钾等电解质、血糖、肌钙蛋白、肾功能与凝血；按可疑病因加查毒物/药物浓度；ROSC后完成12导联心电图。","nursing":"协助按压轮换、给药并记录时间；除颤时确认无人接触患者；监测SpO2、呼气末CO2与心律；复苏后做好气道、皮肤与体温管理护理。","diet":"复苏期禁食水并行胃肠减压；ROSC后意识恢复、胃肠功能允许再评估肠内营养。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1303},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2da9c4b04ad1527b435b4122a59ffd54a033ed42dc3a6c1d76d85857e37d0dd7","pinyin":"weijizhi：xinzangzhouting","initials":"wjz：xzzt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","意识丧失、呼之不应；无自主呼吸或仅叹息样呼吸；大动脉搏动消失；皮肤苍白发绀、瞳孔散大；可先有胸痛、心悸、呼吸困难等前驱表现，部分以抽搐起病。",60],["摘要","危急值界定：无脉+无呼吸+意识丧失。心脏骤停是临床最紧急事件，预后取决于生存链：早期识别呼救→高质量CPR→快速除颤→高级生命支持(ACLS)→复苏后管理；院外存活出院率约10%-20%，院内约15%-25%。",30],["疾病编码","I46.9",30],["原首字母","weijizhi：xinzangzhouting",60]]},{"id":"orders-830689b40c0b74a44494","key":"v1-c9ccc21dfe2a3058|orders-830689b40c0b74a44494","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：过敏性休克","category":"内科危急值","raw":{"name":"危急值：过敏性休克","category":"内科危急值","summary":"危急值界定：暴露可疑致敏原后短时间内累及≥2个器官系统（皮肤黏膜+呼吸/循环/消化），或出现气道梗阻、低血压即严重过敏反应乃至过敏性休克。2025共识更新：肾上腺素IM（大腿中部外侧）是唯一一线紧急药物，抗组胺药与糖皮质激素不再作为一线。","symptoms":["荨麻疹瘙痒、口唇眼睑水肿；喘鸣/喉头水肿、喘息、发绀；低血压、晕厥、心动过速；恶心呕吐、腹痛；多在接触后数分钟至2小时内快速进展，可迅速休克。"],"diagnosis":["依据暴露史+快速进展的多系统受累表现临床诊断，勿等实验室；成人收缩压<90mmHg或较基础下降>30%提示休克；与哮喘发作、血管迷走性晕厥、心源性/低血容量性休克鉴别。"],"infusion":["快速输注晶体液500-1000ml（儿童约20ml/kg），按血压重复；难治性休克用肾上腺素静脉泵入（按反应滴定）或去甲肾上腺素；β阻滞剂相关难治者加胰高血糖素1-2mg IV并尽早入ICU。"],"oral_medication":["无口服紧急用药；皮肤黏膜症状明显者可加西替利嗪10mg口服作二线辅助，不替代肾上腺素。"],"treatment":["1.停止接触过敏原、呼救、评估ABC；2.肾上腺素IM首选并立即执行：成人0.3-0.5mg(1:1000)大腿中部外侧，可q5min重复；儿童0.01mg/kg、最大0.3mg；3.仰卧抬腿、高流量吸氧、快速补液；4.难治性或≥2剂IM无效：肾上腺素静脉泵入或去甲肾上腺素，β阻滞剂者加胰高血糖素1-2mg IV，早期ICU；5.二线辅助：苯海拉明25-50mg IV或西替利嗪10mg缓解皮肤症状，甲泼尼龙1-2mg/kg IV预防双相反应，沙丁胺醇5mg雾化缓解支气管痉挛；6.单剂IM完全缓解且低危者可考虑不转送急诊（备第二支肾上腺素、30min内可达医院、有陪护）；呼吸/心血管受累者观察≥4h，高危重症观察8-10h以上。"],"management":["按受累系统与缓解速度决定留观时长（4h至8-10h以上）；出院前培训肾上腺素笔使用、强调过敏原回避并安排专科随访。"],"notes":["肾上腺素IM是唯一一线紧急药物，注射于大腿中部外侧、越早越好；抗组胺药与激素不能解除气道梗阻或休克，勿因此延误肾上腺素；警惕双相反应（缓解后数小时再发），观察时间需充分。"],"emergency":["喉头水肿/严重喘鸣、休克、意识障碍→立即肾上腺素IM并准备气管插管，同时快速补液并呼救ICU。"],"pinyin":"weijizhi：guominxingxiuke","icd10":"T78.2","physical_exam":"反复ABC评估：声音嘶哑、喘鸣、哮鸣音、SpO2、血压心率灌注、荨麻疹水肿范围、意识状态。","lab_tests":"非诊断必需；发作1-6h内测血清类胰蛋白酶辅助确认；血气与乳酸评估缺氧灌注；心电图、肌钙蛋白排除过敏相关冠脉痉挛(Kounis综合征)；按需血常规、电解质。","nursing":"平卧抬腿、吸氧、心电血压SpO2监护；记录每次肾上腺素给药时间与反应；观察双相反应与输液反应；执行留观时限与出院宣教。","diet":"急性期暂禁食防误吸；明确过敏原后严格回避致敏食物。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1304},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"162a0c7f06946789925564189518e38eba5c2a7f3e7b3412d512b6f6e5317bbd","pinyin":"weijizhi：guominxingxiuke","initials":"wjz：gmxxk","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","荨麻疹瘙痒、口唇眼睑水肿；喘鸣/喉头水肿、喘息、发绀；低血压、晕厥、心动过速；恶心呕吐、腹痛；多在接触后数分钟至2小时内快速进展，可迅速休克。",60],["摘要","危急值界定：暴露可疑致敏原后短时间内累及≥2个器官系统（皮肤黏膜+呼吸/循环/消化），或出现气道梗阻、低血压即严重过敏反应乃至过敏性休克。2025共识更新：肾上腺素IM（大腿中部外侧）是唯一一线紧急药物，抗组胺药与糖皮质激素不再作为一线。",30],["疾病编码","T78.2",30],["原首字母","weijizhi：guominxingxiuke",60]]},{"id":"orders-3e0aae57821994cbac77","key":"v1-c9ccc21dfe2a3058|orders-3e0aae57821994cbac77","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：糖尿病酮症酸中毒","category":"内科危急值","raw":{"name":"危急值：糖尿病酮症酸中毒","category":"内科危急值","summary":"危急阈值：血糖>13.9mmol/L+pH<7.3+HCO3<15mmol/L+血酮阳性（β-羟丁酸≥3mmol/L或尿酮≥+++）。DKA是糖尿病最严重急性并发症，规范补液可降死亡率至<1%（资源有限地区仍<5%）；延误可致脑水肿（尤其儿童）；液体复苏优先于胰岛素。","symptoms":["多饮多尿乏力加重、恶心呕吐、腹痛（可拟似急腹症）、Kussmaul深大呼吸伴烂苹果味、脱水、心率快、意识模糊至昏迷；常由感染、胰岛素中断、应激诱发。"],"diagnosis":["高血糖+酮血症+代谢性酸中毒三联征即诊断；查血糖、血/尿酮体、血气（pH、HCO3、AG）、电解质、肾功能、渗透压；同步寻找诱因（感染、心梗、卒中、药物等）。"],"infusion":["补液最优先：首1h 0.9%NaCl 15-20ml/kg（成人约1-1.5L），第2h 500-1000ml，第3-12h 250-500ml/h；首24h总量4-6L，监测心肾功能；血糖降至约13.9mmol/L改5%GS+0.45%NaCl防低血糖。"],"oral_medication":["急性期无口服用药；恢复进食并过渡皮下胰岛素后，由医师按糖尿病类型决定是否重启口服降糖方案。"],"treatment":["1.补液同时评估处理诱因（感染抗感染等）；2.胰岛素：0.1U/kg IV负荷（严重低钾时省略）→0.1U/kg/h泵入，血糖下降目标50-75mg/dL/h（约3-4mmol/L/h）；降至约13.9mmol/L后减至0.02-0.05U/kg/h并联合5%GS；3.见尿补钾：K<3.3先补钾后给胰岛素防致死性低钾；K3.3-5.5补10-20mmol/h、目标4-5mmol/L；K>5.5暂不补；4.纠酸：pH<6.9可考虑NaHCO3 50-100mmol+400ml D5W缓慢滴注，>7.0即停；pH≥6.9不推荐补碱（反常CNS酸中毒、低钾、组织缺氧）；5.过渡皮下：pH>7.3、HCO3>18、AG正常且能进食后静脉与皮下重叠2-4h。"],"management":["重症入ICU/监护，动态监测血糖、电解质、血气与出入量；儿童严密监护神志瞳孔，疑脑水肿立即按急症处理并呼救。"],"notes":["液体复苏优先于胰岛素，补液不足是可防的主要死因与脑水肿诱因；胰岛素勿过早减量停用防酮症反弹；补碱、补钾严格把握时机。"],"emergency":["严重低钾未纠正、休克、意识恶化、pH持续<7.0或儿童出现脑水肿征象→强化补液与胰岛素泵入，呼救ICU/内分泌科协同处理。"],"pinyin":"weijizhi：tangniaobingtongzhengsuanzhongdu","icd10":"E10.1/E11.1","physical_exam":"评估意识、脱水体征（皮肤弹性、眼窝凹陷）、呼吸频率深度与气味、心率血压、腹部压痛（除外急腹症）；儿童重点观察神志瞳孔识别脑水肿。","lab_tests":"血糖q1h、血酮/尿酮与血气q2-4h、血钾q2-4h、乳酸、肾功能、感染指标、心电图；记录出入量。","nursing":"按医嘱血糖q1h、血钾q2-4h监测记录；正确执行胰岛素泵入防中断外渗；观察呼吸深大、神志与出入量；协助血气复查与心电监护。","diet":"酮症纠正且能进食后过渡糖尿病饮食并衔接皮下胰岛素；恢复期防低血糖。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1305},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"84496cb74227562ee513872a1665834599be54415242b9984f1a378d6565f925","pinyin":"weijizhi：tangniaobingtongzhengsuanzhongdu","initials":"wjz：tnbtzszd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多饮多尿乏力加重、恶心呕吐、腹痛（可拟似急腹症）、Kussmaul深大呼吸伴烂苹果味、脱水、心率快、意识模糊至昏迷；常由感染、胰岛素中断、应激诱发。",60],["摘要","危急阈值：血糖>13.9mmol/L+pH<7.3+HCO3<15mmol/L+血酮阳性（β-羟丁酸≥3mmol/L或尿酮≥+++）。DKA是糖尿病最严重急性并发症，规范补液可降死亡率至<1%（资源有限地区仍<5%）；延误可致脑水肿（尤其儿童）；液体复苏优先于胰岛素。",30],["疾病编码","E10.1/E11.1",30],["原首字母","weijizhi：tangniaobingtongzhengsuanzhongdu",60]]},{"id":"orders-727f213c0241b24054b6","key":"v1-c9ccc21dfe2a3058|orders-727f213c0241b24054b6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：高血糖高渗状态","category":"内科危急值","raw":{"name":"危急值：高血糖高渗状态","category":"内科危急值","summary":"危急阈值：血糖>33.3mmol/L（600mg/dL）+血清渗透压>320mOsm/kg+无/轻度酮症（血酮<0.6mmol/L）。多见于2型糖尿病老年患者，病死率高于DKA（5%-20%），死因主要为高渗致循环衰竭、血栓栓塞与感染；渗透压下降过快仍可致脑水肿。","symptoms":["口渴多尿进行性加重→严重脱水、乏力、嗜睡至昏迷；可伴抽搐及局灶神经体征；常无深大呼吸与明显酮味；老年人多以感染、心梗/卒中、创伤、利尿剂或糖皮质激素等为诱因。"],"diagnosis":["血糖>33.3mmol/L+血浆渗透压>320mOsm/kg+血酮不增高即可诊断；查校正血钠、电解质、血气、血酮、肾功能、感染指标；积极寻找诱因并评估心肾功能以指导补液。"],"infusion":["补液量较DKA更大：首1-2h输0.9%NaCl 1-2L，血钠正常后改0.45%NaCl，再按血钠回归等渗液；首24h总量6-8L，严密监测心肾功能防容量过负荷。"],"oral_medication":["急性期以静脉补液为主，无口服降糖药；恢复进食后由内分泌医师重启口服降糖方案，并调整诱发高渗的药物（如噻嗪类利尿剂、糖皮质激素）。"],"treatment":["1.积极补液为首要措施，使渗透压平稳缓慢下降；2.胰岛素较DKA保守：0.05U/kg/h持续泵入（无负荷量），目标血糖下降3-5mmol/L/h避免过快；血糖降至约16.7mmol/L时加5%GS，防低血糖及渗透压骤降致脑水肿；3.补钾同DKA原则：见尿补钾、防低钾；4.血栓预防：本症血栓风险极高，无禁忌予低分子肝素（依诺肝素40mg SC qd）；5.治疗诱因：感染最常见（经验性抗感染），心梗/卒中/创伤/药物所致者相应处理；6.动态监测血钠、渗透压、血糖，控制下降速度并复查电解质肾功能。"],"management":["老年患者入ICU/监护，监测容量、心功能与神经状态；每日评估血栓预防；记录渗透压、血糖与出入量；恢复期放缓输液速度防脑水肿。"],"notes":["HHS病死率(5%-20%)高于DKA，补液量更大但老年人需警惕心衰与容量过负荷；血钠正常后换半渗液并控制渗透压下降速度防脑水肿；无禁忌尽早抗凝预防血栓。"],"emergency":["昏迷、休克、抽搐或意识进行性恶化→监护下加快补液、必要时保护气道并呼救ICU；渗透压下降过快伴神经恶化时暂停降糖补液方案重新评估。"],"pinyin":"weijizhi：gaoxuetanggaoshenzhuangtai","icd10":"E11.0","physical_exam":"评估意识、脱水程度（皮肤弹性、黏膜干燥、眼窝凹陷、血压心率）、体温及感染灶、神经系统体征；老年患者同时评估心肺功能与容量负荷。","lab_tests":"血糖q1-2h、血钠钾氯与校正血钠、渗透压、血酮/血气、肾功能、乳酸、血常规/CRP或PCT及血培养（感染筛查）、心电图、胸片；必要时头颅CT。","nursing":"监测血糖、电解质、渗透压与出入量并记录；意识障碍者防坠床防误吸、做好皮肤口腔护理；观察容量过负荷（呼吸困难、水肿、颈静脉怒张）与血栓征象；注射低分子肝素并观察出血。","diet":"急性期静脉补液为主；意识恢复、血糖稳定后予糖尿病流质并过渡常规糖尿病饮食，保证饮水。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1306},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c947ff61b9d26824a7834d2494e5759a8da0f35e11cd30b04f38c79afae62d0d","pinyin":"weijizhi：gaoxuetanggaoshenzhuangtai","initials":"wjz：gxtgszt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口渴多尿进行性加重→严重脱水、乏力、嗜睡至昏迷；可伴抽搐及局灶神经体征；常无深大呼吸与明显酮味；老年人多以感染、心梗/卒中、创伤、利尿剂或糖皮质激素等为诱因。",60],["摘要","危急阈值：血糖>33.3mmol/L（600mg/dL）+血清渗透压>320mOsm/kg+无/轻度酮症（血酮<0.6mmol/L）。多见于2型糖尿病老年患者，病死率高于DKA（5%-20%），死因主要为高渗致循环衰竭、血栓栓塞与感染；渗透压下降过快仍可致脑水肿。",30],["疾病编码","E11.0",30],["原首字母","weijizhi：gaoxuetanggaoshenzhuangtai",60]]},{"id":"orders-64982f7d357f0adfa197","key":"v1-c9ccc21dfe2a3058|orders-64982f7d357f0adfa197","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"危急值：急性中毒危象","category":"内科危急值","raw":{"name":"危急值：急性中毒危象","category":"内科危急值","summary":"危急值界定：明确/高度可疑剧毒物接触史+中毒表现。死亡率取决于毒物种类、接触量与就诊时间；常见剧毒物：有机磷、百草枯、氰化物、甲醇/乙二醇、对乙酰氨基酚、一氧化碳、阿片类。主线：脱离现场、清除毒物、生命支持、尽早解毒。","symptoms":["有机磷流涎多汗、肌束颤动、针尖样瞳孔、呼吸抑制；阿片类昏迷+呼吸抑制+针尖样瞳孔；CO头晕头痛、意识障碍；甲醇视物模糊腹痛；对乙酰氨基酚迟发肝损；百草枯口咽灼伤、呼吸困难。"],"diagnosis":["依据接触史+临床综合征快速判断；查明毒物名称、剂量、途径与时间；留血尿胃内容物查毒物/血药浓度（对乙酰氨基酚、甲醇、胆碱酯酶、碳氧血红蛋白）；辅以心电图、血气与影像；警惕混合中毒与迟发毒性。"],"infusion":["建立静脉通路，按需补液维持血压与尿量；甲醇/乙二醇、百草枯等需血液净化者尽早联系转诊；中毒性休克予补液+血管活性药。"],"oral_medication":["吞服类毒物早期予活性炭1g/kg口服或鼻饲（摄入1h内最佳；对醇类、强酸碱、金属无效）；意识障碍先插管保护气道再给药。"],"treatment":["1.脱离现场、脱衣，清水充分冲洗皮肤与眼睛；2.气道保护与呼吸循环支持，意识障碍先插管；3.摄入1h内洗胃，活性炭1g/kg口服/鼻饲（先保气道）；4.解毒剂：有机磷→阿托品5-10mg IV至阿托品化（瞳孔大、口干、心率>100、皮肤干）+氯解磷定1-2g IV首剂、q1h共2-3次；百草枯→血液灌流+大剂量激素+环磷酰胺；氰化物→羟钴胺5-10g IV或硫代硫酸钠12.5g IV；对乙酰氨基酚→NAC 150mg/kg IV→50mg/kg×4h→100mg/kg×16h；甲醇/乙二醇→甲吡唑15mg/kg IV负荷或乙醇+血液透析；阿片类→纳洛酮0.4-2mg IV可重复；CO→100%高流量氧，意识障碍或HbCO>25%予高压氧；5.48-72h关键观察期，警惕迟发毒性；6.中毒科/ICU/血液净化协作并评估自杀风险。"],"management":["按毒物半衰期与迟发毒性确定观察时限（48-72h）；动态复查毒物浓度与肝肾功能凝血；危重症转中毒专科/ICU。"],"notes":["解毒剂尽早足量并按反应滴定（阿托品、纳洛酮）；洗胃先保气道、把握时机；对乙酰氨基酚迟发肝毒按时程复查；疑自服中毒者评估自杀风险。"],"emergency":["昏迷、呼吸抑制、惊厥、心律失常或休克→ABC支持，呼救ICU/中毒专科，尽早解毒并准备血液净化。"],"pinyin":"weijizhi：jixingzhongduweixiang","icd10":"T65.9","physical_exam":"ABC与生命体征；瞳孔及反应、口腔黏膜灼伤、皮肤多汗/灼伤/针眼、呼出气味（大蒜味/苦杏仁味）、肌束颤动、腹部；测体重供解毒剂剂量计算。","lab_tests":"毒物筛查与血药浓度（血尿）、胆碱酯酶、碳氧血红蛋白、血气乳酸、电解质血糖、肝肾功能凝血（对乙酰氨基酚48-72h复查）、心电图、胸片/CT。","nursing":"严密看护防坠床自伤；监测意识、瞳孔、呼吸、SpO2；协助洗胃及活性炭给药防误吸；记录出入量、观察出血；保留毒物标本。","diet":"洗胃与活性炭后暂禁食；稳定后按毒物类型恢复流质；腐蚀性损伤经内镜评估后进食。"},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1307},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8e2a480c368bbc87ba0b6531acd42c63a791fcfe01467941960dd67303728062","pinyin":"weijizhi：jixingzhongduweixiang","initials":"wjz：jxzdwx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","有机磷流涎多汗、肌束颤动、针尖样瞳孔、呼吸抑制；阿片类昏迷+呼吸抑制+针尖样瞳孔；CO头晕头痛、意识障碍；甲醇视物模糊腹痛；对乙酰氨基酚迟发肝损；百草枯口咽灼伤、呼吸困难。",60],["摘要","危急值界定：明确/高度可疑剧毒物接触史+中毒表现。死亡率取决于毒物种类、接触量与就诊时间；常见剧毒物：有机磷、百草枯、氰化物、甲醇/乙二醇、对乙酰氨基酚、一氧化碳、阿片类。主线：脱离现场、清除毒物、生命支持、尽早解毒。",30],["疾病编码","T65.9",30],["原首字母","weijizhi：jixingzhongduweixiang",60]]},{"id":"orders-1263d8e1110503e6f5d9","key":"v1-c9ccc21dfe2a3058|orders-1263d8e1110503e6f5d9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝脓肿","category":"肝胆外科","raw":{"name":"肝脓肿","category":"肝胆外科","summary":"肝脓肿是细菌、真菌或阿米巴原虫经胆道、门静脉、肝动脉或直接蔓延侵入肝脏引起的化脓性感染，以细菌性（化脓性）肝脓肿最常见。典型表现为寒战高热、肝区疼痛、肝大压痛，可并发脓毒症、脓肿破溃（膈下、胸腔、腹腔）。","symptoms":["寒战、高热（弛张热为主，体温可达39～40℃），伴大汗、乏力、纳差","肝区持续性胀痛或钝痛，可向右肩背部放射，深呼吸或体位变动时加重","肝大、肝区压痛及叩击痛，部分可触及波动性肿块","黄疽（多见于胆源性肝脓肿）、恶心呕吐、消瘦","重症者出现感染性休克、意识改变"],"diagnosis":["血常规：白细胞及中性粒细胞比例显著升高，可有贫血；CRP、PCT升高","肝功能：ALT/AST、ALP、GGT、胆红素升高，白蛋白降低","腹部超声：首选，可见肝内液性暗区、脓肿壁；可引导穿刺","增强CT/MRI：明确脓肿数目、大小、部位、是否多房及与血管胆管关系","血培养+脓液培养及药敏：抗生素使用前采血，穿刺时留取脓液","阿米巴血清学（疑阿米巴肝脓肿）、便找阿米巴滋养体"],"infusion":["⚠️ 方案选择提示：请根据患者病情选择以下方案，切勿全部同时使用！","方案1（经验性抗感染，覆盖肠杆菌科+厌氧菌）：","用法：头孢曲松 2g 静滴 qd（或头孢哌酮舒巴坦 3g 静滴 q8h）+ 甲硝唑 0.5g 静滴 q8h〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案2（重症/耐药风险）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h（或美罗培南 1g 静滴 q8h）+ 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案3（支持治疗）：","用法：0.9%氯化钠/5%葡萄糖 静滴；白蛋白、氨基酸营养支持；必要时血管活性药","📌 用药前核对药品名称、剂量、浓度、给药途径与滴速，确认无过敏史；抗菌药物使用前留取血培养。"],"oral_medication":["⚠️ 用药选择提示：同类药物选择一种即可，切勿重复用药！","药物1（序贯/轻症）：","用法：头孢克肟 0.1g bid 或左氧氟沙星 0.5g qd + 甲硝唑 0.4g tid〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（阿米巴肝脓肿）：","用法：甲硝唑 0.4～0.6g tid（疗程10天）后序贯双碘喹啉〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物3（对症）：","用法：对乙酰氨基酚 0.5g 必要时（退热）；双氯芬酸钠栓 必要时（疼痛）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 用药前核对药品名、剂量与疗程；甲硝唑用药期间禁酒。"],"treatment":["抗感染治疗：早期、足量、联合、静脉给药，覆盖肠杆菌科细菌及厌氧菌，根据药敏调整，疗程4～6周（脓肿吸收慢，不宜过早停药）","脓肿引流：直径≥3～5cm或液化明显者，首选超声/CT引导下经皮穿刺置管引流；多发、黏稠、分隔者可多次穿刺或置管冲洗","手术引流指征：脓肿破溃入胸腹腔、厚壁脓肿穿刺失败、胆源性肝脓肿合并胆道梗阻需同时处理胆道","胆源性肝脓肿：解除胆道梗阻（ERCP/ENBD或手术胆道引流）","支持治疗：补液、纠正水电解质紊乱、营养支持、必要时输注白蛋白或血浆","控制基础病：糖尿病者严格控制血糖（血糖高是肝脓肿难愈的重要因素）"],"management":["监测生命体征：体温曲线、血压、心率、尿量，警惕感染性休克","记录引流液色、质、量，保持引流通畅，定期冲洗（遵医嘱）","动态复查血常规、CRP、PCT及肝功能，评估抗感染疗效","每1～2周复查超声/CT，观察脓肿缩小情况（吸收常需数周至数月）","高热者物理降温+药物退热，出汗多者及时补液，保持口腔与皮肤清洁","糖尿病患者监测血糖并请内分泌科协助调整降糖方案"],"notes":["肝脓肿起病常似感冒或肺炎，凡不明原因寒战高热伴肝区疼痛、肝大者应想到本病","脓肿未液化时以抗感染为主，液化后应及时引流；单纯抗生素难以治愈较大脓肿","细菌性肝脓肿需与阿米巴肝脓肿、肝癌中心坏死、膈下脓肿、胆囊炎鉴别","疗程不足易复发，停药需结合症状、炎症指标与影像学吸收情况综合判断"],"emergency":["高热寒战伴血压下降、意识改变（感染性休克）→ 立即抢救并通知上级医师","突发剧烈腹痛、腹膜炎体征（脓肿破溃）→ 急诊手术准备","黄疸进行性加重伴高热、神志改变（胆源性梗阻合并胆管炎）→ 急诊胆道引流"],"pinyin":"gnz","icd10":"K75.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（有无感染性休克）、血氧","一般情况：神志、精神、营养状况、有无大汗及消耗面容","腹部视诊：有无膨隆、手术瘢痕、腹壁静脉曲张","腹部触诊：肝下缘位置、肝区压痛及叩击痛、有无波动性肿块、腹膜刺激征","肝区叩诊：肝浊音界是否上移（膈下脓肿/胸腔积液）、叩击痛部位","胸部：右下肺呼吸音是否减弱（反应性胸腔积液）、有无胸膜摩擦音","皮肤黏膜：黄染（胆源性梗阻）、皮肤感染灶、有无出血点"],"lab_tests":["血常规+CRP+PCT：入院急查，评估感染严重程度，治疗中每3～5天复查评估疗效","肝功能全套：ALT/AST/ALP/GGT/胆红素/白蛋白，判断有无胆道梗阻及肝细胞损伤程度","血培养（需氧+厌氧）×2套：抗生素使用前采血，提高病原学阳性率","脓液细菌/真菌涂片+培养及药敏：穿刺或手术时留取，指导目标性抗感染","腹部超声：入院首选筛查并定位，可引导穿刺引流；治疗后动态随访","增强CT/MRI：脓肿多发、位置深在或拟手术者，明确解剖关系与有无胆道相通","血糖+糖化血红蛋白（糖尿病筛查）、阿米巴抗体（疑阿米巴肝脓肿）"],"nursing":["病情观察：每4小时测体温、脉搏、呼吸、血压，注意热型及有无休克早期表现（脉快、脉压小、皮肤湿冷）","引流管护理：妥善固定，防止脱出、扭曲，准确记录每日引流量与性状，冲洗时严格无菌操作","高热护理：物理降温为主，出汗后及时更换衣物与床单，鼓励多饮水，保持皮肤清洁","用药护理：按时给予抗菌药物，观察有无皮疹、胃肠道反应及二重感染征象","营养与休息：卧床休息，给予高蛋白高维生素易消化饮食，必要时静脉营养支持"],"diet":["急性期半流质/流质饮食，减轻肝脏与胃肠道负担","高蛋白（鱼、瘦肉、蛋、奶、豆制品）、高维生素（新鲜蔬果）、适量碳水","高热期保证摄入液体1500～2000ml/日（必要时静脉补液）","忌酒、忌辛辣刺激及油腻煎炸食物","糖尿病者按糖尿病饮食管理，控制总热量"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1308},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a61a6fe4dfc65632c41505e068d3d61c889d1121dd829ede4880e21c2caa1a11","pinyin":"gannongzhong","initials":"gnz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","寒战、高热（弛张热为主，体温可达39～40℃），伴大汗、乏力、纳差\\n肝区持续性胀痛或钝痛，可向右肩背部放射，深呼吸或体位变动时加重\\n肝大、肝区压痛及叩击痛，部分可触及波动性肿块\\n黄疽（多见于胆源性肝脓肿）、恶心呕吐、消瘦\\n重症者出现感染性休克、意识改变",60],["摘要","肝脓肿是细菌、真菌或阿米巴原虫经胆道、门静脉、肝动脉或直接蔓延侵入肝脏引起的化脓性感染，以细菌性（化脓性）肝脓肿最常见。典型表现为寒战高热、肝区疼痛、肝大压痛，可并发脓毒症、脓肿破溃（膈下、胸腔、腹腔）。",30],["疾病编码","K75.0",30],["原首字母","gnz",60]]},{"id":"orders-72a12f5d462d9d7f27e1","key":"v1-c9ccc21dfe2a3058|orders-72a12f5d462d9d7f27e1","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性梗阻性化脓性胆管炎（AOSC）","category":"肝胆外科","raw":{"name":"急性梗阻性化脓性胆管炎（AOSC）","category":"肝胆外科","summary":"急性梗阻性化脓性胆管炎（AOSC，又称急性重症胆管炎ACST）是在胆道梗阻基础上发生的严重化脓性感染，胆管内压升高致脓性胆汁反流入血，引起脓毒症与多器官功能障碍，进展快、病死率高，属外科急腹症，需紧急胆道减压引流。","symptoms":["Charcot三联征：右上腹痛、寒战高热、黄疸","Reynolds五联征：三联征 + 休克（血压下降）+ 神志改变（烦躁、淡漠、昏迷）","腹痛多位于右上腹或剑突下，持续性胀痛或绞痛，可向右肩背放射","恶心、呕吐，尿色深黄，大便可呈陶土色","病情进展迅速，可出现少尿、无尿、皮肤瘀斑（DIC）等"],"diagnosis":["血常规：白细胞显著升高或降低（危重者可降低），中性粒细胞比例升高，核左移","肝功能及胆红素：总胆红素、直接胆红素、ALP、GGT显著升高，ALT/AST升高","PCT、CRP、乳酸：评估感染与组织灌注，血培养+药敏","腹部超声：首选，可见胆管扩张、结石、胆泥、胆囊情况及梗阻部位","腹部CT/MRCP：明确梗阻部位、病因（结石/肿瘤）、有无肝脓肿","凝血功能、肾功能、血气分析、电解质：评估器官功能损害"],"infusion":["⚠️ 抢救用药，须在监护下使用，根据病情选择！","方案1（抗感染，覆盖肠杆菌科+厌氧菌+肠球菌）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案2（液体复苏）：","用法：平衡盐溶液/0.9%氯化钠 30ml/kg 快速补液（30～60min内），评估后再调整；必要时加用白蛋白","方案3（休克）：","用法：去甲肾上腺素 0.05～0.5μg/kg/min 静脉泵入，维持MAP≥65mmHg（须在补液基础上）","📌 抗菌药物使用前留取血培养；血管活性药经中心静脉或专用通路泵入，防止外渗。"],"oral_medication":["⚠️ 急性期以静脉用药为主，病情稳定后序贯口服：","药物1（抗感染）：","用法：头孢克肟 0.1g bid 或 左氧氟沙星 0.5g qd + 甲硝唑 0.4g tid〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（利胆）：","用法：熊去氧胆酸 250mg tid（梗阻解除后）","药物3（对症）：","用法：间苯三酚 40mg 必要时（解痉止痛，诊断明确后使用）","📌 禁用吗啡等强效镇痛药（可掩盖病情、加重Oddi括约肌痉挛）。"],"treatment":["紧急胆道减压引流：最关键的抢救措施——ERCP+ENBD/EST取石引流，或PTCD，或开腹/腹腔镜胆总管切开T管引流","抗感染：早期足量联合静脉给药（如 头孢哌酮舒巴坦 3g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h），覆盖G-杆菌、厌氧菌及肠球菌，据药敏调整","液体复苏与器官支持：快速补液纠正低血容量（晶体液 30ml/kg 起始），必要时血管活性药（去甲肾上腺素 0.05-0.5μg/kg/min 静滴）、纠正酸中毒与电解质紊乱","纠正凝血功能障碍：补充维生素K1 10mg 静推/肌注 qd、新鲜冰冻血浆 10-15ml/kg 静滴、血小板（有出血倾向者，PLT<50×10⁹/L 输注 1 治疗量）","手术指征：胆道减压失败、胆道穿孔、合并肝脓肿或胆道出血、结石嵌顿取石失败","病因处理：病情稳定后处理结石、肿瘤或胆道狭窄等梗阻原因"],"management":["立即建立两条以上静脉通路，抽血送检（血培养、血常规、生化、凝血、血气）后启动抗感染与补液","持续心电、血压、血氧监护，记录尿量（留置尿管，目标≥0.5ml/kg/h）","观察腹痛、黄疸、神志及体温变化，每1～2小时评估一次Reynolds五联征","引流管护理：记录胆汁引流量与性状（正常金黄色；脓性、血性、泥沙样需警惕）","动态复查血常规、PCT、乳酸、肝肾功能及凝血，评估多器官功能","做好急诊手术/ERCP准备：禁食禁水、备血、术前准备、家属沟通"],"notes":["本病是外科急症，核心原则是『解除梗阻、通畅引流』，抗感染不能替代引流","老年人、糖尿病患者症状可不典型，仅表现为淡漠、纳差、低血压，须警惕","胆道梗阻未解除时，单纯抗感染死亡率高，切勿观望拖延","病情稳定后需明确病因（结石/肿瘤/狭窄），避免复发"],"emergency":["寒战高热+黄疸+腹痛伴血压下降或神志改变（Reynolds五联征）→ 立即抢救、紧急胆道引流","出现少尿、无尿、皮肤瘀斑、呼吸困难（MODS/DIC）→ 转入ICU并多学科抢救","腹痛突然加剧伴腹膜刺激征（胆道穿孔）→ 急诊手术"],"pinyin":"jxgzxhxddgy","icd10":"K83.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压、血氧（重点评估有无休克）","神志与一般情况：意识状态（Reynolds五联征之一）、皮肤湿冷、有无黄疸及贫血","腹部视诊：右上腹膨隆、手术瘢痕、呼吸运动受限","腹部触诊：右上腹压痛、Murphy征、肝区叩击痛、有无腹膜炎体征及包块","腹部叩诊：肝浊音界、移动性浊音（胆漏/腹水）","皮肤黏膜：巩膜与皮肤黄染程度、出血点、瘀斑、输液穿刺部位渗血","心肺：心率增快、心音低钝，注意有无胸腔积液及呼吸急促"],"lab_tests":["血常规+CRP+PCT：急查评估感染程度与白细胞反应，治疗中每2～3天复查","肝功能+胆红素+ALP/GGT：判断梗阻程度与肝细胞损伤，动态监测胆红素下降趋势","血培养×2套+胆汁培养：抗生素前采血、引流时留取胆汁，指导目标治疗","凝血功能+D-二聚体+血小板：警惕DIC，必要时每12～24小时复查","血气分析+乳酸+电解质：评估组织灌注与酸碱失衡，指导液体复苏","肾功能+尿常规：监测急性肾损伤（尿量、肌酐）","腹部超声/CT/MRCP：明确梗阻部位、病因及有无肝脓肿，为引流方式选择提供依据"],"nursing":["休克护理：取休克体位，快速建立静脉通路，遵医嘱补液与用药，每15～30分钟监测血压、心率、尿量","严密观察：意识、体温、腹痛、黄疸、皮肤黏膜出血及尿量变化，发现病情恶化立即报告","引流管护理：ENBD/PTCD/T管妥善固定，记录引流量与颜色，防止牵拉脱出及逆行感染","术前准备：禁食禁水、备皮、备血、留置胃管与尿管，做好急诊手术准备","皮肤护理：黄疸患者皮肤瘙痒避免抓破，保持床单位清洁，观察穿刺点渗液"],"diet":["急性期禁食禁水（需急诊手术或ERCP者）","病情稳定、梗阻解除后：从清流质→低脂流质→低脂半流质逐步过渡","长期：低脂饮食，减少动物脂肪与油炸食物，适量优质蛋白","规律进食早餐，避免长期饥饿（减少胆汁淤积与结石形成）","忌酒、忌暴饮暴食；胆道术后遵医嘱控制胆固醇摄入"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1309},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"585b67288dd1c434a17cfea4975be44246c694886306637caee4206bbf07981b","pinyin":"jixinggengzuxinghuanongxingdanguanyan（AOSC）","initials":"jxgzxhnxdgy（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","Charcot三联征：右上腹痛、寒战高热、黄疸\\nReynolds五联征：三联征 + 休克（血压下降）+ 神志改变（烦躁、淡漠、昏迷）\\n腹痛多位于右上腹或剑突下，持续性胀痛或绞痛，可向右肩背放射\\n恶心、呕吐，尿色深黄，大便可呈陶土色\\n病情进展迅速，可出现少尿、无尿、皮肤瘀斑（DIC）等",60],["摘要","急性梗阻性化脓性胆管炎（AOSC，又称急性重症胆管炎ACST）是在胆道梗阻基础上发生的严重化脓性感染，胆管内压升高致脓性胆汁反流入血，引起脓毒症与多器官功能障碍，进展快、病死率高，属外科急腹症，需紧急胆道减压引流。",30],["疾病编码","K83.0",30],["原首字母","jxgzxhxddgy",60]]},{"id":"orders-5f199d945235a87df3c0","key":"v1-c9ccc21dfe2a3058|orders-5f199d945235a87df3c0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"胆总管结石","category":"肝胆外科","raw":{"name":"胆总管结石","category":"肝胆外科","summary":"胆总管结石分为继发性（胆囊结石排入胆总管）与原发性（胆管内形成，多与胆道感染、胆汁淤积、寄生虫有关）。可无症状，也可引起胆绞痛、梗阻性黄疸、急性胆管炎、急性胰腺炎，是外科常见急症。","symptoms":["右上腹或剑突下绞痛，阵发性加重，向右肩背部放射","寒战、发热（合并胆管炎时），黄疸（结石嵌顿梗阻时）","恶心、呕吐、食欲减退，尿色加深、大便颜色变浅","无症状者仅在体检超声/MRCP时发现胆管扩张或结石","合并急性胰腺炎时出现上腹持续剧痛、向腰背放射、腹胀"],"diagnosis":["肝功能+胆红素：直接胆红素、ALP、GGT升高提示胆道梗阻","血常规+CRP+PCT：合并感染时升高；血培养（发热者）","腹部超声：可见胆管扩张、结石回声（末端结石常显示不清）","MRCP：无创首选，明确结石部位、数目、大小及胆管解剖","CT：评估有无胰腺炎、胆管炎并发症及胆管壁情况","ERCP：诊疗一体，可同时取石；疑结石嵌顿或需治疗时选用","淀粉酶/脂肪酶：疑合并急性胰腺炎时必查"],"infusion":["⚠️ 方案选择提示：请根据病情选择，切勿全部同时使用！","","方案1（抗感染，合并胆管炎时）：","  用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；重症用哌拉西林他唑巴坦 4.5g q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案2（解痉止痛，诊断明确后）：","  用法：间苯三酚 40～80mg（NS 100ml 或 5%GS 100ml）静滴/静推 必要时（可重复）；或山莨菪碱 10mg 肌注","","方案3（补液支持）：","  用法：平衡盐溶液 500～1000ml 静滴；呕吐明显者补钾（见尿补钾）","","📌 禁用吗啡（引起Oddi括约肌痉挛加重梗阻）；使用抗菌药物前留取血培养。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（利胆溶石，仅适用于部分胆固醇结石）：","用法：熊去氧胆酸 250mg tid（疗程6～24个月，需定期复查）","药物2（抗感染序贯）：","用法：头孢克肟 0.1g bid 或 左氧氟沙星 0.5g qd + 甲硝唑 0.4g tid〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物3（对症）：","用法：铝碳酸镁 1.0g tid（胃部不适）；消旋山莨菪碱 10mg 必要时","📌 有症状的胆总管结石以取石/手术为主，药物不能替代解除梗阻。"],"treatment":["ERCP+EST取石：首选（尤其单发、直径<1.5cm、无解剖禁忌），可同时放置ENBD或支架","腹腔镜/开腹胆总管切开取石+T管引流：结石大、多发、嵌顿或ERCP失败者","腹腔镜胆囊切除+胆总管探查：合并胆囊结石者一并处理","合并急性胆管炎：先紧急胆道减压引流（ENBD/PTCD），病情稳定后再取石","合并急性胰腺炎：按胰腺炎规范治疗（禁食、抑酸抑酶、补液），择期处理结石","对症治疗：解痉止痛、补液、纠正电解质紊乱、抗感染"],"management":["观察腹痛、体温、黄疸变化，记录大便颜色及尿色","T管护理：妥善固定、防脱出，记录胆汁量（正常300～700ml/日）与性状，术后2周经T管造影后决定拔管","饮食：低脂饮食，避免暴饮暴食及油腻餐","术后观察有无胆漏（腹痛、发热、引流液胆汁样）、出血及胰腺炎表现","定期复查超声/MRCP，监测结石残留或复发","合并糖尿病、高脂血症者控制基础疾病"],"notes":["胆总管结石一旦引起梗阻性黄疸或胆管炎，须尽早解除梗阻，不宜长期观察","ERCP术后需观察有无胰腺炎（术后淀粉酶升高+腹痛）、出血、穿孔","T管拔管前必须确认胆道通畅（造影无残留结石、无梗阻）","原发性胆总管结石复发率高，术后需定期随访"],"emergency":["寒战高热+黄疸+腹痛（Charcot三联征）或伴休克、神志改变 → 紧急胆道引流","上腹持续剧痛向腰背放射伴呕吐（合并急性胰腺炎）→ 急诊处理并禁食","腹痛突然加剧伴腹膜刺激征（胆道穿孔/胆汁性腹膜炎）→ 急诊手术"],"pinyin":"dzgjs","icd10":"K80.5","physical_exam":["生命体征：体温、脉搏、血压（评估感染与休克）","皮肤黏膜：巩膜及皮肤黄染程度、抓痕（胆汁淤积性瘙痒）、脱水征","腹部视诊：右上腹膨隆、呼吸运动受限、手术瘢痕","腹部触诊：右上腹压痛、Murphy征、肝区叩击痛、有无腹膜刺激征","腹部叩诊：肝浊音界、移动性浊音","腹部听诊：肠鸣音（合并胰腺炎时减弱或消失）","一般情况：营养状态、体重变化（长期胆道疾病）"],"lab_tests":["肝功能+胆红素（总/直接）+ALP+GGT：判断梗阻部位与程度，治疗后观察胆红素下降","血常规+CRP+PCT：评估感染程度，合并胆管炎时显著升高","血培养+胆汁培养及药敏：发热或引流时留取，指导抗生素选择","淀粉酶+脂肪酶：排除/评估合并急性胰腺炎","凝血功能：梗阻性黄疸影响维生素K吸收，术前必查","MRCP（或腹部超声+CT）：明确结石位置、数目、胆管扩张及解剖变异","尿常规+尿胆原/胆红素：辅助判断梗阻性黄疸"],"nursing":["腹痛观察：注意疼痛部位、性质、持续时间及有无腹膜刺激征，禁用吗啡类镇痛药","T管/ENBD护理：妥善固定防脱出，记录引流量与颜色，避免牵拉及逆行感染","黄疸护理：皮肤瘙痒者温水擦洗、勿抓破，剪短指甲，必要时遵医嘱用药","饮食护理：低脂饮食，少量多餐，避免油腻及暴饮暴食，术前禁食禁水","术后观察：腹痛、发热、引流液性状、切口渗液，警惕胆漏、出血与胰腺炎"],"diet":["急性发作期禁食禁水，静脉补充营养与液体","缓解期低脂流质/半流质，逐步过渡到低脂普食","长期低脂饮食：少食动物内脏、蛋黄、油炸食品，多用蒸煮炖","规律早餐、少量多餐，避免长时间空腹（利于胆汁排空）","多饮水，多食新鲜蔬菜水果，控制体重与血脂"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1310},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"349f88047fa6e8ddc805d277dd978221e9d0893b5f2409415d35fb185e5920e5","pinyin":"danzongguanjieshi","initials":"dzgjs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","右上腹或剑突下绞痛，阵发性加重，向右肩背部放射\\n寒战、发热（合并胆管炎时），黄疸（结石嵌顿梗阻时）\\n恶心、呕吐、食欲减退，尿色加深、大便颜色变浅\\n无症状者仅在体检超声/MRCP时发现胆管扩张或结石\\n合并急性胰腺炎时出现上腹持续剧痛、向腰背放射、腹胀",60],["摘要","胆总管结石分为继发性（胆囊结石排入胆总管）与原发性（胆管内形成，多与胆道感染、胆汁淤积、寄生虫有关）。可无症状，也可引起胆绞痛、梗阻性黄疸、急性胆管炎、急性胰腺炎，是外科常见急症。",30],["疾病编码","K80.5",30],["原首字母","dzgjs",60]]},{"id":"orders-03ffd643ded35ccb1546","key":"v1-c9ccc21dfe2a3058|orders-03ffd643ded35ccb1546","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"梗阻性黄疸","category":"肝胆外科","raw":{"name":"梗阻性黄疸","category":"肝胆外科","summary":"梗阻性黄疸是肝内或肝外胆道因结石、肿瘤（胰头癌、壶腹周围癌、胆管癌）、炎性狭窄、寄生虫等原因发生梗阻，胆汁排出受阻、胆红素反流入血所致的临床综合征，以肝外梗阻最常见。核心是明确『梗阻部位（肝内/肝外、高位/低位）+性质（良性/恶性）+有无合并胆管炎』，并尽快解除梗阻。","symptoms":["皮肤、巩膜黄染（巩膜最先出现且最明显），尿色深黄呈浓茶色，大便颜色变浅甚至呈陶土色","皮肤瘙痒（胆汁酸盐沉积刺激神经末梢），可见抓痕，夜间加重","右上腹或上腹胀痛、隐痛（结石多为绞痛；胰头癌多为持续性隐痛并向腰背放射）","恶性梗阻：进行性消瘦、乏力、食欲减退、贫血（消耗性表现）","合并胆管炎：寒战、高热、腹痛（Charcot三联征），重者休克与神志改变（Reynolds五联征）","Courvoisier征：无痛性胆囊肿大，高度提示胰头癌或壶腹周围癌"],"diagnosis":["肝功能+胆红素分类：直接胆红素升高为主（直接/总>50%），ALP与GGT显著升高（胆汁淤积酶谱），ALT/AST轻中度升高","腹部超声：首选筛查——判断肝内胆管扩张（'平行管征'）、胆总管直径、胆囊是否肿大、有无结石与占位","MRCP（磁共振胰胆管成像）：无创显示胆道树全貌，明确梗阻部位、范围、形态（结石/肿瘤/狭窄）","增强CT（腹部+胰腺）：评估肿瘤大小、胰周血管侵犯、淋巴结与远处转移（可切除性判断）","ERCP：诊疗一体——可造影明确梗阻、取石、刷检/活检、置入支架或鼻胆管引流","PTC/PTCD：肝内胆管扩张、ERCP失败或高位梗阻者，可行经皮肝穿刺胆道引流","肿瘤标志物：CA19-9（胰胆系肿瘤敏感）、CEA、AFP（肝癌）","凝血功能（PT/INR）+维生素K：黄疸致维生素K吸收障碍，凝血异常（术前必查）"],"infusion":["⚠️ 按病因与病情选择方案，切勿全部同时使用！","","方案1（保肝退黄，胆汁淤积首选）：","  用法：腺苷蛋氨酸 1g + 5%葡萄糖 250ml 静滴 qd；还原型谷胱甘肽 1.2g 静滴 qd；多烯磷脂酰胆碱 10ml 静滴 qd","","方案2（补充脂溶性维生素、纠正凝血）：","  用法：维生素K1 10mg 肌注 或（NS 100ml 或 5%GS 100ml）静滴 qd（连用3天复查PT/INR）","","方案3（合并胆管炎抗感染）：","  用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；重症：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案4（围手术期营养支持）：","  用法：中长链脂肪乳+复方氨基酸+葡萄糖（全肠外营养）；白蛋白 10g 静滴（低蛋白者）；必要时输注血浆","","📌 黄疸患者禁用或慎用肝毒性药物（如大剂量对乙酰氨基酚、部分抗生素）；术前需纠正凝血与营养状态。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（利胆退黄）：","用法：熊去氧胆酸 250mg tid（餐后）或 腺苷蛋氨酸肠溶片 500mg bid","药物2（止痒）：","用法：考来烯胺 4g tid（与其他药物间隔4小时）或 西替利嗪 10mg qn；炉甘石洗剂外用〔调 ★ 肾功能不全必须减量；老年减量〕","药物3（保肝辅助）：","用法：多烯磷脂酰胆碱 456mg tid 或 水飞蓟宾 70mg tid","药物4（补充脂溶性维生素）：","用法：维生素AD胶丸 1粒 qd + 维生素K1 10mg 口服/肌注","📌 保肝药不宜多种长期叠加使用（增加肝负担）；以解除梗阻为根本治疗。"],"treatment":["解除梗阻为根本：结石→ERCP+EST取石或胆总管切开取石+T管引流；肿瘤→评估根治性切除（胰十二指肠切除、肝门部胆管癌切除）或姑息性胆道引流","术前减黄（争议但特定情况必要）：TBIL>200～300μmol/L、合并胆管炎、严重营养不良或需行大手术者，先行PTCD/ENBD引流1～2周减黄后再手术","胆道引流方式：内镜下支架（塑料/金属）或ENBD；经皮肝穿刺胆道引流（PTCD）；手术胆肠吻合（不能切除者）","保肝退黄与营养支持：腺苷蛋氨酸 1g 静滴 qd、谷胱甘肽 1.2g 静滴 qd、多烯磷脂酰胆碱 465mg 静滴 qd；肠内营养优先，必要时肠外营养+白蛋白","纠正凝血功能障碍：维生素K1 10mg 静推/肌注 qd、新鲜冰冻血浆 10-15ml/kg 静滴、必要时血小板（PLT<50×10⁹/L 输 1 治疗量）","合并急性胆管炎：紧急胆道减压引流（ENBD/PTCD/手术T管），抗感染（头孢哌酮舒巴坦 3g 静滴 q8h）与液体复苏","术后处理：观察胆汁引流量与性状、黄疸消退情况、肝功能恢复，处理胆漏、出血、感染等并发症"],"management":["每日观察并记录：皮肤巩膜黄染程度、尿色、大便颜色、皮肤瘙痒程度（评估梗阻是否缓解）","黄疸相关护理：温水擦洗、避免搔抓、剪短指甲、涂抹润肤剂，必要时用炉甘石洗剂","引流管护理（PTCD/ENBD/T管）：妥善固定防脱出、保持通畅、记录胆汁量与性状（正常金黄色300～700ml/日）、防止逆行感染","凝血与出血观察：牙龈出血、鼻出血、皮下瘀斑、穿刺点渗血、黑便（黄疸患者凝血差）","营养管理：低脂、高蛋白、高维生素饮食，少量多餐；营养不良者加用肠内营养制剂","术前准备：补充维生素K、备血、评估肾功能与营养，做好手术/ERCP前准备","肾功能保护：黄疸患者易发生急性肾损伤（尤其术后），保证足够灌注与尿量"],"notes":["『黄疸+无痛性胆囊肿大（Courvoisier征）』高度提示胰头癌或壶腹周围癌，需尽快完善影像与肿瘤标志物","梗阻性黄疸与肝细胞性黄疸鉴别关键：直接胆红素比例、ALP/GGT升高程度、尿胆原与影像学","合并胆管炎是急症，必须尽快解除梗阻（引流优先于抗感染）","黄疸患者手术风险高（凝血异常、营养不良、肾功能易损、内毒素血症），围手术期需全面优化","恶性梗阻不能切除者，治疗目标是解除梗阻、改善生活质量与延长生存，需与家属充分沟通"],"emergency":["黄疸伴寒战高热、腹痛、神志改变或血压下降（急性梗阻性化脓性胆管炎）→ 紧急胆道引流+抗感染+抗休克","黄疸伴呕血、黑便、穿刺点渗血（凝血障碍/胆道出血）→ 急诊处理并补充凝血因子","黄疸迅速加深伴意识障碍、扑翼样震颤（肝衰竭）→ 急诊救治并转ICU"],"pinyin":"gzxhd","icd10":"K83.1","physical_exam":["生命体征：体温、脉搏、血压（合并胆管炎/脓毒症时）","皮肤黏膜：巩膜与皮肤黄染程度（自然光下观察）、抓痕、出血点、蜘蛛痣、肝掌","一般情况：消瘦、恶病质（恶性梗阻）、营养状态、精神状态（肝性脑病征象）","腹部视诊：右上腹膨隆、腹壁静脉曲张、手术瘢痕、呼吸运动受限","腹部触诊：肝大小与质地（硬、结节提示肿瘤/肝硬化）、胆囊是否肿大及有无压痛（Courvoisier征）、压痛点","腹部叩诊：肝区叩击痛、移动性浊音（腹水）","直肠指检与淋巴结：直肠膀胱陷凹结节（盆腔转移）、左锁骨上淋巴结（Virchow淋巴结，消化道肿瘤转移）"],"lab_tests":["肝功能+胆红素分类（总/直接/间接）+ALP+GGT：判断梗阻性质（胆汁淤积酶谱）与程度，动态观察消退趋势","凝血酶原时间+INR+血小板：黄疸致维生素K依赖凝血因子合成障碍，术前与治疗中必查","肿瘤标志物（CA19-9、CEA、AFP）：良恶性鉴别与随访监测","血常规+CRP+PCT+血培养：合并胆管炎时评估感染；发热者抗生素前采血培养","MRCP/增强CT（腹部+胰腺）：明确梗阻部位、病因（结石/肿瘤/狭窄）与可切除性","肾功能+电解质+血气分析：黄疸患者易发生急性肾损伤，围手术期监测","尿常规（尿胆红素/尿胆原）+大便颜色：辅助判断完全性或不完全性梗阻"],"nursing":["黄疸观察与记录：每日自然光下对比巩膜与皮肤黄染、尿色与大便颜色，及时发现梗阻加重或缓解","皮肤护理：温水清洁（避免碱性肥皂）、涂抹润肤霜、剪短指甲防抓伤、瘙痒严重者遵医嘱用药","引流管护理：PTCD/ENBD/T管固定牢靠、防止牵拉脱出，记录胆汁量（每日）与性状，注意有无血性、浑浊、絮状物（感染）","出血观察：注意牙龈、鼻腔、穿刺点渗血及黑便，发现异常立即报告（黄疸患者凝血功能差）","营养护理：指导低脂高蛋白高维生素饮食、少量多餐，食欲差者加用肠内营养，记录体重与进食量"],"diet":["低脂饮食（减少脂肪吸收负担，脂肪泻者更需控制），禁用油炸、肥肉与浓汤","适量优质蛋白（鱼、瘦肉、蛋清、豆制品）；肝功能差者遵医嘱调整蛋白量","高维生素：新鲜蔬菜水果，必要时补充脂溶性维生素（A、D、E、K）","少量多餐（每日5～6餐），食物细软易消化，保证足够热量（每日25～30kcal/kg）","禁酒、禁辛辣刺激；恶性梗阻患者必要时给予肠内营养制剂或肠外营养支持"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1311},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"15866ede2580a90e5709f6a6a5ac78fd3c6ecc16aaaa3eb0db0cd110be167e45","pinyin":"gengzuxinghuangdan","initials":"gzxhd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤、巩膜黄染（巩膜最先出现且最明显），尿色深黄呈浓茶色，大便颜色变浅甚至呈陶土色\\n皮肤瘙痒（胆汁酸盐沉积刺激神经末梢），可见抓痕，夜间加重\\n右上腹或上腹胀痛、隐痛（结石多为绞痛；胰头癌多为持续性隐痛并向腰背放射）\\n恶性梗阻：进行性消瘦、乏力、食欲减退、贫血（消耗性表现）\\n合并胆管炎：寒战、高热、腹痛（Charcot三联征），重者休克与神志改变（Reynolds五联征）\\nCourvoisier征：无痛性胆囊肿大，高度提示胰头癌或壶腹周围癌",60],["摘要","梗阻性黄疸是肝内或肝外胆道因结石、肿瘤（胰头癌、壶腹周围癌、胆管癌）、炎性狭窄、寄生虫等原因发生梗阻，胆汁排出受阻、胆红素反流入血所致的临床综合征，以肝外梗阻最常见。核心是明确『梗阻部位（肝内/肝外、高位/低位）+性质（良性/恶性）+有无合并胆管炎』，并尽快解除梗阻。",30],["疾病编码","K83.1",30],["原首字母","gzxhd",60]]},{"id":"orders-984b9fcc8976dfdea187","key":"v1-c9ccc21dfe2a3058|orders-984b9fcc8976dfdea187","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝血管瘤","category":"肝胆外科","raw":{"name":"肝血管瘤","category":"肝胆外科","summary":"肝血管瘤是肝脏最常见的良性肿瘤，以海绵状血管瘤为主，多为体检超声偶然发现。绝大多数无症状、生长缓慢，无需治疗；少数巨大血管瘤可有压迫症状或发生破裂、Kasabach-Merritt综合征，需外科处理。","symptoms":["多数无症状，体检影像学发现","体积较大时右上腹隐痛、饱胀不适、餐后加重","巨大血管瘤可触及腹部包块，压迫周围脏器出现恶心、腹胀","极少数发生瘤内出血、破裂致急腹症、失血性休克","巨大血管瘤偶合并血小板减少、凝血异常（Kasabach-Merritt综合征）"],"diagnosis":["腹部超声：首选，典型为高回声、边界清晰；不典型者需进一步检查","增强CT：动脉期边缘结节状强化、门脉期向中心填充（'早出晚归'样表现）","增强MRI：诊断准确性最高，可见'灯泡征'","超声造影：鉴别血管瘤与肝癌、转移瘤","肝功能、AFP：多正常或轻度异常，AFP正常有助于排除肝癌","必要时穿刺活检：一般不推荐（有出血风险），仅在不典型且不能除外恶性时由多学科讨论"],"infusion":["⚠️ 无症状者无需输液用药。需处理者遵医嘱：","方案1（术前/术后支持）：","用法：0.9%氯化钠/葡萄糖 静滴；维生素K1 10mg 静滴 qd（术前）","方案2（介入栓塞术后）：","用法：0.9%氯化钠 静滴 + 还原型谷胱甘肽 1.2g 静滴 qd + 抗生素（按医嘱）","📌 肝血管瘤禁用抗凝、抗血小板药物（除有明确其他指征并评估风险）。"],"oral_medication":["⚠️ 无症状者无需服药。术后/介入后遵医嘱：","药物1（保肝）：","用法：多烯磷脂酰胆碱 456mg tid 或 还原型谷胱甘肽片 0.4g tid","药物2（对症）：","用法：熊去氧胆酸 250mg tid（腹胀、消化不良）","📌 避免自行服用含雌激素类药物及不明成分的保健品。"],"treatment":["随访观察：直径<5cm、无症状者每6～12个月复查超声，无需治疗","手术切除指征：瘤体直径≥10cm伴明显症状、生长迅速、疑恶变、合并破裂出血或Kasabach-Merritt综合征、诊断不明确不能除外恶性","介入治疗：肝动脉栓塞（TAE）、射频消融（RFA）适用于不能耐受手术或不愿手术者","破裂出血：急诊手术止血+部分肝切除，同时抗休克治疗","巨大血管瘤合并血小板减少：糖皮质激素、必要时手术","妊娠期血管瘤增大者：产科与外科共同随访管理"],"management":["解释病情，消除患者对'肝肿瘤'的恐慌，说明良性性质与随访方案","定期复查：超声每6～12个月，必要时增强CT/MRI评估变化","避免剧烈运动、腹部外伤、重体力劳动（巨大血管瘤防破裂）","监测血常规（血小板）、凝血功能（巨大血管瘤）","术后随访：观察切口、肝功能恢复，定期复查影像","避免使用雌激素类药物（可能促进生长）"],"notes":["肝血管瘤绝大多数为良性，'发现即手术'的观念是错误的，应避免过度治疗","诊断不明确时应与肝癌、肝转移瘤、肝腺瘤、局灶性结节性增生鉴别","巨大血管瘤（>10cm）即使无症状也建议定期复查并评估风险","不推荐常规穿刺活检，确有需要应由有经验的中心实施"],"emergency":["右上腹突发剧痛伴腹膜刺激征、血压下降（瘤体破裂出血）→ 立即抗休克并急诊手术","巨大血管瘤伴皮肤瘀斑、牙龈出血、血小板显著下降 → 急诊评估Kasabach-Merritt综合征","剧烈腹痛伴发热、黄疸（瘤内出血/感染）→ 急诊处理"],"pinyin":"gxgl","icd10":"D18.0","physical_exam":["生命体征：血压、心率（警惕破裂出血）","一般情况：营养、精神状态，多无明显异常","腹部视诊：有无膨隆、腹壁静脉曲张、手术瘢痕","腹部触诊：肝下缘、有无质软可压缩包块、表面是否光滑、有无压痛","腹部叩诊：肝区叩击痛（一般阴性）、移动性浊音","皮肤黏膜：有无出血点、瘀斑（合并凝血异常时）","其他：有无合并其他脏器血管瘤（如皮肤、口腔黏膜）表现"],"lab_tests":["肝功能全套：评估肝细胞功能与有无胆汁淤积，介入/手术前后对比","血常规+凝血功能：巨大血管瘤评估有无血小板减少及凝血异常","AFP+CEA+CA19-9：与肝癌、肝转移瘤鉴别","腹部超声：首选筛查与随访，观察大小、回声及血供变化","增强CT或增强MRI：诊断不明确或拟手术者，明确瘤体范围与邻近血管关系","超声造影：用于不典型病例的良恶性鉴别","必要时肝穿刺活检或PET-CT：高度疑恶性且多学科讨论后决定"],"nursing":["病情观察：较大瘤体者观察腹痛性质、有无突发剧痛及血压下降（破裂预警）","活动指导：避免剧烈运动、腹部撞击、重体力劳动及用力排便","介入/术后护理：观察穿刺点出血、腹痛、发热（栓塞后综合征），按医嘱给予镇痛与保肝治疗","心理护理：解释良性性质，缓解焦虑，提高随访依从性","健康指导：避免服用雌激素类及来源不明的保健品，定期复查"],"diet":["均衡饮食，高维生素（新鲜蔬果）、适量优质蛋白","低脂饮食，减轻肝脏与胆道负担","禁酒，避免辛辣刺激与油炸煎炸食品","避免服用含激素成分的食物与保健品","手术后按医嘱从流质逐步过渡到低脂普食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1312},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"262706ff39064aa8f7df86059d4d20ec5b7d42905c92058cf59e7bd8d7b283f0","pinyin":"ganxueguanliu","initials":"gxgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多数无症状，体检影像学发现\\n体积较大时右上腹隐痛、饱胀不适、餐后加重\\n巨大血管瘤可触及腹部包块，压迫周围脏器出现恶心、腹胀\\n极少数发生瘤内出血、破裂致急腹症、失血性休克\\n巨大血管瘤偶合并血小板减少、凝血异常（Kasabach-Merritt综合征）",60],["摘要","肝血管瘤是肝脏最常见的良性肿瘤，以海绵状血管瘤为主，多为体检超声偶然发现。绝大多数无症状、生长缓慢，无需治疗；少数巨大血管瘤可有压迫症状或发生破裂、Kasabach-Merritt综合征，需外科处理。",30],["疾病编码","D18.0",30],["原首字母","gxgl",60]]},{"id":"orders-49288710fc4437fabd74","key":"v1-c9ccc21dfe2a3058|orders-49288710fc4437fabd74","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝癌破裂出血","category":"肝胆外科","raw":{"name":"肝癌破裂出血","category":"肝胆外科","summary":"原发性肝癌自发性破裂出血是肝癌严重并发症，多见于肿瘤较大、位于肝表面或伴肝硬化的患者。表现为突发右上腹剧痛、腹胀、失血性休克，病死率高，需紧急止血与抗休克治疗。","symptoms":["突发右上腹或全腹剧烈疼痛，可向右肩放射","腹胀、腹部膨隆（腹腔积血），移动性浊音阳性","面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）","恶心、呕吐，可有呕血、黑便（合并食管胃底静脉破裂时）","多有肝硬化、肝癌病史，近期体重下降、乏力、黄疸"],"diagnosis":["血常规：血红蛋白进行性下降，白细胞可升高","腹部超声：可见腹腔积液、肝内占位及破裂征象（首选床旁快速检查）","腹腔穿刺：抽出不凝血是重要诊断依据","增强CT：明确肿瘤部位、大小、破裂处、有无活动性出血及血管受累","AFP、肝功能、凝血功能：评估肝癌背景与肝功能储备","DSA肝动脉造影：既诊断也可栓塞止血"],"infusion":["⚠️ 抢救用，须在监护下按病情选择！","","方案1（抗休克/液体复苏）：","  用法：平衡盐溶液+0.9%氯化钠 快速补液（晶体为主），必要时输注红细胞悬液、血浆；目标Hb 70～90g/L（活动性出血时避免过度升压）","","方案2（止血/降低门脉压）：","  用法：生长抑素 250μg 静推后 3mg/12h 泵入 或 奥曲肽 0.1mg 静推后 25～50μg/h 泵入〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","","方案3（抑酸）：","  用法：艾司奥美拉唑 40mg 静推 bid 或 8mg/h 持续泵入〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案4（保肝）：","  用法：还原型谷胱甘肽 1.2g（NS 100ml 或 5%GS 100ml）静滴 qd + 腺苷蛋氨酸 1g 静滴 qd","","📌 输血、输液速度按血压、尿量、Hb动态调整，警惕过量输液加重出血。"],"oral_medication":["⚠️ 急性出血期禁食禁水，不宜口服给药；稳定后遵医嘱：","药物1（降门脉压，口服序贯）：","用法：普萘洛尔 10mg bid 起（心率不低于55次/分）或 卡维地洛 6.25mg bid","药物2（保肝）：","用法：多烯磷脂酰胆碱 456mg tid 或 恩替卡韦 0.5mg qd（HBV相关肝癌抗病毒）","药物3（利尿，腹水者）：","用法：螺内酯 20～40mg qd + 呋塞米 20mg qd（按尿量与电解质调整）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","📌 抗病毒治疗须长期坚持，不可自行停药。"],"treatment":["紧急抗休克：快速建立2条以上静脉通路、补液输血（晶体液 30ml/kg、Hb<70g/L 输红细胞）、必要时血管活性药（去甲肾上腺素 0.05-0.5μg/kg/min 静滴），纠正凝血异常","止血措施：首选TACE（肝动脉栓塞化疗）栓塞出血动脉；也可行急诊手术（肝部分切除/填塞止血/缝扎）","保守治疗：适用于出血量小、血流动力学稳定、肝功能差不能耐受手术者（卧床、腹带加压、输血、止血药 氨甲环酸 1g 静滴 q8h）","纠正凝血功能障碍：维生素K1 10mg 静推 qd、新鲜冰冻血浆 10-15ml/kg、血小板（PLT<50×10⁹/L 输 1 治疗量）、纤维蛋白原（<1.5g/L 输 2g 静滴）","择期抗肿瘤治疗：出血控制、病情稳定后评估TACE、靶向（索拉非尼 400mg 口服 bid/仑伐替尼 8mg 口服 qd，体重<60kg）、免疫或手术切除","抗病毒治疗（HBV/HCV相关肝癌）：恩替卡韦 0.5mg 口服 qd，或丙通沙 400/100mg 口服 qd 12 周"],"management":["绝对卧床、禁食禁水，避免搬动与用力（防止再出血）","严密监测：意识、血压、心率、尿量、腹围（每1～2小时），动态复查血红蛋白","记录腹腔引流及穿刺引流液量与性状，保持引流通畅","输血输液管理：按医嘱输注血制品，观察有无输血反应","疼痛管理：遵医嘱镇痛，避免使用可能诱发肝损伤的药物","心理支持与家属沟通：病情危重，及时告知风险并签署相关知情同意"],"notes":["肝癌自发性破裂出血是急症，病死率高，'先止血、再治瘤'是基本原则","保守治疗期间仍可能再次破裂，必须严密监测并做好急诊介入/手术准备","合并肝硬化者肝功能储备差，治疗方案选择需评估Child-Pugh分级","出血控制后应尽快制定抗肿瘤方案，单纯止血不改善远期预后"],"emergency":["突发右上腹剧痛伴面色苍白、脉搏细速、血压下降 → 立即抢救，急诊介入/手术","腹腔穿刺抽出不凝血、腹围迅速增大 → 提示活动性出血，紧急处理","呕血、黑便伴休克（合并食管胃底静脉破裂）→ 双通道抢救+内镜/介入止血"],"pinyin":"gxplcx","icd10":"C22.0","physical_exam":["生命体征：血压、心率、呼吸（评估休克程度）、体温","一般情况：面色苍白、皮肤湿冷、意识状态（烦躁或淡漠）、体位","腹部视诊：腹胀、腹围增大、腹壁静脉曲张、有无手术瘢痕","腹部触诊：全腹压痛、反跳痛、肌紧张（腹膜刺激征）、肝区包块及压痛","腹部叩诊：移动性浊音（腹腔积血）、肝浊音界","皮肤黏膜：黄疸、蜘蛛痣、肝掌、瘀斑、注射点渗血","直肠指检：有无黑便（合并消化道出血）"],"lab_tests":["血常规+血型+交叉配血：急查血红蛋白与备血，动态监测下降速度","凝血功能+D-二聚体+纤维蛋白原：评估凝血状态，指导血制品输注","肝功能+胆红素+白蛋白：评估肝储备功能（Child-Pugh分级依据）","AFP+肝炎病毒标志物（HBV/HCV）：明确肝癌背景与抗病毒指征","肾功能+电解质+血气分析：评估休克所致器官损伤与酸碱失衡","床旁腹部超声+腹腔穿刺：快速确认腹腔积血与肿瘤部位","增强CT/DSA血管造影：明确出血部位与血管解剖，指导栓塞治疗"],"nursing":["休克护理：平卧、头偏一侧，快速建立静脉通路，遵医嘱补液输血，每15～30分钟监测生命体征","绝对卧床：禁食禁水，避免翻身过频、用力咳嗽与排便，防止再出血","病情观察：腹痛、腹胀、腹围、尿量、意识及皮肤黏膜出血征象，异常立即报告","介入/术后护理：观察穿刺点出血与血肿、足背动脉搏动，制动肢体制动6～8小时","心理与家属沟通：安抚患者与家属情绪，配合抢救与知情同意签署"],"diet":["急性出血期禁食禁水","出血停止、病情稳定后：从温凉流质（米汤、藕粉）开始，逐步过渡到低盐软食","合并肝硬化者：限盐（<2g/日）、适量优质蛋白（避免肝性脑病时过量）","忌粗糙、坚硬、辛辣及过热食物（防再次出血）","禁酒，避免服用损伤肝脏的药物与保健品"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1313},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d7617e8ebd6bf14ca622423be327f254abc7b9fb6ff4e67bb1da6be1b2352c2a","pinyin":"ganaipoliechuxie","initials":"gaplcx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发右上腹或全腹剧烈疼痛，可向右肩放射\\n腹胀、腹部膨隆（腹腔积血），移动性浊音阳性\\n面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）\\n恶心、呕吐，可有呕血、黑便（合并食管胃底静脉破裂时）\\n多有肝硬化、肝癌病史，近期体重下降、乏力、黄疸",60],["摘要","原发性肝癌自发性破裂出血是肝癌严重并发症，多见于肿瘤较大、位于肝表面或伴肝硬化的患者。表现为突发右上腹剧痛、腹胀、失血性休克，病死率高，需紧急止血与抗休克治疗。",30],["疾病编码","C22.0",30],["原首字母","gxplcx",60]]},{"id":"orders-b64645faa884f7ee5f68","key":"v1-c9ccc21dfe2a3058|orders-b64645faa884f7ee5f68","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"门静脉高压症","category":"肝胆外科","raw":{"name":"门静脉高压症","category":"肝胆外科","summary":"门静脉高压症多由肝硬化引起，表现为脾大脾功能亢进、食管胃底静脉曲张破裂出血、腹水等。食管胃底静脉破裂出血是主要致死原因，治疗原则为止血、降门脉压、预防再出血与处理并发症。","symptoms":["呕血、黑便（食管胃底静脉破裂出血），出血量大可致失血性休克","脾大、脾功能亢进（白细胞、血小板减少，贫血）","腹水、腹胀、下肢水肿","乏力、纳差、消瘦，可有黄疸、蜘蛛痣、肝掌","严重者出现肝性脑病（意识改变、扑翼样震颤）、肝肾综合征"],"diagnosis":["血常规：三系减少（脾功能亢进）","肝功能+白蛋白+胆红素+凝血：评估肝储备（Child-Pugh分级）","胃镜：明确食管胃底静脉曲张程度与有无活动性出血（金标准）","腹部超声+彩色多普勒：脾大、门静脉主干内径（>13mm）、有无血栓及腹水","增强CT/门静脉成像：评估侧支循环、脾静脉及门静脉解剖，为手术/介入做准备","肝弹性检测/肝活检：评估肝纤维化程度与病因","血氨：肝性脑病评估"],"infusion":["⚠️ 抢救与治疗用药，按病情选择！","","方案1（降门脉压）：","  用法：生长抑素 250μg 静推 → 3mg/12h 持续泵入；或奥曲肽 0.1mg 静推 → 25～50μg/h 泵入（连用3～5天）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","","方案2（抑酸）：","  用法：艾司奥美拉唑 40mg 静推 q12h 或 8mg/h 持续泵入〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案3（抗感染预防，肝硬化出血常规）：","  用法：头孢曲松 1～2g（NS 100ml 或 5%GS 100ml）静滴 qd（连用3～7天）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案4（补充凝血/血容量）：","  用法：维生素K1 10mg 静滴 qd；新鲜冰冻血浆、红细胞悬液按需；白蛋白 10g 静滴（低蛋白/腹水）","","📌 出血期避免过量输液（维持Hb 70～90g/L即可），防止门脉压升高再出血。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（预防再出血，一级/二级预防）：","用法：普萘洛尔 10mg bid 起，逐步调整至静息心率下降25%或55～60次/分；或卡维地洛 6.25mg bid","药物2（利尿，腹水）：","用法：螺内酯 40mg qd + 呋塞米 20mg qd（按尿量、体重、电解质调整）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物3（乳果糖，防肝性脑病）：","用法：乳果糖 15～30ml bid～tid，调整至每日2～3次软便〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（抗病毒，HBV/HCV）：","用法：恩替卡韦 0.5mg qd 或 替诺福韦 300mg qd","📌 β受体阻滞剂禁用于心率<55次/分、低血压、哮喘患者。"],"treatment":["急性出血期：禁食、绝对卧床、建立双通道补液，输血维持Hb 70～90g/L，生长抑素/奥曲肽降门脉压，抑酸，预防性抗生素","内镜治疗：急诊内镜下套扎（EVL）或硬化剂注射（EIS）止血，是首选止血手段（24小时内）","三腔二囊管压迫：内镜不可及或失败时的临时止血措施（不超过24小时，警惕误吸与食管损伤）","TIPS：内镜/药物止血失败者的挽救治疗，或高危患者早期TIPS","手术：断流术（贲门周围血管离断+脾切除）或分流术，适用于反复出血、内镜治疗失败者","腹水处理：限盐限水、利尿剂、必要时腹腔穿刺放液+白蛋白；顽固性腹水考虑TIPS","病因治疗：抗病毒、戒酒、保肝治疗"],"management":["出血期监测：意识、血压、心率、尿量、出血量（呕血/黑便），动态复查血红蛋白与凝血","三腔二囊管护理：妥善固定、标记刻度、定时放气（每12～24小时）、观察有无误吸与黏膜损伤","预防肝性脑病：保持大便通畅（乳果糖）、控制蛋白摄入（发作期）、避免大量放腹水与低钾","腹水管理：每日测体重、腹围、尿量，监测电解质与肾功能","饮食：出血活动期禁食，止血后24～48小时开始温凉流质，逐步过渡到软食，忌粗糙硬食","出院指导：规律服用降门脉压药、定期胃镜随访、戒酒、避免重体力劳动与用力排便"],"notes":["食管胃底静脉破裂出血是门脉高压最危险的并发症，首次出血病死率约20%～30%","急性出血期慎用大量晶体液与输血（可升高门脉压），目标Hb 70～90g/L","预防再出血：药物（NSBB）+内镜套扎联合方案，需长期坚持","肝性脑病患者限制蛋白摄入应短期进行，长期过度限制可加重营养不良"],"emergency":["大量呕血、黑便伴血压下降、意识改变 → 立即双通道抢救、急诊内镜止血","出现嗜睡、谵妄、扑翼样震颤（肝性脑病）→ 急诊处理并限制蛋白、降血氨","腹胀急剧加重伴少尿、肾功能恶化（肝肾综合征）→ 急诊评估并转ICU"],"pinyin":"mjmygy","icd10":"K76.6","physical_exam":["生命体征：血压、心率、呼吸、意识（评估休克与肝性脑病）","一般情况：面色灰暗、消瘦、皮肤湿冷、营养状态","皮肤黏膜：蜘蛛痣、肝掌、黄疸、瘀斑、注射点渗血、男性乳房发育","腹部视诊：腹壁静脉曲张（'海蛇头'）、腹围增大、脐疝","腹部触诊：肝大小与质地（硬、结节）、脾大（左肋下可触及）、液波震颤","腹部叩诊：移动性浊音、肝浊音界缩小","神经系统：扑翼样震颤、计算力与定向力（肝性脑病分级）"],"lab_tests":["血常规+血小板：评估脾功能亢进及出血后贫血，需动态复查","肝功能+白蛋白+胆红素+胆碱酯酶：评估肝储备功能（Child-Pugh分级）","凝血酶原时间+INR+纤维蛋白原：肝硬化患者凝血差，出血与术前必查","血氨+电解质+肾功能：肝性脑病与肝肾综合征评估，监测低钾低钠","肝炎病毒标志物+HBV-DNA/HCV-RNA：明确病因、指导抗病毒","胃镜：明确静脉曲张程度、有无红色征及活动性出血（出血后24～48小时内）","腹部超声+多普勒+增强CT：评估门静脉内径、有无血栓、脾大及侧支循环"],"nursing":["出血护理：绝对卧床、头偏一侧防误吸，记录呕血与黑便量，快速建立静脉通路配合抢救","三腔二囊管护理：牵引固定、标记刻度、按时放气减压（每12～24小时放气15～30分钟），观察鼻腔黏膜压迫与有无胸痛、呼吸困难","肝性脑病护理：观察意识、行为异常与扑翼样震颤，保持大便通畅，限制蛋白并按医嘱用药，加床档防坠床","腹水护理：每日测腹围、体重、尿量，限制钠盐摄入，放腹水后观察血压与电解质","饮食护理：出血期禁食，止血后逐步温凉流质→软食，忌粗糙、坚硬、过热食物，戒烟酒"],"diet":["出血活动期严格禁食禁水","止血后24～48小时开始温凉流质（米汤、藕粉），逐步过渡到低盐软食","忌粗糙、坚硬、带刺、油炸及过热食物（防划破曲张静脉）","腹水者限盐（每日<2g）、限水（必要时），保证适量优质蛋白（肝性脑病期遵医嘱调整）","戒酒，少量多餐，细嚼慢咽，保持大便通畅"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1314},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"707557845eed9ec68bcfd7f095214898c5466f761e8de93ce380fd851ef60c98","pinyin":"menjingmaigaoyazheng","initials":"mjmgyz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","呕血、黑便（食管胃底静脉破裂出血），出血量大可致失血性休克\\n脾大、脾功能亢进（白细胞、血小板减少，贫血）\\n腹水、腹胀、下肢水肿\\n乏力、纳差、消瘦，可有黄疸、蜘蛛痣、肝掌\\n严重者出现肝性脑病（意识改变、扑翼样震颤）、肝肾综合征",60],["摘要","门静脉高压症多由肝硬化引起，表现为脾大脾功能亢进、食管胃底静脉曲张破裂出血、腹水等。食管胃底静脉破裂出血是主要致死原因，治疗原则为止血、降门脉压、预防再出血与处理并发症。",30],["疾病编码","K76.6",30],["原首字母","mjmygy",60]]},{"id":"orders-7afaab2e848030c7b80e","key":"v1-c9ccc21dfe2a3058|orders-7afaab2e848030c7b80e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性胰腺炎（重症监护与外科处理）","category":"肝胆外科","raw":{"name":"急性胰腺炎（重症监护与外科处理）","category":"肝胆外科","summary":"急性胰腺炎是胰酶异常激活引起胰腺自身消化的炎症反应，轻症（MAP）多可自愈，重症（SAP）可致胰腺坏死、感染、多器官功能障碍，病死率高。外科处理主要针对感染性坏死、腹腔间隔室综合征与胆源性病因。","symptoms":["突发上腹持续剧烈疼痛，向腰背部放射，弯腰抱膝可稍缓解","恶心、呕吐（呕吐后腹痛不缓解）、腹胀、肠鸣音减弱","发热、心率增快、呼吸急促，重症可出现休克、少尿","黄疸（胆源性）、腹胀明显伴腹膜刺激征（重症）","Grey-Turner征（腰胁部瘀斑）、Cullen征（脐周瘀斑）提示重症"],"diagnosis":["血清淀粉酶/脂肪酶：>正常上限3倍有诊断意义（脂肪酶特异性更高）","血常规+CRP+PCT：CRP>150mg/L提示重症；PCT升高提示感染","腹部增强CT（发病72小时后最佳）：评估胰腺坏死范围、积液及并发症（CTSI评分）","腹部超声：筛查胆结石、胆管扩张（胆源性病因）","肝功能+胆红素+血脂+血钙：明确病因（胆源性/高脂血症性/高钙性）","血气分析+乳酸+肾功能：评估器官功能（呼吸、肾脏）","MRCP/ERCP：疑胆总管结石嵌顿时"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（液体复苏）：","  用法：平衡盐溶液（乳酸钠林格） 5～10ml/kg/h 早期积极补液，6～24小时内评估调整，避免过度复苏","","方案2（抑酸抑酶）：","  用法：艾司奥美拉唑 40mg 静推 q12h；生长抑素 3mg/12h 泵入 或 奥曲肽 25～50μg/h 泵入〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案3（镇痛）：","  用法：布桂嗪 100mg 肌注 或 曲马多 100mg（NS 100ml 或 5%GS 100ml）静滴（必要时）；剧痛可用哌替啶 50mg 肌注","","方案4（抗感染，仅用于感染性坏死/胆管炎）：","  用法：哌拉西林他唑巴坦 4.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 美罗培南 1g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","📌 早期不推荐预防性使用抗生素；禁用吗啡（加重Oddi括约肌痉挛）。"],"oral_medication":["⚠️ 急性期需禁食，不宜口服；恢复期遵医嘱：","药物1（胰酶补充，胰腺外分泌功能不全）：","用法：胰酶肠溶胶囊 1～2粒 随餐服用","药物2（抑酸）：","用法：艾司奥美拉唑 20mg qd（餐前）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物3（降脂，高脂血症性）：","用法：非诺贝特 200mg qd（甘油三酯显著升高者）","📌 恢复期严格低脂饮食，禁酒，避免暴饮暴食。"],"treatment":["禁食、胃肠减压：减轻腹胀与胰腺刺激；早期肠内营养（鼻空肠管）优于肠外营养","液体复苏：早期目标导向补液，维持尿量≥0.5ml/kg/h，避免过度补液致组织水肿","镇痛：充分镇痛（布桂嗪、曲马多，必要时哌替啶），禁用吗啡","抑制胰腺分泌：生长抑素/奥曲肽、质子泵抑制剂","病因治疗：胆源性伴胆管炎/梗阻者急诊ERCP+EST（24～72小时内）；高脂血症性者降脂（血浆置换、贝特类）","感染性坏死处理：感染证据明确后（CT示气泡、PCT升高、临床恶化）先行经皮穿刺引流（PCD），必要时行内镜下坏死组织清除或外科清创（'延迟、引流、必要时清创'原则）","器官功能支持：ARDS者机械通气（小潮气量），急性肾损伤者CRRT，腹腔间隔室综合征者减压"],"management":["严密监测：意识、呼吸、血压、心率、尿量、腹围、体温，动态评估器官功能（SOFA评分）","疼痛评估：每4小时评估疼痛评分，遵医嘱镇痛并观察效果","营养支持：禁食期间静脉营养；肠功能恢复后尽早经鼻空肠管肠内营养（避免经胃喂养）","引流管护理：经皮穿刺引流管固定、记录引流液色质（浑浊、脓性、血性需报告）","血糖管理：胰腺炎常伴应激性高血糖，监测血糖并胰岛素治疗（目标7.8～10mmol/L）","液体与电解质：记录24小时出入量，监测血钙、血钾、血钠，纠正低钙（重症常见）"],"notes":["急性胰腺炎早期（1～2周）以器官支持为主，坏死感染多在2周后出现，手术宜'延迟'","不推荐早期预防性使用抗生素，除非有感染性坏死或胆管炎证据","高脂血症性胰腺炎需将甘油三酯降至5.65mmol/L以下并长期管理，否则易复发","重症患者需多学科（消化、外科、ICU、影像、营养）协作管理"],"emergency":["呼吸急促、血氧下降、少尿（ARDS/急性肾损伤）→ 转入ICU，机械通气/CRRT","高热、腹胀加剧、CT示胰腺坏死积气（感染性坏死）→ 急诊穿刺引流并抗感染","腹内压明显升高伴少尿、气道压升高（腹腔间隔室综合征）→ 急诊减压处理","胆源性胰腺炎伴胆管炎、胆总管梗阻 → 72小时内ERCP+EST"],"pinyin":"jxyxyzzjkywkcl","icd10":"K85.9","physical_exam":["生命体征：体温、脉搏、呼吸、血压、血氧（评估重症与休克）","一般情况：痛苦面容、体位（弯腰抱膝）、意识状态、皮肤湿冷","腹部视诊：腹胀、肠型、腹壁瘀斑（Grey-Turner/Cullen征）","腹部触诊：上腹压痛、肌紧张、反跳痛（腹膜炎）、有无包块（假性囊肿/脓肿）","腹部叩诊：移动性浊音（腹水/胰性腹水）、肝浊音界","腹部听诊：肠鸣音减弱或消失（麻痹性肠梗阻）","肺部：呼吸音减弱（胸腔积液、ARDS）、呼吸频率与深度"],"lab_tests":["血清淀粉酶+脂肪酶：诊断与动态观察（脂肪酶特异性更高、持续更久）","血常规+CRP+PCT：CRP>150mg/L提示重症，PCT升高提示感染性坏死","肝功能+胆红素+GGT/ALP：判断胆源性病因及有无胆道梗阻","血脂（甘油三酯）+血钙：明确高脂血症性、高钙性病因（TG>11.3mmol/L为高危）","血气分析+乳酸+肾功能+电解质：评估器官功能与灌注（重症每12～24小时复查）","增强CT（发病72小时后）：评估坏死范围与并发症（CTSI评分）","腹部超声/MRCP：胆结石、胆管扩张、胰周积液，指导ERCP决策"],"nursing":["疼痛护理：评估疼痛部位、性质与评分，遵医嘱镇痛，协助弯腰屈膝位减轻疼痛","胃肠减压护理：保持胃管通畅、记录引流液的色质量，观察腹胀缓解情况","液体管理：准确记录24小时出入量，监测尿量（≥0.5ml/kg/h）、中心静脉压，警惕肺水肿","营养护理：禁食期间口腔护理，肠内营养经鼻空肠管滴注，注意温度、速度与耐受性（腹胀、腹泻）","重症监护：监测意识、呼吸、血氧、血糖、腹内压，发现器官功能恶化立即报告"],"diet":["急性期严格禁食禁水（必要时胃肠减压）","腹痛缓解、肠鸣音恢复、血淀粉酶下降后：从无脂流质（米汤、稀藕粉）开始","逐步过渡：低脂流质→低脂半流质→低脂软食，少量多餐","长期严格低脂饮食：禁油炸、肥肉、动物内脏、浓汤；禁酒、戒烟","高脂血症者控制总热量与碳水，增加膳食纤维；恢复期适量优质蛋白"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1315},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"09d361cce9a44b3aaf3481e28c759da60d7183cd59b77ddf071269e550999365","pinyin":"jixingyixianyan（zhongzhengjianhuyuwaikechuli）","initials":"jxyxy（zzjhywkcl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发上腹持续剧烈疼痛，向腰背部放射，弯腰抱膝可稍缓解\\n恶心、呕吐（呕吐后腹痛不缓解）、腹胀、肠鸣音减弱\\n发热、心率增快、呼吸急促，重症可出现休克、少尿\\n黄疸（胆源性）、腹胀明显伴腹膜刺激征（重症）\\nGrey-Turner征（腰胁部瘀斑）、Cullen征（脐周瘀斑）提示重症",60],["摘要","急性胰腺炎是胰酶异常激活引起胰腺自身消化的炎症反应，轻症（MAP）多可自愈，重症（SAP）可致胰腺坏死、感染、多器官功能障碍，病死率高。外科处理主要针对感染性坏死、腹腔间隔室综合征与胆源性病因。",30],["疾病编码","K85.9",30],["原首字母","jxyxyzzjkywkcl",60]]},{"id":"orders-12000d00d7fdf690c01a","key":"v1-c9ccc21dfe2a3058|orders-12000d00d7fdf690c01a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"乳腺脓肿（哺乳期）","category":"甲状腺乳腺外科","raw":{"name":"乳腺脓肿（哺乳期）","category":"甲状腺乳腺外科","summary":"乳腺脓肿是哺乳期急性乳腺炎未及时控制、炎症局限液化形成的脓腔，多见于初产妇产后3～4周。表现为乳房局部红肿热痛、波动感包块，伴发热，需及时切开引流并保持排乳通畅。","symptoms":["乳房局部红肿、灼热、剧痛，可触及波动性包块","发热、寒战、乏力，体温可达38.5℃以上","患侧乳房排乳不畅或乳汁呈絮状、脓性","同侧腋窝淋巴结肿大伴压痛","脓肿破溃后可见脓液流出，疼痛缓解"],"diagnosis":["乳房超声：首选，明确脓肿部位、大小、数目、是否多房（可引导穿刺）","血常规+CRP：白细胞升高、CRP升高","乳汁/脓液细菌培养及药敏：指导抗生素选择（金黄色葡萄球菌最常见）","必要时穿刺抽脓：既诊断又治疗（浅表脓肿）","体温与局部体征动态评估：判断是否形成脓肿（波动感是重要体征）"],"infusion":["⚠️ 兼顾哺乳安全，选择方案时注意药物是否影响哺乳！","","方案1（抗感染，哺乳期可用）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 头孢曲松 2g 静滴 qd（哺乳期相对安全）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（青霉素过敏）：","  用法：克林霉素 0.6g（NS 100ml 或 5%GS 100ml）静滴 q8h（哺乳期可用）","","方案3（支持/退热）：","  用法：0.9%氯化钠 静滴；对乙酰氨基酚 0.5g 必要时（哺乳期安全）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 避免使用四环素类、喹诺酮类、磺胺类（影响婴儿）；用药期间可按医嘱继续哺乳或暂停患侧哺乳。"],"oral_medication":["⚠️ 哺乳期用药，选择对婴儿安全的药物！","药物1（抗感染序贯）：","用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（青霉素过敏）：","用法：克林霉素 0.3g tid","药物3（对症）：","用法：对乙酰氨基酚 0.5g 必要时（退热镇痛，哺乳期安全）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 避免使用喹诺酮类、四环素类、磺胺类及甲硝唑大剂量；服药期间观察婴儿有无腹泻、皮疹。"],"treatment":["切开引流：脓肿形成后主要治疗手段，行放射状切口（避免损伤乳管）、充分分离多房脓腔、放置引流条","穿刺抽脓：适用于直径<5cm的浅表单房脓肿（超声引导下），可反复穿刺+冲洗","抗感染：选择哺乳期安全抗生素（如 头孢呋辛 0.5g 口服 bid），疗程10～14天，按药敏调整","保持排乳通畅：患侧继续排乳（可挤奶弃去或按医嘱哺乳），避免乳汁淤积","退热镇痛：对乙酰氨基酚 0.5g 口服 q6h（24h≤4次）或布洛芬 0.4g 口服 q8h（哺乳期可用）","脓肿破溃或引流后：每日换药，观察引流是否通畅"],"management":["排乳管理：指导正确哺乳姿势与含接方式，哺乳后手法挤奶或用吸奶器排空患侧","切口换药：观察引流液量与性状，引流条逐渐拔除，保持引流通畅","哺乳指导：患侧可继续哺乳（除非脓液污染乳头），健侧正常哺乳，用药按医嘱","疼痛管理：哺乳前热敷、哺乳后冷敷，必要时遵医嘱镇痛","观察体温与局部红肿变化，警惕脓肿复发或多房脓肿残留","纠正乳头皲裂（哺乳后涂乳汁或羊脂膏）以防复发"],"notes":["哺乳期乳腺炎的关键是'排空乳汁+抗感染'，脓肿形成必须引流，抗生素不能替代引流","切口应取放射状以减少乳管损伤；乳晕部脓肿取乳晕边缘弧形切口","超声显示多房脓肿或脓腔分隔时应充分分离，避免残留导致复发","继续哺乳不会使婴儿感染（致病菌多为金黄色葡萄球菌），反而有利于恢复"],"emergency":["高热寒战伴乳房红肿迅速扩大、皮肤发紫黑（乳房的坏死性筋膜炎）→ 急诊手术清创","脓肿破溃大出血或引流后持续高热 → 急诊评估并调整治疗","出现感染性休克征象 → 立即抢救"],"pinyin":"rnzzbry","icd10":"O91.1","physical_exam":["生命体征：体温、脉搏、血压（评估感染程度）","一般情况：精神状态、有无脱水及中毒症状","乳房视诊：红肿范围、皮肤颜色（有无发紫发黑）、破溃口、乳头皲裂或内陷","乳房触诊：包块部位、大小、边界、波动感、压痛程度、有无多房分隔","腋窝触诊：淋巴结大小、数目、压痛（同侧腋窝）","对侧乳房检查：有无对称病变或积乳","哺乳情况询问：哺乳频次、含接姿势、有无乳头损伤"],"lab_tests":["血常规+CRP：入院急查评估感染程度，治疗后3～5天复查","乳汁/脓液细菌培养+药敏：用药前留取，指导目标性抗感染（多为金黄色葡萄球菌）","乳房超声：明确脓肿数目、大小、部位及是否多房，超声引导穿刺/引流","PCT+血培养（高热寒战者）：排除脓毒症","血糖：反复发作或愈合差者排查糖尿病","肝功能+肾功能：选择抗生素前评估脏器功能（哺乳期用药安全）"],"nursing":["乳房护理：按医嘱热敷/冷敷，指导哺乳前后排空乳汁，保持乳头清洁干燥","切口护理：换药时观察引流液色质量，保持引流条通畅，注意无菌操作","体温监测：每4小时测体温，高热时物理降温并遵医嘱用药","哺乳指导：示范正确含接与哺乳姿势，教会手法挤奶，避免乳汁淤积","心理护理：哺乳期患者焦虑明显，解释继续哺乳的益处，减轻负罪感与压力"],"diet":["清淡易消化饮食，高蛋白（鱼、瘦肉、蛋、奶）促进炎症修复","多饮水（每日2000ml以上），保证乳汁分泌","多食新鲜蔬菜水果补充维生素C，增强抵抗力","忌辛辣刺激、油腻及酒类","保证充足热量摄入（哺乳期需额外300～500kcal/日）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1316},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"701a0e229d08d3623eee5e76653601eff6679933a9fa36ad76f1793af92d9e7b","pinyin":"ruxiannongzhong（buruqi）","initials":"rxnz（brq）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乳房局部红肿、灼热、剧痛，可触及波动性包块\\n发热、寒战、乏力，体温可达38.5℃以上\\n患侧乳房排乳不畅或乳汁呈絮状、脓性\\n同侧腋窝淋巴结肿大伴压痛\\n脓肿破溃后可见脓液流出，疼痛缓解",60],["摘要","乳腺脓肿是哺乳期急性乳腺炎未及时控制、炎症局限液化形成的脓腔，多见于初产妇产后3～4周。表现为乳房局部红肿热痛、波动感包块，伴发热，需及时切开引流并保持排乳通畅。",30],["疾病编码","O91.1",30],["原首字母","rnzzbry",60]]},{"id":"orders-8589e51abb7198352a5b","key":"v1-c9ccc21dfe2a3058|orders-8589e51abb7198352a5b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺术后并发症处理","category":"甲状腺乳腺外科","raw":{"name":"甲状腺术后并发症处理","category":"甲状腺乳腺外科","summary":"甲状腺手术后常见并发症包括术后出血（可致窒息）、喉返神经与喉上神经损伤、甲状旁腺功能减退（低钙）、甲状腺危象、切口感染等。术后48小时内以出血与呼吸困难最危险，需重点观察。","symptoms":["颈部肿胀、切口渗血、引流血量增多（术后出血）","呼吸困难、发绀、颈部紧迫感（血肿压迫气管，危急）","声音嘶哑、饮水呛咳（喉返神经/喉上神经损伤）","口周及手足麻木、手足抽搐（甲状旁腺损伤致低钙）","高热、心率>120次/分、烦躁（甲状腺危象）"],"diagnosis":["术后监测：生命体征、颈部肿胀、引流量（每1～2小时观察，术后6～12小时最关键）","血钙+血磷+白蛋白：术后1～2天查，低钙者每日复查","血甲状旁腺激素（PTH）：评估甲状旁腺功能","甲状腺功能（FT3/FT4/TSH）：评估术后甲状腺功能状态","血气分析+血氧：呼吸困难者评估缺氧程度","颈部超声/床旁检查：评估血肿范围与气道受压","间接喉镜/纤维喉镜：评估声带运动（声音嘶哑者）"],"infusion":["⚠️ 按并发症选择方案，切勿全部同时使用！","","方案1（低钙抽搐）：","  用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（10min以上），必要时重复；继以10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持（监测血钙、心电图QT间期）","","方案2（甲状腺危象）：","  用法：丙硫氧嘧啶 600mg 鼻饲/口服后 200mg q8h + 碘剂（服PTU后1小时给复方碘溶液）+ 普萘洛尔 20～40mg q6h + 氢化可的松 100mg（NS 100ml 或 5%GS 100ml）静滴 q8h〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案3（止血/支持）：","  用法：氨甲环酸 0.5g（NS 100ml 或 5%GS 100ml）静滴（必要时）；维生素C、补液支持；必要时输血〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","📌 葡萄糖酸钙静推速度必须缓慢（<2ml/min），防止心脏抑制；监测心电图与血钙。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（补钙，低钙者长期）：","用法：碳酸钙D3 600mg bid～tid + 骨化三醇 0.25～0.5μg qd（血钙正常后可逐渐减停）","药物2（甲状腺功能替代/抑制）：","用法：左甲状腺素钠 25～50μg qd 起（术后甲减，晨起空腹服）或 根据TSH调整","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 左甲状腺素需空腹服用，与钙剂间隔4小时以上；补钙方案需按血钙动态调整。"],"treatment":["术后出血：颈部肿胀、呼吸困难立即床旁打开切口清除血肿，必要时急诊气管插管/气管切开+手术探查止血","喉返神经损伤：多为暂时性，予神经营养药（甲钴胺 0.5mg 口服 tid、维生素B1 10mg 口服 tid）、理疗，观察3～6个月；双侧损伤致呼吸困难需气管切开","低钙抽搐：静脉补钙（10%葡萄糖酸钙 10-20ml 稀释后缓慢静推/静滴）+ 口服钙剂（碳酸钙 0.6g 口服 tid）与骨化三醇 0.25μg 口服 qd，监测血钙至稳定","甲状腺危象：禁食、物理降温、PTU 600mg 口服/鼻饲 首剂后 200mg q8h、碘剂（复方碘溶液 5滴 口服 q6h，服PTU后1h再用）、β受体阻滞剂（普萘洛尔 20-40mg 口服 q6h）、糖皮质激素（氢化可的松 100mg 静滴 q8h）、补液与支持治疗","喉上神经损伤：进水呛咳者改为固体食物+小口饮水，多数可代偿恢复","切口感染/积液：换药、必要时引流+抗生素（头孢呋辛 1.5g 静滴 q8h）"],"management":["术后体位：取半卧位，利于呼吸与引流；颈部勿过度活动","引流观察：记录引流液量与性状，术后24小时引流量<50ml可考虑拔管","呼吸道管理：床旁备气管切开包、吸引器；观察有无呼吸困难、喘鸣、颈部肿胀","声音评估：每日评估声音变化并记录，声嘶者避免长时间说话","血钙监测与宣教：告知低钙症状（口周麻木、手足抽搐），出现时立即报告","术后随访：术后1个月复查甲功、血钙，评估是否需要激素替代治疗"],"notes":["术后48小时内最危险的并发症是出血致气道压迫，必须床旁观察，随时准备打开切口","暂时性甲状旁腺功能减退多在数周内恢复，永久性者需终身补钙与维生素D","喉返神经损伤多为暂时性（术后3～6个月恢复），双侧损伤须警惕窒息","甲状腺危象多发生于术前准备不充分的甲亢患者，重在预防（术前控制甲功、服碘）"],"emergency":["术后颈部迅速肿胀、呼吸困难、喘鸣、发绀 → 立即床旁拆线清除血肿，必要时气管插管/切开","手足抽搐伴喉痉挛、意识改变（重度低钙）→ 立即静脉缓慢推注葡萄糖酸钙","高热>39℃、心率>140次/分、烦躁谵妄（甲状腺危象）→ 立即按危象抢救"],"pinyin":"jzxshbfzcl","icd10":"T81.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压、血氧（重点：呼吸与颈部情况）","颈部：切口有无渗血渗液、颈部肿胀程度、有无皮下瘀斑与波动感","呼吸道：呼吸频率与深度、有无喘鸣、三凹征、声音嘶哑程度","神经系统：面部与口周感觉、Chvostek征与Trousseau征（低钙）、声带功能","引流管：位置、引流量与性状、是否通畅","一般情况：精神状态（烦躁提示危象或缺氧）、皮肤温度与湿度","心脏：心率、心律（低钙可致QT延长、心律失常）"],"lab_tests":["血钙+血磷+白蛋白+镁：术后1～2天必查，低钙者每日复查至稳定","甲状旁腺激素（PTH）：评估甲状旁腺损伤程度与恢复可能","甲状腺功能（FT3、FT4、TSH）：术后评估甲状腺功能与替代治疗剂量","血常规+CRP：评估出血、感染情况","血气分析+血氧饱和度：呼吸困难者评估缺氧与二氧化碳蓄积","凝血功能：术后出血者评估凝血状态","心电图（必要时）：低钙时监测QT间期延长；危象时监测心律失常"],"nursing":["重点观察：术后6～12小时内每30～60分钟观察颈部肿胀、呼吸、引流量与声音变化","体位护理：血压平稳后取半卧位，头颈部制动，避免剧烈咳嗽与颈部过伸","急救准备：床旁备气管切开包、吸引器、氧气、葡萄糖酸钙，随时配合抢救","低钙观察：询问口周麻木、手足麻刺感，观察Chvostek征，出现抽搐立即报告并备钙剂","引流管护理：妥善固定，记录引流量与性状，防止脱出与逆行感染"],"diet":["术后6小时可进温凉流质（避免过热引起切口渗血）","逐步过渡到半流质、软食，1～2天内恢复正常饮食","高蛋白、高维生素饮食促进切口愈合","低钙者增加含钙食物（牛奶、豆制品、虾皮），并按医嘱服钙剂与维生素D","呛咳者进食固体食物、小口慢咽，避免稀薄液体呛入气道"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1317},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1bb23fc77816db153cdc6e5d3f789afe9c2901ad555db5dcb08016c41cf0a081","pinyin":"jiazhuangxianshuhoubingfazhengchuli","initials":"jzxshbfzcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","颈部肿胀、切口渗血、引流血量增多（术后出血）\\n呼吸困难、发绀、颈部紧迫感（血肿压迫气管，危急）\\n声音嘶哑、饮水呛咳（喉返神经/喉上神经损伤）\\n口周及手足麻木、手足抽搐（甲状旁腺损伤致低钙）\\n高热、心率>120次/分、烦躁（甲状腺危象）",60],["摘要","甲状腺手术后常见并发症包括术后出血（可致窒息）、喉返神经与喉上神经损伤、甲状旁腺功能减退（低钙）、甲状腺危象、切口感染等。术后48小时内以出血与呼吸困难最危险，需重点观察。",30],["疾病编码","T81.0",30],["原首字母","jzxshbfzcl",60]]},{"id":"orders-28ffcd9d8702b213cca0","key":"v1-c9ccc21dfe2a3058|orders-28ffcd9d8702b213cca0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"消化道吻合口瘘","category":"胃肠外科","raw":{"name":"消化道吻合口瘘","category":"胃肠外科","summary":"消化道吻合口瘘是胃肠手术后严重并发症，多见于食管胃吻合、结直肠吻合、小肠吻合术后，常发生于术后5～7天。表现为发热、腹痛、腹膜炎体征、引流液异常，重者可致腹腔感染、脓毒症与多器官功能障碍。","symptoms":["术后5～7天出现发热（常为持续高热或体温再次升高）","腹痛、腹胀、腹膜炎体征（压痛、反跳痛、肌紧张）","引流管引出浑浊液体、肠内容物、胆汁样或粪样液体","心率增快、呼吸急促、白细胞与CRP升高","重者出现血压下降、少尿、意识改变（脓毒症）"],"diagnosis":["引流液检查：引流液胆红素、淀粉酶、肌酐测定（与血清比较判断是否为消化液）","口服亚甲蓝试验：口服亚甲蓝后引流液变蓝提示吻合口瘘","腹部CT（含口服造影剂）：明确瘘口位置、腹腔积液与脓肿范围（首选）","上消化道造影/泛影葡胺造影：明确瘘口部位与大小（食管胃吻合口瘘）","血常规+CRP+PCT+血培养：评估感染程度与脓毒症","腹部超声：评估腹腔积液、脓肿位置（可引导穿刺）","内镜检查：谨慎使用，必要时明确瘘口情况"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（抗感染，覆盖G-杆菌+厌氧菌+肠球菌）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（重症/腹腔感染）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案2（营养支持）：","用法：全肠外营养（葡萄糖+氨基酸+脂肪乳+电解质+维生素），经中心静脉输注；必要时补充白蛋白","方案3（液体复苏/器官支持）：","用法：平衡盐溶液按需补液；去甲肾上腺素泵入（脓毒症休克者）；艾司奥美拉唑 40mg 静推 q12h〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","📌 抗感染需覆盖肠道菌群并按培养结果调整；营养支持优先考虑肠内（瘘口远端造瘘喂养）。"],"oral_medication":["⚠️ 急性期需禁食，不宜口服给药；恢复期遵医嘱：","药物1（抑酸）：","用法：艾司奥美拉唑 20mg qd（减少消化液分泌）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（消化酶/止泻，恢复期）：","用法：胰酶肠溶胶囊 1～2粒 随餐；蒙脱石散 3g tid（腹泻者）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物3（益生菌）：","用法：双歧杆菌三联活菌 2粒 bid（恢复期调节肠道菌群）","📌 恢复饮食须经主管医师评估瘘口愈合情况后逐步进行。"],"treatment":["充分引流：最关键措施——经皮穿刺置管引流（超声/CT引导）或原引流管冲洗引流，避免脓液积聚","禁食+胃肠减压：减少消化液经瘘口漏出，食管胃吻合口瘘需持续胃肠减压","抗感染：早期经验性广谱，如哌拉西林他唑巴坦 4.5g 静滴 q8h 或头孢哌酮舒巴坦 3g 静滴 q8h，据培养调整，注意腹腔脓肿形成","营养支持：早期肠外营养，条件允许时行瘘口远端肠内营养（肠瘘远端造瘘喂养）","生长抑素/奥曲肽：奥曲肽 0.1mg 皮下注射 q8h，减少消化液分泌，促进瘘口愈合","手术指征：引流不畅伴弥漫性腹膜炎、保守治疗无效、瘘口大（>1cm）或吻合口完全裂开、大出血","器官功能支持：脓毒症休克（去甲肾上腺素 0.05-0.5μg/kg/min 静滴泵入）、ARDS、急性肾损伤的相应处理"],"management":["严密监测：体温、心率、血压、尿量、腹痛及腹膜刺激征，动态评估脓毒症（qSOFA、SOFA）","引流管护理：保持通畅（低压冲洗、避免负压过大），准确记录引流量与性状变化","皮肤护理：瘘口周围皮肤用皮肤保护剂/造口粉保护，防止消化液腐蚀","营养评估与支持：每日计算热量与氮量，监测前白蛋白、白蛋白与体重","出入量管理：准确记录24小时出入量，纠正水电解质与酸碱失衡","心理护理与家属沟通：病程长、费用高，需耐心解释并取得配合"],"notes":["吻合口瘘的关键是『充分引流+营养支持+抗感染』，多数可通过保守治疗愈合","引流不彻底是治疗失败的主要原因，脓肿形成必须及时穿刺或手术引流","术后5～7天是吻合口瘘高发期，此期间出现不明原因发热、心率增快、腹痛需高度警惕","营养状况差、低蛋白、糖尿病、长期使用激素者吻合口瘘风险高"],"emergency":["弥漫性腹膜炎伴血压下降（吻合口裂开+腹腔感染性休克）→ 急诊手术探查","引流管引出大量新鲜血液（吻合口出血）→ 急诊内镜/手术止血","呼吸困难、血氧下降（脓毒症致ARDS）→ 转ICU机械通气支持"],"pinyin":"xhwdkhl","icd10":"T81.8","physical_exam":["生命体征：体温、脉搏、呼吸、血压、血氧（评估脓毒症）","一般情况：精神、面色、皮肤弹性（脱水）、营养状态","腹部视诊：切口有无红肿渗液、腹部膨隆、肠型","腹部触诊：压痛、反跳痛、肌紧张（腹膜炎范围）、有无包块（脓肿）","腹部叩诊：移动性浊音（腹腔积液）、肝浊音界","腹部听诊：肠鸣音减弱或消失（麻痹性肠梗阻）","引流管：位置、引流量与性状（浑浊、胆汁样、粪样）、周围皮肤情况"],"lab_tests":["血常规+CRP+PCT：评估感染严重程度，每2～3天复查","引流液生化（胆红素、淀粉酶、肌酐）：判断是否为消化液，协助定位瘘口","血培养+引流液培养及药敏：指导目标性抗感染","肝功能+白蛋白+前白蛋白：评估营养状态与肝脏功能","电解质+肾功能+血气分析：评估脱水、酸碱失衡与器官功能","腹部CT（含口服造影剂）：明确瘘口位置、腹腔积液与脓肿","消化道造影（泛影葡胺）：明确瘘口部位、大小及是否通畅引流"],"nursing":["病情观察：每小时监测生命体征（发热、心率增快、血压下降提示病情恶化），观察腹痛与腹膜炎体征变化","引流护理：保持引流管通畅，记录引流量与性状，冲洗时严格无菌，避免负压过大损伤组织","皮肤护理：瘘口周围皮肤及时清洁，涂抹氧化锌软膏或造口护肤粉，防止消化液腐蚀","营养护理：肠外营养配置与输注规范（现配现用、定时定量），肠内营养注意温度、速度与耐受","发热护理：物理降温、补充水分，观察有无寒战与感染加重"],"diet":["急性期严格禁食禁水，行胃肠减压与肠外营养","瘘口愈合、引流减少、肠功能恢复后：从少量温开水试饮开始","逐步过渡：清流质→流质→低渣半流质→软食，避免高纤维、产气与刺激性食物","高蛋白、高热量、易消化饮食，少量多餐促进愈合","食管胃吻合口瘘患者进食后保持半卧位30分钟以上，防反流"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1318},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5f1db69ee4a94fbd974721423aa522d9baee7d0d028c0ca687eb07e24cd34a24","pinyin":"xiaohuadaowenhekoulou","initials":"xhdwhkl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后5～7天出现发热（常为持续高热或体温再次升高）\\n腹痛、腹胀、腹膜炎体征（压痛、反跳痛、肌紧张）\\n引流管引出浑浊液体、肠内容物、胆汁样或粪样液体\\n心率增快、呼吸急促、白细胞与CRP升高\\n重者出现血压下降、少尿、意识改变（脓毒症）",60],["摘要","消化道吻合口瘘是胃肠手术后严重并发症，多见于食管胃吻合、结直肠吻合、小肠吻合术后，常发生于术后5～7天。表现为发热、腹痛、腹膜炎体征、引流液异常，重者可致腹腔感染、脓毒症与多器官功能障碍。",30],["疾病编码","T81.8",30],["原首字母","xhwdkhl",60]]},{"id":"orders-658d5066955ccdee50b0","key":"v1-c9ccc21dfe2a3058|orders-658d5066955ccdee50b0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肠造口管理","category":"胃肠外科","raw":{"name":"肠造口管理","category":"胃肠外科","summary":"肠造口是将肠管经腹壁引出形成的排泄通道，分为结肠造口（多为单腔/双腔，排泄物较稠）与回肠造口（排泄物稀、含消化酶，易致皮肤损伤）。重点在于造口护理、并发症防治与生活质量指导。","symptoms":["造口周围皮肤红肿、糜烂、疼痛（排泄物刺激或底盘过敏）","造口水肿、出血、狭窄、回缩或脱垂","排泄物量多、稀薄（回肠造口）致脱水与电解质紊乱","造口排气、排便不受控制，气味与外观影响心理状态","造口周围皮肤感染、真菌感染或肉芽组织增生"],"diagnosis":["造口评估：类型、位置、大小、形状、颜色（正常为红色/粉红色、湿润）","造口周围皮肤评估：用DET评分（颜色改变、糜烂、组织增生）评估皮肤损伤程度","排泄物评估：量、性状、气味，回肠造口量>1000ml/日需警惕脱水","电解质+肾功能：回肠造口高排量者监测","造口指诊（结肠造口术后6周）：评估有无狭窄","必要时造口造影/内镜：评估狭窄、脱垂、瘘等情况"],"infusion":["⚠️ 按病情选择，切勿全部同时使用！","","方案1（回肠造口高排量致脱水）：","  用法：0.9%氯化钠 500～1000ml 静滴；必要时补钾（见尿补钾）；监测电解质","","方案2（造口周围严重皮肤损伤继发感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（按药敏调整）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（营养支持，高排量/营养不良）：","  用法：肠外营养或肠内营养液缓慢滴注","","📌 补液需根据造口排出量调整，避免过量或不足；出现少尿、口干、头晕及时就诊。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（减少排泄量/减慢肠蠕动）：","用法：洛哌丁胺 2mg tid～qid（回肠造口高排量，餐前30分钟服用）","药物2（止泻/吸附）：","用法：蒙脱石散 3g tid 或 双歧杆菌三联活菌 2粒 bid〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物3（皮肤护理）：","用法：氧化锌软膏（造口周围皮肤保护）、造口护肤粉+皮肤保护膜","📌 避免自行服用泻药、产气药及含镁抗酸剂；服用片剂需注意是否完整排出（吸收不良）。"],"treatment":["造口护理规范：选择合适尺寸的造口底盘（孔径大于造口1～2mm），更换频次（回肠造口2～3天，结肠造口3～7天）","皮肤损伤处理：清洁后使用造口护肤粉+皮肤保护膜，严重者用无酒精皮肤保护剂，避免用含酒精或油性产品","造口狭窄：定期指诊扩张（术后6周后），严重者手术重建","造口脱垂/回缩：使用合适凸面底盘与腹带，必要时手术","高排量管理：洛哌丁胺、补液、低渣饮食，必要时静脉补液","造口旁疝预防：避免提重物与腹压增高，使用造口腹带","心理与生活指导：饮食、沐浴、运动、工作与性生活指导，必要时心理支持"],"management":["每日观察造口颜色（暗红、发黑提示缺血）、水肿、出血与排泄物","教会患者/家属自行更换造口袋，出院前至少掌握1次完整操作","记录每日造口排出量与性状，回肠造口>1000～1500ml/日需就医","饮食指导：细嚼慢咽、少量多餐，避免产气（豆类、洋葱、碳酸饮料）与易堵塞食物（玉米、蘑菇、坚果）","造口周围皮肤每次更换时评估并记录，出现损伤及时处理","定期随访：术后1、3、6个月门诊随访，评估造口与营养状态"],"notes":["回肠造口排泄物含消化酶，对皮肤腐蚀性强，底盘必须严密贴合、及时更换","造口本身无痛觉神经，出现疼痛多来自周围皮肤或腹壁问题","造口不是疾病而是治疗手段，多数患者可恢复正常生活、工作与社交","结肠造口灌洗可帮助部分患者建立规律排便，需在专业人员指导下开展"],"emergency":["造口颜色变暗、发黑、剧烈疼痛（造口缺血坏死）→ 立即就医","造口大量出血、脱垂不能回纳或嵌顿 → 急诊处理","回肠造口排出量骤增伴口干、头晕、少尿（严重脱水）→ 急诊补液","腹痛、腹胀、停止排气排便（造口梗阻）→ 急诊就诊"],"pinyin":"czkgl","icd10":"Z93.2","physical_exam":["生命体征：体温、脉搏、血压（脱水者可有心率增快、血压下降）","一般情况：营养状态、皮肤弹性、体重变化","造口评估：类型、位置、大小、颜色（正常红色/粉红、湿润、有光泽）、水肿情况","造口功能：排气排便情况、排泄物量、性状与气味","造口周围皮肤：有无红肿、糜烂、皮疹、真菌感染、肉芽增生（DET评分）","腹部检查：有无造口旁疝（站立位与卧位对比）、腹壁紧张度、有无压痛","造口指诊（术后6周）：评估内径有无狭窄（正常可容指尖）"],"lab_tests":["电解质+肾功能：回肠造口高排量者监测低钠、低钾、低镁及肾功能（每1～2周）","血常规+白蛋白+前白蛋白：评估营养状态与贫血（造口患者常见）","造口周围皮肤分泌物培养：皮肤感染或真菌感染时留取","维生素B12（回肠造口/末端回肠切除者）：每年监测，必要时肌注补充","血糖+糖化血红蛋白：糖尿病患者（影响造口周围皮肤愈合）","必要时造口造影/内镜：评估狭窄、脱垂、瘘或梗阻"],"nursing":["造口护理操作：更换造口袋时动作轻柔，清洁用温水与软纱布（不用酒精、碘伏），测量造口尺寸选择合适底盘","皮肤保护：每次更换评估皮肤，使用造口护肤粉+保护膜，底盘粘贴后按压30～60秒确保密封","观察要点：造口颜色、水肿、出血、排泄物量性状，发现异常（发黑、剧痛、高排量）立即报告","饮食指导：细嚼慢咽、定时进餐、避免产气与堵塞食物，回肠造口者注意补充水分与电解质","心理护理：鼓励表达感受，介绍造口康复者经验，指导沐浴、运动、着装与社交，减轻自卑与焦虑"],"diet":["少量多餐（每日5～6餐），细嚼慢咽，定时进食形成规律排便","回肠造口：低渣饮食为主，限制高纤维食物，注意补充水分与电解质（含钠钾饮品）","避免产气食物：豆类、洋葱、萝卜、碳酸饮料、啤酒","避免易堵塞食物：玉米、蘑菇、芹菜、坚果、带籽水果（回肠造口尤需注意）","避免刺激性食物：辛辣、油腻、酒精；结肠造口者可适量增加膳食纤维调节排便"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1319},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0da621de547a809816ba05b14b3f879887c8d18f7a23ac15d078034c05c151aa","pinyin":"changzaokouguanli","initials":"czkgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","造口周围皮肤红肿、糜烂、疼痛（排泄物刺激或底盘过敏）\\n造口水肿、出血、狭窄、回缩或脱垂\\n排泄物量多、稀薄（回肠造口）致脱水与电解质紊乱\\n造口排气、排便不受控制，气味与外观影响心理状态\\n造口周围皮肤感染、真菌感染或肉芽组织增生",60],["摘要","肠造口是将肠管经腹壁引出形成的排泄通道，分为结肠造口（多为单腔/双腔，排泄物较稠）与回肠造口（排泄物稀、含消化酶，易致皮肤损伤）。重点在于造口护理、并发症防治与生活质量指导。",30],["疾病编码","Z93.2",30],["原首字母","czkgl",60]]},{"id":"orders-0860854ef7eec7847cfa","key":"v1-c9ccc21dfe2a3058|orders-0860854ef7eec7847cfa","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"术后腹腔脓肿","category":"胃肠外科","raw":{"name":"术后腹腔脓肿","category":"胃肠外科","summary":"术后腹腔脓肿是腹部手术后因感染性积液局限形成的脓腔，多见于吻合口瘘、腹腔污染、术后出血继发感染。表现为术后持续发热、腹痛、白细胞升高，需引流+抗感染治疗。","symptoms":["术后持续或再次出现发热（弛张热为主），伴寒战","腹痛、腹胀、局部压痛或包块，可有腹膜刺激征","食欲减退、恶心呕吐、乏力、消瘦","白细胞与CRP、PCT升高，进行性加重","脓肿压迫周围脏器可出现相应症状（黄疸、肠梗阻、尿频等）"],"diagnosis":["血常规+CRP+PCT：感染指标持续不降或再次升高","血培养+引流液培养及药敏：明确病原菌","腹部增强CT：首选，明确脓肿部位、大小、数目及与周围脏器的关系","腹部超声：可床旁操作并引导穿刺引流（尤其盆腔、膈下脓肿）","诊断性穿刺：抽出脓液可确诊，同时送培养","腹部X线/造影：观察有无膈下游离气体、肠梗阻表现","必要时MRI：评估深部脓肿与瘘管"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（经验性抗感染，覆盖肠道菌群）：","  用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 头孢哌酮舒巴坦 3g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案2（重症/耐药风险）：","  用法：美罗培南 1g（NS 100ml）静滴 q8h，必要时联合万古霉素（疑MRSA/肠球菌）〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","","方案3（支持治疗）：","  用法：补液、白蛋白、肠外或肠内营养；必要时血管活性药（脓毒症休克）","","📌 抗生素使用前留取血培养与脓液培养；疗程需足够（常4～6周），并依赖充分引流。"],"oral_medication":["⚠️ 待病情稳定、引流充分后序贯口服：","药物1（抗感染）：","用法：阿莫西林克拉维酸 0.625g tid 或 头孢克肟 0.1g bid + 甲硝唑 0.4g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（对症）：","用法：对乙酰氨基酚 0.5g 必要时（退热）；双歧杆菌三联活菌 2粒 bid（菌群调节）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 口服序贯须在体温正常、感染指标明显下降后，由主管医师决定。"],"treatment":["充分引流：首选超声/CT引导下经皮穿刺置管引流；多房或黏稠脓液可置入多孔引流管并冲洗","抗感染：早期经验性广谱，覆盖G-杆菌、厌氧菌与肠球菌，据药敏调整，疗程4～6周","手术引流：穿刺失败、多房脓肿、脓肿破裂、合并吻合口瘘或肠瘘者行手术引流+瘘口处理","营养支持：早期肠外营养，必要时瘘口远端肠内营养；补充白蛋白","器官功能支持：脓毒症、ARDS、急性肾损伤的相应处理","病因处理：吻合口瘘、异物残留、腹腔积血等原发因素的处理"],"management":["每日监测体温曲线、腹痛与腹部体征，动态复查血常规、CRP、PCT","引流管护理：固定、通畅、记录引流量与性状，冲洗严格无菌，拔管前复查影像确认脓腔消失","营养与出入量管理：记录24小时出入量，纠正电解质与酸碱失衡","疼痛与发热护理：按医嘱镇痛、物理降温，出汗后及时补液与更换衣物","早期活动：鼓励床上活动与早期下床（促进引流与肠功能恢复）","血糖管理：糖尿病患者监测并控制血糖（影响感染控制）"],"notes":["腹腔脓肿治疗的核心是『引流』，抗生素不能替代引流","术后持续发热或感染指标不降，必须想到腹腔脓肿，及时行增强CT","盆腔脓肿可出现腹泻、里急后重，容易误诊为肠炎；膈下脓肿可有肩痛、呃逆","脓肿引流后需警惕形成肠瘘，观察引流液有无肠内容物"],"emergency":["高热寒战伴血压下降（脓毒症休克）→ 立即抢救并急查血培养、启动抗感染","突发剧烈腹痛伴腹膜刺激征（脓肿破裂）→ 急诊手术引流","脓肿压迫致肠梗阻、黄疸或呼吸困难 → 急诊处理与引流"],"pinyin":"shfqznz","icd10":"K65.0","physical_exam":["生命体征：体温、脉搏、呼吸、血压（评估脓毒症）","一般情况：精神、营养状态、脱水征、皮肤弹性","腹部视诊：腹部膨隆、切口愈合情况（有无红肿渗液）、手术瘢痕","腹部触诊：压痛部位与范围、反跳痛、肌紧张、有无包块（脓肿壁）","腹部叩诊：移动性浊音、局部叩击痛、肝浊音界","腹部听诊：肠鸣音（减弱提示肠麻痹）","直肠/阴道指检：盆腔脓肿可触及触痛性包块或波动感"],"lab_tests":["血常规+CRP+PCT：评估感染程度与治疗反应，每2～3天复查","血培养×2套+脓液培养及药敏：抗生素前采血，穿刺时留取脓液","肝功能+胆红素：膈下脓肿或合并胆道问题时动态观察","肾功能+电解质+血气分析：评估脓毒症所致器官功能损害","腹部增强CT：明确脓肿部位、数目、范围及与邻近脏器关系（治疗后复查评估消退）","腹部超声：床旁筛查并引导穿刺引流，治疗后随访","白蛋白+前白蛋白+血红蛋白：评估营养状态与感染消耗"],"nursing":["发热护理：每4小时测体温，高热时物理降温+遵医嘱退热，观察热型与伴随症状","引流管护理：妥善固定、防止脱出，保持通畅，准确记录引流液色质量，冲洗时注意无菌与压力","体位护理：半卧位利于脓液局限与引流，鼓励床上活动与深呼吸","营养支持：鼓励高蛋白高热量饮食，肠外营养者规范输注并观察反应","病情观察：腹痛、腹部体征、尿量、意识变化，警惕脓毒症与脓肿破裂"],"diet":["急性期：流质或禁食（视病情与是否需手术决定），静脉营养支持","恢复期：高蛋白、高热量、易消化饮食（鱼、瘦肉、蛋、奶）","低脂饮食（合并胆道问题者），少量多餐","多食新鲜蔬菜水果补充维生素，促进感染控制与切口愈合","忌辛辣刺激、油腻与酒类；糖尿病患者按糖尿病饮食管理"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1320},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"f855618eca4991e5f03e6eff0e4f7e6d0029b0fd577a8a7204a3f952d6219ece","pinyin":"shuhoufuqiangnongzhong","initials":"shfqnz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后持续或再次出现发热（弛张热为主），伴寒战\\n腹痛、腹胀、局部压痛或包块，可有腹膜刺激征\\n食欲减退、恶心呕吐、乏力、消瘦\\n白细胞与CRP、PCT升高，进行性加重\\n脓肿压迫周围脏器可出现相应症状（黄疸、肠梗阻、尿频等）",60],["摘要","术后腹腔脓肿是腹部手术后因感染性积液局限形成的脓腔，多见于吻合口瘘、腹腔污染、术后出血继发感染。表现为术后持续发热、腹痛、白细胞升高，需引流+抗感染治疗。",30],["疾病编码","K65.0",30],["原首字母","shfqznz",60]]},{"id":"orders-b92e240ffd3fdce198b9","key":"v1-c9ccc21dfe2a3058|orders-b92e240ffd3fdce198b9","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"嵌顿性腹股沟疝","category":"疝与腹壁外科","raw":{"name":"嵌顿性腹股沟疝","category":"疝与腹壁外科","summary":"嵌顿性腹股沟疝是指腹腔脏器（多为小肠、大网膜）通过疝环后不能回纳，若不及时处理可发展为绞窄性疝（肠管血运障碍、坏死）。属外科急症，需尽快复位或手术。","symptoms":["腹股沟区突发肿块，不能回纳，局部疼痛明显","腹痛、腹胀、恶心呕吐（肠梗阻表现），停止排气排便","肿块变硬、触痛明显，可有皮肤红肿","绞窄时出现发热、心率增快、腹膜刺激征、休克","婴幼儿表现为哭闹不安、拒食、呕吐、腹股沟肿块"],"diagnosis":["体格检查：腹股沟区肿块、不能回纳、有无压痛与皮肤改变（最关键）","腹部立位平片：可见肠管扩张、气液平面（合并肠梗阻）","腹部超声：判断疝内容物性质（肠管、网膜）、有无血流信号（绞窄）","腹部CT：评估疝内容物、有无肠坏死、闭襻性肠梗阻（复杂病例）","血常规+CRP+PCT+乳酸：评估感染与肠缺血（乳酸升高提示绞窄）","电解质+血气分析：评估呕吐所致脱水与酸碱失衡"],"infusion":["⚠️ 抢救与术前用药，按病情选择！","方案1（液体复苏/补液）：","用法：平衡盐溶液 500～1000ml 静滴（纠正脱水与电解质紊乱）；呕吐明显者补钾（见尿补钾）","方案2（抗感染，绞窄/术前）：","用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（或头孢曲松 2g qd + 甲硝唑）〔调 CrCl<30 减量；青霉素过敏禁用〕","方案3（胃肠减压与支持）：","用法：0.9%氯化钠 静滴；抑酸（艾司奥美拉唑 40mg 静推 q12h）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","📌 绞窄性疝需尽快手术，抗感染与补液为术前准备，不可因等待而延误手术。"],"oral_medication":["⚠️ 急诊期需禁食，不宜口服给药；保守复位成功后遵医嘱：","药物1（通便，防腹压增高）：","用法：乳果糖 15ml bid（保持大便通畅）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物2（对症）：","用法：对乙酰氨基酚 0.5g 必要时（镇痛退热）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 复位成功后仍应尽早择期手术修补，避免再次嵌顿。"],"treatment":["手法复位：适用于嵌顿时间短（<4～6小时）、无腹膜刺激征、无绞窄征象者——头低臀高屈髋位，轻柔持续按压疝环，复位后观察腹部体征","急诊手术：手法复位失败、嵌顿>6小时、疑绞窄、伴腹膜炎或休克者，行疝囊高位结扎+疝修补（无张力修补或传统修补）","肠管评估：术中对嵌顿肠管活力评估，坏死肠段行肠切除吻合","液体复苏与电解质纠正：尤其儿童与老年人","胃肠减压：伴肠梗阻者留置胃管","嵌顿复发预防：择期行疝修补术"],"management":["禁止暴力复位：反复暴力按压可致肠管破裂、假性复位（肠管回纳腹腔但已坏死）","复位后观察：腹痛、腹膜炎体征、排气排便、生命体征，警惕假性复位与肠坏死","术前准备：禁食禁水、备皮、留置胃管与尿管、备血、做好急诊手术准备","疼痛与生命体征监测：注意有无绞窄表现（腹痛加剧、发热、心率增快、血压下降）","术后护理：观察切口、阴囊水肿、疼痛与排尿情况（老年男性警惕尿潴留）","健康指导：避免腹压增高（咳嗽、便秘、负重），出院后门诊随诊"],"notes":["嵌顿疝处理原则是『早复位、早手术』，超过6小时或疑绞窄者不宜反复手法复位","手法复位后需严密观察24～48小时，警惕假性复位（肠管已坏死但回纳腹腔）","婴幼儿嵌顿疝手法复位成功率较高，但复位后应择期手术以防复发","腹股沟疝一旦确诊，建议尽早择期手术，避免嵌顿风险（尤其老年人、慢性咳嗽、便秘者）"],"emergency":["腹股沟肿块不能回纳伴剧烈腹痛、呕吐（嵌顿）→ 急诊手术","发热、心率增快、腹膜刺激征、乳酸升高（绞窄坏死）→ 立即急诊手术","手法复位后腹痛加重、出现腹膜炎体征（假性复位）→ 立即手术探查"],"pinyin":"qdxfggs","icd10":"K40.3","physical_exam":["生命体征：体温、脉搏、呼吸、血压（评估有无毒血症/休克）","一般情况：精神、脱水征（呕吐所致）、营养状态","腹股沟区：肿块大小、形状、质地、压痛、能否回纳、皮肤颜色与温度","腹部视诊：有无膨隆、肠型（肠梗阻）","腹部触诊：压痛、反跳痛、肌紧张（腹膜炎）、其他部位有无疝","腹部叩诊与听诊：移动性浊音、肠鸣音（亢进或减弱）","阴囊/大阴唇：有无肿胀、瘀斑（嵌顿内容物坠入）"],"lab_tests":["血常规+CRP+PCT：评估感染，白细胞升高提示绞窄可能","乳酸+血气分析：乳酸升高提示肠缺血坏死，是绞窄重要指标","电解质+肾功能：呕吐致低钾低氯性碱中毒、脱水与肾功能损害","腹部立位平片：明确有无肠梗阻及气液平面","腹部超声/CT：评估疝内容物性质、有无肠壁缺血及闭襻性梗阻","凝血功能+血型+交叉配血：急诊手术前准备","心肌酶+心电图（老年患者）：术前心血管风险评估"],"nursing":["术前护理：禁食禁水、胃肠减压、快速建立静脉通路补液，做好急诊手术准备","病情观察：腹痛性质与程度、肿块变化、呕吐与排气排便、生命体征，警惕绞窄征象","体位护理：卧床休息，头低臀高屈髋位可减轻张力（手法复位前）","术后护理：观察切口渗血、阴囊水肿与疼痛，指导咳嗽时按压切口","排尿护理：老年男性术后警惕尿潴留，必要时诱导排尿或导尿","健康宣教：避免便秘、剧烈咳嗽与重体力劳动，保持大便通畅"],"diet":["急性期禁食禁水（可能急诊手术）","术后肠功能恢复（排气）后：从流质开始逐步过渡到半流质、软食","恢复期高蛋白、高维生素、易消化饮食促进切口愈合","多饮水、多食蔬菜水果与粗纤维食物，保持大便通畅","忌辛辣刺激、产气食物与烟酒；慢性咳嗽者积极治疗呼吸道疾病"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1321},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"275fe92c827c23646cb720888ca9833699f4f5cc532e85bc781f12f0fc0dd3d9","pinyin":"qiandunxingfugugoushan","initials":"qdxfggs","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹股沟区突发肿块，不能回纳，局部疼痛明显\\n腹痛、腹胀、恶心呕吐（肠梗阻表现），停止排气排便\\n肿块变硬、触痛明显，可有皮肤红肿\\n绞窄时出现发热、心率增快、腹膜刺激征、休克\\n婴幼儿表现为哭闹不安、拒食、呕吐、腹股沟肿块",60],["摘要","嵌顿性腹股沟疝是指腹腔脏器（多为小肠、大网膜）通过疝环后不能回纳，若不及时处理可发展为绞窄性疝（肠管血运障碍、坏死）。属外科急症，需尽快复位或手术。",30],["疾病编码","K40.3",30],["原首字母","qdxfggs",60]]},{"id":"orders-3a38ebf48236d3969d57","key":"v1-c9ccc21dfe2a3058|orders-3a38ebf48236d3969d57","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腹壁切口疝","category":"疝与腹壁外科","raw":{"name":"腹壁切口疝","category":"疝与腹壁外科","summary":"腹壁切口疝是腹部手术后因切口愈合不良、腹壁薄弱或腹内压增高，腹腔内容物经原切口或切口旁突出形成的疝，多见于腹部大手术后。表现为站立或用力时切口处隆起，需手术修补（多采用补片无张力修补）。","symptoms":["站立、咳嗽或用力时切口处出现可复性包块，平卧可消失","局部坠胀不适或隐痛，包块增大时明显","疝内容物嵌顿时出现腹痛、呕吐、腹胀（肠梗阻表现）","巨大切口疝可致腹壁功能障碍、便秘、呼吸受限","部分患者有切口感染、裂开或多次手术史"],"diagnosis":["体格检查：站立位与卧位对比，可扪及疝环大小与内容物性质","腹部增强CT（含Valsalva动作）：首选，明确疝环大小、疝囊内容物、腹壁肌肉状态及有无隐匿疝（对手术方案至关重要）","腹部超声：评估疝内容物与疝环","腹部立位平片：合并肠梗阻时","血常规+CRP：评估有无感染或嵌顿","术前评估：腹壁功能、呼吸功能（巨大切口疝影响呼吸）、营养状态、血糖"],"infusion":["⚠️ 术前术后按医嘱用药，切勿全部同时使用！","","方案1（术前预防性抗感染，修补术前30～60分钟）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；必要时白蛋白、氨基酸营养支持","","方案3（嵌顿/绞窄术前）：","  用法：补液+头孢呋辛 1.5g q8h + 甲硝唑 0.5g q8h；胃肠减压〔调 CrCl<30 减量；青霉素过敏禁用〕","","📌 切口疝修补术为清洁-污染手术，预防性抗生素主要针对革兰阳性球菌。"],"oral_medication":["⚠️ 术后与恢复期用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（通便，防腹压增高）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（止咳，慢性咳嗽者）：","用法：氨溴索 30mg tid 或 复方甲氧那明 2粒 tid〔调 妊娠早期禁用；胃溃疡者慎用〕","📌 术后避免用力排便与剧烈咳嗽，必要时用镇咳与通便药物（腹压增高是复发主因）。"],"treatment":["手术治疗：主要治疗手段，行切口疝修补术——开放或腹腔镜（IPOM/肌后间隙修补），多用补片行无张力修补","术前准备：控制血糖、戒烟、改善营养、治疗慢性咳嗽与便秘、减重（BMI>35需减重）","巨大切口疝：术前渐进性气腹或肉毒素注射辅助关腹，必要时行组织结构分离技术（CST）","嵌顿/绞窄：急诊手术，切除坏死肠管并修补","术后腹带加压：减少切口张力与积液，指导正确使用","康复指导：避免提重物（3个月内）、腹压增高动作，逐步恢复活动"],"management":["术前评估与优化：控制血糖（<8mmol/L）、戒烟≥4周、纠正营养不良、治疗便秘与慢性咳嗽","术后观察：切口有无红肿、渗液、积液（血清肿）、补片感染征象","引流管护理：记录引流量与性状，量少后择期拔除","腹带固定：术后使用腹带3个月，避免剧烈咳嗽与用力排便","早期活动：术后第1天床上活动，逐步下床，避免剧烈活动与提重物","随访：术后1、3、6、12个月复查，评估有无复发与慢性疼痛"],"notes":["切口疝不会自愈，一旦确诊应择期手术，嵌顿风险随疝环增大而增加","腹内压增高（肥胖、慢性咳嗽、便秘、前列腺增生）是复发主要原因，术前术后必须控制","术前CT评估疝环大小与腹壁肌肉缺损范围是选择术式的关键","补片感染是最严重的并发症之一，术中严格无菌、术后警惕切口红肿渗液"],"emergency":["疝块不能回纳伴腹痛、呕吐、停止排气排便（嵌顿）→ 急诊手术","疝块处皮肤红肿、发热、剧烈疼痛（绞窄/感染）→ 立即急诊处理","疝内容物破溃致腹壁缺损与肠管外露 → 急诊抢救手术"],"pinyin":"fbqks","icd10":"K43.2","physical_exam":["生命体征：体温、脉搏、血压（评估嵌顿/感染）","一般情况：BMI、营养状态、有无慢性咳嗽与便秘","腹部视诊：原切口瘢痕、包块位置与大小、站立位与卧位对比、皮肤颜色（有无红肿）","腹部触诊：疝环大小（可容指数）、内容物性质、有无压痛、能否回纳、腹壁肌肉力量","腹部叩诊与听诊：肠鸣音（嵌顿者亢进或减弱）","呼吸系统：呼吸音、有无慢性阻塞性肺疾病（影响手术与复发）","其他：有无合并腹股沟疝、脐疝等多发疝"],"lab_tests":["血常规+CRP：评估有无感染或嵌顿，术前基线值","血糖+糖化血红蛋白：糖尿病患者术前必须控制（影响切口愈合与感染）","白蛋白+前白蛋白+血红蛋白：评估营养状态（营养不良增加复发风险）","凝血功能+肝肾功能：术前常规评估","腹部增强CT（含Valsalva）：明确疝环大小、腹壁缺损范围、疝内容物及有无隐匿疝","肺功能+血气分析（巨大切口疝/吸烟者）：评估呼吸功能与手术耐受","心电图+心脏超声（老年患者）：术前心血管评估"],"nursing":["术前护理：指导戒烟、练习深呼吸与有效咳嗽（双手按压切口），训练床上排便","术后体位与活动：术后早期床上活动，麻醉清醒后取半卧位，术后1天开始下床活动","切口观察：注意有无渗血、渗液、红肿及积液（血清肿），腹带妥善固定","腹压管理：指导避免剧烈咳嗽、用力排便与提重物，必要时用镇咳通便药","引流护理：保持引流管通畅，记录引流量与性状，警惕补片感染（持续渗液、发热）"],"diet":["术前：高蛋白、高维生素饮食，纠正营养不良，控制体重","术后：肠功能恢复后从流质逐步过渡到高蛋白软食","多饮水、多食粗纤维蔬菜水果，保持大便通畅（防便秘致腹压增高）","少量多餐，避免暴饮暴食与产气食物（减轻腹胀）","忌烟酒，糖尿病患者按糖尿病饮食严格控糖"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1322},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0d4c88046b7a0689260174c07d35779af122a8f788db070ffe1772aa8da2d7b9","pinyin":"fubiqiekoushan","initials":"fbqks","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","站立、咳嗽或用力时切口处出现可复性包块，平卧可消失\\n局部坠胀不适或隐痛，包块增大时明显\\n疝内容物嵌顿时出现腹痛、呕吐、腹胀（肠梗阻表现）\\n巨大切口疝可致腹壁功能障碍、便秘、呼吸受限\\n部分患者有切口感染、裂开或多次手术史",60],["摘要","腹壁切口疝是腹部手术后因切口愈合不良、腹壁薄弱或腹内压增高，腹腔内容物经原切口或切口旁突出形成的疝，多见于腹部大手术后。表现为站立或用力时切口处隆起，需手术修补（多采用补片无张力修补）。",30],["疾病编码","K43.2",30],["原首字母","fbqks",60]]},{"id":"orders-0b05e2805acffe57bf1b","key":"v1-c9ccc21dfe2a3058|orders-0b05e2805acffe57bf1b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"创伤性血胸","category":"胸外科","raw":{"name":"创伤性血胸","category":"胸外科","summary":"创伤性血胸是胸部外伤后血液积聚于胸膜腔，多因肋骨骨折断端刺破肋间血管或胸内血管、肺组织损伤所致。按出血量分为少量（<500ml）、中量（500～1500ml）、大量（>1500ml）。进行性血胸与凝固性血胸需手术处理。","symptoms":["胸痛、呼吸困难，呼吸动度减弱，患侧叩诊浊音","面色苍白、脉搏细速、血压下降（出血量大者）","气管向健侧移位（大量血胸），患侧呼吸音减弱","可伴咯血（肺损伤）、皮下气肿、肋骨骨折体征","晚期可出现发热（血液吸收热或感染）"],"diagnosis":["胸部X线：胸膜腔积液影，肋膈角变钝（少量）至大片致密影（大量）","胸部CT：明确出血量、肺损伤、肋骨骨折及是否合并气胸（首选）","诊断性胸腔穿刺：抽出不凝血即可确诊，并可判断出血量","床旁超声：快速评估胸腔积液并动态观察出血速度","血常规+血型+交叉配血：血红蛋白动态下降提示活动性出血","凝血功能+血气分析：评估出血与呼吸功能"],"infusion":["⚠️ 抢救用，必须在监护下按病情选择！","","方案1（抗休克/液体复苏）：","  用法：平衡盐溶液+0.9%氯化钠 快速补液（晶体为主）；输注红细胞悬液、新鲜冰冻血浆（大量输血按1:1:1比例），目标Hb 70～90g/L","","方案2（止血辅助）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（伤后3小时内）；维生素K1 10mg 静滴〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（抗感染）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（或头孢曲松 2g qd）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（镇痛）：","  用法：曲马多 100mg（NS 100ml 或 5%GS 100ml）静滴 必要时；避免使用抑制呼吸的镇静药","","📌 抗休克同时应尽快胸腔闭式引流并做好急诊手术准备。"],"oral_medication":["⚠️ 急性期以静脉治疗为主；稳定后遵医嘱：","药物1（抗感染序贯）：","用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（化痰）：","用法：氨溴索 30mg tid（促进排痰，防肺不张）〔调 妊娠早期禁用；胃溃疡者慎用〕","📌 肋骨骨折疼痛明显者应充分镇痛，以利于咳嗽排痰、防肺部感染。"],"treatment":["抗休克治疗：快速补液输血，纠正低血容量，必要时血管活性药","胸腔闭式引流：中量以上血胸或进行性血胸应置管引流（腋中线第4～5肋间）","开胸探查指征：引流血量>1500ml或每小时>200ml持续3小时、引流后血压仍不稳定、疑心脏大血管损伤","凝固性血胸：伤后3～7天行胸腔镜清除血块，防机化性血胸与脓胸","肋骨骨折处理：多根多处骨折（连枷胸）予胸壁固定、必要时呼吸机内固定","抗感染与镇痛：预防脓胸，充分镇痛利于咳嗽排痰"],"management":["严密监测生命体征：血压、心率、呼吸、血氧、尿量，每15～30分钟评估一次（休克期）","引流观察：记录引流量、速度与性状（血性、鲜红、持续增多提示活动性出血）","输血输液管理：按医嘱输注血制品，观察有无输血反应","呼吸管理：鼓励深呼吸与有效咳嗽，必要时雾化吸入，预防肺不张与肺部感染","复查胸片/CT：评估血胸吸收与有无包裹性积液","观察有无感染征象（发热、白细胞升高、积液混浊），警惕脓胸"],"notes":["血胸引流后血液可因胸膜去纤维化而不凝，抽出不凝血是诊断关键","进行性血胸是急诊开胸的重要指征，需密切监测引流量与速度","凝固性血胸未及时清除可形成机化性血胸，影响肺功能并易继发脓胸","血胸易继发感染形成脓胸，需预防性抗感染并动态评估"],"emergency":["引流血量>1500ml或每小时>200ml持续3小时、血压不稳 → 急诊开胸探查","呼吸困难加重、气管移位伴血压下降（大量血胸）→ 立即减压并抗休克","出现心脏压塞征象（颈静脉怒张、心音遥远、血压下降）→ 急诊心包穿刺/手术"],"pinyin":"csxx","icd10":"S27.1","physical_exam":["生命体征：血压、心率、呼吸、血氧（评估失血性休克与呼吸功能）","一般情况：面色苍白、皮肤湿冷、意识状态、颈静脉充盈","颈部与气管：气管是否向健侧移位、有无皮下气肿","胸部视诊：胸廓畸形、呼吸动度减弱、肋间隙、有无开放伤口","胸部触诊：肋骨压痛与骨擦感、语颤减弱、皮下握雪感","胸部叩诊与听诊：患侧浊音、呼吸音减弱或消失","腹部：有无合并腹腔脏器损伤（腹膜炎体征）"],"lab_tests":["血常规+血型+交叉配血：动态监测血红蛋白（下降提示活动性出血），术前备血","凝血功能+D-二聚体：评估创伤性凝血病与DIC风险","血气分析+乳酸：评估缺氧、组织灌注与休克程度","胸部CT：明确血胸量、肺损伤、肋骨骨折与合并伤（首选）","床旁超声（FAST）：快速评估胸腔及心包积液、腹腔积液","心肌酶+心电图（疑心脏损伤）：评估心脏挫伤与心律失常","引流液检查（血细胞比容、细菌培养）：判断是否为持续出血或继发感染"],"nursing":["休克护理：平卧、保温、快速建立静脉通路，遵医嘱补液输血，每15～30分钟监测生命体征与尿量","闭式引流护理：保持引流管通畅与密闭，观察水封瓶波动与引流量速度，记录颜色性状，警惕持续出血","呼吸道护理：协助翻身拍背、雾化吸入，鼓励有效咳嗽排痰，预防肺不张与肺炎","疼痛护理：评估疼痛并遵医嘱镇痛，指导咳嗽时按压胸壁减轻疼痛","术前准备：拟手术者禁食禁水、备皮、备血、留置胃管与尿管"],"diet":["急性期禁食禁水（拟急诊手术者），必要时静脉营养","病情稳定后：高蛋白、高热量、高维生素饮食促进创伤修复","多饮水，多食蔬菜水果，保持大便通畅","避免产气食物与辛辣刺激食物，戒烟酒","贫血者增加含铁与优质蛋白食物（瘦肉、动物肝脏、蛋奶）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1323},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6ff6f71239ecac0474eb9f8a85b26fd0f82419eb14174e0203f6d55af29e6908","pinyin":"chuangshangxingxuexiong","initials":"csxxx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","胸痛、呼吸困难，呼吸动度减弱，患侧叩诊浊音\\n面色苍白、脉搏细速、血压下降（出血量大者）\\n气管向健侧移位（大量血胸），患侧呼吸音减弱\\n可伴咯血（肺损伤）、皮下气肿、肋骨骨折体征\\n晚期可出现发热（血液吸收热或感染）",60],["摘要","创伤性血胸是胸部外伤后血液积聚于胸膜腔，多因肋骨骨折断端刺破肋间血管或胸内血管、肺组织损伤所致。按出血量分为少量（<500ml）、中量（500～1500ml）、大量（>1500ml）。进行性血胸与凝固性血胸需手术处理。",30],["疾病编码","S27.1",30],["原首字母","csxx",60]]},{"id":"orders-658bdfaf5b7271462a72","key":"v1-c9ccc21dfe2a3058|orders-658bdfaf5b7271462a72","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"连枷胸（多根多处肋骨骨折）","category":"胸外科","raw":{"name":"连枷胸（多根多处肋骨骨折）","category":"胸外科","summary":"连枷胸指相邻多根（≥3根）多处肋骨骨折，胸壁失去肋骨支撑形成浮动胸壁，出现反常呼吸运动（吸气时塌陷、呼气时膨出），导致通气障碍、缺氧，常合并肺挫伤，是胸部创伤的危重情况。","symptoms":["胸痛剧烈，深呼吸、咳嗽时加重，局部压痛与骨擦感","反常呼吸运动（吸气时患处胸壁塌陷、呼气时膨出）","呼吸困难、发绀、呼吸急促，血氧下降","可伴皮下气肿、气胸、血胸、咯血","重者出现呼吸衰竭、休克、意识改变"],"diagnosis":["体格检查：反常呼吸运动、肋骨压痛与骨擦感、皮下气肿（关键体征）","胸部CT（含三维重建）：明确骨折数目、部位、移位及肺挫伤程度（首选）","胸部X线：可见肋骨骨折线、气胸、血胸、肺挫伤影（早期肺挫伤可阴性）","血气分析：评估低氧血症与通气障碍（PaO2下降、PaCO2可正常或升高）","床旁超声：评估胸腔积液与气胸，可引导穿刺","血常规+凝血功能+血型：评估出血与备血；心肌酶排除心脏挫伤"],"infusion":["⚠️ 抢救用药，按病情选择！","","方案1（镇痛，重点）：","  用法：曲马多 100mg（NS 100ml）静滴 q8h（必要时）；或氟比洛芬酯 50mg 静滴 q12h；剧痛者行硬膜外/椎旁阻滞镇痛（需麻醉科协作）","","方案2（液体管理）：","  用法：限制晶体液（避免加重肺挫伤肺水肿），平衡盐溶液按需；必要时白蛋白","","方案3（抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 头孢曲松 2g 静滴 qd（合并肺挫伤/开放伤）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（化痰/支持）：","  用法：氨溴索 30mg 静滴 bid；必要时雾化吸入（布地奈德+特布他林）〔调 妊娠早期禁用；胃溃疡者慎用〕","","📌 充分镇痛是治疗核心（利于咳嗽排痰、减少呼吸机依赖），避免过量补液加重肺水肿。"],"oral_medication":["⚠️ 稳定后遵医嘱，同类只选一种：","药物1（镇痛）：","用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（化痰）：","用法：氨溴索 30mg tid 或 乙酰半胱氨酸 0.6g tid〔调 妊娠早期禁用；胃溃疡者慎用〕","药物3（通便镇咳）：","用法：乳果糖 15ml bid；复方甲氧那明 2粒 tid（干咳明显者）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 镇痛需持续足量，疼痛控制不佳会导致排痰困难与肺部感染。"],"treatment":["镇痛：硬膜外/椎旁神经阻滞或静脉镇痛（多模式镇痛），是治疗关键","胸壁固定：胸带包扎、肋骨固定板或手术内固定（多发移位明显、呼吸功能差者）","呼吸支持：吸氧，必要时无创或有创机械通气（内固定作用）；肺挫伤重者按ARDS处理（小潮气量）","胸腔闭式引流：合并气胸/血胸者","液体管理：限制晶体液，避免肺水肿加重","抗感染、化痰、鼓励咳嗽排痰，预防肺部感染与肺不张","合并伤处理：腹部脏器损伤、心脏挫伤、颅脑损伤等"],"management":["监测呼吸功能：呼吸频率、血氧、血气分析，动态评估氧合指数","镇痛评估：每4小时评估疼痛评分（目标<3分），保证深呼吸与有效咳嗽","呼吸道管理：翻身拍背、雾化吸入、鼓励咳痰，必要时吸痰（注意避免诱发气胸）","出入量与液体管理：限制晶体液，记录24小时出入量，警惕肺水肿","复查影像：伤后24～48小时复查CT评估肺挫伤进展","康复：疼痛控制后鼓励早期床上活动与下床活动，预防深静脉血栓（必要时抗凝）"],"notes":["连枷胸的主要危险是合并肺挫伤与呼吸衰竭，治疗核心是镇痛+呼吸管理","反常呼吸运动早期可不明显，需仔细查体并结合影像判断","肺挫伤常在伤后24～48小时进展，需动态复查与评估","避免过量补液，限制性液体策略可减少肺水肿与呼吸衰竭"],"emergency":["呼吸窘迫、血氧持续下降、PaO2<60mmHg（呼吸衰竭）→ 立即机械通气并转ICU","反常呼吸明显伴循环不稳定 → 急诊胸壁固定并评估手术内固定","合并张力性气胸或大量血胸 → 立即减压/引流"],"pinyin":"ljx","icd10":"S22.5","physical_exam":["生命体征：呼吸频率与形态、血氧、心率、血压（评估呼吸衰竭与休克）","一般情况：意识、发绀、是否可平卧、烦躁程度","胸部视诊：胸壁畸形、反常呼吸运动、呼吸动度、肋间隙","胸部触诊：肋骨压痛与骨擦感、皮下气肿（握雪感）、语颤减弱","胸部叩诊与听诊：浊音或鼓音（血胸/气胸）、呼吸音减弱、湿啰音（肺挫伤）","颈部与气管：气管移位（张力性气胸）、颈静脉怒张（心脏压塞）","合并伤评估：腹部压痛（肝脾破裂）、颅脑与脊柱损伤"],"lab_tests":["血气分析（含氧合指数）：评估低氧血症与呼吸衰竭，动态复查（每6～12小时）","血常规+血型+交叉配血：评估失血与备血","凝血功能+D-二聚体：创伤性凝血病风险","心肌酶（CK-MB、肌钙蛋白）+心电图：评估心脏挫伤","胸部CT（含三维重建）：明确骨折与肺挫伤范围，为首选检查","床旁超声+肝脾胰超声：排除胸腹联合伤","乳酸+肝肾功能：评估组织灌注与器官功能"],"nursing":["呼吸护理：半卧位、持续吸氧，监测血氧与呼吸形态，发现反常呼吸加重或发绀立即报告","镇痛护理：按医嘱定时给予镇痛，评估疼痛评分与呼吸改善情况（疼痛控制是排痰前提）","排痰护理：每2小时翻身拍背，雾化吸入后鼓励咳痰，无力咳痰者协助吸痰","固定护理：胸带包扎松紧适宜，观察皮肤受压与呼吸受限情况","并发症观察：体温、痰液性状（肺部感染）、尿量、下肢肿胀（深静脉血栓）"],"diet":["急性期禁食或流质（视病情与是否手术），必要时静脉营养","高蛋白、高热量、高维生素饮食促进骨折愈合与创伤修复","适量饮水（限液者按医嘱），保持痰液稀释","多食蔬菜水果防便秘（避免用力排便），必要时用缓泻剂","戒烟酒，避免产气与辛辣刺激食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1324},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2c06cd134d8c5e08ef7416ad76434629259be78b5ea268527d64481b56bd008b","pinyin":"lianjiaxiong（duogenduochuleiguguzhe）","initials":"ljx（dgdclggz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","胸痛剧烈，深呼吸、咳嗽时加重，局部压痛与骨擦感\\n反常呼吸运动（吸气时患处胸壁塌陷、呼气时膨出）\\n呼吸困难、发绀、呼吸急促，血氧下降\\n可伴皮下气肿、气胸、血胸、咯血\\n重者出现呼吸衰竭、休克、意识改变",60],["摘要","连枷胸指相邻多根（≥3根）多处肋骨骨折，胸壁失去肋骨支撑形成浮动胸壁，出现反常呼吸运动（吸气时塌陷、呼气时膨出），导致通气障碍、缺氧，常合并肺挫伤，是胸部创伤的危重情况。",30],["疾病编码","S22.5",30],["原首字母","ljx",60]]},{"id":"orders-588017527e834b574ad3","key":"v1-c9ccc21dfe2a3058|orders-588017527e834b574ad3","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"嵌顿痔（急性痔嵌顿）","category":"肛肠外科","raw":{"name":"嵌顿痔（急性痔嵌顿）","category":"肛肠外科","summary":"嵌顿痔是内痔脱出后肛门括约肌痉挛使其不能回纳，痔核发生充血、水肿、血栓形成甚至坏死。表现为肛门剧烈疼痛、痔核脱出水肿，属肛肠科急症，需及时处理（手法复位、消肿后手术）。","symptoms":["肛门剧烈疼痛（持续性胀痛或灼痛），坐卧不宁","痔核脱出肛门外，水肿、充血，呈暗紫色，触痛明显","可有表面糜烂、渗液、出血甚至坏死","排便困难、里急后重，因疼痛不敢排便","可伴发热、乏力（合并感染时）"],"diagnosis":["体格检查：痔核脱出、水肿、色泽（暗紫提示血栓）、有无坏死","肛门视诊与直肠指检：评估脱出范围、括约肌张力、有无其他病变","血常规+CRP：评估感染与坏死","肛门镜（急性期慎用）：水肿消退后评估内痔分度","排除其他疾病：直肠脱垂、肛管癌、尖锐湿疣等","必要时盆腔CT/MRI（疑坏死性筋膜炎等严重感染）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（消肿/改善循环）：","用法：七叶皂苷钠 10～20mg + 0.9%氯化钠 250ml 静滴 qd；或地奥司明静脉制剂（按说明书）","方案2（抗感染，合并坏死/感染）：","用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","方案3（镇痛）：","用法：氟比洛芬酯 50mg 静滴 q12h 或 曲马多 100mg 静滴 必要时；0.9%氯化钠 静滴","📌 早期以手法复位+消肿为主，出现坏死或复位失败需手术治疗。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（改善静脉张力/消肿）：","用法：地奥司明片 2片 bid（午餐、晚餐时服）或 迈之灵 2片 bid","药物2（通便，防便秘）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（局部用药）：","用法：复方角菜酸酯栓 1枚 纳肛 bid；马应龙麝香痔疮膏 外用（便后坐浴后）","药物4（镇痛）：","用法：布洛芬 0.3g 必要时 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ 肾功能不全禁用/慎用；活动性溃疡禁用；★ 妊娠晚期禁用〕","📌 避免使用刺激性泻药；便后温水坐浴后用药效果更好。"],"treatment":["手法复位：早期（水肿轻、无坏死）在局部麻醉/镇痛下，涂润滑剂后轻柔持续挤压回纳，成功后卧床观察","消肿治疗：卧床休息、抬高臀部、静脉用七叶皂苷钠或口服地奥司明，温水坐浴","手术指征：手法复位失败、痔核坏死、血栓形成剧痛、反复嵌顿——行外剥内扎术（Milligan-Morgan）或吻合器痔上黏膜环切术（PPH）","急性期手术注意：水肿严重时解剖层次不清，可先行消肿治疗（3～7天）后手术（除非坏死需急诊）","镇痛与通便：充分镇痛，保持排便通畅","术后护理：坐浴、换药、通便、避免久坐久蹲"],"management":["卧床休息，取侧卧位减轻肛门受压与水肿","温水坐浴：每日2～3次，每次15～20分钟（水温40℃左右），促进水肿消退","排便管理：保持大便通畅（缓泻剂），避免久蹲、用力排便，便后温水清洗坐浴","水肿与疼痛观察：记录痔核大小、色泽变化，出现发黑坏死立即报告","术后观察：创面渗血、排尿情况（术后尿潴留常见，必要时导尿），疼痛与排便情况","健康宣教：忌久坐久蹲、忌辛辣酒类、多饮水多纤维，做提肛运动"],"notes":["嵌顿痔的处理原则是『先消肿、后手术』，除非已坏死需急诊手术","急性期手术因水肿解剖不清，术后并发症（肛门狭窄、失禁）风险高","嵌顿痔常合并血栓形成，剧烈疼痛多因血栓所致","预防复发：保持大便通畅、避免久坐久蹲、忌辛辣酒类、做提肛运动"],"emergency":["痔核发黑、坏死、剧痛伴高热 → 急诊手术","大量出血（痔核糜烂出血）→ 急诊止血处理","会阴部广泛红肿、发热伴休克（坏死性筋膜炎可能）→ 急诊清创抢救"],"pinyin":"qdz","icd10":"K64.5","physical_exam":["生命体征：体温、脉搏、血压（评估感染与疼痛应激）","一般情况：面色（疼痛所致）、体位（拒坐）","肛周视诊：痔核脱出大小、色泽（暗紫/发黑）、水肿程度、有无糜烂渗液","肛门触诊：痔核触痛、张力、能否回纳、括约肌痉挛程度","直肠指检（轻柔）：排除直肠肿瘤、息肉等","腹部：有无压痛与包块（排除其他急腹症）","全身：有无贫血貌（长期出血）、有无发热"],"lab_tests":["血常规+CRP：评估感染、坏死与贫血（长期便血者）","凝血功能：拟手术者术前评估","血糖：糖尿病影响创面愈合与感染风险","肝肾功能+心电图：术前常规评估（尤其老年患者）","结肠镜（病情稳定后）：40岁以上或有便血者排除结直肠肿瘤","必要时盆腔CT/MRI：疑严重感染或坏死性筋膜炎时"],"nursing":["疼痛护理：评估疼痛评分，遵医嘱镇痛；协助侧卧位，避免久坐","坐浴护理：每日温水坐浴2～3次（40℃左右、15～20分钟），便后追加一次","复位护理：手法复位后卧床观察，注意痔核是否再次脱出（咳嗽、用力时）","排便护理：保持大便通畅，必要时用缓泻剂，避免久蹲与用力","术后护理：观察创面渗血、排尿及疼痛情况，术后48小时内警惕出血"],"diet":["多饮水（每日2000ml以上），多食高纤维蔬菜水果与粗粮","清淡易消化饮食，避免辛辣刺激、油炸与酒类","适量优质蛋白促进创面愈合","避免坚硬粗糙食物与刺激性饮料（咖啡、浓茶）","规律排便，避免便秘与腹泻（均可加重痔）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1325},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"443a77740475484d95ed293d6e7262e647692f82fe3b6d04ff416a87c356b90d","pinyin":"qiandunzhi（jixingzhiqiandun）","initials":"qdz（jxzqd）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肛门剧烈疼痛（持续性胀痛或灼痛），坐卧不宁\\n痔核脱出肛门外，水肿、充血，呈暗紫色，触痛明显\\n可有表面糜烂、渗液、出血甚至坏死\\n排便困难、里急后重，因疼痛不敢排便\\n可伴发热、乏力（合并感染时）",60],["摘要","嵌顿痔是内痔脱出后肛门括约肌痉挛使其不能回纳，痔核发生充血、水肿、血栓形成甚至坏死。表现为肛门剧烈疼痛、痔核脱出水肿，属肛肠科急症，需及时处理（手法复位、消肿后手术）。",30],["疾病编码","K64.5",30],["原首字母","qdz",60]]},{"id":"orders-439319a36b6aff02b9a5","key":"v1-c9ccc21dfe2a3058|orders-439319a36b6aff02b9a5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"输尿管结石（肾绞痛）","category":"泌尿外科","raw":{"name":"输尿管结石（肾绞痛）","category":"泌尿外科","summary":"输尿管结石多由肾结石下移所致，典型表现为突发腰腹部绞痛（肾绞痛）、向会阴部放射、伴血尿。结石直径<0.6cm多可自行排出，较大或伴梗阻、感染、肾功能损害者需体外冲击波碎石或输尿管镜取石。","symptoms":["突发一侧腰腹部绞痛，阵发性加剧，向同侧下腹、会阴部及大腿内侧放射","恶心、呕吐、腹胀（反射性），面色苍白、大汗、辗转不安","肉眼或镜下血尿","尿频、尿急、尿痛（结石位于输尿管下段时）","合并感染时寒战高热、腰痛加重；双侧梗阻或孤立肾梗阻可致无尿"],"diagnosis":["尿常规：镜下血尿（红细胞增多），合并感染时白细胞增多","泌尿系超声：首选筛查，可见结石强回声、肾积水、输尿管扩张","腹部CT平扫（泌尿系CTU/CT）：金标准，明确结石部位、大小、数目及有无梗阻","腹部平片（KUB）：可见阳性结石影（尿酸结石不显影）","血常规+CRP+PCT：评估感染；合并发热者查血培养","肾功能+电解质：评估梗阻所致肾功能损害","静脉肾盂造影（IVP）：必要时评估肾功能与解剖（现多被CT替代）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","方案1（解痉镇痛）：","用法：间苯三酚 40～80mg + 0.9%氯化钠 100ml 静滴（或静推）；或山莨菪碱 10mg 肌注；剧痛用哌替啶 50mg 肌注 + 间苯三酚","方案2（补液促排）：","用法：0.9%氯化钠/葡萄糖 500～1000ml 静滴（无梗阻、无肾功能不全者）","方案3（抗感染，合并感染时）：","用法：头孢曲松 2g 静滴 qd 或 左氧氟沙星 0.5g 静滴 qd（按药敏调整）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","📌 合并感染梗阻者属急症，须尽早解除梗阻（引流/置管），单纯抗感染无效。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（排石/利尿）：","用法：坦索罗辛 0.2mg qn（输尿管下段结石助排）或 硝苯地平 10mg tid","药物2（解痉镇痛）：","用法：双氯芬酸钠栓 50mg 纳肛 必要时 或 塞来昔布 200mg bid〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物3（通淋排石，中成药）：","用法：排石颗粒 1袋 tid 或 尿石通丸 1袋 tid（辅助排石）","药物4（抗感染序贯）：","用法：头孢克肟 0.1g bid 或 左氧氟沙星 0.5g qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","📌 多饮水、适度运动有助于排石；尿酸结石者可碱化尿液（枸橼酸氢钾钠）。"],"treatment":["保守排石：结石<0.6cm、无梗阻感染、疼痛可控者——大量饮水（每日2500～3000ml）、适度运动（跳绳、跳跃）、解痉镇痛、α受体阻滞剂助排，2～4周复查","体外冲击波碎石（ESWL）：结石0.6～2cm、肾及输尿管上段结石，无梗阻感染者","输尿管镜碎石取石（URS+钬激光）：中下段结石、ESWL失败、结石嵌顿或合并梗阻者","经皮肾镜取石（PCNL）：肾结石>2cm、鹿角形结石或URS失败者","急诊引流：合并感染梗阻、脓毒症、无尿或孤立肾梗阻者行输尿管支架或经皮肾造瘘引流","代谢评估与预防：结石成分分析，针对性预防（多饮水、限钠、限草酸、碱化尿液）"],"management":["疼痛评估与处理：评估疼痛部位、性质、评分，遵医嘱解痉镇痛并观察效果","观察排石：排尿时用滤网收集结石（送成分分析），观察有无结石排出","饮水管理：无梗阻/心肾功能允许者每日饮水2500～3000ml，夜间加饮","尿量与尿色观察：记录尿量，观察有无血尿加重与脓尿","感染监测：体温、寒战、腰痛加重、白细胞与PCT（警惕梗阻性化脓性感染）","复查随访：2～4周复查超声/CT评估结石位置与有无肾积水"],"notes":["结石合并感染并梗阻属泌尿外科急症，需尽快解除梗阻引流，否则可致脓毒症","肾绞痛发作时禁用过量补液（加重梗阻侧压力），以解痉镇痛为主","直径>0.6cm结石自行排出可能性小，应积极介入治疗，避免长期梗阻损害肾功能","结石复发率高（5年约50%），需长期生活方式干预与随访"],"emergency":["寒战高热伴腰痛、白细胞升高（梗阻性化脓性肾盂肾炎）→ 紧急解除梗阻引流（支架/肾造瘘）","无尿或孤立肾梗阻、肾功能急剧恶化 → 急诊引流","剧烈绞痛不能缓解伴呕吐、脱水 → 急诊镇痛补液并评估梗阻"],"pinyin":"sngjs","icd10":"N20.1","physical_exam":["生命体征：体温、脉搏、血压（评估感染与疼痛应激）","一般情况：痛苦面容、大汗、辗转不安、脱水征","腹部视诊：有无膨隆、手术瘢痕","腹部触诊：患侧肾区压痛、输尿管走行区压痛、有无腹膜刺激征（鉴别急腹症）","肾区叩击痛：患侧明显（肾绞痛特征性体征）","下腹部与膀胱区：有无压痛、膀胱充盈（尿潴留）","其他：睾丸/阴唇有无牵涉痛、有无皮疹（带状疱疹鉴别）"],"lab_tests":["尿常规+尿沉渣：镜下或肉眼血尿，白细胞提示感染","泌尿系超声+腹部CT平扫：明确结石部位、大小、肾积水（CT为金标准）","血常规+CRP+PCT：评估感染；发热者加血培养","肾功能（肌酐、尿素氮）+电解质：评估梗阻性肾功能损害","尿培养+药敏：合并感染时指导抗生素","血钙、血磷、尿酸、甲状旁腺激素（复发者）：代谢性病因筛查","结石成分分析：排石或取石后送检，指导预防"],"nursing":["疼痛护理：评估疼痛评分（肾绞痛常达7～10分），遵医嘱及时解痉镇痛，观察缓解情况","排石护理：指导大量饮水与适度跳跃运动，排尿用滤网收集结石","病情观察：体温、尿量、尿色、腰痛变化，警惕感染与无尿","饮水指导：无梗阻者每日饮水2500～3000ml，分次饮用，夜间加饮一次","术后护理（碎石/取石后）：观察血尿程度、支架管位置、排尿情况，指导避免剧烈运动"],"diet":["大量饮水（每日2500～3000ml），保持尿量2000ml以上","草酸钙结石：限制高草酸食物（菠菜、甜菜、坚果、巧克力）、限钠","尿酸结石：限制高嘌呤食物（动物内脏、海鲜、浓肉汤），碱化尿液","适量钙摄入（不必过度限制，过度限钙反而增加结石风险），避免过量维生素C","少饮浓茶咖啡与碳酸饮料，避免高动物蛋白饮食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1326},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8f62c6fa3086a641ebe0031c2f43fb73a1290eb81b3cc9d45f5ffeac1a873182","pinyin":"shuniaoguanjieshi（shenjiaotong）","initials":"sngjs（sjt）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发一侧腰腹部绞痛，阵发性加剧，向同侧下腹、会阴部及大腿内侧放射\\n恶心、呕吐、腹胀（反射性），面色苍白、大汗、辗转不安\\n肉眼或镜下血尿\\n尿频、尿急、尿痛（结石位于输尿管下段时）\\n合并感染时寒战高热、腰痛加重；双侧梗阻或孤立肾梗阻可致无尿",60],["摘要","输尿管结石多由肾结石下移所致，典型表现为突发腰腹部绞痛（肾绞痛）、向会阴部放射、伴血尿。结石直径<0.6cm多可自行排出，较大或伴梗阻、感染、肾功能损害者需体外冲击波碎石或输尿管镜取石。",30],["疾病编码","N20.1",30],["原首字母","sngjs",60]]},{"id":"orders-da68fcd397f87f203e64","key":"v1-c9ccc21dfe2a3058|orders-da68fcd397f87f203e64","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"经尿道前列腺电切术后管理（TURP）","category":"泌尿外科","raw":{"name":"经尿道前列腺电切术后管理（TURP）","category":"泌尿外科","summary":"经尿道前列腺电切术（TURP）是良性前列腺增生的经典术式，术后需重点管理出血、冲洗、膀胱痉挛、TURP综合征（稀释性低钠血症）与排尿功能恢复，远期注意尿道狭窄与逆行射精等。","symptoms":["术后血尿（初始为淡红色，逐渐转清；持续鲜红提示活动性出血）","膀胱痉挛：下腹胀痛、尿道口灼痛、强烈尿意，冲洗液反流","TURP综合征：烦躁、恶心呕吐、血压升高后下降、心率增快、意识改变（术中/术后早期）","排尿困难、尿线细、尿失禁（术后早期多见，多可恢复）","发热、腰痛（尿路感染/附睾炎）"],"diagnosis":["术后观察：尿色、冲洗液颜色、引流量（判断出血）","血常规+凝血功能：评估出血与贫血","电解质（血钠）：TURP综合征监测（血钠<125mmol/L为重度）","肾功能+尿常规：评估肾功能与感染","尿培养+药敏：发热者","膀胱超声：评估残余尿量、膀胱血块","尿道膀胱镜（术后狭窄/持续血尿）：评估尿道与膀胱颈情况"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（膀胱冲洗/补液）：","  用法：0.9%氯化钠 持续膀胱冲洗（术后24～48小时，冲洗速度依据尿色调整）；静脉补液按需","","方案2（止血）：","  用法：氨甲环酸 0.5～1g（NS 100ml 或 5%GS 100ml）静滴 qd（必要时）；维生素K1 10mg 静滴；必要时输血〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 头孢曲松 2g 静滴 qd（术后24～48小时，或按尿培养调整）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（解痉，膀胱痉挛）：","  用法：间苯三酚 40mg（NS 100ml 或 5%GS 100ml）静滴 qd～bid；或托特罗定 2mg bid（口服）","","📌 TURP综合征须立即停用冲洗、利尿、纠正低钠（3%氯化钠缓慢静滴），并请上级医师处理。"],"oral_medication":["⚠️ 术后用药，同类只选一种：","药物1（抗感染序贯）：","用法：头孢克肟 0.1g bid 或 左氧氟沙星 0.5g qd（疗程3～7天）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（解痉，膀胱痉挛）：","用法：托特罗定 2mg bid 或 索利那新 5mg qd（青光眼、尿潴留者慎用）","药物3（通便，防用力）：","用法：乳果糖 15ml bid（避免用力排便诱发出血）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（镇痛）：","用法：塞来昔布 200mg qd 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","📌 术后1～2个月内避免用力、久坐、骑车、性生活（防继发出血）。"],"treatment":["持续膀胱冲洗：术后24～48小时，冲洗速度依尿色调整，保持引流通畅，防止血块堵塞","止血处理：冲洗液鲜红时加快冲洗、牵引导尿管压迫膀胱颈、必要时膀胱镜下血块清除与电凝止血","膀胱痉挛处理：解痉药（间苯三酚 40mg 静滴 q8h、托特罗定 2mg 口服 bid）、调整导尿管气囊位置与牵引、适当镇痛","TURP综合征处理：立即停止冲洗、静脉利尿（呋塞米 20-40mg 静推）、缓慢静滴3%氯化钠纠正低钠、监测电解质与意识","抗感染：术后预防性抗生素24～48小时，如头孢呋辛 1.5g 静滴 q12h，有感染征象按培养调整","拔管与排尿训练：术后2～5天视尿色拔除导尿管，评估排尿与残余尿","远期并发症处理：尿道狭窄行尿道扩张/内切开；尿失禁行盆底肌训练"],"management":["冲洗与引流观察：记录冲洗液入量与出量、尿色变化（淡红→清亮为正常过程）","膀胱痉挛观察与处理：询问下腹胀痛与尿意，及时报告并遵医嘱解痉","电解质监测：术中/术后早期监测血钠（TURP综合征），注意烦躁、恶心、血压波动","体位与活动：术后平卧，导尿管牵引期间避免屈髋；拔管后逐步下床活动","排尿功能评估：拔管后观察排尿通畅度、尿线、有无尿失禁，必要时测残余尿","出院指导：术后1～2个月避免剧烈运动、久坐、骑车、重体力劳动与性生活；多饮水；出现血尿加重及时就诊"],"notes":["术后出血是最常见并发症，多数通过加快冲洗与牵引尿管控制，持续鲜红需膀胱镜处理","TURP综合征因冲洗液大量吸收致稀释性低钠血症，是术中/术后早期危重并发症，需高度警惕","术后早期尿失禁多为暂时性（尿道括约肌功能恢复需数周至数月），须做盆底肌训练","逆行射精是常见远期并发症（发生率约50%～70%），术前应告知患者"],"emergency":["冲洗液持续鲜红、血压下降（活动性出血）→ 立即加快冲洗、牵引尿管，必要时膀胱镜止血输血","烦躁、恶心呕吐、血压波动伴血钠下降（TURP综合征）→ 立即停冲洗、利尿、补高渗钠","高热寒战伴腰痛（尿源性脓毒症）→ 立即抗感染、留取培养、必要时解除梗阻"],"pinyin":"jndqlxqdszhgl","icd10":"N40","physical_exam":["生命体征：血压、心率、体温（评估出血、感染与TURP综合征）","意识状态：烦躁、嗜睡（TURP综合征重要表现）","腹部：下腹膨隆与压痛（膀胱充盈/血块堵塞）、有无腹膜刺激征","导尿管与冲洗：位置、牵引状态、冲洗液颜色与通畅度、尿道口有无渗血","膀胱区叩诊：浊音界（膀胱充盈程度）","下肢：有无水肿、深静脉血栓征象（术后卧床）","直肠指检（必要时）：前列腺窝情况、有无血肿"],"lab_tests":["血钠+电解质：术后早期监测（TURP综合征），异常者每4～6小时复查","血常规+凝血功能：评估出血与贫血，术后6～24小时复查","肾功能+尿常规：评估肾功能与感染","尿培养+药敏：发热或尿路感染征象时","前列腺特异性抗原（PSA）：术后随访（术后3个月复查基线值）","膀胱残余尿测定+尿流率：拔管后评估排尿功能","心电图（老年患者）：术前术后心血管评估"],"nursing":["冲洗护理：保持持续膀胱冲洗通畅，依尿色调整速度，防止血块堵塞；冲洗液温度适宜（接近体温）","出血观察：每30～60分钟观察尿色与冲出液，鲜红色立即报告医师","膀胱痉挛护理：观察下腹胀痛与尿意，安慰患者、调整尿管牵引、遵医嘱解痉","导尿管护理：妥善固定、防止牵拉与脱出，尿道口每日清洁，牵引期间避免屈髋","拔管后排尿指导：鼓励多饮水（每日2000～3000ml），观察排尿情况，指导盆底肌训练"],"diet":["术后6小时可进流质（麻醉清醒、无恶心呕吐后），逐步过渡到普食","多饮水（每日2000～3000ml），稀释尿液、减少血块形成","高纤维饮食（蔬菜、水果、粗粮），保持大便通畅，避免用力排便","忌辛辣刺激食物与酒类（刺激膀胱与前列腺窝出血）","适量优质蛋白促进创面愈合；避免浓茶咖啡（刺激膀胱）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1327},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"65e441f5ccfcc07770facca92f9d873b52748e010877ffc91c4347cebaef4818","pinyin":"jingniaodaoqianliexiandianqieshuhouguanli（TURP）","initials":"jndqlxdqshgl（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","术后血尿（初始为淡红色，逐渐转清；持续鲜红提示活动性出血）\\n膀胱痉挛：下腹胀痛、尿道口灼痛、强烈尿意，冲洗液反流\\nTURP综合征：烦躁、恶心呕吐、血压升高后下降、心率增快、意识改变（术中/术后早期）\\n排尿困难、尿线细、尿失禁（术后早期多见，多可恢复）\\n发热、腰痛（尿路感染/附睾炎）",60],["摘要","经尿道前列腺电切术（TURP）是良性前列腺增生的经典术式，术后需重点管理出血、冲洗、膀胱痉挛、TURP综合征（稀释性低钠血症）与排尿功能恢复，远期注意尿道狭窄与逆行射精等。",30],["疾病编码","N40",30],["原首字母","jndqlxqdszhgl",60]]},{"id":"orders-88a0310bbc7f92697021","key":"v1-c9ccc21dfe2a3058|orders-88a0310bbc7f92697021","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"股骨颈骨折","category":"骨科","raw":{"name":"股骨颈骨折","category":"骨科","summary":"股骨颈骨折多见于老年人（骨质疏松、跌倒）与高能量损伤的年轻人，是常见髋部骨折。因股骨头血供特殊，骨折不愈合与股骨头坏死发生率高。治疗依据年龄、骨折类型与移位程度选择内固定或关节置换。","symptoms":["髋部疼痛，不能站立与行走（不完全骨折可勉强行走）","患肢短缩、外旋畸形（典型外旋45°～60°）","髋部压痛、纵向叩击痛（足跟叩击痛）阳性","髋关节活动受限，被动活动疼痛加剧","嵌插型骨折症状轻，易漏诊（老年人跌倒后髋痛应警惕）"],"diagnosis":["髋关节X线（正位+侧位/斜位）：首选，可显示骨折线、移位与股骨颈干角变化","髋关节CT：X线阴性但临床怀疑者，或评估骨折细节","髋关节MRI：X线阴性、高度怀疑隐匿性骨折者的金标准","骨密度检查：老年患者评估骨质疏松","血常规+凝血+肝肾功能+心电图：术前评估（老年患者需评估心肺功能）","心脏超声+肺功能（必要时）：评估手术耐受性","下肢血管超声（疑深静脉血栓）：术前评估"],"infusion":["⚠️ 按围手术期需要选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴；过敏者用克林霉素 0.6g〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（镇痛）：","  用法：氟比洛芬酯 50mg（NS 100ml）静滴 q12h 或 曲马多 100mg 静滴 必要时；术前可行髂筋膜间隙阻滞","","方案3（抗凝预防深静脉血栓）：","  用法：低分子肝素 0.4ml 皮下注射 qd（术后12～24小时开始，按体重与肾功能调整）","","方案4（补液/支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；必要时输血（Hb<70g/L或<80g/L伴症状）","","📌 老年患者注意控制输液速度，避免心衰；抗凝需评估出血风险。"],"oral_medication":["⚠️ 术后与康复期用药，按医嘱选择：","药物1（镇痛）：","用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（抗骨质疏松）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd；阿仑膦酸钠 70mg 每周一次（空腹，服后直立30分钟）","药物3（抗凝序贯）：","用法：利伐沙班 10mg qd（术后35天，按医嘱）或 达比加群〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","药物4（通便）：","用法：乳果糖 15ml bid（卧床期间防便秘）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 抗骨质疏松治疗需长期坚持并定期复查骨密度与血钙。"],"treatment":["手术治疗为主：老年人（>65岁）移位型骨折推荐人工股骨头置换或全髋关节置换，以早期下床、减少卧床并发症","内固定：年轻患者、无移位或嵌插型骨折行闭合/切开复位空心钉内固定","术前准备：皮牵引/丁字鞋制动，完善检查，评估心肺功能，控制血糖与血压","术后康复：早期（术后1～2天）坐起与下床（置换者），逐步负重训练；内固定者遵医嘱部分负重","并发症防治：深静脉血栓（抗凝+气压治疗）、肺部感染（翻身拍背）、压疮（减压床垫）、泌尿系感染","抗骨质疏松治疗：老年患者规范治疗，预防再骨折"],"management":["术前制动与体位：患肢外展中立位，丁字鞋或皮牵引，避免内收内旋（防骨折移位加重）","疼痛管理：多模式镇痛（髂筋膜阻滞+静脉镇痛），评估疼痛评分","深静脉血栓预防：药物抗凝+间歇充气压力泵+早期活动，观察下肢肿胀与疼痛","术后观察：切口渗血、引流量、患肢末梢血运与感觉、足背动脉搏动","体位护理（置换术后）：避免患髋屈曲>90°、内收、内旋（防脱位），两腿间放置外展枕","康复训练：踝泵运动、股四头肌等长收缩、逐步坐起站立与行走（助行器保护）"],"notes":["老年人髋部骨折应尽早手术（一般48小时内），延迟手术增加卧床并发症与病死率","股骨颈骨折易发生股骨头缺血坏死（尤其移位型），需定期随访（X线/MRI）","置换术后需预防假体脱位：避免盘腿、坐矮凳、患侧卧位（术后早期）","老年患者需同时治疗骨质疏松，预防再骨折（'骨折联络服务'模式）"],"emergency":["患肢剧痛、肿胀进行性加重伴张力性水疱、足背动脉搏动减弱（骨筋膜室综合征）→ 急诊减压","术后突发呼吸困难、胸痛、血氧下降（肺栓塞）→ 立即抢救、抗凝、转ICU","术后切口大量渗血伴血压下降 → 急诊处理并输血"],"pinyin":"ggjz","icd10":"S72.0","physical_exam":["生命体征：血压、心率、呼吸（评估创伤与合并症）","一般情况：意识、营养状态、有无其他部位损伤","患肢视诊：短缩、外旋畸形（典型45°～60°）、肿胀、皮肤完整性","患肢触诊：髋部压痛、纵向叩击痛、骨擦感（避免反复检查）、皮温","髋关节活动度：主动与被动活动受限程度（疼痛明显时轻柔检查）","神经血管检查：足背动脉、胫后动脉搏动、足趾感觉与运动、毛细血管充盈","合并伤评估：脊柱、骨盆、颅脑及胸腹部损伤"],"lab_tests":["髋关节X线（正位+侧位）：首选，明确骨折部位、类型与移位程度","髋关节CT/MRI：X线阴性但疑隐匿骨折者（MRI为金标准）","血常规+凝血功能+肝肾功能+电解质：术前常规评估","心电图+心脏超声+肺功能：老年患者手术耐受性评估","血糖+糖化血红蛋白：糖尿病患者围手术期管理","骨密度（DEXA）+血钙磷+碱性磷酸酶+25-羟维生素D：骨质疏松评估与治疗依据","下肢静脉超声+D-二聚体：术前评估深静脉血栓（尤其伤后延迟手术者）"],"nursing":["术前护理：患肢制动（丁字鞋或皮牵引）、外展中立位，避免搬动时旋转患肢；观察末梢血运","疼痛护理：评估疼痛评分，遵医嘱镇痛，协助舒适体位（患肢垫软枕）","并发症预防：每2小时翻身（轴式翻身）、拍背排痰、踝泵运动、气压治疗预防深静脉血栓与压疮","术后护理：观察切口渗血、引流量、患肢肿胀与末梢血运，按医嘱使用抗凝药物","体位与康复：置换术后两腿间放外展枕，避免屈髋>90°、内收内旋；指导早期功能锻炼与助行器使用"],"diet":["高蛋白、高钙、高维生素饮食（牛奶、鱼虾、豆制品、绿叶蔬菜）促进骨折愈合","适量补充维生素D（晒太阳、蛋黄、深海鱼），必要时遵医嘱补充","多饮水（每日2000ml以上），预防泌尿系感染与便秘","多食蔬菜水果与粗粮，保持大便通畅（卧床期间易便秘）","控制体重与血糖，戒烟限酒（吸烟影响骨折愈合与伤口愈合）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1328},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"eaab81706e9bdfb5cac65ab8a39eb0efa69af36eebc2454f18081e77ff2bf296","pinyin":"gugujingguzhe","initials":"ggjgz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","髋部疼痛，不能站立与行走（不完全骨折可勉强行走）\\n患肢短缩、外旋畸形（典型外旋45°～60°）\\n髋部压痛、纵向叩击痛（足跟叩击痛）阳性\\n髋关节活动受限，被动活动疼痛加剧\\n嵌插型骨折症状轻，易漏诊（老年人跌倒后髋痛应警惕）",60],["摘要","股骨颈骨折多见于老年人（骨质疏松、跌倒）与高能量损伤的年轻人，是常见髋部骨折。因股骨头血供特殊，骨折不愈合与股骨头坏死发生率高。治疗依据年龄、骨折类型与移位程度选择内固定或关节置换。",30],["疾病编码","S72.0",30],["原首字母","ggjz",60]]},{"id":"orders-e6af6ef63ee746eb5dae","key":"v1-c9ccc21dfe2a3058|orders-e6af6ef63ee746eb5dae","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"骨筋膜室综合征","category":"骨科","raw":{"name":"骨筋膜室综合征","category":"骨科","summary":"骨筋膜室综合征是肢体骨筋膜室内压力升高致肌肉与神经缺血、坏死的急症，多见于前臂、小腿骨折后或挤压伤、血管损伤。典型表现为'5P征'（剧痛、被动牵拉痛、感觉异常、肌力减退、无脉/苍白），需紧急切开减压，否则致截肢或肾衰竭。","symptoms":["患肢进行性剧烈疼痛，与损伤程度不符，镇痛药难以缓解","被动牵拉痛（被动伸直手指或足趾时剧痛）——早期最可靠体征","患肢肿胀紧张、皮肤发亮、张力增高、皮温下降","感觉异常（麻木、蚁走感），逐渐出现肌力减退、瘫痪","晚期：远端动脉搏动消失、苍白、无脉（5P征全部出现提示已不可逆）"],"diagnosis":["临床评估为主：疼痛、被动牵拉痛、肿胀张力、感觉与肌力、脉搏（5P征）","筋膜室内压测定：>30mmHg（或舒张压-室压<30mmHg）提示需手术减压","患肢X线：明确骨折部位与类型","血常规+肌酸激酶（CK）+肌红蛋白+肾功能+电解质：评估肌肉坏死与横纹肌溶解（CK显著升高）","血气分析+乳酸：评估组织缺血与酸中毒","多普勒超声/血管造影（必要时）：评估血管损伤与血流","尿常规+尿肌红蛋白：警惕急性肾损伤"],"infusion":["⚠️ 抢救用药，须在准备手术的同时进行！","方案1（碱化尿液、保护肾脏，横纹肌溶解）：","用法：5%碳酸氢钠 125～250ml 静滴（维持尿pH>6.5）；0.9%氯化钠 大量补液（维持尿量>100ml/h，按心功能调整）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","方案2（抗感染，切开减压后）：","用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（开放创面）〔调 CrCl<30 减量；青霉素过敏禁用〕","方案3（镇痛/支持）：","用法：曲马多 100mg 静滴 必要时（注意疼痛可能被掩盖）；白蛋白、必要时输血","📌 禁止抬高患肢（降低灌注压加重缺血）；禁止冷敷（加重血管收缩）；禁止按摩。"],"oral_medication":["⚠️ 急性期以静脉治疗与手术为主，不宜口服给药；恢复期遵医嘱：","药物1（镇痛）：","用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（营养神经）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid","药物3（通便）：","用法：乳果糖 15ml bid（卧床防便秘）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 康复期需配合物理治疗与功能锻炼，防止关节僵硬与肌肉萎缩。"],"treatment":["紧急筋膜切开减压：明确诊断后应立即手术（不可等待），行筋膜切开+坏死组织清除，创面开放引流","解除外固定与包扎：立即松解石膏、绷带、敷料，患肢置于心脏水平（不抬高）","血运与骨折处理：合并血管损伤者行血管探查修复；骨折行外固定支架固定","横纹肌溶解处理：大量补液、碱化尿液、利尿，监测肾功能、CK与电解质，必要时血液净化（CRRT）","创面处理：减压后创面开放，待肿胀消退后（约5～7天）二期缝合或植皮","抗感染：开放创面需抗生素，按培养调整","晚期处理：肌肉坏死广泛者（功能丧失、感染无法控制）考虑截肢；后期行功能重建"],"management":["立即解除外固定与包扎，患肢平放（不抬高、不冷敷、不按摩）","严密观察：疼痛程度、被动牵拉痛、感觉与肌力、末梢循环（每15～30分钟评估）","监测筋膜室内压（必要时），做好急诊手术准备（禁食、备皮、备血）","液体与尿量管理：维持尿量>100ml/h，监测尿色（茶色/酱油色提示肌红蛋白尿）","术后创面护理：观察渗液、气味、颜色，保持引流通畅，注意无菌操作","肾功能监测：每日查肾功能、CK、电解质，警惕急性肾损伤"],"notes":["骨筋膜室综合征是急症，'宁可切开、不可延误'——延误可致不可逆肌肉神经坏死","被动牵拉痛是最重要的早期体征，远端动脉搏动存在不能排除本病","严禁抬高患肢、冷敷与按摩（均加重缺血）","警惕横纹肌溶解致急性肾损伤与挤压综合征（大量肌红蛋白入血）"],"emergency":["剧痛进行性加重+被动牵拉痛+患肢紧张发硬 → 立即急诊筋膜切开减压","尿色呈茶色/酱油色、尿量减少（横纹肌溶解/急性肾损伤）→ 立即补液碱化尿液，必要时CRRT","肢体远端发凉、发绀、无脉（晚期缺血）→ 急诊手术探查，必要时截肢"],"pinyin":"gjmszhz","icd10":"M79.8","physical_exam":["生命体征：血压、心率、呼吸（评估挤压伤全身反应）","一般情况：意识、有无合并颅脑与胸腹损伤、尿量","患肢视诊：肿胀程度、皮肤张力与颜色（苍白/发绀/水疱）、有无开放伤口","患肢触诊：张力（硬如木板）、皮温、压痛范围、骨擦感","被动牵拉痛：被动伸直手指/足趾是否引起剧痛（关键体征）","神经评估：感觉（麻木范围）、肌力（分度记录）、两点辨别觉","血管评估：足背/胫后动脉或桡/尺动脉搏动、毛细血管充盈时间、肢体远端温度"],"lab_tests":["肌酸激酶（CK）+肌红蛋白：显著升高提示肌肉坏死程度，需动态监测（每6～12小时）","肾功能（肌酐、尿素氮）+电解质+血气分析：评估急性肾损伤与酸中毒","尿常规+尿肌红蛋白+尿量：监测肌红蛋白尿与肾功能","血常规+凝血功能+D-二聚体：评估创伤性凝血病与DIC","筋膜室内压测定：>30mmHg或舒张压-室压<30mmHg为手术指征","患肢X线：明确骨折部位与类型（不可因检查延误减压）","肝功能+血钙磷（挤压综合征）：评估器官功能与电解质紊乱"],"nursing":["紧急处理：立即松解石膏/绷带/敷料，患肢置于心脏水平，禁止抬高、冷敷与按摩","疼痛观察：每15～30分钟评估疼痛程度与被动牵拉痛，镇痛药物不能掩盖病情观察","循环监测：观察末梢皮肤颜色、温度、动脉搏动与毛细血管充盈，异常立即报告","术前护理：迅速禁食、备皮、备血、建立静脉通路，做好急诊手术准备","术后护理：创面开放引流，观察渗液与气味，保持敷料清洁；监测尿量（>100ml/h）、尿色与肾功能"],"diet":["急性期禁食（准备急诊手术）","术后高蛋白、高热量、高维生素饮食促进创面愈合与组织修复","大量饮水（在尿量允许下）促进肌红蛋白排泄，必要时碱化尿液","多食蔬菜水果防便秘；避免高钾食物（肾功能受损者限制香蕉、橙子、土豆）","戒烟（影响微循环与愈合）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1329},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4283a9a0ee41df9c85ebf75f42b878669ef4a02c3548d837663dc1960b80e18f","pinyin":"gujinmoshizonghezheng","initials":"gjmszhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","患肢进行性剧烈疼痛，与损伤程度不符，镇痛药难以缓解\\n被动牵拉痛（被动伸直手指或足趾时剧痛）——早期最可靠体征\\n患肢肿胀紧张、皮肤发亮、张力增高、皮温下降\\n感觉异常（麻木、蚁走感），逐渐出现肌力减退、瘫痪\\n晚期：远端动脉搏动消失、苍白、无脉（5P征全部出现提示已不可逆）",60],["摘要","骨筋膜室综合征是肢体骨筋膜室内压力升高致肌肉与神经缺血、坏死的急症，多见于前臂、小腿骨折后或挤压伤、血管损伤。典型表现为'5P征'（剧痛、被动牵拉痛、感觉异常、肌力减退、无脉/苍白），需紧急切开减压，否则致截肢或肾衰竭。",30],["疾病编码","M79.8",30],["原首字母","gjmszhz",60]]},{"id":"orders-b5dfd3de37b2f6c5644d","key":"v1-c9ccc21dfe2a3058|orders-b5dfd3de37b2f6c5644d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化脓性骨髓炎","category":"骨科","raw":{"name":"化脓性骨髓炎","category":"骨科","summary":"化脓性骨髓炎是骨组织（骨髓、骨质、骨膜）的化脓性感染，多由金黄色葡萄球菌经血行（急性血源性）或开放性骨折、手术后（创伤性/术后）感染所致。急性期以抗感染为主，慢性期常需手术清创+死腔处理，易复发。","symptoms":["急性期：寒战高热（体温可达39℃以上）、患肢剧痛、局部红肿热、活动受限","患肢局部压痛明显、肿胀，可有波动感（骨膜下脓肿）","慢性期：窦道形成、反复流脓、局部肿痛、患肢畸形或短缩","全身：乏力、消瘦、贫血、食欲减退（慢性消耗）","婴幼儿可表现为烦躁、拒奶、假性瘫痪（患肢不敢活动）"],"diagnosis":["血常规+CRP+PCT+血培养：急性期白细胞与炎症指标显著升高，血培养阳性率约50%","X线：急性期早期可阴性（2周后出现骨质破坏、骨膜反应），慢性期可见死骨、包壳、窦道","MRI：早期诊断最敏感，可显示骨髓水肿、骨膜下脓肿与软组织脓肿范围","CT：显示死骨、骨皮质破坏与死腔优于X线","穿刺/脓液培养及药敏：明确病原菌（最关键），必要时骨活检","骨扫描（ECT）：早期敏感但特异性差","窦道造影：明确窦道走行与死腔范围"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（急性期经验性抗感染，覆盖金黄色葡萄球菌）：","  用法：头孢唑林 1～2g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 氯唑西林 2g 静滴 q6h；或万古霉素 1g 静滴 q12h（疑MRSA，监测血药浓度）〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","","方案2（重症/混合感染）：","  用法：哌拉西林他唑巴坦 4.5g（NS 100ml 或 5%GS 100ml）静滴 q8h + 万古霉素 1g 静滴 q12h〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（支持治疗）：","  用法：0.9%氯化钠/葡萄糖 静滴；白蛋白、输血（贫血者）；必要时营养支持","","📌 抗感染疗程长（急性期4～6周，慢性期术后6～12周），必须依培养与药敏调整，且需充分引流。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（口服序贯，敏感菌）：","用法：头孢氨苄 0.5g qid 或 阿莫西林克拉维酸 0.625g tid；克林霉素 0.3g qid（青霉素过敏）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（MRSA，口服序贯）：","用法：利奈唑胺 0.6g bid 或 复方磺胺甲噁唑 2片 bid（需监测血常规与肝肾功能）","药物3（对症/支持）：","用法：对乙酰氨基酚 0.5g 必要时；碳酸钙D3 600mg qd（骨质疏松/骨修复）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 口服抗感染须严格遵医嘱足疗程完成，不可自行停药（易复发、致耐药）。"],"treatment":["抗感染：早期足量静脉给药（覆盖金黄色葡萄球菌），据血/脓培养与药敏调整，疗程足够（急性4～6周）","引流：骨膜下脓肿或软组织脓肿应尽早切开引流，缓解骨内压、防止死骨形成","手术清创：慢性骨髓炎需手术清除死骨、坏死组织与窦道，处理死腔（肌瓣填塞、抗生素骨水泥、载抗生素骨水泥链珠）","固定：患肢制动（石膏、支具或外固定支架），防止病理性骨折","支持治疗：营养支持、纠正贫血与低蛋白、镇痛","窦道处理：保持引流通畅，避免窦道闭合致感染扩散","长期随访：X线/CT/MRI复查，监测复发（慢性骨髓炎复发率高）"],"management":["观察全身与局部：体温、局部红肿热、疼痛、窦道分泌物量与性状","患肢制动与保护：石膏或支具固定，避免负重与病理性骨折","引流/窦道护理：保持引流通畅，每日换药，观察分泌物性状与气味","抗感染管理：严格按时给药，观察药物不良反应（万古霉素需监测血药浓度与肾功能）","营养与支持：高蛋白、高热量饮食，必要时肠内/肠外营养；纠正贫血","康复训练：急性期制动，稳定后逐步关节活动与肌力训练，防止关节僵硬"],"notes":["急性骨髓炎治疗不及时可转为慢性，导致死骨形成、窦道与长期反复发作","病原学检查（血培养、脓液培养）是用药关键，应在抗生素使用前留取","慢性骨髓炎单纯抗感染难以治愈，必须手术清除死骨与死腔","糖尿病足合并骨髓炎需同时控制血糖、改善血供（血管评估）"],"emergency":["急性骨髓炎伴高热寒战、血压下降（脓毒症）→ 立即抢救并急诊引流","患肢剧烈疼痛伴张力增高、被动牵拉痛（合并骨筋膜室综合征）→ 急诊减压","病理性骨折或大量流脓伴全身中毒症状 → 急诊清创处理"],"pinyin":"hnxgmy","icd10":"M86.9","physical_exam":["生命体征：体温、脉搏、血压（评估感染/脓毒症）","一般情况：营养状态、贫血貌、精神萎靡、慢性消耗表现","患肢视诊：肿胀、皮肤发红、窦道及分泌物、瘢痕、肢体畸形或短缩","患肢触诊：局部皮温升高、压痛范围、波动感（脓肿）、骨性隆起（骨包壳）","关节活动度：相邻关节活动受限程度（疼痛所致）","神经血管：远端动脉搏动、感觉与肌力（长期病变可致神经受压）","脊柱/多发部位检查：血源性骨髓炎可累及多处（小儿多见）"],"lab_tests":["血常规+CRP+PCT：评估感染程度，治疗中每1～2周复查（CRP下降提示有效）","血培养×2套+脓液/骨组织培养及药敏：抗生素使用前留取，明确病原菌（关键）","X线（患肢正侧位）：急性期早期可阴性，慢性期观察死骨、包壳与骨破坏","MRI（患肢）：早期诊断与评估脓肿范围（敏感度最高）","CT：评估死骨、骨皮质破坏与死腔范围（术前规划）","肝肾功能+电解质+白蛋白：评估营养状态与用药安全（万古霉素需监测肾功能与血药浓度）","骨扫描（ECT）：多发或早期病例筛查（必要时）"],"nursing":["病情观察：每4小时测体温，观察局部红肿热痛范围及窦道分泌物量、性状与气味","患肢护理：制动、抬高（减轻肿胀）、避免负重与挤压，防止病理性骨折","换药与引流护理：严格无菌操作，保持引流通畅，观察引流液与窦道分泌物变化","用药护理：按时静脉给药，观察药物不良反应（皮疹、腹泻、肾功能损害），万古霉素输注时间>60分钟","营养与心理护理：鼓励高蛋白高热量饮食，慢性病程长需心理支持与康复指导"],"diet":["高蛋白、高热量饮食（鱼、瘦肉、蛋、奶、豆制品）促进骨修复与抗感染","高维生素：新鲜蔬菜水果，必要时补充维生素C与维生素D","充足钙与磷（牛奶、虾皮、骨头汤）及维生素D促进骨愈合","多饮水（每日2000ml以上），促进代谢产物排泄","贫血者增加含铁食物（动物肝脏、红肉）；忌烟酒与辛辣刺激"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1330},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"55b77bf19ae828aa0279ffa2287ee89e051a704c101bcf6a501a4ae0dd4c3e20","pinyin":"huanongxinggusuiyan","initials":"hnxgsy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性期：寒战高热（体温可达39℃以上）、患肢剧痛、局部红肿热、活动受限\\n患肢局部压痛明显、肿胀，可有波动感（骨膜下脓肿）\\n慢性期：窦道形成、反复流脓、局部肿痛、患肢畸形或短缩\\n全身：乏力、消瘦、贫血、食欲减退（慢性消耗）\\n婴幼儿可表现为烦躁、拒奶、假性瘫痪（患肢不敢活动）",60],["摘要","化脓性骨髓炎是骨组织（骨髓、骨质、骨膜）的化脓性感染，多由金黄色葡萄球菌经血行（急性血源性）或开放性骨折、手术后（创伤性/术后）感染所致。急性期以抗感染为主，慢性期常需手术清创+死腔处理，易复发。",30],["疾病编码","M86.9",30],["原首字母","hnxgmy",60]]},{"id":"orders-96233460a05b7e75d6c5","key":"v1-c9ccc21dfe2a3058|orders-96233460a05b7e75d6c5","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腹股沟疝（成人）","category":"疝与腹壁外科","raw":{"name":"腹股沟疝（成人）","category":"疝与腹壁外科","summary":"腹股沟疝是腹腔内脏器经腹股沟区薄弱处突出形成的疝，分为斜疝（经腹股沟管深环，最多见，可进入阴囊）、直疝（经直疝三角，少见于老年人）和股疝（经股环，女性多见、最易嵌顿）。成人腹股沟疝不能自愈，原则上应手术治疗，首选无张力修补（补片）。","symptoms":["腹股沟区可复性包块：站立、行走、咳嗽或用力时出现，平卧或手推可回纳","局部坠胀感或隐痛，久站、劳累后加重","斜疝包块呈梨形，可降入阴囊（男性）；直疝呈半球形，一般不进入阴囊","难复性疝：包块不能完全回纳（内容物与疝囊粘连），无明显疼痛","嵌顿/绞窄：包块突然增大、变硬、不能回纳，剧痛伴恶心呕吐（肠梗阻）、发热、腹膜刺激征"],"diagnosis":["体格检查：站立位与卧位对比、咳嗽冲击感（指尖冲击试验）、能否回纳、疝环大小（最关键）","腹股沟区超声：明确疝内容物与疝环，鉴别淋巴结肿大、鞘膜积液、精索静脉曲张、脂肪瘤","腹部CT（含Valsalva）：肥胖、隐匿疝、复发疝或拟腹腔镜手术者，明确分型与解剖","腹部立位平片：嵌顿疝合并肠梗阻时可见气液平面","血常规+CRP+乳酸：嵌顿/绞窄时白细胞升高、乳酸升高（提示肠缺血）","鉴别诊断：鞘膜积液（透光试验阳性）、精索静脉曲张、睾丸肿瘤、隐睾、股疝（女性）"],"infusion":["⚠️ 按围手术期需要选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时，置入补片者必用）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴；青霉素过敏者克林霉素 0.6g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（嵌顿/绞窄术前，合并肠梗阻）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；平衡盐溶液 500～1000ml 静滴补液〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（术后支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；老年患者注意补液速度","","📌 无张力修补（补片）术为清洁手术，预防性抗生素以覆盖金黄色葡萄球菌为主。"],"oral_medication":["⚠️ 术后用药，按医嘱选择，同类只选一种：","药物1（镇痛）：","用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物2（通便，防腹压增高）：","用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物3（镇咳，慢性咳嗽者）：","用法：复方甲氧那明 2粒 tid 或 氨溴索 30mg tid；吸烟者术前戒烟≥2周〔调 妊娠早期禁用；胃溃疡者慎用〕","药物4（前列腺增生者，防排尿困难）：","用法：坦索罗辛 0.2mg qn（遵医嘱）","📌 术后避免用力排便、剧烈咳嗽与提重物（腹压增高是复发主因）。"],"treatment":["成人腹股沟疝原则上均应手术：疝不能自愈，且嵌顿风险随病程增加（股疝嵌顿率最高）","无张力修补术：Lichtenstein术（开放，平片补片）为经典术式；腹腔镜TAPP/TEP适用于双侧疝、复发疝、需快速恢复者","组织修补（Bassini/Shouldice）：仅用于补片禁忌（感染风险高、补片过敏）者，复发率高","嵌顿疝：手法复位（嵌顿<4～6小时、无绞窄征象）成功后择期手术；复位失败或疑绞窄者急诊手术","绞窄疝：急诊手术，切除坏死肠管+疝修补（感染情况下不做补片修补）","术前优化：控制慢性咳嗽、便秘、前列腺增生，戒烟，减重，控制血糖","术后并发症处理：血清肿（多自行吸收，避免反复穿刺）、慢性疼痛（神经阻滞/药物）、切口感染（换药引流，必要时取出补片）"],"management":["术前准备：完善检查（血常规、凝血、心电图、胸片）、控制咳嗽与便秘、备皮、术前排空膀胱","术后体位与活动：麻醉清醒后取平卧位（可垫高阴囊），术后6小时可下床轻度活动","切口观察：观察有无渗血、渗液、红肿；阴囊水肿/血清肿常见（可自行吸收，避免挤压）","疼痛管理：评估疼痛评分，遵医嘱镇痛；术后慢性疼痛（>3个月）需专科评估","腹压管理：避免剧烈咳嗽、用力排便、提重物（术后1～3个月内），必要时用药控制","出院指导：术后1周、1个月门诊复查；腹腔镜术后2周内避免剧烈运动；复发及时就诊"],"notes":["成人腹股沟疝不会自愈，'疝气带'仅能临时缓解症状，不能治愈，且可能增加嵌顿风险","股疝（女性多见）最易嵌顿绞窄，一经确诊应尽早手术","嵌顿疝手法复位成功后仍需择期手术（复发嵌顿率高）","腹腔镜修补（TAPP/TEP）术后恢复快、慢性疼痛少，但对术者技术要求高","腹压增高因素（慢性咳嗽、便秘、前列腺增生、重体力劳动）需同步治疗，否则易复发"],"emergency":["包块突然增大变硬、不能回纳伴剧痛、呕吐（嵌顿）→ 急诊手术","发热、心率增快、腹膜刺激征、乳酸升高（绞窄坏死）→ 立即急诊手术","手法复位后腹痛加重、出现腹膜炎（假性复位）→ 立即手术探查"],"pinyin":"fggscrz","icd10":"K40.9","physical_exam":["生命体征：体温、脉搏、血压（嵌顿时评估感染与休克）","一般情况：年龄、有无慢性咳嗽、便秘、前列腺增生、重体力劳动史","站立位视诊：包块位置、形状（梨形/半球形）、是否降入阴囊、体位变化时变化","卧位触诊：能否回纳、疝环大小（可容指尖/指/两指）、咳嗽冲击感","鉴别检查：透光试验（鞘膜积液阳性）、睾丸与附睾触诊、精索情况","嵌顿评估：包块张力、压痛、皮肤颜色与温度、有无腹膜刺激征","对侧与股部检查：有无双侧疝、股疝（卵圆窝处包块）"],"lab_tests":["血常规+CRP：术前基线，嵌顿时白细胞升高提示感染/绞窄","乳酸+血气分析：嵌顿/绞窄时乳酸升高提示肠缺血坏死（重要指标）","凝血功能+肝肾功能+心电图+胸片：术前常规评估（老年患者需心肺评估）","腹股沟区超声：明确疝内容物与疝环，鉴别鞘膜积液、淋巴结、精索静脉曲张","腹部CT（含Valsalva）：隐匿疝、复发疝、双侧疝或拟腹腔镜手术者的术前评估","腹部立位平片：嵌顿疝合并肠梗阻时（气液平面）","血糖+糖化血红蛋白：糖尿病患者术前控糖（影响补片感染风险）"],"nursing":["术前护理：戒烟、训练床上排便与有效咳嗽（按压切口）、术前排空膀胱、备皮","术后体位：平卧、可垫高阴囊（减轻水肿），麻醉清醒后6小时可下床轻度活动","切口与阴囊观察：注意渗血、阴囊水肿与血肿（必要时冷敷、托起阴囊）","腹压管理：指导避免剧烈咳嗽、用力排便与提重物，必要时使用镇咳通便药","疼痛护理：评估疼痛并遵医嘱镇痛，指导咳嗽时用手按压切口减轻张力","出院宣教：保持切口清洁干燥、术后1～3个月避免重体力劳动、按时复查"],"diet":["术前禁食禁水6～8小时","术后6小时可进流质，逐步过渡到半流质、软食、普食","高蛋白、高维生素饮食促进切口与补片愈合","多饮水、多食蔬菜水果与粗纤维，保持大便通畅（防便秘致腹压增高）","忌辛辣刺激、产气食物与烟酒；慢性咳嗽者积极治疗呼吸道疾病"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1331},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8bd49d127a6534f8a8e22b8c7a1dbbda6ebed5f5034b3853dd539cb15f0142df","pinyin":"fugugoushan（chengren）","initials":"fggs（cr）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹股沟区可复性包块：站立、行走、咳嗽或用力时出现，平卧或手推可回纳\\n局部坠胀感或隐痛，久站、劳累后加重\\n斜疝包块呈梨形，可降入阴囊（男性）；直疝呈半球形，一般不进入阴囊\\n难复性疝：包块不能完全回纳（内容物与疝囊粘连），无明显疼痛\\n嵌顿/绞窄：包块突然增大、变硬、不能回纳，剧痛伴恶心呕吐（肠梗阻）、发热、腹膜刺激征",60],["摘要","腹股沟疝是腹腔内脏器经腹股沟区薄弱处突出形成的疝，分为斜疝（经腹股沟管深环，最多见，可进入阴囊）、直疝（经直疝三角，少见于老年人）和股疝（经股环，女性多见、最易嵌顿）。成人腹股沟疝不能自愈，原则上应手术治疗，首选无张力修补（补片）。",30],["疾病编码","K40.9",30],["原首字母","fggscrz",60]]},{"id":"orders-72f71d9943fe28999305","key":"v1-c9ccc21dfe2a3058|orders-72f71d9943fe28999305","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"大隐静脉曲张","category":"血管外科","raw":{"name":"大隐静脉曲张","category":"血管外科","summary":"大隐静脉曲张是下肢浅静脉因静脉壁薄弱、瓣膜功能不全致血液反流、静脉高压，表现为下肢浅静脉迂曲扩张。按CEAP分级评估严重程度（C0～C6，C6为活动性溃疡）。治疗包括弹力袜压迫、硬化剂注射、激光/射频腔内闭合（EVLA/RFA）及大隐静脉高位结扎+剥脱术。","symptoms":["下肢浅静脉迂曲、扩张、隆起（小腿内侧大隐静脉走行区最明显），站立时加重、平卧抬高患肢减轻","患肢酸胀、沉重、乏力、易疲劳，久站久坐后加重","踝部与足靴区轻度肿胀（下午明显），夜间可抽筋","病程进展：皮肤营养障碍——色素沉着、湿疹、脂质硬化、白色萎缩，最终形成静脉性溃疡（C6）","并发症：血栓性浅静脉炎（局部红肿热痛、条索状硬结）、曲张静脉破裂出血、深静脉血栓"],"diagnosis":["体格检查：站立位视诊静脉曲张范围与CEAP分级，Trendelenburg试验（判断大隐静脉瓣膜功能）、Perthes试验（判断深静脉通畅性）","下肢静脉彩色多普勒超声：首选，评估大隐/小隐静脉反流时间（>0.5秒为异常）、深静脉通畅性与瓣膜功能（术前必查）","下肢静脉造影：必要时（复杂病例、复发、拟手术者）","D-二聚体+凝血功能：疑血栓性浅静脉炎或深静脉血栓时","踝肱指数（ABI）：合并动脉硬化闭塞症者评估动脉血供（排除动脉性溃疡）","排除继发性因素：髂静脉受压（May-Thurner）、下腔静脉阻塞、盆腔肿瘤压迫（左下肢突发肿胀者）"],"infusion":["⚠️ 按病情选择方案，切勿全部同时使用！","","方案1（术前/术后静脉活性药物）：","  用法：七叶皂苷钠 10～20mg + 0.9%氯化钠 250ml 静滴 qd；或地奥司明静脉制剂","","方案2（血栓性浅静脉炎/抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（合并感染）；必要时低分子肝素 0.4ml 皮下注射 qd（按医嘱）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（术后补液支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；老年患者注意补液量与速度","","📌 术前需评估深静脉通畅性；术后按医嘱使用抗凝药物预防深静脉血栓。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（静脉活性药物，改善症状）：","用法：地奥司明片 2片 bid（午餐、晚餐时服）或 迈之灵 2片 bid；或 羟苯磺酸钙 0.5g tid","药物2（镇痛）：","用法：塞来昔布 200mg qd 或 洛索洛芬钠 60mg tid（餐后）〔调 ★ eGFR<30 禁用；心血管血栓风险〕","药物3（抗凝预防，术后，按医嘱）：","用法：利伐沙班 10mg qd 或 低分子肝素（注射）〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","药物4（通便）：","用法：乳果糖 15ml bid〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 药物仅缓解症状，不能根治；弹力袜与手术是主要治疗手段。"],"treatment":["压迫治疗：医用弹力袜（压力19～30mmHg或更高，根据CEAP分级选择）——适用于早期、症状轻、妊娠期、不愿手术者，需长期穿着（晨起穿、睡前脱）","硬化剂注射+加压：适用于小范围、术后残留或复发的曲张静脉；禁忌用于大隐静脉主干反流","腔内热消融（EVLA激光/RFA射频）：大隐静脉主干反流的首选微创术式，创伤小、恢复快","高位结扎+剥脱术（传统手术）：大隐静脉高位结扎+主干及曲张静脉剥脱，适用于粗大主干、瘤样扩张者","CHIVA/血流动力学纠正术：保留静脉的微创术式，需术者熟练掌握超声血流动力学评估","溃疡处理：静脉性溃疡以压力治疗+清创+敷料为主，必要时植皮；同时处理反流静脉以促进愈合","并发症处理：血栓性浅静脉炎（抗炎、抗凝、必要时剥脱）、曲张静脉破裂出血（加压止血、抬高患肢、必要缝合）"],"management":["术前评估：下肢静脉超声（深静脉通畅性、反流部位）、ABI（排除动脉病变）、CEAP分级记录","弹力袜使用指导：测量踝围与小腿围选择合适尺寸，晨起未下床前穿，睡前脱下；注意皮肤观察与清洁","术后护理：抬高患肢（高于心脏水平20～30cm）、弹力绷带/弹力袜加压（一般持续2～6周）、早期下床活动","观察患肢：皮温、颜色、肿胀、足背动脉搏动、有无小腿疼痛与压痛（警惕深静脉血栓）","抗凝与出血观察：按医嘱使用抗凝药物，观察切口渗血、皮下瘀斑与牙龈出血","康复指导：避免久站久坐（每30～60分钟活动下肢、踝泵运动）、控制体重、抬高下肢休息","随访：术后1、3、6个月复查静脉超声，评估反流复发与溃疡愈合情况"],"notes":["术前必须行下肢静脉超声，确认深静脉通畅——深静脉阻塞者禁忌行浅静脉剥脱（会加重肢体肿胀）","弹力袜是基础治疗，需长期坚持；尺寸不当会影响疗效并致皮肤损伤","静脉性溃疡愈合慢、易复发，压力治疗（弹力袜/绷带）是愈合与防复发的关键","避免久站久坐、跷二郎腿；睡眠时抬高下肢15～20cm；控制体重与便秘","左下肢突发明显肿胀需警惕髂静脉受压综合征或深静脉血栓（及时超声检查）"],"emergency":["曲张静脉破裂出血（喷血或涌血）→ 立即抬高患肢、局部加压包扎，必要时缝合止血","下肢突发明显肿胀、疼痛、皮温升高（深静脉血栓）→ 急诊超声并抗凝治疗","曲张静脉红肿热痛形成条索伴发热（血栓性浅静脉炎）→ 抗炎抗凝，评估血栓蔓延至深静脉风险"],"pinyin":"dyjmqz","icd10":"I83.9","physical_exam":["生命体征：血压、心率、体温（合并血栓或感染时）","站立位视诊：曲张静脉分布与范围、CEAP分级（C0～C6）、有无溃疡、色素沉着、湿疹、脂质硬化","Trendelenburg试验：抬高患肢排空静脉后止血带阻断，观察充盈顺序判断瓣膜功能","Perthes试验（深静脉通畅试验）：行走后曲张静脉是否减轻、有无肢体肿胀加重","触诊：曲张静脉质地（柔软/硬结）、皮温、压痛、有无条索状硬结（血栓性静脉炎）","足背动脉搏动+踝肱指数：评估动脉血供（溃疡鉴别）","下肢周径测量：双侧对比评估水肿程度（髌骨上/下缘10cm）；Homan征（深静脉血栓）"],"lab_tests":["下肢静脉彩色多普勒超声：必查，评估大隐/小隐静脉反流时间、深静脉通畅性与瓣膜功能","D-二聚体+凝血功能：疑血栓性浅静脉炎或深静脉血栓时，术后抗凝监测","血常规+CRP：溃疡或血栓性静脉炎合并感染时","踝肱指数（ABI）+下肢动脉超声：排除动脉硬化闭塞症（溃疡鉴别）","血糖+糖化血红蛋白：糖尿病足与溃疡鉴别及术前控糖","肝肾功能+心电图：术前评估与用药安全（尤其抗凝药物）","必要时下肢静脉造影/CTV：复杂、复发或疑髂静脉受压者"],"nursing":["术前护理：皮肤准备（尤其溃疡创面清洁换药）、弹力袜测量与试穿、评估深静脉通畅性","术后体位：患肢抬高20～30cm（高于心脏水平），促进静脉回流、减轻肿胀","弹力绷带/弹力袜护理：保持平整无皱褶、松紧适宜，观察末梢血运、皮温、足背动脉搏动","早期活动：术后6小时床上踝泵运动，术后第1天下床活动（预防深静脉血栓）","并发症观察：切口渗血、皮下瘀斑、小腿肿胀疼痛（深静脉血栓）、足背麻木与感觉异常（神经损伤）","健康宣教：避免久站久坐与跷腿、控制体重、坚持穿弹力袜、抬高下肢休息、按时复查"],"diet":["高纤维饮食（蔬菜、水果、粗粮），保持大便通畅（防便秘增加腹压，影响静脉回流）","适量优质蛋白促进溃疡与切口愈合（鱼、瘦肉、蛋、奶）","限制高盐饮食，减轻水肿","控制总热量与体重（肥胖是静脉曲张加重因素）","多饮水，忌辛辣刺激与酒类；戒烟（吸烟影响血管内皮功能）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1332},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a85895d68275951934b62bef5b03a8c36bf78c95ae78c6f1ead5de34278a0953","pinyin":"dayinjingmaiquzhang","initials":"dyjmqz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","下肢浅静脉迂曲、扩张、隆起（小腿内侧大隐静脉走行区最明显），站立时加重、平卧抬高患肢减轻\\n患肢酸胀、沉重、乏力、易疲劳，久站久坐后加重\\n踝部与足靴区轻度肿胀（下午明显），夜间可抽筋\\n病程进展：皮肤营养障碍——色素沉着、湿疹、脂质硬化、白色萎缩，最终形成静脉性溃疡（C6）\\n并发症：血栓性浅静脉炎（局部红肿热痛、条索状硬结）、曲张静脉破裂出血、深静脉血栓",60],["摘要","大隐静脉曲张是下肢浅静脉因静脉壁薄弱、瓣膜功能不全致血液反流、静脉高压，表现为下肢浅静脉迂曲扩张。按CEAP分级评估严重程度（C0～C6，C6为活动性溃疡）。治疗包括弹力袜压迫、硬化剂注射、激光/射频腔内闭合（EVLA/RFA）及大隐静脉高位结扎+剥脱术。",30],["疾病编码","I83.9",30],["原首字母","dyjmqz",60]]},{"id":"orders-93dd3d3a16eb3b6e9760","key":"v1-c9ccc21dfe2a3058|orders-93dd3d3a16eb3b6e9760","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"甲状腺结节外科处理","category":"甲状腺乳腺外科","raw":{"name":"甲状腺结节外科处理","category":"甲状腺乳腺外科","summary":"甲状腺结节是甲状腺内局部异常生长的肿块，成人超声检出率高达20%～70%，其中恶性约5%～15%。处理核心是良恶性鉴别（超声TI-RADS分级+细针穿刺FNA），以及是否需要手术及手术方式（腺叶切除/全切/颈淋巴结清扫）。","symptoms":["多无症状，体检或超声偶然发现颈部肿块","结节较大时可自觉颈部异物感、吞咽不适、声音嘶哑（压迫喉返神经提示恶性可能）","颈侧区淋巴结肿大（提示淋巴结转移）","合并甲亢时心悸、多汗、消瘦；合并甲减时乏力、畏寒、水肿","结节迅速增大、质地坚硬、活动度差、伴声嘶或呼吸困难提示恶性或压迫"],"diagnosis":["甲状腺超声：首选——评估结节大小、形态（纵横比>1）、边界、回声、钙化（微钙化提示恶性）、血流，按TI-RADS分级","甲状腺功能（FT3、FT4、TSH）+甲状腺抗体：评估功能状态，指导治疗","细针穿刺抽吸细胞学检查（FNA）：TI-RADS≥4类或结节≥1cm（高危者>0.5cm）时行，按Bethesda分类报告","颈部增强CT/MRI：评估胸骨后甲状腺肿、气管受压及颈部淋巴结（拟手术者）","降钙素+癌胚抗原（CEA）：疑甲状腺髓样癌时必查","甲状腺核素显像：TSH降低者评估有无'热结节'","喉镜检查：声音嘶哑或拟手术者评估声带运动"],"infusion":["⚠️ 按围手术期需要选择方案，切勿全部同时使用！","","方案1（术前预防性抗感染，切皮前0.5～1小时）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后补钙，出现低钙时）：","  用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（10min以上）；继以10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持","","方案3（术后补液支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；维生素C 2g 静滴 qd","","📌 葡萄糖酸钙静推速度必须缓慢并监测心电图；甲状腺部分切除术后常规监测血钙。"],"oral_medication":["⚠️ 用药选择提示：同类药物选一种，切勿重复用药！","药物1（术后TSH抑制/替代治疗）：","用法：左甲状腺素钠 25～50μg qd 起（晨起空腹，早餐前30～60分钟）；按TSH调整剂量","药物2（补钙与维生素D，低钙者）：","用法：碳酸钙D3 600mg bid～tid + 骨化三醇 0.25～0.5μg qd","药物3（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 左甲状腺素钠需空腹服用，与钙剂、铁剂、豆制品间隔4小时以上，不可自行停药。"],"treatment":["良性结节：多数无需手术——每6～12个月复查超声与甲功；结节>4cm或有压迫症状、影响美观、生长迅速者考虑手术","手术指征：FNA提示恶性或可疑恶性、TI-RADS≥4类且结节较大、结节压迫气管食管致呼吸困难/吞咽困难、胸骨后甲状腺肿、合并甲亢内科治疗无效、结节快速增大","术式选择：一侧腺叶+峡部切除（单侧良性或低危微小癌）；甲状腺全切（双侧病变、高危甲状腺癌）；颈淋巴结清扫（有淋巴结转移）","甲状腺癌术后：TSH抑制治疗、必要时碘-131治疗、定期监测Tg与超声","术后并发症处理：出血（紧急处理）、喉返神经损伤（神经营养+观察）、甲状旁腺功能减退（补钙+骨化三醇）、甲状腺危象","良性结节非手术选择：射频/微波消融、无水乙醇注射（囊性结节），适用于不愿或不宜手术者"],"management":["术前准备：完善超声、FNA、甲功、喉镜、血钙与凝血；甲亢者需先控制甲功（抗甲状腺药+碘剂准备）","术后体位与观察：半卧位，颈部制动；术后6～12小时内重点观察颈部肿胀、呼吸、声音与引流","血钙监测：术后1～2天查血钙，低钙者每日复查并口服/静脉补钙，询问口周麻木与手足抽搐","引流管护理：记录引流量与性状，一般术后24～48小时（<30～50ml）拔除","嗓音观察：记录声音嘶哑与呛咳情况，声嘶明显者行喉镜检查","随访：术后1个月复查甲功与血钙，调整左甲状腺素剂量；甲状腺癌按危险分层定期复查Tg、超声"],"notes":["绝大多数甲状腺结节为良性，'发现结节就手术'的观念不正确，需结合超声分级与FNA结果决策","FNA是良恶性鉴别的关键，TI-RADS≥4类或结节≥1cm应行穿刺","术后最危险的并发症是出血致气道压迫（术后48小时内），需床旁备气管切开包","双侧喉返神经损伤可致窒息，单侧损伤多表现为声音嘶哑（多数可代偿恢复）","甲状腺癌总体预后良好（乳头状癌10年生存率>90%），规范手术+术后管理是关键"],"emergency":["术后颈部迅速肿胀、呼吸困难、喘鸣、发绀 → 立即床旁拆线清除血肿，必要时气管插管/切开","术后手足抽搐、喉痉挛（重度低钙）→ 立即静脉缓慢推注葡萄糖酸钙","结节迅速增大伴呼吸困难（气管压迫或瘤内出血）→ 急诊评估与处理"],"pinyin":"jzxjjwkcl","icd10":"E04.1","physical_exam":["生命体征：体温、脉搏、呼吸、血压（评估甲功状态与压迫）","颈部视诊：颈部有无隆起、随吞咽上下移动（甲状腺特征）、手术瘢痕、颈部静脉怒张","甲状腺触诊：结节大小、数目、质地（硬/韧/囊性）、边界、活动度、压痛、随吞咽移动度","颈部淋巴结触诊：颈侧区（Ⅱ～Ⅵ区）有无肿大淋巴结及质地、活动度","气管与压迫征象：气管有无偏移、有无呼吸困难与吞咽困难、声音嘶哑","甲功相关体征：突眼、手抖、皮肤湿润（甲亢）；面色苍白、水肿、反应迟钝（甲减）","喉镜（必要时）：评估声带运动（术前与声嘶患者）"],"lab_tests":["甲状腺功能（FT3、FT4、TSH）+甲状腺抗体（TPOAb、TgAb）：评估功能状态与自身免疫背景","甲状腺超声+TI-RADS分级：评估结节特征与恶性风险（必查）","FNA细胞学（Bethesda分类）：TI-RADS≥4类或结节≥1cm时行，良恶性鉴别关键","降钙素+CEA：疑甲状腺髓样癌（家族史、多发结节）时必查","血钙+血磷+甲状旁腺激素（PTH）：术前基线，术后监测低钙","颈部增强CT/MRI：评估胸骨后甲状腺肿、气管受压与淋巴结转移","凝血功能+血常规+心电图+喉镜：术前常规评估"],"nursing":["术前护理：颈部准备、禁食禁水、了解声音与吞咽情况并记录（作为术后对比基线）","术后重点观察（6～12小时内）：颈部肿胀、呼吸、声音、引流液与切口渗血，床旁备气管切开包","体位护理：血压平稳后取半卧位，头颈部制动，避免剧烈咳嗽与颈部过伸","低钙观察：询问口周麻木、手足麻刺感，观察Chvostek征，异常立即报告并备钙剂","用药护理：左甲状腺素空腹服用（与钙剂间隔4小时），观察心悸、多汗（剂量过大）或乏力（剂量不足）"],"diet":["术后6小时进温凉流质（避免过热引起切口渗血），逐步过渡半流质、软食","高蛋白、高维生素饮食促进切口愈合","低钙者增加含钙食物（牛奶、豆制品、虾皮、绿叶菜），并按医嘱补钙与维生素D","甲状腺癌术后需碘-131治疗者：治疗前2～4周低碘饮食（禁海带、紫菜、海鱼、加碘盐）","忌烟酒与辛辣刺激；甲亢者避免浓茶咖啡与含碘丰富食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1333},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"61864f0ee9b0d8b41f40e5dd1d67ffad46534855892eb08f684523f72ada2aa6","pinyin":"jiazhuangxianjiejiewaikechuli","initials":"jzxjjwkcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多无症状，体检或超声偶然发现颈部肿块\\n结节较大时可自觉颈部异物感、吞咽不适、声音嘶哑（压迫喉返神经提示恶性可能）\\n颈侧区淋巴结肿大（提示淋巴结转移）\\n合并甲亢时心悸、多汗、消瘦；合并甲减时乏力、畏寒、水肿\\n结节迅速增大、质地坚硬、活动度差、伴声嘶或呼吸困难提示恶性或压迫",60],["摘要","甲状腺结节是甲状腺内局部异常生长的肿块，成人超声检出率高达20%～70%，其中恶性约5%～15%。处理核心是良恶性鉴别（超声TI-RADS分级+细针穿刺FNA），以及是否需要手术及手术方式（腺叶切除/全切/颈淋巴结清扫）。",30],["疾病编码","E04.1",30],["原首字母","jzxjjwkcl",60]]},{"id":"orders-aae0e4ab93dbd9ec33ea","key":"v1-c9ccc21dfe2a3058|orders-aae0e4ab93dbd9ec33ea","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"化疗前评估与知情同意","category":"化疗","raw":{"name":"化疗前评估与知情同意","category":"化疗","summary":"化疗前评估是保证化疗安全有效的必要环节，包括肿瘤诊断与分期确认、体能状态评分（ECOG/KPS）、重要脏器功能（骨髓、肝、肾、心、肺）评估、既往治疗与合并症、静脉通路选择及心理社会评估，并签署化疗知情同意书。","symptoms":["评估肿瘤相关症状：疼痛、消瘦、进食与排便情况、有无胸腹水、有无骨转移疼痛","评估体能状态：ECOG评分（0～4）或KPS评分，能否耐受化疗","评估既往治疗：手术、放疗、化疗药物与剂量、疗效与不良反应（尤其骨髓抑制、心脏毒性）","评估合并症：高血压、糖尿病、冠心病、肾功能不全、肝炎（乙肝/丙肝）、感染灶","化疗禁忌征象：ECOG≥3（除非可获益）、严重骨髓抑制、重要脏器功能衰竭、活动性感染、妊娠"],"diagnosis":["血常规（含白细胞、中性粒细胞、血红蛋白、血小板）：化疗前1周内，中性粒细胞≥1.5×10⁹/L、血小板≥75～100×10⁹/L方可化疗","肝功能：ALT/AST、胆红素、白蛋白；肝功能异常者按程度调整剂量（胆红素升高需减量）","肾功能：肌酐+尿素氮+肌酐清除率（顺铂、甲氨蝶呤等需按肌酐清除率调整）","心电图+心脏超声（LVEF）：拟用蒽环类、曲妥珠单抗者必查（基线LVEF）","肿瘤标志物+影像学（CT/MRI/PET-CT）：基线评估，用于疗效评价（RECIST标准）","病毒学筛查：乙肝五项+HBV-DNA（HBV携带者需预防性抗病毒）、丙肝、HIV","生育与心理评估：育龄患者避孕与生育力保存咨询，心理状态评估"],"infusion":["⚠️ 化疗前预处理用药（按方案选择，须在化疗药前30～60分钟给予）！","方案1（止吐预处理，高致吐方案）：","用法：阿瑞匹坦 125mg 口服（d1）+ 昂丹司琼 8mg 静推 + 地塞米松 10～20mg 静推〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案2（紫杉醇预处理，防过敏）：","用法：地塞米松 20mg 口服（化疗前12小时与6小时）+ 苯海拉明 20mg 肌注 + 西咪替丁 300mg 静推（化疗前30～60分钟）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案3（水化，顺铂/大剂量MTX）：","用法：0.9%氯化钠 1000～2000ml 静滴（化疗前6～12小时开始）；必要时加甘露醇/呋塞米利尿〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","📌 化疗药物必须由具备资质的医护人员配置与输注；外渗高风险药物（蒽环类、长春碱类）须经中心静脉或PICC输注。"],"oral_medication":["⚠️ 化疗前口服预处理与支持用药：","药物1（止吐）：","用法：阿瑞匹坦 125mg（d1）+ 80mg（d2～d3）qd；或 昂丹司琼 8mg bid〔调 ★ 肝功能不全减量；QT延长风险〕","药物2（激素预处理）：","用法：地塞米松 20mg（化疗前12小时与6小时，紫杉醇方案）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物3（预防性抗病毒，HBV携带者）：","用法：恩替卡韦 0.5mg qd 或 替诺福韦 300mg qd（化疗前1周开始，持续至化疗结束后6～12个月）","药物4（升白预防，必要时）：","用法：聚乙二醇化rhG-CSF 6mg 皮下注射（化疗后24～48小时，每周期一次）","📌 所有预处理用药必须在化疗前按时给予；HBV携带者不预防性抗病毒可致爆发性肝炎。"],"treatment":["明确诊断与分期：病理确诊、影像分期，明确化疗目的（新辅助/辅助/姑息/根治）","制定方案：根据瘤种、分期、指南（NCCN/CSCO）与患者体能状态选择方案与剂量强度","脏器功能剂量调整：肝功能异常（胆红素升高）→ 蒽环类、紫杉类、长春碱类减量；肾功能不全 → 顺铂、甲氨蝶呤、卡铂减量（卡铂按Calvert公式 AUC 4-6 计算）","静脉通路选择：发疱性药物（蒽环类、长春碱类）必须经PICC/CVC/输液港；避免外周小静脉推注","预处理：止吐（昂丹司琼 8mg 静推 + 地塞米松 10mg 静推）、抗过敏（紫杉醇前地塞米松 20mg 口服）、水化（顺铂前生理盐水 1000ml 静滴）、亚叶酸钙解救（大剂量MTX后 15mg/m² 静滴 q6h）","知情同意：告知方案、预期疗效、常见与严重不良反应、替代方案、费用，签署同意书","支持治疗准备：止吐药、升白针（G-CSF 5μg/kg 皮下注射 qd）、口腔护理、营养支持、心理支持"],"management":["建立化疗档案：记录方案、剂量、给药日期、不良反应与处理（便于后续调整）","化疗前核对：患者身份、体表面积/体重、药物名称剂量、给药途径、过敏史（'三查七对'）","基线数据留存：血常规、肝肾功能、心电图、LVEF、肿瘤标志物与影像（疗效评价基线）","患者宣教：化疗期间饮食、口腔护理、感染预防、体温监测、药物外渗的识别与报告","心理支持：解释化疗过程与不良反应可防可控，减轻恐惧；必要时心理科会诊","生育力保存与避孕：育龄患者化疗前咨询生殖医学，化疗期间严格避孕"],"notes":["化疗前必须确认血常规与肝肾功能达标，否则应延迟化疗或减量（不可勉强上药）","蒽环类药物需计算累积剂量（表柔比星≤900mg/m²，多柔比星≤550mg/m²），并监测LVEF","HBV携带者化疗可致乙肝病毒再激活（爆发性肝炎），必须预防性抗病毒","紫杉醇预处理不规范可致严重过敏反应，必须严格按时给药","化疗知情同意须由患者本人或法定代理人签署，并记录不良反应告知内容"],"emergency":["化疗前出现活动性感染、发热（中性粒细胞缺乏伴发热）→ 先控制感染，暂缓化疗","既往化疗出现严重过敏反应（喉头水肿、休克）→ 再次使用同类药物需慎重并备抢救","化疗前发现重要脏器功能衰竭（急性肝衰、心衰）→ 暂缓化疗并多学科评估"],"pinyin":"hlpqgyzqty","icd10":"Z51.1","physical_exam":["生命体征：体温（感染筛查）、脉搏、呼吸、血压、体重与体表面积计算","体能状态：ECOG评分（0～4）或KPS评分（记录于病历）","一般情况：营养状态、消瘦程度、有无贫血与黄疸、有无水肿与胸腹水","浅表淋巴结：颈部、锁骨上、腋窝、腹股沟淋巴结大小与数目（疗效评价基线）","心肺：心界、心率心律、肺部呼吸音（胸腔积液）、有无心衰征象","腹部：肝脾大小、有无腹块与腹水、有无压痛（肿瘤侵犯）","皮肤与静脉：外周静脉条件（是否适合置管）、有无感染灶、既往化疗血管损伤与色素沉着","口腔与黏膜：口腔黏膜完整性（化疗前基线，评估口腔炎风险）"],"lab_tests":["血常规（五分类）：化疗前1周内必查，评估中性粒细胞、血红蛋白、血小板是否达标","肝功能（ALT/AST/胆红素/白蛋白）+肾功能（肌酐/尿素氮/肌酐清除率）：决定剂量调整","心电图+心脏超声（LVEF）：拟用蒽环类、曲妥珠单抗者必查基线值","肿瘤标志物（按瘤种选择CEA/CA19-9/AFP/CA125/PSA等）+增强CT/MRI：基线评估与疗效评价","乙肝五项+HBV-DNA+丙肝抗体+HIV：化疗前常规筛查（指导预防性抗病毒）","电解质+血糖：化疗前基线，顺铂方案需关注镁、钾、钙","尿常规+妊娠试验（育龄女性）：化疗前必查"],"nursing":["化疗前宣教：讲解方案流程、常见不良反应（恶心呕吐、脱发、骨髓抑制）与应对方法，签署同意书","静脉评估：评估外周血管条件，发疱性药物建议置入PICC/CVC/输液港，记录置管与维护日期","体重与体表面积：准确测量身高体重并计算体表面积，双人核对化疗剂量","心理护理：减轻焦虑与恐惧，介绍成功案例，鼓励家属参与","安全核对：化疗药物双人核对（药名、剂量、途径、时间），配置与输注过程严格无菌"],"diet":["化疗前保持均衡营养，纠正营养不良与贫血（高蛋白、高热量、高维生素）","治疗前1～2小时避免大量进食（减少呕吐），可进少量清淡易消化食物","避免生冷、未煮熟食物与不洁饮水（化疗期间免疫力低，防感染）","如有口腔黏膜炎风险，避免过烫、过硬、辛辣及酸性食物","忌酒；服用中药/保健品需先咨询主管医师（可能影响化疗药物代谢）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1334},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a1a6971b231075223cd902491778b04659d325bc1e00237a9bbe6a4cab5a5fe3","pinyin":"hualiaoqianpingguyuzhiqingtongyi","initials":"hlqpgyzqty","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","评估肿瘤相关症状：疼痛、消瘦、进食与排便情况、有无胸腹水、有无骨转移疼痛\\n评估体能状态：ECOG评分（0～4）或KPS评分，能否耐受化疗\\n评估既往治疗：手术、放疗、化疗药物与剂量、疗效与不良反应（尤其骨髓抑制、心脏毒性）\\n评估合并症：高血压、糖尿病、冠心病、肾功能不全、肝炎（乙肝/丙肝）、感染灶\\n化疗禁忌征象：ECOG≥3（除非可获益）、严重骨髓抑制、重要脏器功能衰竭、活动性感染、妊娠",60],["摘要","化疗前评估是保证化疗安全有效的必要环节，包括肿瘤诊断与分期确认、体能状态评分（ECOG/KPS）、重要脏器功能（骨髓、肝、肾、心、肺）评估、既往治疗与合并症、静脉通路选择及心理社会评估，并签署化疗知情同意书。",30],["疾病编码","Z51.1",30],["原首字母","hlpqgyzqty",60]]}]);